\subsection{MPTP}
\label{app:MPTP}

\begin{algorithm}
\caption{Multi-party Training Process w.r.t. $D$ (MPTP)}
\label{alg:D}
\textbf{Insurer Input:} data: $\{X_i, Y_i\}_{i=1}^n$, hypothesis class: $\cH$ (if obtain $T$ via supervised learning) \\
\textbf{Insurer Output:} $\{\tilde{X}_i\}_{i=1}^n$ \\
\textbf{TTP Input:} data: $\{\tilde{X}_i, Y_i, D_i\}$, hypothesis class: $\cF$, risk function: $\cR(f_1, \ldots, f_{|\cD|})$ (Eq. (\ref{eq:TTPpopLoss}))
\begin{algorithmic}
\Repeat
\State train $f_1, \ldots, f_{|\cD|}$ by minimizing Eq. (\ref{eq:TTPpopLoss})
\Until{Convergence}
\State compute $h^*(\tilde{X})$ using Eq. (\ref{eq:TTPDFP})
\State \Return{$f_1, \ldots, f_{|\cD|}, h^*(\tilde{X})$}
\end{algorithmic}
\textbf{TTP Output:} $f_1, \ldots, f_{|\cD|}, h^*(\tilde{X})$
\end{algorithm}

\subsection{MPTP-LDP}
\label{app:MPTP-LDP}

\begin{algorithm}
\caption{Multi-party Training Process w.r.t. $S$ (MPTP-LDP)}\label{alg:S-NE}
\textbf{Insurer Input:} data: $\{X_i, Y_i\}_{i=1}^n$, hypothesis class: $\cH$ (if obtain $T$ via supervised learning), hypothesis class: $\cK$ (if obtain $X^*$ via supervised learning) \\
\textbf{Insurer Output:} $\{\tilde{X}_i\}_{i=1}^n, \{X_i^*\}_{i=1}^n$ \\
\textbf{TTP Input:} data: $\{\tilde{X}_i, Y_i, S_i\}_{i=1}^n, \{X_i^*, S_i\}_{i=1}^n$, hypothesis class $\cG$, risk function: $\forall k \in [n_1]$, $\cR(g_k) = \sum_{j=1}^{m} L(g_k(X_{k,j}^*, S_{k,j}))$ (see Lemma \ref{lemma:NE}), hypothesis class: $\cF$, risk function: $\cR(f_1, \ldots, f_{|\cD|})$ (Eq. (\ref{eq:Risk-LDP})), 
\begin{algorithmic}
\If {scenario 2 ($\pi, \bar{\pi}$ unknown)}
    \State compute $\hat{\pi}_k, \hat{\bar{\pi}}_k, k \in [n_1]$ (by applying Lemma \ref{lemma:NE})
    \State compute $\hat{C}_1$ using $\hat{\pi}_k, \hat{\bar{\pi}}_k, k \in [n_1]$ (by $C_1$ estimation procedure \ref{procedure:C_1})
    \State compute $\hat{\pi}, \hat{\bar{\pi}}$ using $\hat{C}_1$
    \State compute $\hat{\boldsymbol{\Pi}}^{-1}$ using $\hat{\pi}, \hat{\bar{\pi}}$
\Else 
    \State compute $\boldsymbol{\Pi}^{-1}$ using $\pi, \bar{\pi}$
\EndIf
\Repeat
\State train $f_1, \ldots, f_{|\cD|}$ by minimizing Eq. (\ref{eq:Risk-LDP}) 
\Until{convergence}
\State compute $h^*(\tilde{X})$ using Eq. (\ref{eq:TTPDFP})
\State \Return{$f_1, \ldots, f_{|\cD|}, h^*(\tilde{X})$} 
\end{algorithmic}
\textbf{TTP Output:} $f_1, \ldots, f_{|\cD|}, h^*(\tilde{X})$
\end{algorithm}

