\section{Deferred Proofs}

\subsection{Lemma \ref{lemma:Risk-LDP} Proof}
\label{proof:lemmaRisk-LDP}

\textbf{Lemma \ref{lemma:Risk-LDP}} Given the privacy parameter $\epsilon$, minimizing the following risk (Risk-LDP) Eq. (\ref{eq:Risk-LDP}) under $\epsilon$-LDP w.r.t. privatized sensitive attributes $S$ is equivalent of minimizing Eq. (\ref{eq:TTPpopLoss}) w.r.t. true sensitive attributes $D$ at the population level:
\begin{equation}
    \cR^{LDP}(f_1, \ldots, f_{|\cD|}) = \sum_{k=1}^{|\cD|} \sum_{j=1}^{|\cD|} \left( \boldsymbol{\Pi}_{kj}^{-1} \Ex_{Y, \tilde{X} \mid S = j} \left[ L \bigr(f_k(\tilde{X}),Y \bigr) \right] \cdot \sum_{l = 1}^{|\cD|} \boldsymbol{T}_{kl}^{-1} \bbP(S = l) \right),
\end{equation}
where $\boldsymbol{\Pi}^{-1}$ and $\boldsymbol{T}^{-1}$ are $|\cD| \times |\cD|$ row-stochastic matrics.
\begin{proof}

\textbf{Step 1:}

Since the $\epsilon$-LDP randomization mechanism is independent of $X, Y$, therefore, the distribution of $S$ is fully characterized by the privacy parameter $\epsilon$ and the distribution of $D$. Therefore, the distribution of $S$ is deterministic once the privacy parameter $\epsilon$ and the distribution of $D$ is given.

\textbf{Step 2:} Recover distributions w.r.t. $D$ 

Inspired by proposition 1 in \cite{mozannar2020fair}. Let $\cE_1, \cE_2$ be two probability events defined with respect to $(\tilde{X},Y,\hat{Y})$, then consider the following probability:
\[
\begin{aligned}
    & \bbP(\cE_1, \cE_2 \mid S=d) \\ 
    =& \sum_{d' \in D} \bbP(\cE_1, \cE_2 \mid S=d, D=d') \bbP(D=d' \mid S=d)\\
    =& \sum_{d' \in D} \bbP(\cE_1, \cE_2 \mid D=d') \bbP(D=d' \mid S=d)\\
    =& \sum_{d' \in D} \bbP(\cE_1, \cE_2 \mid D=d') \frac{ \bbP(S=d \mid D=d') \bbP(D=d')}{\sum_{d'' \in D} \bbP(S=d \mid D=d'') \bbP(D=d'')}\\
    =& P(\cE_1, \cE_2 \mid D=d)\frac{\pi \bbP(D = d)}{\pi \bbP(D = d) + \underset{d''\setminus d}{\sum}\bar{\pi}\bbP(D = d^{''})}+\sum_{d'\setminus d}P(\cE_1, \cE_2 \mid D=d')\frac{\bar{\pi}\bbP(D = d')}{\pi \bbP(D = d) + \underset{d''\setminus d}{\sum}\bar{\pi}\bbP(D = d^{''})}.
\end{aligned}
\]

Then, let $\cE_1 = Y, \cE_2 = \tilde{X}$, we obtain the following:
\[
\begin{aligned}
    & \bbP(Y, \tilde{X} \mid S=d) \\ 
    =& \sum_{d' \in D} \bbP(Y, \tilde{X} \mid S=d, D=d') \bbP(D=d' \mid S=d)\\
    =& \sum_{d' \in D} \bbP(Y, \tilde{X} \mid D=d') \bbP(D=d' \mid S=d)\\
    =& \sum_{d' \in D} \bbP(Y, \tilde{X} \mid D=d') \frac{ \bbP(S=d \mid D=d') \bbP(D=d')}{\sum_{d'' \in D} \bbP(S=d \mid D=d'') \bbP(D=d'')}\\
    =& P(Y, \tilde{X} \mid D=d)\frac{\pi \bbP(D = d)}{\pi \bbP(D = d) + \underset{d''\setminus d}{\sum}\bar{\pi}\bbP(D = d^{''})}+\sum_{d'\setminus d}P(Y, \tilde{X} \mid D=d')\frac{\bar{\pi}\bbP(D = d')}{\pi \bbP(D = d) + \underset{d''\setminus d}{\sum}\bar{\pi}\bbP(D = d^{''})}.
\end{aligned}
\]

Denote $p_d = \bbP(D = d)$, then let $\boldsymbol{\Pi}$ be the following $|\cD|\times|\cD|$ matrix with the following entries:
\[
\begin{cases}
\boldsymbol{\Pi}_{i,i} = \frac{\pi p_i}{\pi p_i + \underset{d''\setminus i}{\sum}\bar{\pi}p_{d''}}, \text{for $i \in D$}\\
\boldsymbol{\Pi}_{i,j} = \frac{\bar{\pi}p_j}{\pi p_i + \underset{d''\setminus i}{\sum}\bar{\pi}p_{d''}}, \text{for $i,j \in D$ s.t.,$i \ne j$}
\end{cases},
\]
then we have the following system of linear equations:
\[
\begin{bmatrix}
\bbP(Y,\tilde{X} \mid S=1)\\
.\\
.\\
.\\
\bbP(Y,\tilde{X} \mid S=|\cD|)
\end{bmatrix}
= \boldsymbol{\Pi}
\begin{bmatrix}
\bbP(Y,\tilde{X} \mid D=1)\\
.\\
.\\
.\\
\bbP(Y,\tilde{X} \mid D=|\cD|)
\end{bmatrix},
\]
denote as $\boldsymbol{s_1} = \boldsymbol{\Pi} \boldsymbol{d_1}$, where $\boldsymbol{s_1} = \bbP(Y,\tilde{X} \mid S)$, $\boldsymbol{d_1} = \bbP(Y,\tilde{X} \mid D)$.

Since $\boldsymbol{\Pi}$ is row-stochastic and invertible, we show that the entries of $\boldsymbol{\Pi}^{-1}$ take the following forms:
\[
\begin{cases}
\boldsymbol{\Pi}_{i,i}^{-1} = \frac{\pi + |\cD| - 2}{|\cD|\pi - 1}\frac{\pi p_i + \sum_{d''\setminus i} \bar{\pi}p_{d''}}{p_i}, \text{for $i \in D$}\\
\boldsymbol{\Pi}_{i,j}^{-1} = \frac{\pi - 1}{|\cD|\pi - 1}\frac{\bar{\pi} p_i + \sum_{d''\setminus i} \pi p_{d''}}{p_i}, \text{for $i,j \in D$ s.t.,$i \ne j$}
\end{cases},
\]

multiplying $\boldsymbol{\Pi}^{-1}$ on both side, we recovered
\[
\begin{aligned}
    \bbP(Y,\tilde{X} \mid D=k) &= \sum_{j=1}^{|\cD|}\boldsymbol{\Pi}_{kj}^{-1} \bbP(Y,\tilde{X} \mid S=j) \\
    &= \boldsymbol{\Pi}_{k\cdot}^{-1} \bbP(Y,\tilde{X} \mid S)
\end{aligned}
\]
where $\boldsymbol{\Pi}_{k \cdot}^{-1}$ denotes the $k^{\text{th}}$ row of $\boldsymbol{\Pi}^{-1}$.

However, there is still one component that we do need to estimate in order to recover the population distribution of $\bbP(Y, \tilde{X} \mid D)$. We need to further estimate $\bbP(D = d)$. Using the same technique, to estimate $\bbP(D=d)$, first write $P(S=d)$ in terms of the conditional probability of $S$ given $D$ as:
\[
\begin{aligned}
    \bbP(S=d) &= \sum_{d'\in D} \bbP(S=d \mid D=d') \bbP(D=d') \\
       &= \bbP(S=d \mid D=d) \bbP(D=d) + \sum_{d'\setminus d} \bbP(S=d \mid D=d') \bbP(D=d') \\
       &= \pi p_d + \sum_{d'\setminus d}\bar{\pi}p_{d'}.
\end{aligned}
\]

Then we write the above expression in terms of a system of linear equations. Let $\boldsymbol{T}$ be an $|\cD|\times|\cD|$ matrix with the following entries:
\[
\begin{cases}
\boldsymbol{T}_{i,i}=\pi, \text{for $i \in D$}\\
\boldsymbol{T}_{i,j}=\bar{\pi}, \text{for $i,j \in D$ s.t.,$i \ne j$}
\end{cases},
\]
then we have the following system of linear equations:
\[
\begin{bmatrix}
\bbP(S=1)\\
.\\
.\\
.\\
\bbP(S=|\cD|)
\end{bmatrix}
= \boldsymbol{T}
\begin{bmatrix}
\bbP(D=1)\\
.\\
.\\
.\\
\bbP(D=|\cD|)
\end{bmatrix},
\]
denote as $\boldsymbol{s}_2 = \boldsymbol{T} \boldsymbol{d}_2$, where $\boldsymbol{s}_2 = \bbP(S)$ and $\boldsymbol{d}_2 = \bbP(D)$.

It follows the same argument that $\boldsymbol{T}$ is row-stochastic and invertible and it is easy to verify that $\boldsymbol{T}^{-1}$ takes the following form:
\[
\begin{cases}
\boldsymbol{T}_{i,i}^{-1} = \frac{\pi + |\cD| - 2}{|\cD|\pi - 1}, \text{for $i \in D$}\\
\boldsymbol{T}_{i,j}^{-1} = \frac{\pi - 1}{|\cD|\pi - 1}, \text{for $i,j \in D$ s.t.,$i \ne j$}
\end{cases},
\]
by multiplying $\boldsymbol{T}^{-1}$ on both side, we obtain:
\[
\begin{aligned}
    \bbP(D=k) &= \sum_{j=1}^{|\cD|} \boldsymbol{T}_{kj} \bbP(S = j) \\
    &= \boldsymbol{T}_{k\cdot}^{-1} \bbP(S).
\end{aligned}
\]

\textbf{Step 3:} Recover the loss w.r.t. D

At the population level, we have recovered that:
\[
\bbP(Y, \tilde{X} \mid D = k) = \boldsymbol{\Pi}_{k\cdot}^{-1} \bbP(Y,\tilde{X} \mid S),
\]
where $\bbP(D = k) = \boldsymbol{T}_{k \cdot}^{-1} \bbP(S)$ is used in calculation of $\boldsymbol{\Pi}_{k \cdot}^{-1}$.

Hence, we recover the population equivalent of Eq. (\ref{eq:TTPpopLoss}):
\[
\begin{aligned}
    &\sum_{k=1}^{|\cD|} \left( \Ex_{Y,\tilde{X} \mid D = k}\left[ L \bigr( Y, f_k(\tilde{X}) \bigr) \right] \cdot \bbP(D = k) \right) \\ 
    =& \sum_{k=1}^{|\cD|} \left( \int_Y\int_{\tilde{X}} \bbP(Y,\tilde{X} \mid D = k) L \left( Y, f_k(\tilde{X}) \right) d\tilde{X}dY  \cdot \bbP(D = k) \right) \\
    =& \sum_{k=1}^{|\cD|} \left( \left[ \int_Y\int_{\tilde{X}} \sum_{j=1}^{|\cD|}\boldsymbol{\Pi}_{kj}^{-1} \bbP(Y,\tilde{X} \mid S=j) L \bigr( Y, f_k(\tilde{X}) \bigr) d\tilde{X}dY \right] \cdot \sum_{l = 1}^{|\cD|} \boldsymbol{T}_{kl}^{-1} \bbP(S = l) \right) \\
    =& \sum_{k=1}^{|\cD|} \left( \left[ \sum_{j=1}^{|\cD|} \int_Y\int_{\tilde{X}} \boldsymbol{\Pi}_{kj}^{-1} \bbP(Y, \tilde{X} \mid S = j) L \bigr( Y, f_k(\tilde{X}) \bigr) d\tilde{X}dY \right] \cdot \sum_{l = 1}^{|\cD|} \boldsymbol{T}_{kl}^{-1} \bbP(S = l) \right)\\
    =& \sum_{k=1}^{|\cD|} \sum_{j=1}^{|\cD|} \left( \boldsymbol{\Pi}_{kj}^{-1} \Ex_{Y, \tilde{X} \mid S = j} \left[ L \bigr(f_k(\tilde{X}),Y \bigr) \right] \cdot \sum_{l = 1}^{|\cD|} \boldsymbol{T}_{kl}^{-1} \bbP(S = l) \right).
\end{aligned}
\]

Therefore, we conclude that it is equivalent to minimizing:
\[
(f_{1^*}, \ldots, f_{|\cD|^*}) \leftarrow \underset{f_1, \ldots, f_{|\cD|}}{\arg \min} \sum_{k=1}^{|\cD|} \sum_{j=1}^{|\cD|} \left( \boldsymbol{\Pi}_{kj}^{-1} \Ex_{Y, \tilde{X} \mid S = j} \left[ L \bigr(f_k(\tilde{X}),Y \bigr) \right] \cdot \sum_{l = 1}^{|\cD|} \boldsymbol{T}_{kl}^{-1} \bbP(S = l) \right)
\]

% But, it shall be noted that empirically, although the entries of $\hat{\bbP}(Y, X \mid D = k), k = 1, \ldots, |\cD|$ sum to $1$, some entries might be in fact negative. Thus, we need to project the derived empirical estimator onto a simplex of the corresponding dimension for it to be valid.

% We now define the orthogonal projection of $x$ onto a simplex as:
% \[
% \text{proj}_{\bm{\mathit{\Delta}}}(\bm{\mathrm{x}}):= \arg\min_{\bm{\mathrm{y}}}\frac{1}{2}\|\mathrm{y}-\mathrm{x}\|_2^2, \  \text{s.t.}\medspace \bm{\mathrm{y}}^T\bm{1} = 1, \bm{\mathrm{y}}>0,
% \]
% which can be solved optimally in a non-iterative manner in time $\cO(|\cD|log|\cD|)$.

% Therefore, a well-defined empirical estimator $\hat{\bbP}(Y, X \mid D = k)$ is obtained through its orthogonal projection to the $|\cD| - 1$ simplex:
% \[
% \begin{aligned}
% \hat{\bbP}(Y, X \mid D = k) &= \text{proj}_{\bm{\mathit{\Delta}}} \Bigr( \sum_{j=1}^{|\cD|} \boldsymbol{\Pi}_{kj}^{-1} \hat{\bbP}(Y, X | S = j) \Bigr) \\
% &= \text{proj}_{\bm{\mathit{\Delta}}} \Bigr( \boldsymbol{\Pi}_{k \cdot}^{-1} \hat{\bbP}(Y, X \mid S) \Bigr)
% \end{aligned}
% \]
% where $\hat{\bbP}(Y, X \mid S)$ is the empirical distribution from data.

This completes the proof.
\end{proof}

