\subsection{\textbf{Theorem} \ref{theorem:GEB} Proof}
\label{proof:theoremGEB}
\textbf{Theorem \ref{theorem:GEB}}  For any $\delta \in (0,\frac{1}{2})$, $C_1 = \frac{\pi + |\cD| - 2}{|\cD|\pi - 1}$, denote $VC(\cF)$ as the VC-dimension of the hypothesis class $\cF$, and $K$ be some constant that depends on $VC(\cF)$. Let $f = \{f_k\}_{k=1}^{|\cD|}$ where $f_k \in \cF$ and let $L: Y \times Y \to \bbR_+$ be a loss function bounded by some constant $M$. Denote $k^* \leftarrow \underset{k}{\arg\max} |\hat{\cR}^{LDP}(f_k)\hat{\bbP}(D = k) - \cR^{LDP}(f_k)\bbP(D = k)|$, if $n \ge \frac{8 \ln{(\frac{|\cD|}{\delta})}}{\min_k \bbP(S = k)}$ \, then with probability $1 - 2\delta$:
\[
\hat{\cR}^{LDP}(f) \le \cR(f^*) + K\sqrt{\frac{VC(\cF) + \ln{( \frac{\delta}{2})}}{2n}} \frac{2C_1 M|\cD|}{\bbP(S = k^*)}.
\]

\begin{proof}
\textbf{Step 1:} simplify the objective

Denote $\cR(f)$ as the expected risk of $(f_1, \ldots, f_{|\cD|})$ defined in Lemma \ref{lemma:Risk-LDP}, $\cR(f_k)$ as the expected risk of $f_k$ defined as $\Ex_{Y, \tilde{X} \mid D = k} \left[ L \left( f_k(\tilde{X}, Y) \right) \right]$, and $\hat{\cR}(f_k)$ as the empirical risk of $f_k$ that depends on the data set given, then we start with
\[
\begin{aligned}
    & \bbP \left( \left| \hat{\cR}^{LDP}(f)\hat{\bbP}(D = k) - \cR(f)\bbP(D = k) \right| > \epsilon \right) \\
    =& \bbP \left( \left| \hat{\cR}^{LDP}(f)\hat{\bbP}(D = k) + \cR^{LDP}(f)\bbP(D = k) - \cR^{LDP}(f)\bbP(D = k) - \cR(f)\bbP(D = k) \right| > \epsilon \right) \\
    \le& \bbP \left( \left| \hat{\cR}^{LDP}(f)\hat{\bbP}(D = k) - \cR^{LDP}(f)\bbP(D = k) \right| + \left| \cR^{LDP}(f)\bbP(D = k) - \cR(f)\bbP(D = k) \right| > \epsilon \right) \\
    \overset{(a)}{=}& \bbP \left( \left| \hat{\cR}^{LDP}(f)\hat{\bbP}(D = k) - \cR^{LDP}(f)\bbP(D = k) \right| \ge \epsilon) \right) \\
    =& \bbP \left( \left| \sum_{k=1}^{|\cD|} \hat{\cR}^{LDP}(f_k)\hat{\bbP}(D = k) - \sum_{k=1}^{|\cD|} \cR^{LDP}(f_k)\bbP(D = k) \right| > \epsilon \right) \\
    \le& \bbP \left( \sum_{k=1}^{|\cD|} \left|\hat{\cR}^{LDP}(f_k)\hat{\bbP}(D = k) - \cR^{LDP}(f_k)\bbP(D = k) \right| > \epsilon \right) \\
    \overset{(b)}{\le}& \bbP \left( \underset{k}{\max} \left| \hat{\cR}^{LDP}(f_k)\hat{\bbP}(D = k) - \cR^{LDP}(f_k)\bbP(D = k) \right| > \frac{\epsilon}{|\cD|} \right) \\
    \overset{(c)}{=}& \bbP \left( \left| \sum_{j=1}^{|\cD|}\hat{\boldsymbol{\Pi}}_{k^*j}^{-1} \frac{1}{n_j} \sum_{i: S_i=j} L \left( Y_i, f_{k^*}(\tilde{X}_i) \right) \sum_{l = 1}^{|\cD|} \hat{\boldsymbol{T}}_{k^*l}^{-1}\frac{n_l}{n} - \boldsymbol{\Pi}_{k^* \cdot}^{-1} \Ex_{Y,\tilde{X}|S} \left[ L \left( Y, f_{k^*}(\tilde{X}) \right) \right] \boldsymbol{T}_{k^* \cdot}^{-1}\bbP(S) \right| > \frac{\epsilon}{|\cD|} \right),
\end{aligned}
\]
where $k^* \leftarrow \underset{k}{\arg\max} \left| \hat{\cR}^{LDP}(f_k)\hat{\bbP}(D = k) - \cR^{LDP}(f_k)\bbP(D = k) \right|$ and $\hat{\bbP}(S = k) = \frac{n_k}{n}$. 

$\boldsymbol{T}^{-1}$ and $\boldsymbol{\Pi}^{-1}$ are as introduced in Lemma \ref{lemma:Risk-LDP}.

(a) is obtained from the population equivalence of two risks from Lemma \ref{lemma:Risk-LDP}. 

(b) is followed by for two events $A, B$, if $A$ implies $B$ then $P(A) < P(B)$.

(c) is obtained by expanding $\hat{\cR}^{LDP}(f_{k^*})\hat{\bbP}(D = k^*)$ and $\cR^{LDP}(f_{k^*}) \bbP(D = k^*)$ respectively.

\textbf{Step 2:} concentration of the empirical risk under Risk-LDP

Denote $n_{y\tilde{x}s}^N = \sum_i \ones(y_i = y, \tilde{x}_i = \tilde{x}, s_i = s), \boldsymbol{Q}_{y\tilde{x}s} = \bbP(Y=y, \tilde{X}=\tilde{x}, S=s)$, and define the random variable $N_{y\tilde{x}s} = \{i \mid y_i = y, \tilde{x}_i = \tilde{x}, s_i = s\}$. We can deduce $n_s^N = \sum_{\tilde{x} \in \tilde{X}, y \in Y} \ones(y_i = y, \tilde{x}_i = \tilde{x}, s_i = s)$. Then, we have $\Ex[\hat{\cR}^{LDP}(f_{k^*}) \hat{\bbP}(D = k^*) \mid N_{Y\tilde{X}S}] = \cR^{LDP}(f_{k^*}) \bbP(D = k^*)$, where $N_{YXS}$ denotes all possible $N_{y\tilde{x}s}$. Using similar approach of Lemma 2 in \cite{mozannar2020fair}, we can write:
\[
\begin{aligned}
    & \bbP \left( \hat{\cR}^{LDP}(f_{k^*})^N \hat{\bbP}(D = k^*)^N - \cR^{LDP}(f_{k^*}) \bbP(D = k^*) > \frac{\epsilon}{|\cD|} \right) \\
    \overset{(a)}{=}& \sum_{N_{Y\tilde{X}S}} \bbP \left( \hat{\cR}^{LDP }(f_{k^*})^N \hat{\bbP}(D = k^*)^N - \cR^{LDP}(f_{k^*}) \bbP(D = k^*) > \frac{\epsilon}{|\cD|} \biggr| N_{Y\tilde{X}S} \right) \cdot \bbP(N_{Y\tilde{X}S}) \\
    \overset{(b)}{\le}& \bbP \left( \bigcup_{\tilde{x} \in \tilde{X}, y \in Y, s \in S} \left\{ n_s^N < \frac{n \sum_{\tilde{x} \in \tilde{X}, y \in Y}\boldsymbol{Q}_{y\tilde{x}s}}{2} \right\} \right) \\
    &+ \sum_{\forall \tilde{x},y, N_{y\tilde{x}s}: n_s^N \ge \frac{n \sum_{\tilde{x} \in \tilde{X}, y \in Y} \boldsymbol{Q}_{y\tilde{x}s}}{2}} \bbP \left( \hat{\cR}^{LDP}(f_{k^*})^N \hat{\bbP}(D = k^*)^N - \cR^{LDP}(f_{k^*}) \bbP(D = k^*) > \frac{\epsilon}{|\cD|} \Bigr| N_{Y\tilde{X}S} \right) \cdot \bbP(N_{Y\tilde{X}S}) \\
    \overset{(c)}{\le}& |\cD| \exp{\left\{ - \frac{\min_s n \sum_{\tilde{x} \in \tilde{X}, y \in Y} \boldsymbol{Q}_{y\tilde{x}s}}{8} \right\}} \\
    &+ \sum_{\forall \tilde{x},y, N_{y\tilde{x}s}: n_s^N \ge \frac{n \sum_{\tilde{x} \in \tilde{X}, y \in Y} \boldsymbol{Q}_{y\tilde{x}s}}{2}} \bbP \left( \hat{\cR}^{LDP}(f_{k^*})^N \hat{\bbP}(D = k^*) - \cR^{LDP}(f_{k^*}) \bbP(D = k^*) > \frac{\epsilon}{|\cD|} \Bigr| N_{Y\tilde{X}S} \right) \cdot \bbP(N_{Y\tilde{X}S}),
\end{aligned}
\]
where: 

(a) follows by conditioning over all possible configurations of $N_{y\tilde{x}s} \subset [n]$. 

(b) is obtained by splitting the configurations where $\forall \tilde{x},y, N_{y\tilde{x}s}: n_s^N \ge \frac{n \sum_{\tilde{x} \in \tilde{X}, y \in Y} \boldsymbol{Q}_{y\tilde{x}s}}{2}$ and the complement of the event and upper bound the complement of the event by the probability that $\exists s$ s.t. $n_s^N < \frac{n \sum_{\tilde{x} \in \tilde{X}, y \in Y} \boldsymbol{Q}_{y\tilde{x}s}}{2}$. 

(c) is obtained by the union bound and we know $n_s^N \sim \text{Binomial} \left( n, \sum_{\tilde{x} \in \tilde{X}, y \in Y} \boldsymbol{Q}_{y\tilde{x}s} \right)$ and apply the Chernoff bound on $n_{y\tilde{x}s}^N$.

Notice that $f_k(\cdot)$ only takes $\tilde{X} \in T(\cX)$ as input, therefore, we will be able to apply the McDiarmid Inequality \cite{mcdiarmid_1989}. Let $X^n = (X_1, \ldots, X_n) \in X^n$ be n independent random variables and let $g: X^n \to \bbR$, if there exists constants $c_1, \ldots, c_n$ s.t. 
\[
\underset{x_1,\ldots,x_i,x'_i, \ldots, x_n}{\sup} |g(x_1,\ldots,x_i,\ldots,x_n) - g(x_1,\ldots,x'_i,\ldots,x_n)| \le c_i, i = 1, \ldots, n,
\]
then $\forall \epsilon > 0$:
\[
\bbP(|g(x_1,\ldots,x_i,\ldots,x_n) - \Ex[g(x_1,\ldots,x'_i,\ldots,x_n)]| > \epsilon) \le 2 \exp{\biggr( -\frac{2 \epsilon^2}{\sum_{i=1}^n c_i^2} \biggr)}.
\]

Since by conditioning on $N_{Y\tilde{X}S}$, then for $\hat{\cR}^{LDP}(f_{k^*})$, everything else is now deterministic except for $f_{k^*}$, in other words, by conditioning on $N_{Y\tilde{X}S}$, the value of $\hat{\cR}^{LDP}(f_{k^*})$ only depends on $f_{k^*}$. Then, for two datasets $N, N'$ where they only differ by one value of $f_{k^*}(\tilde{X}_i)$, we try to bound how much $f_{k^*}$ can change.

Recall from Lemma \ref{lemma:Risk-LDP}, we computed the entries of $\boldsymbol{\Pi}^{-1}$ takes the following form:
\[
\begin{cases}
\boldsymbol{\Pi}_{i,i}^{-1} = \frac{\pi + |\cD| - 2}{|\cD|\pi - 1}\frac{\pi p_i + \sum_{d''\setminus i} \bar{\pi}p_{d''}}{p_i}, \text{for $i \in D$}\\
\boldsymbol{\Pi}_{i,j}^{-1} = \frac{\pi - 1}{|\cD|\pi - 1}\frac{\bar{\pi} p_i + \sum_{d''\setminus i} \pi p_{d''}}{p_i}, \text{for $i,j \in D$ s.t.,$i \ne j$}
\end{cases}.
\]
For simplicity, let $C_1 = \frac{\pi + |\cD| - 2}{|\cD|\pi - 1}, C_2 = \frac{\pi - 1}{|\cD|\pi - 1}$, since we do not have access to $D$, therefore we can not directly observe $p_d$, hence 
we write $\boldsymbol{\Pi}^{-1}$ in terms of $\boldsymbol{P}_s$ where $\boldsymbol{P}_s = \bbP(S)$:
\[
\begin{cases}
\boldsymbol{\Pi}_{i,i}^{-1} = C_1 \frac{\pi \boldsymbol{T}_{i \cdot}^{-1} \boldsymbol{P}_s + \sum_{l \setminus i} \bar{\pi} \boldsymbol{T}_{l \cdot}^{-1} \boldsymbol{P}_s}{\boldsymbol{T}_{i \cdot}^{-1} \boldsymbol{P}_s}, \text{for $i \in D$}\\
\boldsymbol{\Pi}_{i,j}^{-1} = C_2 \frac{\bar{\pi} \boldsymbol{T}_{i \cdot}^{-1} \boldsymbol{P}_s + \sum_{l \setminus i} \pi \boldsymbol{T}_{l \cdot}^{-1} \boldsymbol{P}_s}{\boldsymbol{T}_{i \cdot}^{-1} \boldsymbol{P}_s}, \text{for $i,j \in D$ s.t.,$i \ne j$}
\end{cases},
\]
we also computed $\boldsymbol{T}^{-1}$ as:
\[
\begin{cases}
\boldsymbol{T}_{i,i}^{-1} = \frac{\pi + |\cD| - 2}{|\cD|\pi - 1}, \text{for $i \in D$}\\
\boldsymbol{T}_{i,j}^{-1} = \frac{\pi - 1}{|\cD|\pi - 1}, \text{for $i,j \in D$ s.t.,$i \ne j$}
\end{cases},
\]

then we have 
\[
\begin{aligned}
    & \underset{N,N'}{\sup} \left| \hat{\cR}^{LDP}(f_{k^*})^N \hat{\bbP}(D = k^*)^N - \hat{\cR}^{LDP}(f_{k^*})^{N'} \hat{\bbP}(D = k^*)^{N'} \right| \\
    \overset{(a)}{\le}&\underset{N,N'}{\sup} \left| \hat{\cR}^{LDP}(f_{k^*})^N - \hat{\cR}^{LDP}(f_{k^*})^{N'} \right| \\
    =& \Biggr| C_1 \frac{\pi \boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N + \sum_{l \setminus k} \bar{\pi} \boldsymbol{T}_{l \cdot}^{-1} \boldsymbol{P}_s^N}{\boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N} \hat{\cR}^{LDP}(f_{k^*})^N + \sum_{j \setminus k} C_2 \frac{\bar{\pi} \boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N + \sum_{l \setminus k} \pi \boldsymbol{T}_{l \cdot}^{-1} \boldsymbol{P}_s^N}{\boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N} \hat{\cR}^{LDP}(f_{k^*})^N \\ 
    &-  C_1 \frac{\pi \boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N + \sum_{l \setminus k} \bar{\pi} \boldsymbol{T}_{l \cdot}^{-1} \boldsymbol{P}_s^N}{\boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N} \hat{\cR}^{LDP}(f_{k^*})^{N'} + \sum_{j \setminus k} C_2 \frac{\bar{\pi} \boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N + \sum_{l \setminus k} \pi \boldsymbol{T}_{l \cdot}^{-1} \boldsymbol{P}_s^N}{\boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N} \hat{\cR}^{LDP}(f_{k^*})^{N'} \Biggr| \\
    =& \Biggr|  C_1 \frac{\pi \boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N + \sum_{l \setminus k} \bar{\pi} \boldsymbol{T}_{l \cdot}^{-1} \boldsymbol{P}_s^N}{\boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N} \left( \frac{\sum_{i \in N, \tilde{x} \in \tilde{X}, y \in Y, S = k} L \left( y_i, f_{k^*}(\tilde{x}_i) \right)}{n_{k^*}} - \frac{\sum_{i \in N', \tilde{x} \in \tilde{X}, y \in Y, S = k} L \left( y_i, f_{k^*}(\tilde{x}_i) \right)}{n_{k^*}} \right) \\ 
    &+ \sum_{j \setminus k} C_2 \frac{\bar{\pi} \boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N + \sum_{l \setminus k} \pi \boldsymbol{T}_{l \cdot}^{-1} \boldsymbol{P}_s^N}{\boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N} \left( \frac{\sum_{i \in N, \tilde{x} \in \tilde{X}, y \in Y, S = j} L \left( y_i, f_{k^*}(\tilde{x}_i) \right)}{n_{k^*}} - \frac{\sum_{i \in N', \tilde{x} \in \tilde{X}, y \in Y, S = j} L \left( y_i, f_{k^*}(\tilde{x}_i) \right)}{n_{k^*}} \right) \Biggr| \\
    \overset{(b)}{\le}& \left| C_1 \frac{\pi \underset{m \in [|\cD|]}{\max} \ \boldsymbol{T}_{m \cdot}^{-1} \boldsymbol{P}_s^N + (|\cD|-1)\bar{\pi} \underset{m \in [|\cD|]}{\max} \ \boldsymbol{T}_{m \cdot}^{-1} \boldsymbol{P}_s^N}{\boldsymbol{T}_{k^* \cdot}^{-1} \boldsymbol{P}_s^N} \cdot \frac{M}{n_{k^*}} \right| \\
    =& \left| C_1 \bigr( \pi + \bar{\pi}(|\cD| - 1) \bigr) \cdot \frac{M}{n_{k^*}} \right| \\
    \overset{(c)}{=}& \left| \frac{C_1 M}{n_{k^*}} \right|,
\end{aligned}
\]
where (a) is followed by the fact that we only consider the change in $\tilde{X}$, and $\hat{\bbP}(D = k^*) \le 1$. (b) is obtained by $C_2 \le 0, \forall \pi \in(\frac{1}{|\cD|}, 1]$. (c) is followed by the fact that $\pi + \bar{\pi}(|\cD| - 1) = 1$.

Now, we are ready to apply the McDiarmid Inequality:
\[
\begin{aligned}
   & \sum_{\forall \tilde{x},y, N_{y\tilde{x}s}: n_s^N \ge \frac{n \sum_{\tilde{x} \in \tilde{X}, y \in Y} \boldsymbol{Q}_{y\tilde{x}s}}{2}} \bbP \left( \hat{\cR}^{LDP}(f_{k^*})^N - \cR^{LDP}(f_{k^*}) > \frac{\epsilon}{|\cD|} \Bigr| N_{Y\tilde{X}S} \right) \cdot \bbP(N_{Y\tilde{X}S}) \\
   \le& \sum_{\forall x,y, N_{y\tilde{x}s}: n_s^N \ge \frac{n \sum_{\tilde{x} \in \tilde{X}, y \in Y} \boldsymbol{Q}_{y\tilde{x}s}}{2}} 2\exp{ \left\{ - \frac{\frac{2 \epsilon^2}{|\cD|^2}}{n \cdot \bigr( \frac{C_1 M}{n_{k^*}} \bigr)^2} \right\}} \cdot \bbP(N_{Y\tilde{X}S}) \\
   \overset{(a)}{\le}& 2 \exp{ \left\{ -2n\epsilon^2 \left( \frac{\bbP(S=k^*)}{2C_1 M |\cD|} \right)^2 \right\}},
\end{aligned}
\]
where (a) is obtained since when $n_{k^*} = \frac{n \sum_{\tilde{x} \in \tilde{X}, y \in Y} \boldsymbol{Q}_{y\tilde{x}k^*}}{2} = \frac{n\bbP(S=k^*)}{2}$, the quantity is maximized. 

Now, we have:
\[
\bbP \left( \left| \hat{\cR}^{LDP}(f) - \cR(f) \right| > \epsilon \right) \le |\cD|\exp{ \left\{ - \frac{\min_k \bbP(S = k)}{8} \right\}} + 2\exp{ \left\{ -2n \epsilon^2 \left( \frac{\bbP(S = k^*)}{2C_1 M|\cD|} \right)^2 \right\}},
\]
solve for $\delta$, we now have, for any $\delta \in (0, \frac{1}{2}), \epsilon \ge \sqrt{\frac{\ln{( \frac{\delta}{2})}}{2n}} \frac{2C_1 M|\cD|}{\bbP(S = k^*)}$, if $n \ge \frac{8 \ln{(\frac{|\cD|}{\delta})}}{\min_k \bbP(S = k)}$, then 
\[
\bbP \left( \left| \hat{\cR}^{LDP}(f) - \cR(f) \right| > \epsilon \right) \le 2\delta
\]

\textbf{Step 3:} Obtain the final result

Recall that one can easily show
\[
\hat{\cR}^{LDP}(f) - \cR(f^*) \le 2 \ \underset{f \in \cF}{\sup} \left| \cR^{LDP}(f) - \hat{\cR}^{LDP}(f) \right|,
\]
but we have already established similar results for one single hypothesis in \textbf{Step 2}. Therefore, what remains is to extend the previous result that bounds the generalization error between any single hypothesis and the optimal hypothesis in the entire hypothesis class. And this can be done easily by introducing the VC-dimension of the hypothesis $\cF$. Denote the VC-dimension of our hypothesis class $\cF$ as $VC(\cF)$, then with some constant $K$ and for any $\delta \in (0, \frac{1}{2})$, if $n \ge \frac{8 \ln{(\frac{|\cD|}{\delta})}}{\min_k \bbP(S = k)}$, we have:
\[
\hat{\cR}^{LDP}(f) \le \cR(f^*) + K\sqrt{\frac{VC(\cF) + \ln{( \frac{\delta}{2})}}{2n}} \frac{2C_1 M|\cD|}{\bbP(S = k^*)}.
\]

This completes the proof.
\end{proof}

