\subsection{\textbf{Theorem} \ref{theorem:GEB-NE} Proof}
\label{proof:theoremGEB-NE}
\textbf{Theorem \ref{theorem:GEB-NE}}
For any $\delta \in (0,\frac{1}{3})$, $C_1 = \frac{\pi + |\cD| - 2}{|\cD|\pi - 1}$, denote $VC(\cF)$ as the VC-dimension of the hypothesis class $\cF$, and $K$ be some constant that depends on $VC(\cF)$. If Assumption A, B, and Lemma \ref{lemma:NE} hold, let $f = \{f_k\}_{k=1}^{|\cD|}$ where $f_k \in \cF$ and let $L: Y \times Y \to \bbR_+$ be a loss function bounded by some constant $M$. Denote $k^* \leftarrow \underset{k}{\arg\max} |\hat{\cR}^{LDP}(f_k) \hat{\bbP}(D = k) - \cR^{LDP}(f_k) \bbP(D = k)|$, if $n \ge \frac{8 \ln{(\frac{|\cD|}{\delta})}}{\min_k \bbP(S = k)}$, $n_1\ge \frac{1}{c(\Tilde{\epsilon}-\theta)^2}(M_g+\frac{C_1+\theta}{\ln 2})^2 \ln(\frac{2}{\delta})$, and $M_g+\frac{C_1+\theta}{\ln 2}>\Tilde{\epsilon}>\theta$,  where $c$ is an absolute constant, then with probability $1 - 3\delta$:
\[
\hat{\cR}^{LDP}(f) \le \cR(f^*) + K\sqrt{\frac{VC(\cF) + \ln{( \frac{\delta}{2})}}{2n}} \frac{2(C_1+\Tilde{\epsilon}) M|\cD|}{\bbP(S = k^*)}.  
\]

\begin{proof}

We will first introduce some preliminaries that will be used in the proof. We will first introduce how we obtain $\hat{C}_1$ and then state the assumptions used for the proof.

\textbf{Step 1: Grouping:} we evenly divide $\{ X_i^*, S_i \}_{i=1}^n,$ into $n_1$ groups, with $m=\frac{n}{n_1}$ samples each. \textbf{Step 2: Estimating within groups:}  for any $k\in [n_1],$ within each group $\{ X_{k,j}^*, S_{k,j}\}_{j=1}^{m}$, we can derive an $m$-dimension vector $\boldsymbol{\eta}_{j^*,k}^m(X_{k,\cdot}^*) = \bigr( \hat{\bbP}_k(S = j^*|X_{k,1}^*), \ldots, \hat{\bbP}_k(S = j^*|X_{k,m}^*) \bigr)$ and $\hat{\pi}_k=\| \boldsymbol{\eta}_{j^*,k}^m(X_{k,\cdot}^*) \|_{\infty}$, as defined in Lemma \ref{lemma:NE}. Then, by a simple plug in to get $\hat{C}_{1,k}=\frac{\hat{\pi}_k+|\cD|-2}{|\cD|\hat{\pi}_k-1}$. \textbf{Step 3: Averaging:} $\hat{C}_1$ is our estimator for $C_1$, computed as $\hat{C}_1=\frac{1}{n_1}\sum_{k=1}^{n_1}\hat{C}_{1,k}, \hat{C}_{1,k}, k\in[n_1]$. 

Next, we state two assumptions used to derive Theorem \ref{theorem:GEB-NE} (noise rate is estimated from the data).

\textbf{Assumption A:}\ (Sub-exponentiality) For all $k \in [n_1]$, define $\hat{g}_k(X^*)=\hat{\bbP}_k(S=j^* | X^*)$ There exists a constant $M_{g}>0,$ such that $\|\hat{C}_{1,k}\|_{\psi_1}= \|\min_{i\in[m]}\frac{\hat{g}_k(X_{k,i}^*)+|\cD|-2}{|\cD|\hat{g}_k(X_{k,i}^*)-1}\|_{\psi_1} \leq M_g$ for all $k\in[n_1],$ where $\|\cdot\|_{\psi_1}$ is the sub-exponential norm: $\|X\|_{\psi_1}=\inf \{t>0 | \Ex [e^{X/t}] \le 2\}$. 

\textbf{Assumption B:}\ (Nearly Unbiasedness) For all $k\in[n_1]$, $\hat{C}_{1,k}$ is a ``nearly" unbiased estimator of $C_1$, namely $\left|\Ex[\hat{C}_{1,k}]-C_1\right|<\theta$ for all $k\in[n_1]$, where $\theta>0$.

Now, we begin the proof.

\textbf{First}, we will prove a concentration inequality with regard to $\hat{C}_1$ and $C_1$.

%For any $k\in [n_1],$ we have $\hat{C}_{1,k}=\frac{\hat{\pi}_k+|\cD|-2}{|\cD|\hat{\pi}_k-1}$, where $\hat{\pi}_k=\| \boldsymbol{\eta}_{s,k}(T(X)^*) \|_{\infty}$ is the maximum. Notice that $\hat{C}_{1,k}$ is a decreasing function with regard to $\hat{\pi}$, we have $\hat{C}_{1,k}=\min_{i\in[m]} \hat{C}^{(i)}_{1,k},$ where $\hat{C}^{(i)}_{1,k}=\frac{g_k(\Tilde{T}(X_{k,i}))+|\cD|-2}{|\cD|g_k(\Tilde{T}(X_{k,i}))_k-1}$.

%Consequently, for any $t>0$,
%\[
%\bbE \exp\left(|\hat{C}_{1,k}|/t\right) \leq \bbE \underset{i\in[m]}{\min}\exp\left(|\hat{C}^{(i)}_{1,k}|/t\right), 
%\]
%which implies $\| \hat{C}_{1,k} \|_{\psi_1} \leq \min_{i\in[m]}\| \hat{C}^{(i)}_{1,k} \|_{\psi_1} \leq M_g.$

Since for any constant $L$, we have
\[
\begin{aligned}
    \|L\|_{\psi_1} &=\inf \{t>0 | \Ex [e^{|L|/t}] \le 2\} \\
    &= \inf \{t>0 | e^{|L|/t} \le 2\} \\
    &= \frac{|L|}{\ln 2},
\end{aligned}
\]
and $\|\cdot \|_{\psi_1}$ is a norm, we can conclude that the standardized statistic $\Tilde{C}_{1,k} = \hat{C}_{1,k} - \Ex [\hat{C}_{1,k}]$ is also sub-exponential:
\[
\begin{aligned}
    \| \Tilde{C}_{1,k} \|_{\psi_1}&\leq  \| \hat{C}_{1,k} \|_{\psi_1} + \| \Ex [\hat{C}_{1,k}] \|_{\psi_1} \\
    &\leq M_q + \frac{|\Ex [\hat{C}_{1,k}|]}{\ln 2}\\
    &\overset{(a)}{=} M_q+ \frac{C_1+\theta}{\ln 2},
\end{aligned}
\]
where (a) is obtained by Assumption B.

Among different groups, the data are mutually independent, then we know that $\{\Tilde{C}_{1,k}\}_{k=1}^{n_1}$ are independent random variables with mean $0$.

Therefore, we can apply Bernstein inequality(\cite{HDP}):
\[
\bbP\left( \left| \frac{1}{n_1} \sum_{k=1}^{n_1} \Tilde{C}_{1,k} \right| > \Tilde{\epsilon}+\theta \right) \leq 2 \exp \left[-c \min\left(\frac{(\Tilde{\epsilon}+\theta)^2}{(M_g+C_1 / \ln 2)^2}, \frac{\Tilde{\epsilon}+\theta}{M_g+C_1 / \ln 2}\right)n_1\right], 
\]
where $c>0$ is an absolute constant.

Since we have $M_g+\frac{C_1+\theta}{\ln 2}>\Tilde{\epsilon}>\theta$, which implies $\frac{\Tilde{\epsilon}}{M_g+C_1 / \ln 2}<1$,   we can transform the inequality above into
\[
\begin{aligned}
    \bbP\left(\left|\hat{C}_1-C_1\right|>\Tilde{\epsilon}\right) &= \bbP\left( \left| \frac{1}{n_1} \sum_{k=1}^{n_1} \Tilde{C}_{1,k} \right| > \Tilde{\epsilon}-\theta \right) \\
    &\leq 2 \exp \left[-c  \frac{(\Tilde{\epsilon}-\theta)^2}{(M_g+(C_1+\theta) / \ln 2)^2}n_1\right] \\
    &\overset{(a)}{\leq} \delta,
\end{aligned}
\]
where (a) is obtained by $n_1\ge \frac{1}{c(\tilde{\epsilon}-\theta)^2}(M_g+\frac{C_1+\theta}{\ln 2})^2 \ln(\frac{2}{\delta})$.

\textbf{Second}, we can apply Theorem \ref{theorem:GEB} to the case when using $\hat{\pi}$ instead of $\pi$. Therefore, by the end of \textbf{Step 2} in the proof of Theorem \ref{theorem:GEB}, we will derive the following conclusion:

 For any $\delta \in (0, \frac{1}{3}), \epsilon \ge \sqrt{\frac{\ln{( \frac{\delta}{2})}}{2n}} \frac{2\hat{C}_1 M|\cD|}{\bbP(S = k^*)}$, if $n \ge \frac{8 \ln{(\frac{|\cD|}{\delta})}}{\min_k \bbP(S = k)}$, then 
\[
\bbP \bigr( |\hat{\cR}^{LDP}(f) - \cR(f)| > \epsilon \bigr) \le 2\delta.
\]

\textbf{Third}, Assume the events 
\[
\begin{aligned}
    &A_1=\left\{\left|\hat{C}_1- C_1\right|\le\Tilde{\epsilon}\right\},\\
    &A_2= \left\{ |\hat{\cR}^{LDP}(f) - \cR(f)| \le \epsilon,  \epsilon \ge \sqrt{\frac{\ln{ (\frac{\delta}{2})}}{2n}} \frac{2\hat{C}_1 M|\cD|}{\bbP(S = k^*)}, n \ge \frac{8 \ln{(\frac{|\cD|}{\delta})}}{\min_k \bbP(S = k)}\right\},\\
    &A_3= \left\{ |\hat{\cR}^{LDP}(f) - \cR(f)| \le \epsilon,  \epsilon \ge \sqrt{\frac{\ln{ (\frac{\delta}{2})}}{2n}} \frac{2(C_1+\Tilde{\epsilon}) M|\cD|}{\bbP(S = k^*)},n \ge \frac{8 \ln{(\frac{|\cD|}{\delta})}}{\min_k \bbP(S = k)}\right\},   
\end{aligned}
\]
then we have $A_1\cap A_2\subseteq A_3.$

From the \textbf{First} part and \textbf{Second} part of the proof, we have $\bbP(A_1^C)\leq\delta,\bbP(A_2^C)\leq 2\delta$, then
\[
\bbP(A_3) \geq \bbP(A_1\cap A_2) \geq 1-\bbP(A_1^C)-\bbP(A_2^C) \geq 1-3\delta,
\]
which is equivalent to the following statement:
For any $\delta \in (0, \frac{1}{3}), \epsilon \ge \sqrt{\frac{\ln{( \frac{\delta}{2})}}{2n}} \frac{(2(C_1+\Tilde{\epsilon}) M|\cD|}{\bbP(S = k^*)}$, if $n \ge \frac{8 \ln{(\frac{|\cD|}{\delta})}}{\min_k \bbP(S = k)}$, then 
\[
\bbP \bigr( |\hat{\cR}^{LDP}(f) - \cR(f)| > \epsilon \bigr) \le 3\delta.
\]

\textbf{Finally}, similar to \textbf{Step 3} in the proof of Theorem \ref{theorem:GEB}, recall that one can easily show
\[
\hat{\cR}^{LDP}(f) - \cR(f^*) \le 2 \ \underset{f \in \cF}{\sup} \bigr| \cR^{LDP}(f) - \hat{\cR}^{LDP}(f) \bigr|,
\]
but we have already established similar results for one single hypothesis in \textbf{Step 2}. Therefore, what remains is to extend the previous result that bounds the generalization error between any single hypothesis and the optimal hypothesis in the entire hypothesis class. And this can be done easily by introducing the VC-dimension of the hypothesis $\cF$. Denote the VC-dimension of our hypothesis class $\cF$ as $VC(\cF)$, then with some constant $K$ and for any $\delta \in (0, \frac{1}{3})$, if $n \ge \frac{8 \ln{(\frac{|\cD|}{\delta})}}{\min_k \bbP(S = k)}$, then with probability $1 - 3\delta$ we have:
\[
\hat{\cR}^{LDP}(f) \le \cR(f^*) + K\sqrt{\frac{VC(\cF) + \ln{( \frac{\delta}{2})}}{2n}} \frac{2(C_1+\Tilde{\epsilon}) M|\cD|}{\bbP(S = k^*)}.
\]

This completes the proof.
\end{proof}


