\section{Appendix: Proof Proposition 1}
Let the pmf of $X$ be given by
\begin{equation}
f(x;\theta)=h(x)\exp\{x ~ a(\theta)-b(\theta)\}.\label{pmfx}
\end{equation}
Denoting the derivative of $a(\theta)$ w.r.t. $\theta$ by $a'(\theta)$, and similarly for $b(\theta)$, it follows readily that
\begin{equation}
E(X)=\frac{b'(\theta)}{a'(\theta)}.\label{EX}
\end{equation}
Now, consider $Y_j=U+X_j$ for $j=1,...,m$, where the random variables $U,X_1,...,X_m$ are simultaneously independent, all having density $f(x;\theta_j)$ as in (\ref{pmfx}), where $j=0$ corresponds to $U$. 

Say that we have observations $(y_{11},...,y_{1m}),\ldots,(y_{n1},,...,y_{nm})$.
Letting $z_i=\min(y_{i1},...,y_{im})$, from (\ref{pmfx}), the likelihood is
\begin{align}
L(\theta_0,\theta_1,...,\theta_m)
&=\prod_{i=1}^n\left[\sum_{u_i=0}^{z_i} 
f(u_i;\theta_0)f(y_{i1}-u_i;\theta_1)\ldots f(y_{im}-u_i;\theta_m)
\right]\notag\\
&=\prod_{i=1}^n\left[\sum_{u_i=0}^{z_i} 
h(u_i)h(y_{i1}-u_i)\ldots h(y_{im}-u_i)
\cdot\exp\left\{-\sum_{j=0}^m b(\theta_j)\right\}\right.\notag\\
&\left.
\times\exp\left\{u_ia(\theta_0)+\sum_{j=1}^m (y_{ij}-u_i)a(\theta_j)\right\}
\right]\notag\\
&=\exp\left\{-n\sum_{j=0}^m b(\theta_j)\right\}
\sum_{u_1=0}^{z_1}\ldots\sum_{u_n=0}^{z_n}
\left\{\prod_{i=1}^n h(u_i)\right\}\exp\left\{\sum_{i=1}^nu_i a(\theta_0)\right\}\notag\\
&\times g_1(\theta_1) \ldots g_m(\theta_m),\label{likp1}
\end{align}
where for $j=1,...,m$,
\begin{align}
g_j(\theta_k)&=\left\{\prod_{i=1}^n h(y_{ij}-u_i)\right\}
\exp\left\{\sum_{i=1}^n(y_{ij}-u_i)a(\theta_j)\right\}\notag\\
&=C_j\exp\left\{\left(n\bar y_j-\sum_{i=1}^n u_i\right)a(\theta_j)\right\},
\label{gj}
\end{align}
with
$$C_j=\prod_{i=1}^nh(y_{ij}-u_i).$$
Now, suppressing the arguments of the likelihood function in (\ref{likp1}), its first derivative w.r.t. $\theta_1$ may be expressed as
\begin{align*}
\frac{\partial L}{\partial\theta_1}&=-nb'(\theta_1)L
+\exp\left\{-n\sum_{j=0}^m b(\theta_j)\right\}\sum_{u_1=0}^{z_1}\ldots\sum_{u_n=0}^{z_n}
\left\{\prod_{i=1}^n h(u_i)\right\}\\
&\times\exp\left\{\sum_{i=1}^nu_i a(\theta_0)\right\}
 g_1'(\theta_1)g_2(\theta_2)\ldots g_m(\theta_m),
\end{align*}
where via (\ref{gj}),
$$g_1'(\theta_1)=\left(n\bar y_1-\sum_{i=1}^n u_i\right)a'(\theta_1)
g_1(\theta_1),$$
so that
\begin{equation}
\frac{\partial L}{\partial\theta_1}=\left\{-b'(\theta_1)+\bar y_1a'(\theta_1)\right\}nL-a'(\theta_1)\exp\left\{-n\sum_{j=0}^m b(\theta_j)\right\}\sum_{i=1}^n A_i,\label{likder}
\end{equation}
where e.g.
\begin{align}
A_n&=\sum_{u_1=0}^{z_1}\ldots\sum_{u_{n-1}=0}^{z_{n-1}}
\left\{\prod_{i=1}^{n-1} h(u_i)\right\}
\exp\left\{\sum_{i=1}^{n-1}u_i a(\theta_0)\right\}\notag\\
&\times\sum_{u_n=0}^{z_n}h(u_n)u_n\exp\left\{u_na(\theta_0)\right\}
g_1(\theta_1)\ldots g_m(\theta_m).\label{An}
\end{align}
Now, because
$$\frac{\partial}{\partial\theta_0}\exp\left\{u_na(\theta_0)\right\}
=a'(\theta_0)\exp\left\{u_na(\theta_0)\right\},$$
(\ref{An}) and (\ref{likp1}) yield
\begin{align*}
\sum_{i=1}^n A_i
&=\frac{1}{a'(\theta_0)}\frac{\partial}{\partial\theta_0}
\sum_{u_1=0}^{z_1}\ldots\sum_{u_n=0}^{z_n}\left\{\prod_{i=1}^n h(u_i)\right\}\exp\left\{\sum_{i=1}^n u_ia(\theta_0)\right\}
g_1(\theta_1)\ldots g_m(\theta_m)\\
&=\frac{1}{a'(\theta_0)}\frac{\partial}{\partial\theta_0}
\left[\exp\left\{n\sum_{j=0}^m b(\theta_j)\right\}L\right]\\
&=\frac{1}{a'(\theta_0)}\exp\left\{n\sum_{j=0}^m b(\theta_j)\right\}
\left\{b'(\theta_0)nL+\frac{\partial L}{\partial\theta_0}\right\},
\end{align*}
so that by (\ref{likder}),
\begin{equation}
\frac{\partial L}{\partial\theta_1}=\left\{-b'(\theta_1)+\bar y_1a'(\theta_1)\right\}nL-\frac{a'(\theta_1)}{a'(\theta_0)}
\left\{b'(\theta_0)nL+\frac{\partial L}{\partial\theta_0}\right\}.\label{likder1}
\end{equation}
Hence, because $\partial L/(\partial\theta_0)=0$ for the MLE $\theta_0=\hat\theta_0$, (\ref{likder1}) yields
$$\left.\frac{\partial L}{\partial\theta_1}\right|_{\theta_0=\hat\theta_0}
=\left\{-\frac{b'(\theta_1)}{a'(\theta_1)}+\bar y_1-\frac{b'(\theta_0)}{a'(\theta_0)}\right\}a'(\theta_1)nL,$$
i.e. from (\ref{EX}) and $Y_1=U+X_1$,
$$\left.\frac{\partial L}{\partial\theta_1}\right|_{\theta_0=\hat\theta_0}
=\left\{-E(X_1)+\bar y_1-E(U)\right\}a'(\theta_1)nL=\left\{\bar y_1-E(Y_1)\right\}a'(\theta_1)nL,$$
which, since $a(\theta_1)$ is not constant, is zero only if $E(Y_1)=\bar y_1$, as was to be shown. The proof that at the MLEs, $E(Y_j)=\bar y_j$ for any $j>1$, is similar.


