\begin{lemma}\cite{Huo-Ren-Xu}\label{Cauchy-formula-lemma-2}
Let     $\Omega$ be a domain in $M$ with smooth boundary $\partial \Omega$. If  $ \phi  \in C^1(\Omega,  M) \cap C(\overline{\Omega},  M)$ and $f\in C^1(U, \mathbb{A}) \cap C(\overline{\Omega},\mathbb{A})$, then
 $$\int_{\partial \Omega}   \phi    (n f)dS= \int_{\Omega} \Big((\phi \overline{\partial}_{\mathcal{B}}  )f + \phi (\overline{\partial}_{\mathcal{B}} f)
  - \sum_{s=0}^{m} [v_s, \overline{\partial}_{\mathcal{B}} \phi_s, f]\Big)dV,
$$
and
 $$\int_{\partial \Omega}  ( \phi n )fdS= \int_{\Omega} \Big((\phi \overline{\partial}_{\mathcal{B}}  )f + \phi (\overline{\partial}_{\mathcal{B}} f)
  - \sum_{t=0}^{d} [v_t, \overline{\partial}_{\mathcal{B}} f_t,\phi ]\Big)dV,
$$
where  $\nu=(\nu_1, \ldots, \nu_n):\partial \Omega\rightarrow \R^{(m+1)n}=M^{n}$ is the unit exterior normal to $\partial \Omega$, $dS$ and  $dV$ stand  for  the   classical   Lebesgue surface  element and volume element  in $\mathbb{R}^{m+1}$, respectively.
\end{lemma}
\begin{proof}
Let $\phi=\sum_{s=0}^{m}\phi_sv_s \in C^1(\Omega, M) \cap C(\overline{\Omega},  M)$ and $f=\sum_{t=0}^{d}f_tv_t \in C^1(\Omega,  \mathbb{A}) \cap C(\overline{\Omega},  \mathbb{A})$.
By the divergence theorem, we have for all real-valued functions $\phi_{s}, f_t\in C^1(\Omega) \cap C(\overline{\Omega})$
$$\int_{\partial \Omega}   \phi_{s}f_t   n_{k} dS
=\int_{\Omega}(   (\partial_{_k}\phi_{s} )f_t + \phi_{s} (\partial_{k}f_t) ) dV,\quad k=0,1,\ldots,m. $$
By multiplying $v_k, k=0,1,\ldots,m,$  on both sides of the above formula, respectively, and  taking summation, we obtain
$$\int_{\partial \Omega}   \phi_{s}f_t  n dS =
\int_{ \Omega} ( (\overline{\partial}_{\mathcal{B}}  \phi_{s} )f_t+ \phi_{s} (\overline{\partial}_{\mathcal{B}}  f_t) )dV.$$
Then, by multiplying  $v_s, s=0,1,\ldots,m,$  from the left side,  we have
$$\int_{\partial \Omega}   \phi     n f_{t}dS =
\int_{\Omega}  ( (  \phi \overline{\partial}_{\mathcal{B}} )f_t  + \phi  (\overline{\partial}_{\mathcal{B}}  f_t ) )dV.$$
Hence, by multiplying $v_t, t=0,1,\ldots,d,$ from the right side and taking the sum,
$$\int_{ \partial \Omega}   ( \phi    n )fdS
=\int_{ \Omega} \Big(( \phi\overline{\partial}_{\mathcal{B}}  )f
+ \sum_{t=0}^{d} ( \phi (\overline{\partial}_{\mathcal{B}} f_t) )  v_t \Big) dV,$$
which gives
\begin{eqnarray*}
  \int_{\partial \Omega} (  \phi n ) fdS
&=& \int_{ \Omega}\Big( (\phi \overline{\partial}_{\mathcal{B}}  )f  + \phi (\overline{\partial}_{\mathcal{B}} f) +
\sum_{t=0}^{d} [\phi,  \overline{\partial}_{\mathcal{B}} f_t , v_t]\Big)dV
\\
&=&\int_{ \Omega}\Big( (\phi \overline{\partial}_{\mathcal{B}}  )f  + \phi (\overline{\partial}_{\mathcal{B}} f) -
\sum_{t=0}^{d} [ v_t,  \overline{\partial}_{\mathcal{B}} f_t ,\phi]\Big)dV,
 \end{eqnarray*}
as desired.
 \end{proof}



