\begin{lemma}\label{Bochner Martinel Holder continuous}
Let $ \alpha\in (0,1)$. If $f\in \Lambda^{\alpha}(\Gamma)$, then $\Phi\in \Lambda^{\alpha}(\Gamma)$.
\end{lemma}
\begin{proof}
Let $x $ and $x'$ be two points in $\Gamma$ with $|x -x'|=\delta$, where  $\delta$ is small enough. Consider the ball $B(x,2\delta)$ and  $\Gamma_{\delta}=\Gamma\cap B(x, 2\delta)$. Now    $\Phi(x)-\Phi(x')$ can be decomposed into two integrals  over $\sigma_{\delta}$ and  $\Gamma\setminus\sigma_{\delta}$, i.e.
\begin{eqnarray*}
\Phi(x)-\Phi(x')=I_1+I_2,
\end{eqnarray*}
where
\begin{eqnarray*}
I_1(x,x')
=
\int_{\Gamma_{\delta}}K (x,y)\ast (f(y)-f(x))- \int_{ \Gamma_{\delta}}K(x',y)\ast (f(y)-f(x')),
\\
I_1(x,x')
=
\int_{\Gamma\setminus \Gamma_{\delta}} K (x,y)\ast (f(y)-f(x))- \int_{\Gamma\setminus \Gamma_{\delta}}K(x',y)\ast (f(y)-f(x')).
\end{eqnarray*}
To  estimate the integral   $I_1$, we  note that $|y-x|\leq 2 \delta$   for all $y\in \Gamma_{\delta}$, then
$$ \Big|\int_{\Gamma_{\delta}}K (x,y)\ast (f(y)-f(x))\Big|\leq C \int_{\Gamma_{\delta}}|y-x|^{\alpha+1-n(m+1)}dS(y)
  \leq C \delta^{\alpha},$$
and $|y-x'|\leq 3 \delta$  for all $y\in \Gamma_{\delta}$,
$$ \Big|\int_{\Gamma_{\delta}}K (x',y)\ast (f(y)-f(x'))\Big|\leq C \int_{\Gamma_{\delta}}|y-x'|^{\alpha+1-n(m+1)}dS(y)
  \leq C \delta^{\alpha}.$$
Let us estimate the integral   $I_2$:
\begin{eqnarray}\label{eq: I_2 decompoes}
\begin{split}
I_2=&\int_{\Gamma\setminus \Gamma_{\delta}}  (K (x,y)-K (x',y))\ast (f(y)-f(x))
\\
&+\int_{\Gamma\setminus \Gamma_{\delta}}K (x',y) \ast  (f(x')-f(x)).
