\section{Full problem definitions}\label{app:problems}
\begin{definition}
    \textsc{Disjointness}: $ \{0, 1\}^n \times \{0, 1\}^n \rightarrow \{0, 1\}$ is the problem of finding if two sets represented as bitstrings are disjoint, with \textsc{Disjointness}$(x, y) = \bigwedge_{i \in [n]} \lnot (x_i \land y_i)$. We encode a \textsc{Disjointness} instance $(x,y)$ with the string $x| y$ over $\Sigma = \{0, 1, |\}$.
\end{definition}

\begin{definition}
    \textsc{Equality}: ${0, 1}^n \times {0, 1}^n \rightarrow \{0, 1\}$ is the problem of finding if two bitstrings are equal, with \textsc{Equality}$(x, y) = 1[x = y]$. We encode an \textsc{Equality} instance $(x,y)$ with the string $x| y$ over $\Sigma = \{0, 1, |\}$.
\end{definition}

\begin{definition}
    \textsc{Index}: $\{0, 1\}^n \times [n] \rightarrow \{0, 1\}$ is the problem of identifying the bit at a given index into the input, with \textsc{Index}$(x, i) = x_i$. We encode an \textsc{Index} instance $(x,i)$ with the string $xi$ over $\Sigma = \{0, 1\}\cup [n]$.
\end{definition}

\begin{definition}
    \textsc{Reachability}: $([n] \times [n])^m \times [n] \times [n] \rightarrow \{0, 1\}$ is the problem of determining if there is path from $s$ to $t$ in a directed graph $G$ with $n$ nodes and $m$ edges. To encode the problem with perfect tokenization, let $\Sigma = [n]\times [n] \cup [n]$ where the token $(i, j) \in \Sigma$ represents edge $(i, j)$ and the integer tokens represent nodes. An instance of \textsc{Reachability} is specified by the edge list of $G$ in arbitrary order followed by the nodes $s$ and $t$. 
\end{definition}


\begin{definition}
    \textsc{Majority}: $\{0, 1\}^n \rightarrow \{0, 1\}$ is the problem of determining whether the input has strictly more ones than zeros, with \textsc{Majority}$(x) = 1\left[\sum_{i \in [n]}x_i > n / 2\right]$.
\end{definition}

\begin{definition}
    Given input $x \in \mathbb Z_m^n $, \textsc{Match3}$_n$ is the problem of determining whether there are some $i,j\in [n]$ such that $x_n + x_{i} + x_{j} \equiv 0$ (mod $m$). Additionally, \textsc{Match2}$_n$ is the problem of determining whether there is some $i \in [n]$ such that $x_n + x_i \equiv 0$ (mod $m$). We encode instances of these problems with the string $x$ over $\Sigma = \mathbb Z_m$.
\end{definition}

\begin{definition}
  \textsc{Unique}: $\Sigma^* \rightarrow \Sigma\cup \{\emptyset\}$ is the problem of identifying any unique token in the input. That is, \textsc{Unique}$(x_1\dots x_n) = x_i$ s.t.\ $\sum_{j = 1}^n1[x_j = x_i] = 1$, or $\emptyset$ if no such $x_i$ exists.
\end{definition}

\begin{definition}
    \textsc{SetDiff}: $\Sigma^* \times \Sigma^* \rightarrow \Sigma \cup \{\emptyset\}$ is the problem of identifying any token in the first part of the input that doesn't appear in the second part. That is, \textsc{SetDiff}$(c_1\dots c_n, d_1\dots d_m) = c_i$ for some $i \in [n]$ such that $c_i \ne d_j$ for all $j \in [m]$, or $\emptyset$ if no such element exists. We encode a \textsc{SetDiff} instance $(c, d) \in \Sigma^* \times \Sigma^*$ with the string $c|d$ over $\Sigma \cup \{|\}$.
\end{definition}

\section{Proofs}\label{app:proofs}

\begin{proof}[Proof of \Cref{thm:one-token}]
     For \textsc{Index} instances given as $s = xi$, the idea is simple: we set $g(s_{k+1}\dots s_n, k, s_j, j) = 1$ if and only if $j = s_n$. The suffix oracle returns whatever token is attended to---unless the index is in the suffix (i.e., $s_n \ge k+1$), in which case the suffix oracle immediately returns $s_j$. No output from $f$ is required.

    For a \textsc{Disjointness} instance encoded as $s = x|y$, the key is that we only need a single counterexample bit where $x_i = y_i = 1$ to conclude that $x$ and $y$ are not disjoint. If no such counterexample exists, then they are disjoint. We can construct a $(1,1)$-BAPO using this fact. The prefix oracle outputs $0$ (``no counterexample found'') if (a) the token $|$ is not in the prefix or (b) if the token $|$ is in the prefix and the starting bits of $y$ present in the prefix are disjoint with the corresponding bits of $x$. If there is a counterexample bit in $y$ visible in the prefix, the prefix oracle outputs 1. If the suffix oracle receives a 1 from $f$, it always outputs 0 indicating $x$ and $y$ are not disjoint. Meanwhile, the attention function attends to any prefix bits that would be a counterexample to the disjointness of $x$ and $y$; i.e., $g(s_{k+1}\dots s_n, k, s_i, i)= 1$ if and only if either (a) $|$ is not in the suffix and $i' = i+ (k + |s_{k+1}\dots s_n| - 1)/2 +1 \ge k+1$ (i.e., the token we need to compare to $s_i$ is in the suffix) and $s_{i'} = s_i=1$ or (b) $|$ is in the suffix and $s_{i'} = s_i =1$. If the attended token set $G$ is nonempty, then $x$ and $y$ are not disjoint and the suffix oracle outputs 0. If the attended token set is empty and $|$ is in the suffix, the suffix oracle can check the portion of $x$ present in the suffix against the corresponding bits of $y$. If no counterexample bits are found (by $f$, $g$, or $h$), then none exists and the suffix oracle outputs 1. 

    For \textsc{Equality}, the same idea applies: we only need one counterexample $x_i \ne y_i$ to conclude that $x \ne y$. The construction is precisely the same as for \textsc{Disjointness}, except we look for counterexamples where $x_i \ne y_i$ rather than $x_i = y_i = 1$.
\end{proof}



