\section{MQ-RBF-based RK methods}\label{sec2}
\noindent
Consider the initial value problem of the form
\begin{equation}\label{ivp}
u'(t)=f(t,u), \quad a\le t\le b,
\end{equation}
with initial condition
$$u(t_0)=u_0,$$
where we assume that $u(t) \in C^{\infty}[a, b]$ and $f(t, u)$ is a class of $C^\infty$ function. We divide the interval $[a, b]$ uniformly into subintervals $\{[t_i,t_{i+1}]\}_{i=1}^{N}$, where $t_i = a + ih, i = 0, 1, \ldots, N$, and $h = (b-a)/N$ is the size of the grid. 
We next derive the adaptive multiquadratic RBF based RK methods. Integrating \eqref{ivp} into the interval $[t_i,t_{i+1}]$, and applying the integral mean value theorem, we get
\begin{equation}\label{mvt}
u(t_{i+1})=u(t_i)+hf(t_i+\theta h, u(t_i+\theta h)), 
\end{equation}
where any value of $\theta \in [0,1]$ produces a numerical method.
When $\theta=0$, \eqref{mvt} yields
\begin{equation*}\label{euler}
u_{i+1}=u_i+hf(t_i, u_i),
\end{equation*}
which is the well known \textit{Euler} method.
When $\theta=1$, using \eqref{mvt} we obtain an implicit method as
\begin{equation}\label{th=1}
u_{i+1}=u_i+hf(t_{i+1}, u_{i+1}).
\end{equation}
Instead of using the classical \textit{Euler} method, as done in conventional RK methods to solve the problem explicitly, the idea is to approximate $u_{i+1}$ appearing on the right-hand side of \eqref{th=1} using the MQ-RBF \textit{Euler} method, i.e.,
\begin{equation}\label{rbfeu}
u_{i+1}=\left(1+\frac{\varepsilon_{2i}^2h^2}{2}\right)\left(u_i+hf(t_{i},u_i)\right).
\end{equation}
Applying \eqref{rbfeu} to \eqref{th=1}, we get
\begin{equation}
u_{i+1}=u_i+hf\left(t_{i+1}, \left(1+\frac{\varepsilon_{2i}^2h^2}{2}\right)u_i+h\left(1+\frac{\varepsilon_{2i}^2h^2}{2}\right)f(t_{i},u_i)\right).
\end{equation}
If we set 
\begin{align*}
K_1&=f(t_{i},u_i)\\
K_2&=f\left(t_{i+1}, \left(1+\frac{\varepsilon_{2i}^2h^2}{2}\right)u_i+h\left(1+\frac{\varepsilon_{2i}^2h^2}{2}\right)K_1\right)
\end{align*}
we get the method as 
\begin{equation}
u_{i+1}=u_i+hK_2.
\end{equation}
However, for $\theta=1/2$, \eqref{mvt} yields
\begin{equation}\label{th=1b2}
u_{i+1}=u_i+hf\left(t_{i}+\frac{h}{2}, u\left(t_{i}+\frac{h}{2}\right)\right).
\end{equation}
Note that $\left(t_{i}+\frac{h}{2}\right)$ is not a nodal point. Approximating $u\left(t_{i}+\frac{h}{2}\right)$ directly by the MQ-RBF \textit{Euler} method with spacing $h/2$, we get the method as
\begin{equation}
u_{i+1}=u_i+hf\left(t_{i}+\frac{h}{2}, \left(1+\frac{\varepsilon_{2i}^2h^2}{8}\right)u_i+\frac{h}{2}\left(1+\frac{\varepsilon_{2i}^2h^2}{8}\right)f(t_{i},u_i)\right).
\end{equation}
However, if we use the approximation
$$u'\left(t_i+\frac{h}{2}\right)\approx \frac{1}{2}\left(u'(t_i)+f(t_{i+1},u(t_j+h))\right),$$
with the MQ-RBF \textit{Euler} method, we get
$$f\left(t_{i}+\frac{h}{2}, u\left(t_{i}+\frac{h}{2}\right)\right)\approx \frac{1}{2}\left(f(t_i,u_i)+f\left(t_{i+1},\left(1+\frac{\varepsilon_{2i}^2h^2}{2}\right)\left(u_i+hf(t_{i},u_i)\right)\right)\right).$$
Thus, \eqref{th=1b2} can be approximated by
\begin{equation}
u_{i+1}=u_i+\frac{h}{2}\left(f(t_i,u_i)+f\left(t_{i+1},\left(1+\frac{\varepsilon_{2i}^2h^2}{2}\right)\left(u_i+hf(t_{i},u_i)\right)\right)\right),
\end{equation}
which can be written as 
\begin{equation}
u_{i+1}=u_i+\frac{h}{2}[K_1+K_2],
\end{equation}
where $K_1$ and $K_2$ is defined earlier.\\
When integrating \eqref{ivp} into the interval $[t_i,t_{i+1}]$, $f(t,u)$ can be considered as the slope of the solution curve that continuously varies over $[t_i,t_{i+1}]$. We may also interpret the methods in \eqref{th=1} and \eqref{th=1b2} as the cases when the slope of the solution curve in the interval $[t_i,t_{i+1}]$ is approximated by a single slope at the terminal point and midpoint, respectively. However, similar to RK methods,  the proposed method uses a weighted average of slopes over the given interval, rather than a single slope. Thus, we define the general MQ-RBF-based RK methods as
$$u_{i+1}=u_{i}+h[\text{weighted average of slopes over the given interval}].$$
Next, we derive explicit MQ-RBF-based RK methods with different stages. To determine the parameters involved, we expand $u_{i+1}$ and the function $f$ in powers of $h$, and optimize the value of the shape parameter $\varepsilon_i$, ensuring that the expansion matches the Taylor series of the exact solution up to a certain number of terms. This allows the proposed methods to achieve a higher order of convergence than conventional RK methods with the same number of stages.

\subsection{MQ-RBF-based RK2 method: Two-stage method of third-order accuracy}\label{MR1}
\noindent
Consider the following explicit MQ-RBF-based RK method with two slopes
\begin{align}\label{2me1}
\nonumber   K_1&=f(t_{i},\textbf{u}_i),\\
\nonumber   K_2&=f\left(t_{i}+c_2 h, \left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(\textbf{u}_i+ha_{21}K_1\right)\right),\\
\textbf{u}_{i+1}&=\textbf{u}_i+h[w_1K_1+w_2K_2],
\end{align}
where the parameters $c_2$, $a_{21}$, $w_1$ and $w_2$ selected to ensure that $\textbf{u}_{i+1}$ provides a close approximation to $\textbf{u}(t_{i+1})$.\\
The above two-stage method can be rewritten as the following iterative scheme:
\begin{equation}\label{2me2}
\begin{cases}
	\textbf{u}^{(1)}=\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\textbf{u}_i+a_{21}h\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)f_i,\\
	\textbf{u}_{i+1}=\left[1-\frac{w_1}{a_{21}}\right]\textbf{u}_i+\frac{w_1}{a_{21}}\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)^{-1}\textbf{u}^{(1)}+w_2 h f(t_i+c_2h,\textbf{u}^{(1)}).
\end{cases}
\end{equation}
Let $u_i$ be the exact solution of the given initial value problem (IVP). Then, using the Taylor series expansion about $t_i$, the local truncation error can be obtained as
\begin{eqnarray}\label{e1}
\nonumber  \tau_i&=&\frac{\textbf{u}_{i+1}-\textbf{u}_{i}}{h}-(w_1K_1+w_2K_2)\\
\nonumber   &=&(1-w_1-w_2)f+h\left[\left(\frac{1}{2}-w_2c_2\right)f_t+\left(\frac{1}{2}-w_2a_{21}\right)f_uf\right]+h^2\bigg[\left(\frac{1}{6}-\frac{w_2c_2^2}{2}\right)f_{tt}\\
&&+\left(\frac{1}{3}-w_2c_2a_{21}\right)f_{tu}f+\left(\frac{1}{6}-\frac{w_2a_{21}^2}{2}\right)f^2f_{uu}+\left(\frac{f_t+ff_u}{6}-\frac{w_2c_{2}^2\varepsilon_{2i}^2}{2}u_i\right)f_u\bigg]+\mathcal{O}(h^3).
\end{eqnarray}
Consider 
\begin{equation}\label{p1}
a_{21}=c_2, \quad w_1=1-\frac{1}{2c_2} \quad \text{and} \quad w_2=\frac{1}{2c_2}, \quad c_2\ne 0.
\end{equation}
With these conditions on parameters and $\varepsilon_{2i}=0$, it is evident that the proposed scheme \eqref{2me2} reduces to the conventional RK2 method with second-order convergence.\\
Together with \eqref{p1}, if we further impose the condition
\begin{equation}\label{p2}
3w_2a_{21}^2=1,
\end{equation}
the parameters are then uniquely determined as
$$a_{21}=c_2=\frac{2}{3}, \quad w_1=\frac{1}{4} \quad \text{and} \quad w_2=\frac{3}{4},$$
causing the first three terms in the coefficient of $h^2$ to vanish. If we set $\varepsilon_{2i}^2=0$, then \eqref{2me2} reduces to \textit{Ralston}'s method, a second-order method with minimal local error represented by the remaining term. However, setting the remaining terms in the coefficient of $h^2$ to zero allows us to optimize $\varepsilon_{2i}$ as
\begin{equation}
\varepsilon_{2i}^2=\frac{f_t+ff_u}{u_i}=\frac{u_i''}{{u_i}},
\end{equation}
thereby elevating the scheme \eqref{2me2} to third-order accuracy.

\subsection{MQ-RBF-based RK3 method: Three-stage method of fourth-order accuracy}\label{MR2}
\noindent
We now use three evaluations of $f$ and define the MQ-RBF-based RK3 method as
\begin{equation}\label{3me1}
\textbf{u}_{i+1}=\textbf{u}_i+h[w_1K_1+w_2K_2+w_3K_3],
\end{equation}
with
\begin{align*}
K_1&=f(t_{i},\textbf{u}_i),\\
K_2&=f\left(t_{i}+c_2 h, \left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(\textbf{u}_i+ha_{21}K_1\right)\right),\\
K_3&=f\left(t_{i}+c_3 h, \left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)\big(\textbf{u}_i+h(a_{31}K_1+a_{32}K_2)\big)\right).
\end{align*}
The alternative form of the above scheme is
\begin{equation}\label{3me2}
\begin{cases}
	\textbf{u}^{(1)}=\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)u_i+a_{21}h\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)f_i,\\
	\textbf{u}^{(2)}=\left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)\left[\left(1-\frac{a_{31}}{a_{21}}\right)\textbf{u}_i+\frac{a_{31}}{a_{21}}\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)^{-1}\textbf{u}^{(1)}+a_{32}hf\left(t_i+c_2h,\textbf{u}^{(1)}\right)\right],\\
	\textbf{u}_{i+1}=\left[1-\frac{w_1}{a_{21}}-\frac{w_2}{a_{32}}\left(1-\frac{a_{31}}{a_{21}}\right)\right]\textbf{u}_i+\left[\frac{w_1}{a_{21}}-\frac{a_{31}w_2}{a_{32}a_{21}}\right]\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)^{-1}\textbf{u}^{(1)}\\
	\quad \quad \quad  +\frac{w_2}{a_{32}}\left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)^{-1}\textbf{u}^{(2)}+w_3h f(t_i+c_3h,\textbf{u}^{(2)}).
\end{cases}
\end{equation}
By expanding $K_2$ and $K_3$ in the Taylor series about $t_i$ and substituting into \eqref{3me1}, and applying two conditions from the RK3 method given as
\begin{equation}\label{pv31}
a_{21}=c_2 \quad \text{and} \quad  a_{31}+a_{32}=c_3,
\end{equation}
the local truncation error can be simplified as
\begin{eqnarray}\label{e3}
\nonumber  \tau_i&=&\frac{\textbf{u}_{i+1}-\textbf{u}_{i}}{h}-(w_1K_1+w_2K_2+w_3K_3)\\
\nonumber   &=&(1-w_1-w_2-w_3)f+h\left[\left(\frac{1}{2}-w_2c_2-w_3c_3\right)(f_t+f_uf)\right]+h^2\bigg[\left(\frac{1}{6}-\frac{w_2c_2^2+w_3c_3^2}{2}\right)(f_{tt}+f^2f_{uu})\\
\nonumber  &&+\left(\frac{1}{3}-w_2c_2^2-w_3c_3^2\right)f_{tu}f+\left(\frac{1}{6}-\frac{a_{32}c_2w_3}{2}\right)(f_tf_u+f_u^2f)-\left(\frac{w_2c_{2}^2\varepsilon_{2i}^2+w_3c_{3}^2\varepsilon_{3i}^2}{2}\right)f_uu_i\bigg]\\
\nonumber&&+h^3\bigg[\left(\frac{1}{24}-\frac{w_2c_2^3+w_3c_3^3}{6}\right)(f_{ttt}+f_{uuu}f^3)+\left(\frac{1}{8}-a_{32}c_2c_3w_3\right)(f_tf_{tu}+f_tf_{uu}f)+\left(\frac{1}{24}-\frac{a_{32}c_2^2w_3}{2}\right)f_{tt}f_u\\
\nonumber &&\left(\frac{5}{24}-a_{32}c_2(c_2+c_3)w_3\right)f_{tu}f_uf+\left(\frac{1}{8}-\frac{w_2c_2^3+w_3c_3^3}{2}\right)(f_{ttu}f+f_{t uu}f^2)+\left(\frac{1}{6}-\frac{a_{32}c_2^2w_3}{2}-a_{32}c_2c_3w_3\right)f_{uu}f_uf^2\\
&&+\left(\frac{f_t+f_uf}{24}-\frac{a_{32}c_2^2w_3}{2}\varepsilon_{2i}^2u_i\right)f_u^2-\left(\frac{w_2c_2^3\varepsilon_{2i}^2+w_3c_3^3\varepsilon_{3i}^2}{2}\right)\left(u_i(f_{uu}f+f_{tu}) { +f_uf}\right) \bigg]+\mathcal{O}(h^4).
\end{eqnarray}
Clearly, applying the conditions
\begin{equation}\label{pv32}
w_1+w_2+w_3=1, \quad  2(w_2c_2+w_3c_3 )=1, \quad 3(w_2c_2^2+w_3c_3^2 )=1 \quad \text{and} \quad 6a_{32}c_2w_3=1,
\end{equation}
along with
\begin{equation}\label{pv33}
w_2c_2^2\varepsilon_{2i}^2+w_3c_3^2\varepsilon_{3i}^2=0,
\end{equation}
eliminates the constant term, $h$ term and $h^2$ term in the local truncation error \eqref{e3}, ensuring that the scheme is of order 3. Furthermore, if $\varepsilon_{2i}=\varepsilon_{3i}=0$, we recover the classical RK3 method. However, to achieve fourth-order accuracy, we need to optimize the shape parameters. For this, two additional conditions are required, which are specified in the following four distinct cases:
\begin{description}
\item[B1] $w_2c_2^3+w_3c_3^3=\frac{1}{4} \quad \text{and} \quad a_{32}c_2^2w_3=\frac{1}{12}$.\\
In this case the parameters are uniquely determined as
$$a_{21}=c_{2}=\frac{1}{2}, \quad a_{31}=-1, \quad a_{32}=2, \quad c_3=1, \quad w_1=\frac{1}{6}, \quad w_2=\frac{2}{3} \quad \text{and} \quad w_3=\frac{1}{6}.$$
In addition to the constant, $h$ and $h^2$ terms, these parameter values eliminate the coefficients of $f_{ttt}, \ f_{uuu}f^3, \ f_{tt}f_u$, $f_{ttu}f$ and $f_{t uu}f^2 $ in the $h^3$ term of \eqref{e3}. Now, by setting the remaining $h^3$ terms to zero, and using condition \eqref{pv32}, we obtain
$$\varepsilon_{2i}^2=\frac{{ (f_{uu}f-f_u^2+f_{tu})}u_i''}{{ (f_{uu}f-f_u^2+f_{tu})}u_i+{ f_uf}} \quad \text{and} \quad \varepsilon_{3i}^2=-\varepsilon_{2i}^2,$$
thereby making the proposed method fourth-order accurate. Note that this is only possible when the function $f$ satisfies condition $(f_{uu}f-f_u^2+f_{tu})u+f_uf\ne 0$ whenever $(f_{uu}f-f_u^2+f_{tu})(f_t+f_u f)\ne0$, otherwise the method exhibits only third-order accuracy.

\item[B2] $w_2c_2^3+w_3c_3^3=\frac{1}{4} \quad \text{and} \quad a_{32}c_2(c_2+c_3)w_3=\frac{5}{24}$.\\
For this case, we have two sets of solutions which are discussed below.
\begin{description}
	\item[(a)]  $a_{21}=c_{2}=\frac{5}{8}+\frac{\sqrt{33}}{24}, \quad a_{31}=-\frac{49}{256}+\frac{29\sqrt{33}}{768}, \quad a_{32}=\frac{209}{256}-\frac{61\sqrt{33}}{768}, \quad c_3=\frac{5}{8}-\frac{\sqrt{33}}{24}, \quad w_1=\frac{1}{8}, \quad w_2=\frac{7}{16}-\frac{3\sqrt{33}}{176} \quad \text{and} \quad w_3=\frac{7}{16}+\frac{3\sqrt{33}}{176}$. 
	These specific values eliminate the  $f_{ttt}, \ f_{uuu}f^3, \ f_{tu}f_uf, \ f_{ttu}f$ and $f_{tuu}f^2 $ terms from the coefficients of $h^3$ in \eqref{e3}.
	To eliminate the remaining  leading error term of $\mathcal{O}(h^3)$ we require 
	$$\varepsilon_{2i}^2=\dfrac{12f_u^2u_i''+(3+\sqrt{33})(f^2f_{uu}-f_{tt})f_u+2(3+\sqrt{33})(f_{uu}f+f_{tu})f_t}{\left[2(3+\sqrt{33})(f f_{uu}+f_{tu})+(15+\sqrt{33})f_u^2\right]u_i{ +2(3+\sqrt{33})f_uf}} \ \ \text{and} \ \ \varepsilon_{3i}^2=\frac{-7-\sqrt{33}}{4}\varepsilon_{2i}^2.$$

	\item[(b)]  $a_{21}=c_{2}=\frac{5}{8}-\frac{\sqrt{33}}{24}, \quad a_{31}=-\frac{49}{256}-\frac{29\sqrt{33}}{768}, \quad a_{32}=\frac{209}{256}+\frac{61\sqrt{33}}{768}, \quad c_3=\frac{5}{8}+\frac{\sqrt{33}}{24}, \quad w_1=\frac{1}{8}, \quad w_2=\frac{7}{16}+\frac{3\sqrt{33}}{176} \quad \text{and} \quad w_3=\frac{7}{16}-\frac{3\sqrt{33}}{176}$.
	Furthermore, by eliminating the leading error term of $\mathcal{O}(h^3)$ in \eqref{e3}, we get 
	$$\varepsilon_{2i}^2=\dfrac{12f_u^2u_i''+(3-\sqrt{33})(f_{uu}f^2-f_{tt})f_u+2(3-\sqrt{33})(f_{uu}f+f_{tu})f_t}{\left[2(3-\sqrt{33})(f f_{uu}+f_{tu})+(15-\sqrt{33})f_u^2\right]u_i{ +2(3-\sqrt{33})f_uf}} \ \ \text{and} \ \ \varepsilon_{3i}^2=\frac{-7+\sqrt{33}}{4}\varepsilon_{2i}^2.$$

\end{description}
\item[B3] $w_2c_2^3+w_3c_3^3=\frac{1}{4} \quad \text{and} \quad \frac{a_{32}c_2^2w_3}{2}+a_{32}c_2c_3w_3=\frac{1}{6}$.\\
These conditions eliminate the terms $f_{ttt}, \ f_{uuu}f^3, \  f_{ttu}f, \ f_{tuu}f^2$  and $f_{uu}f_uf^2$ from the coefficients of $h^3$ in \eqref{e3}, and provide two sets of parameter values.
\begin{description}
	\item[(a)] $a_{21}=c_{2}= 1, \quad a_{31}=\frac{1}{4}, \quad a_{32}=\frac{1}{4}, \quad c_3= \frac{1}{2}, \quad w_1=\frac{1}{6}, \quad w_2=\frac{1}{6}  \quad \text{and} \quad w_3= \frac{2}{3}$. 
	Further optimizing the shape function as
	$$\varepsilon_{2i}^2=\dfrac{f_u^2u_i''-(f_{tu}f+f_{tt})f_u+(f_{uu}f+f_{tu})f_t}{\left[f_{uu}f+f_{tu}+2f_u^2\right]u_i{ +f_uf}} \ \ \text{and} \ \ \varepsilon_{3i}^2=-\varepsilon_{2i}^2,$$
	We obtain the MQ-RBF-based RK3 method of fourth-order accuracy.
	\item[(b)] $a_{21}=c_{2}= \frac{1}{3}, \quad a_{31}=-\frac{5}{12}, \quad a_{32}=\frac{5}{4}, \quad c_3= \frac{5}{6}, \quad w_1=\frac{1}{10}, \quad w_2=\frac{1}{2}  \quad \text{and} \quad w_3= \frac{2}{5}$. We further optimize the shape parameters as 
	$$\varepsilon_{2i}^2=\dfrac{3f_u^2u_i''+(f_{tu}f+f_{tt})f_u-(f_{uu}f+f_{tu})f_t}{\left[-f_{uu}f-f_{tu}+2f_u^2\right]u_i{ -f_uf}} \ \ \text{and} \ \ \varepsilon_{3i}^2=-\frac{1}{5}\varepsilon_{2i}^2,$$
	to obtain the fourth-order MQ-RBF-based RK3 method.
\end{description}
\item[B4] $a_{32}c_2c_3w_3=\frac{1}{8} \quad \text{and} \quad a_{32}c_2^2w_3=\frac{1}{12}$.\\
These conditions provide unique values for parameters used as
$a_{21}=c_{2}= \frac{1}{2}, \quad a_{31}=0, \quad a_{32}=\frac{3}{4}, \quad c_3= \frac{3}{4}, \quad w_1=\frac{2}{9}, \quad w_2=\frac{1}{3}  \quad \text{and} \quad w_3= \frac{4}{9}$,
which annihilate the terms $f_{t}f_{tu}$, $f_{t}f_{uu}f$, $f_{tt}f_u$, $f_{tu}f_u f$ and $f_{uu}f_uf^2$ from the coefficient of $h^3$ in \eqref{e3}. We then equate the remaining terms in the coefficient of $h^3$ in \eqref{e3} to zero in order to obtain the shape functions as
$$\varepsilon_{2i}^2=\dfrac{12f_u^2u_i''+f_{ttt}+f_{uuu}f^3+3(f_{ttu}+f_{tuu}f)f}{3\left(-f_{uu}f-f_{tu}+4f_u^2\right)u_i{ -3f_uf}} \ \ \text{and} \ \ \varepsilon_{3i}^2=-\frac{1}{3}\varepsilon_{2i}^2.$$
Evidently, scheme \eqref{3me2} along with given parameters is of fourth-order accuracy.
\end{description}
\subsection{MQ-RBF-based RK4 method: Four-stage method of fifth-order accuracy} \label{MR3}
\noindent 
It is evident from the scheme presented in the preceding subsection that including a shape parameter at each stage can analytically enhance the order of the scheme by one. We apply the same technique to construct the four-stage MQ-RBF-based RK method as
\begin{equation}\label{4me1}
\textbf{u}_{i+1}=\textbf{u}_i+h[w_1K_1+w_2K_2+w_3K_3+w_4K_4],
\end{equation}
with
\begin{align*}
K_1&=f(t_{i},\textbf{u}_i),\\
K_2&=f\left(t_{i}+c_2 h, \left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(\textbf{u}_i+ha_{21}K_1\right)\right),\\
K_3&=f\left(t_{i}+c_3 h, \left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)\big(\textbf{u}_i+h(a_{31}K_1+a_{32}K_2)\big)\right)\\
K_4&=f\left(t_{i}+c_4 h, \left(1+\frac{\varepsilon_{4i}^2(c_{4}h)^2}{2}\right)\big(\textbf{u}_i+h(a_{41}K_1+a_{42}K_2+a_{43}K_3)\big)\right),
\end{align*}
which can alternatively be written as
\begin{equation}\label{4me2}
\begin{cases}
	\textbf{u}^{(1)}=\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\textbf{u}_i+a_{21}h\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)f_i,\\
	\textbf{u}^{(2)}=\left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)\left[\left(1-\frac{a_{31}}{a_{21}}\right)\textbf{u}_i+\frac{a_{31}}{a_{21}}\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)^{-1}\textbf{u}^{(1)}+a_{32}hf\left(t_i+c_2h,\textbf{u}^{(1)}\right)\right],\\
	\textbf{u}^{(3)}=\left(1+\frac{\varepsilon_{4i}^2(c_{4}h)^2}{2}\right)\Big[\left(1-\frac{a_{41}}{a_{21}}-\frac{a_{42}}{a_{32}}\left(1-\frac{a_{31}}{a_{21}}\right)\right)\textbf{u}_i+\left(\frac{a_{41}}{a_{21}}-\frac{a_{31}a_{42}}{a_{32}a_{21}}\right)\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)^{-1}\textbf{u}^{(1)}\\
	\quad \quad \quad+\frac{a_{42}}{a_{32}} \left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)^{-1}\textbf{u}^{(2)} +a_{43}hf\left(t_i+c_3h,\textbf{u}^{(2)}\right)\Big],\\
	\textbf{u}_{i+1}=\left[1-\frac{w_1}{a_{21}}-\frac{w_2}{a_{32}}\left(1-\frac{a_{31}}{a_{21}}\right)-\frac{w_3}{a_{43}}\left(1-\frac{a_{41}}{a_{21}}-\frac{a_{42}}{a_{32}}\left(1-\frac{a_{31}}{a_{21}}\right)\right)\right]\textbf{u}_i+\left[\frac{w_1}{a_{21}}-\frac{a_{31}w_2}{a_{32}a_{21}}-\frac{w_3}{a_{43}}\left(\frac{a_{41}}{a_{21}}-\frac{a_{31}a_{42}}{a_{32}a_{21}}\right)\right]\\
	\quad \quad \quad \left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)^{-1}\textbf{u}^{(1)} +\left[\frac{w_2}{a_{32}}-\frac{w_3a_{42}}{a_{43}a_{32}} \right]\left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)^{-1}\textbf{u}^{(2)}+\frac{w_3}{a_{43}}\left(1+\frac{\varepsilon_{4i}^2(c_{4}h)^2}{2}\right)^{-1}\textbf{u}^{(3)}\\
	\quad \quad \quad +w_4h f(t_i+c_4h,\textbf{u}^{(3)}).
\end{cases}
\end{equation}
Under the conditions
\begin{equation}\label{pv41}
a_{21}=c_2, \quad a_{31}+a_{32}=c_3, \quad a_{41}+a_{42}+a_{43}=c_4,
\end{equation}
the Taylor series expansion of \eqref{4me1} yields the local truncation error as
\begin{eqnarray}\label{e4}
\nonumber  \tau_i&=&\frac{\textbf{u}_{i+1}-\textbf{u}_{i}}{h}-(w_1K_1+w_2K_2+w_3K_3+w_4K_4)\\
\nonumber   &=&(1-w_1-w_2-w_3-w_4)f+h\left[\left(\frac{1}{2}-w_2c_2-w_3c_3-w_4c_4\right)(f_t+f_uf)\right]+h^2\bigg[\left(\frac{1}{6}-\frac{w_2c_2^2+w_3c_3^2+w_4c_4^2}{2}\right)\\ 
\nonumber  &&(f_{tt}+f^2f_{uu}+2f_{tu}f)
+\left(\frac{1}{6}-a_{32}c_2w_3+w_4(c_2a_{42}+c_3a_{43})\right)(f_tf_u+f_u^2f) -\left(\frac{w_2c_{2}^2\varepsilon_{2i}^2+w_3c_{3}^2\varepsilon_{3i}^2+w_4c_{4}^2\varepsilon_{4i}^2}{2}\right)f_uu_i\bigg]\\
\nonumber&&+h^3\bigg[\left(\frac{1}{24}-\frac{w_2c_2^3+w_3c_3^3+w_4c_4^3}{6}\right)(f_{ttt}+f_{uuu}f^3+3f_{ttu}f+3f_{t uu}f^2)\\
\nonumber &&+\left(\frac{1}{8}-a_{32}c_2c_3w_3-(a_{42}c_2+a_{43}c_3)c_4w_4\right)(f_tf_{tu}+f_tf_{uu}f)+\left(\frac{1}{24}-\frac{a_{32}c_2^2w_3+(a_{42}c_2^2+a_{43}c_3^2)w_4}{2}\right)f_{tt}f_u\\
\nonumber &&+\left(\frac{5}{24}-a_{32}c_2(c_2+c_3)w_3-a_{42}c_2(c_2+c_4)w_4-a_{43}c_3(c_3+c_4)w_4\right)f_{tu}f_uf\\
\nonumber&&+\left(\frac{1}{6}-a_{32}c_2\left(\frac{c_2}{2}+c_3\right)w_3-a_{42}c_2\left(\frac{c_2}{2}+c_4\right)w_4-a_{43}c_3\left(\frac{c_3}{2}+c_4\right)w_4\right)f_{uu}f_uf^2\\
\nonumber&&+\left(\left(\frac{1}{24}-a_{32}a_{43}c_2w_4\right)(f_t+ff_u)-\frac{(a_{32}w_3+a_{42}w_4)c_2^2\varepsilon_{2i}^2+a_{43}c_3^2w_4\varepsilon_{3i}^2}{2}u_i\right)f_u^2 \\
\nonumber&&-\left(\frac{w_2c_2^3\varepsilon_{2i}^2+w_3c_3^3\varepsilon_{3i}^2+w_4c_4^3\varepsilon_{4i}^2}{2}\right)\left(u_i(f_{uu}f+f_{tu}) { +f_uf}\right)\bigg]+h^4\bigg[\left(\frac{1}{120}-\frac{w_2c_2^4+w_3c_3^4+w_4c_4^4}{24}\right)(f_{tttt}+f_{uuuu}f^4\\
\nonumber&&+4f_{tttu}f+4f_{tuuu}f^3 +6f_{ttuu}f^2)+\left(\frac{1}{20}-\frac{a_{32}c_2c_3^2w_3+(a_{42}c_2+a_{43}c_3)c_4^2w_4}{2}\right)(f_{ttu}f_t+2f_{tuu}f_tf+f_{uuu}f_tf^2)\\
\nonumber&& +\left(\frac{1}{30}-\frac{a_{32}c_2^2c_3w_3+(a_{42}c_2^2+a_{43}c_3^2)c_4w_4}{2}\right)(f_{tt}f_{tu}f+2f_{tu}^2f+f_{tt}f_{uu}f+f_{uu}^2f^3+3f_{tu}f_{uu}f^2)\\
\nonumber&&+\left(\frac{1}{120}-\frac{a_{32}c_2^3w_3+(a_{42}c_2^3+a_{43}c_3^3)w_4}{6}\right)f_{ttt}f_u+\left(\frac{7}{120}-a_{43}a_{32}c_2(c_3+c_4)w_4\right)f_tf_{tu}f_u+\left(\frac{1}{120}-\frac{a_{32}a_{43}c_2^2w_4}{2}\right)f_{tt}f_u^2\\
\nonumber&&+\left(\frac{1}{40}-\frac{a_{32}^2c_2^2w_3+(a_{42}c_2+a_{43}c_3)^2w_4}{2}\right)f_{uu}f_{t}^2+\left(\frac{3}{40}-\frac{a_{32}c_2(c_2^2+c_3^2)w_3+a_{42}c_2(c_2^2+c_4^2)w_4+a_{43}c_3(c_3^2+c_4^2)w_4}{2}\right)\\
\nonumber&&f_{ttu}f_{u}f+\left(\frac{1}{8}-\frac{a_{32}c_2(c_2^2+2c_3^2)w_3+a_{42}c_2(c_2^2+2c_4^2)w_4+a_{43}c_3(c_3^2+2c_4^2)w_4}{2}\right)f_{tuu}f_uf^2 \\
\nonumber&&+\left(\frac{3}{40}-a_{32}a_{43}c_2(c_2+c_3+c_4)w_4\right)f_{tu}f_{u}^2f+\bigg(\frac{13}{120}-a_{32}^2c_2^2w_3-a_{32}a_{43}c_2(c_3+c_4)w_4-a_{42}a_{43}c_2c_3w_4-a_{42}^2c_2^2w_4\\
\nonumber&& -a_{43}^2c_3^2w_4\bigg)f_{uu}f_tf_uf+\bigg(\frac{11}{120}-\frac{a_{32}^2c_2^2w_3}{2}-\frac{2a_{32}a_{43}c_2(c_3+c_4)+2a_{42}a_{43}c_2c_3+a_{42}^2c_2^2 +a_{43}^2c_3^2+a_{32}a_{43}c_2^2}{2}w_4\bigg)f_{uu}f_u^2f^2\\
\nonumber&&+\left(\frac{7}{120}-\frac{a_{32}c_2(c_2^2+3c_3^2)w_3+(a_{42}c_2(c_2^2+3c_4^2)+a_{43}c_3(c_3^2+3c_4^2))w_4}{6}\right)f_{uuu}f_uf^3-\frac{(w_2c_2^4\varepsilon_{2i}^2+w_3c_3^4\varepsilon_{3i}^2+w_4c_4^4\varepsilon_{4i}^2)}{4}\\
\nonumber&& \left(\left(f_{ttu}+2f_{tuu}+f_{uuu}\right)u_{i} { +2(f_{uu}f^2+f_{tu}f)}\right){ -\frac{a_{32}w_3c_2^3\varepsilon_{2i}^2+w_4a_{42}c_2^3\varepsilon_{2i}^2+w_4a_{43}c_3^3\varepsilon_{3i}^2}{2}f_u^2f}\\
\nonumber &&-\frac{w_3a_{32}(c_2+c_3)c_2^2\varepsilon_{2i}^2+w_4a_{42}(c_2+c_4)c_2^2\varepsilon_{2i}^2+w_4a_{43}(c_3+c_4)c_3^2\varepsilon_{3i}^2}{2}\left(f_{tu}f_u+f_{uu}f_uf\right)u_i+\frac{a_{32}a_{43}c_2^2w_4\varepsilon_{2i}^2}{2}f_u^3u_i \\
\nonumber && -\frac{a_{32}c_2w_3c_3^2\varepsilon_{3i}^2+(a_{42}c_2+a_{43}c_3)w_4c_4^2\varepsilon_{4i}^2}{2}\left(\left(f_tf_{uu}+f_uf_{uu}f\right)u_i+{ f_u^2f+f_tf_u}\right)-\frac{(w_2c_2^4\varepsilon_{2i}^4+w_3c_3^4\varepsilon_{3i}^4+w_4c_4^4\varepsilon_{4i}^4)}{8}{ f_{uu}u_i^2}\\
&&+\frac{f_u^3u_i''}{120}\bigg]+\mathcal{O}(h^5).
\end{eqnarray}
If we impose the conditions 
\begin{eqnarray}\label{pv42}
\nonumber  & w_1+w_2+w_3+w_4=1, \quad   2(w_2c_2+w_3c_3+w_4c_4)=1, \quad 3(w_2c_2^2+w_3c_3^2+w_4c_4^2)=1, \quad 4(w_2c_2^3+w_3c_3^3+w_3c_4^3)=1\\
\nonumber &6(a_{32}w_3c_2+a_{42}w_4c_2+a_{43}w_4c_3)=1, \quad 8(a_{32}w_3c_2c_3+a_{42}w_4c_2c_4+a_{43}w_4c_3c_4)=1, \quad 12(a_{32}w_3c_2^2+a_{42}w_4c_2^2+a_{43}w_4c_3^2)=1,\\
&24a_{32}a_{43}w_4c_2=1,
\end{eqnarray}
along with 
\begin{eqnarray}\label{pc43}
\nonumber &w_2c_2^2\varepsilon_{2i}^2+w_3c_3^2\varepsilon_{3i}^2+w_4c_4^2\varepsilon_{4i}^2=0, \quad w_2c_2^3\varepsilon_{2i}^2+w_3c_3^3\varepsilon_{3i}^2+w_4c_4^3\varepsilon_{4i}^2=0, \quad a_{32}w_3c_2^2\varepsilon_{2i}^2+a_{42}w_4c_2^2\varepsilon_{2i}^2+a_{43}w_4c_3^2\varepsilon_{3i}^2=0, \\
\end{eqnarray}
then all the constant, $h$, $h^2$, and $h^3$ terms in $\tau_n$ vanish, indicating that our scheme, namely the MQ-RBF-based RK4 method, is fourth-order accurate. However, to achieve fifth-order accuracy, the $h^4$ terms must also vanish. To this end, we propose two possible values for the shape parameters.
\begin{description}
\item[C1] Consider $a_{32}c_2c_3^2w_3+(a_{42}c_2+a_{43}c_3)c_4^2w_4=\frac{1}{10}$ and $a_{32}c_2^2c_3w_3+(a_{42}c_2^2+a_{43}c_3^2)c_4w_4=\frac{1}{15}$, so that we obtain
\begin{eqnarray*}
	&a_{21}=c_2=\frac{2}{5}, \quad a_{31}=-\frac{3}{20}, \quad a_{32}=\frac{3}{4}, \quad a_{41}=\frac{19}{44},\quad a_{42}=-\frac{15}{44}, \quad a_{43}=\frac{10}{11}, \quad c_{3}=\frac{3}{5}, \quad c_{4}=1,\\
	&w_{1}=w_4=\frac{11}{72}, \quad w_{2}=w_3=\frac{25}{72}.
\end{eqnarray*}
Now, using \eqref{pc43} and equating the leading error term in $\mathcal{O}(h^4)$ to zero, we get
$$ \varepsilon_{3i}^2=-\frac{2}{3}\varepsilon_{2i}^2, \quad \varepsilon_{4i}^2=\frac{2}{11}\varepsilon_{2i}^2,$$
where $\varepsilon_{2i}^2$ is a real valued solution of the equation $\alpha x^2+\beta x+\gamma=0 $, with 
\begin{eqnarray*}
	\alpha&=&168 f_{uu}u_i^2\\
	\beta&=& (  66f_{ttu}+66f_{uuu} f^2+ 132f_{tuu}f- 462f_{tu}f_u- 270f_{uu}f_t-732f_{uu}f_uf+ 330f_u^3)u_i\\
	&& { + 132f^2f_{uu}-402f_u^2f+132f_{tu}f-270f_tf_u}\\
	\gamma&=&11(f_{tttt}+f_{uuuu}f^4+4 f_{tttu}f+4f_{tuuu}f^3+6f_{ttuu}f^2)- 44 (f_{ttt}f_u+3f_{ttu}f_u f+3f_u f_{tuu} f^2+f_u  f_{uuu}f^3)\\
	&&+ 330 f_t f_{tu} f_u +330 f_{tu} f_u^2f+ 135 f_t^2  f_{uu}+600 f_t  f_uf_{uu}f +465f_u^2  f_{uu}f^2-330 f_u^3u_i''. 
\end{eqnarray*}
\item[C2] Consider $a_{32}c_2c_3^2w_3+(a_{42}c_2+a_{43}c_3)c_4^2w_4=\frac{1}{10}$ and $a_{32}^2c_2^2w_3+(a_{42}c_2+a_{43}c_3)^2w_4=\frac{1}{20}$, so that we obtain
\begin{eqnarray*}
	&a_{21}=c_2=\frac{1}{4}, \quad a_{31}=-\frac{6}{25}, \quad a_{32}=\frac{21}{25}, \quad a_{41}=\frac{6}{5},\quad a_{42}=-\frac{57}{35}, \quad a_{43}=\frac{10}{7}, \quad c_{3}=\frac{3}{5}, \quad c_{4}=1,\\
	&w_{1}=\frac{1}{9}, \quad w_{2}=\frac{16}{63}, \quad w_{3}=\frac{125}{252}, \quad w_{4}=\frac{5}{36}.
\end{eqnarray*}
Now, using \eqref{pc43} and equating the leading error term in $\mathcal{O}(h^4)$ to zero, we get
$$\varepsilon_{3i}^2=-\frac{\varepsilon_{2i}^2}{6}, \ \ \text{and}\ \ \varepsilon_{4i}^2=\frac{\varepsilon_{2i}^2}{10},$$
where $\varepsilon_{2i}^2$ is a real valued solution of the equation $\alpha x^2+\beta x+\gamma=0 $, 
with 
\begin{eqnarray*}
	\alpha&=&3f_{uu}u_i^2\\
	\beta&=&6 (f_{ttu}+f^2f_{uuu}+2f_{tuu}f-7f_{tu}f_u-7f_{uu}f_uf+5f_u^3)u_i {  +12(f_{uu}f^2-f_u^2f+f_{tu}f)}\\
	\gamma&=&f_{tttt}+ 4 f_{tttu}f+ 6 f_{ttuu}f^2+ 4 f_{tuuu}f^3+f_{uuuu}f^4 - 4(f_{ttt}+ 3 f_{ttu} f+3 f_{tuu} f^2+ f_{uuu}f^3)f_u\\
	&&+ 18f_{tt} f_{tu} +18f_{tt} f_{uu}f + 18 f_{uu}^2f^3+36 f_{tu}^2f+ 54f_{tu} f_{uu}f^2 + 30f_{uu}f_u^2 f^2 + 48 f_{uu} f_t f_u f + 48 f_{tu}f_t f_u   \\
	&& + 12 f_{tu} f_u^2f - 18f_{tt} f_u^2 - 48f_u^3u_i''
\end{eqnarray*}
\end{description}
It is important to note that in both cases described above, the resulting quadratic equations may not yield real roots. In such situations, eliminating the $h^4$ term in \eqref{e4} is not always feasible. Nevertheless, the MQ-RBF-based RK4 method \eqref{3me1} still achieves fourth-order accuracy.
