\section{Convergence of MQ-RBF-based RK methods}\label{sec3}%of MQ-RBF--RK methods}
%\subsection{MQ-RBF-based RK2 method}
\noindent
To analyze the convergence of the MQ-RBF-based RK methods proposed in Section~\ref{sec2}, we study the behavior of the difference between the exact solution of IVP \eqref{ivp} and the corresponding numerical solution. To guarantee the unique existence of an exact solution to \eqref{ivp}, we assume that $f(t, u)$ is Lipschitz continuous with a Lipschitz constant $L$ throughout this section. Suppose that the interval $[a,b]$ is partitioned into $N$ equal subintervals, resulting in a uniform grid of $N+1$ nodes, i.e., 
$$a=t_0<t_1<\cdots<t_N=b,$$
where for each $n=0,1,\ldots,N$, the grid nodes are defined as $t_n=a+nh$, with $h=(b-a)/N$. 
Let $u_i = u(t_i)$ denote the exact solution at time $t_i$, and let $\textbf{u}_i$ denote its numerical approximation obtained using the MQ-RBF-based RK methods. Then we have the following results:
\begin{theorem}\label{th1}
Consider that $\varepsilon_{2i}^2$ is bounded for all $i=0,1,\ldots,N-1$. Then the MQ-RBF-based RK2 method \eqref{2me1}, satisfying \eqref{p1}, converges.
\end{theorem}
\textit{Proof.} Let $E_{i+1}:=|u_{i+1}-\textbf{u}_{i+1}|$. For a fixed $t=t_i$, \eqref{2me1} yields
\begin{eqnarray*}
K_1(v)&=&f(t_{i},v),\\
K_2(v)&=&f\left(t_{i}+c_2 h, \left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(v+ha_{21}K_1(v)\right)\right).
\end{eqnarray*}
It is clear that the exact solution of \eqref{ivp} satisfies
\begin{equation}\label{2con1}
u_{i+1}=u_i+h(w_1K_1(u_i)+w_2K_2(u_i))+h\tau_i,
\end{equation}
where $\tau_i$ is the local truncation error defined in \eqref{e1}. Moreover, due to the Lipschitz continuity of $f(t,u)$ with respect to $u$, it follows that
$$|K_1(u_i)-K_1(\textbf{u}_i)|=|f(t_i,u_i)-f(t_i,\textbf{u}_i)|\le L|u_i-\textbf{u}_i|,$$ and
\begin{eqnarray*}
\Big|K_2(u_i)-K_2(\textbf{u}_i)|&=&|f\left(t_{i}+c_2 h, \left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(u_i+ha_{21}K_1\right)\right)-f\left(t_{i}+c_2 h, \left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(\textbf{u}_i+ha_{21}K_1\right)\right)\Big|\\
&\le& L\Big|\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(u_i+ha_{21}K_1(u_i)\right)-\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(\textbf{u}_i+ha_{21}K_1(\textbf{u}_i)\right)\Big|\\
&\le& L\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\Big(|u_i-\textbf{u}_i|+ha_{21}|K_1(u_i)-K_1(\textbf{u}_i)|\Big)\\
&\le& L(1+ha_{21}L)\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)|u_i-\textbf{u}_i|.
\end{eqnarray*}
Now, subtracting \eqref{2con1} from \eqref{2me1}, we obtain
\begin{eqnarray}\label{ec1}
\nonumber   E_{i+1}&=&|u_i-\textbf{u}_i+hw_1(K_1(u_i)-K_1(\textbf{u}_i))+hw_2(K_2(u_i)-K_2(\textbf{u}_i))+h\tau_i|\\
&\le&\varphi_iE_i+h|\tau_i|,
\end{eqnarray}
where $\varphi_i=1+(w_1+w_2)hL+w_2a_{21}h^2L^2+\left(w_2hL+w_2a_{21}h^2L^2\right)\frac{c_2^2h^2\varepsilon_{2i}^2}{2}$, and $E_i=|u_i-\textbf{u}_i|$. Let 
$$\mathcal{C}_2=\displaystyle \max_{i=0,\ldots,N-1}\left(\sup_{0< h\le b-a}\frac{\left(2w_2L+hL^2\right)c_2^2h^2\varepsilon_{2i}^2}{4e^{hL}}\right).$$
Since $\varepsilon_i$ is bounded for all $i=0,1, \ldots, N-1$, we have $\mathcal{C}_2<\infty$. Thus, we have
\begin{eqnarray*}
\varphi_i&=&1+hL+\frac{1}{2}h^2L^2+\left(w_2hL+\frac{1}{2}h^2L^2\right)\frac{c_2^2h^2\varepsilon_{2i}^2}{2}\\
&\le&\left(1+\mathcal{C}_2 \right)e^{hL}\\
&\le&e^{(L+\mathcal{C}_2)h}.
\end{eqnarray*}
and consequently, by induction, \eqref{ec1} yields
\begin{equation}
E_i\le \left(e^{(L+\mathcal{C}_2)h}\right)^{i-1}\varphi_kE_0+h\sum_{k=1}^{i-1}\left(e^{(L+\mathcal{C}_2)h}\right)^{i-k}|\tau_{k-1}|+h|\tau_{i-1}|.
\end{equation}
Assuming $E_0=0$, we obtain
\begin{equation*}
E_i\le ihe^{(L+\mathcal{C}_2)ih}\|\tau\|_{\infty}\le (b-a)e^{(L+\mathcal{C}_2)(b-a)}\|\tau\|_{\infty},
\end{equation*}
for all $i=0,1,\ldots N-1$, where $\|\tau\|_{\infty}=\displaystyle \max_{0,\ldots,N-1}|\tau_i|$.
Therefore, for $h=(b-a)/N$, we have
$$\lim_{h\to 0}E_i=0.$$
This implies that $\textbf{u}_N\to u_N=u(b)$ as $h$ tends to zero. Hence, the MQ-RBF-based RK2 method \eqref{2me1} converges. 
%\subsection{MQ-RBF-based RK3 method}
\begin{theorem}
Consider that $\varepsilon_{2i}^2$ and $\varepsilon_{3i}^2$ are bounded for all $i=0,1,\ldots,N-1$. Then the MQ-RBF-based RK3 method \eqref{3me1}, satisfying \eqref{pv31} and \eqref{pv32}, is convergent.
\end{theorem}
\textit{Proof.} By the definition of local truncation error, from \eqref{e3} we can write
\begin{equation}\label{3con1}
u_{i+1}=u_i+h(w_1K_1(u_i)+w_2K_2(u_i)+w_3K_3(u_i))+h\tau_i.
\end{equation}
Let us fix $t=t_i$ and define
\begin{align*}
K_1(v)&=f(t_{i},v),\\
K_2(v)&=f\left(t_{i}+c_2 h, \left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(v+ha_{21}K_1(v)\right)\right),\\
K_3(v)&=f\left(t_{i}+c_3 h, \left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)\big(v+h(a_{31}K_1(v)+a_{32}K_2(v))\big)\right),
\end{align*}
accordingly. Then, invoking the Lipschitz continuity of $f(t,u)$ with respect to $u$, we can estimate
\begin{eqnarray*}
|K_1(u_i)-K_1(\textbf{u}_i)|&\le& L|u_i-\textbf{u}_i|,\\
|K_2(u_i)-K_2(\textbf{u}_i)| &\le& L(1+ha_{21}L)\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)|u_i-\textbf{u}_i|,
\end{eqnarray*}
and
\begin{eqnarray*}
|K_3(u_i)-K_3(\textbf{u}_i)|&\le& L\left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)\left(1+h(a_{31}+a_{32})L+a_{21}a_{32}h^2L^2+(1+hLa_{21})a_{32}hL\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)|u_i-\textbf{u}_i|.
\end{eqnarray*}
Thus, subtracting \eqref{3con1} from \eqref{3me1} implies
$$E_{i+1}\le\varphi_iE_i+h|\tau_i|,$$
where $E_i=|u_i-\textbf{u}_i|$ and
\begin{eqnarray*}
\varphi_i&=&1+h(w_1+w_2+w_3)L+(w_2a_{21}+w_3(a_{31}+a_{32}))h^2L^2+h^3L^3w_3a_{21}a_{32}+hL(w_2+(a_{21}w_2+a_{32}w_3)hL\\
&&+a_{21}a_{32}w_3h^2L^2)\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}   +hw_3L(1+hL(a_{31}+a_{32})+h^2L^2a_{21}a_{32})\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2} \\ &&+h^2L^2(1+hLa_{21})a_{32}w_3\frac{\varepsilon_{2i}^2(c_{2}h)^2\varepsilon_{3i}^2(c_{3}h)^2}{4}.
\end{eqnarray*}
Let $$\mathcal{C}_3=\max_{i=0,\ldots,N-1}\left(\sup_{0<h\le(b-a)}\frac{2Lc_{2}^2h^2\mathcal{C}_{31}\varepsilon_{2i}^2+ 2Lc_{3}^2h^2\mathcal{C}_{32}\varepsilon_{3i}^2 +L^2h^5c_{2}^2c_{3}^2\mathcal{C}_{33}\varepsilon_{2i}^2\varepsilon_{3i}^2}{4e^{hL}}\right),$$
where
$\mathcal{C}_{31}=w_2+(c_{2}w_2+a_{32}w_3)hL+\frac{1}{6}h^2L^2$, $\mathcal{C}_{32}=1+hLw_3c_{3}+\frac{1}{6}h^2L^2$ and $\mathcal{C}_{33}=a_{32}w_3+\frac{1}{6}hL$. Since $\varepsilon_{2i}^2$ and $\varepsilon_{2i}^2$ are bounded for all $i=0,1,\ldots,N-1$, it follows that $\mathcal{C}_3<\infty$. Consequently, we have
\begin{eqnarray*}
\varphi_i &=&1+hL+\frac{1}{2}h^2L^2+\frac{1}{6}h^3L^3+hL\left(w_2+(c_{2}w_2+a_{32}w_3)hL+\frac{1}{6}h^2L^2\right)\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}   \\ &&
+hL\left(1+hLw_3c_{3}+\frac{1}{6}h^2L^2\right)\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2} +h^2L^2\left(a_{32}w_3+\frac{1}{6}hL\right)\frac{\varepsilon_{2i}^2(c_{2}h)^2\varepsilon_{3i}^2(c_{3}h)^2}{4}\\
&\le&(1+\mathcal{C}_3h)e^{hL}\\
&\le&e^{(L+\mathcal{C}_3)h}.
\end{eqnarray*}
Thus, by arguments similar to those in Theorem \ref{th1}, we can show that $\textbf{u}_N\to u_N=u(b)$ as $h$ tends to zero, i.e., the MQ-RBF-based RK$3$ method \eqref{3me1} is convergent.
\begin{theorem}
Assume that $\varepsilon_{2i}^2$, $\varepsilon_{3i}^2$ and $\varepsilon_{4i}^2$ are bounded for all $i=0,1,\ldots,N-1$. Then the MQ-RBF-based RK$4$ method \eqref{4me1}, satisfying \eqref{pv41} and \eqref{pv42}, is convergent.
\end{theorem}
\textit{Proof.} For $t=t_i$, let us define
\begin{align*}
K_1(v)&=f(t_{i},v),\\
K_2(v)&=f\left(t_{i}+c_2 h, \left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)\left(v+ha_{21}K_1(v)\right)\right),\\
K_3(v)&=f\left(t_{i}+c_3 h, \left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)\big(v+h(a_{31}K_1(v)+a_{32}K_2(v))\big)\right)\\
K_4(v)&=f\left(t_{i}+c_4 h, \left(1+\frac{\varepsilon_{4i}^2(c_{4}h)^2}{2}\right)\big(v+h(a_{41}K_1(v)+a_{42}K_2(v)+a_{43}K_3(v))\big)\right),
\end{align*}
so that, using \eqref{e4}, we can write the exact solution of \eqref{ivp} as
\begin{equation}\label{4con1}
u_{i+1}=u_i+h(w_1K_1(u_i)+w_2K_2(u_i)+w_3K_3(u_i)+w_4K_4(u_i))+h\tau_i.
\end{equation}
Moreover, it follows from the Lipschitz continuity of $f(t,u)$ with respect to $u$ that
\begin{eqnarray*}
|K_1(u_i)-K_1(\textbf{u}_i)|&\le& L|u_i-\textbf{u}_i|,\\
|K_2(u_i)-K_2(\textbf{u}_i)| &\le& L(1+ha_{21}L)\left(1+\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)|u_i-\textbf{u}_i|,\\
|K_3u(_i)-K_3(\textbf{u}_i)|&\le&L\left(1+\frac{\varepsilon_{3i}^2(c_{3}h)^2}{2}\right)\left(1+h(a_{31}+a_{32})L+a_{21}a_{32}h^2L^2+(1+hLa_{21})a_{32}hL\frac{\varepsilon_{2i}^2(c_{2}h)^2}{2}\right)|u_i-\textbf{u}_i|,
\end{eqnarray*}
and
\begin{eqnarray*}
|K_4(u_i)-K_4(\textbf{u}_i)|&\leq & L \left(\frac{1+\varepsilon_{4i}^{2}(c_{4}h)^2}{2}\right) \left[ 1+hL\left( a_{41}+a_{42}\left(\frac{1+\varepsilon_{2i}^{2}(c_{2}h)^2}{2}\right)+a_{43}\left(\frac{1+\varepsilon_{3i}^{2}(c_{3}h)^2}{2}\right) \right) \right.\\
&&+ h^{2}L^{2} \left( a_{42}a_{21}\left(\frac{1+\varepsilon_{2i}^{2}(c_{2}h)^2}{2}\right)+\left(\frac{1+\varepsilon_{3i}^{2}(c_{3}h)^2}{2}\right) \left( a_{43}a_{31}+a_{43}a_{32}\left(\frac{1+\varepsilon_{2i}^{2}(c_{2}h)^2}{2}\right)\right) \right) \\
&&\left.+h^{3}L^{3} \left( \left(\frac{1+\varepsilon_{3i}^{2}(c_{3}h)^2}{2}\right) 
\left( a_{43}a_{21}a_{31}+a_{43}a_{21}a_{32} \frac{\varepsilon_{2i}^{2}(c_{2}h)^{2}}{2} \right) \right) \right]|u_{i}-\textbf{u}_{i}|.
\end{eqnarray*}
Using \eqref{4con1} and \eqref{4me1} and employing the above inequalities, we can obtain
$$E_{i+1}=\varphi_iE_i+h|\tau_{i}|,$$
where $E_i=|u_i-\textbf{u}_i|$ and
$ \varphi_i\le 1+hL+\frac{1}{2}h^2L^2+\frac{1}{6}h^3L^3+\frac{1}{24}h^4L^4+\mathcal{C}_4he^{hL}\le e^{(L+\mathcal{C}_4)h},$
where, $$\mathcal{C}_4=\max_{i=0,\ldots,N-1}\left(\sup_{0<h\le(b-a)}\frac{4\mathcal{C}_{41}\varepsilon_{2i}^2+4\mathcal{C}_{42}\varepsilon_{3i}^2+4\mathcal{C}_{43}\varepsilon_{4i}^2+2\mathcal{C}_{44}\varepsilon_{2i}^2\varepsilon_{3i}^2+2\mathcal{C}_{45}\varepsilon_{2i}^2\varepsilon_{4i}^2+2\mathcal{C}_{46}\varepsilon_{3i}^2\varepsilon_{4i}^2+\mathcal{C}_{47}\varepsilon_{2i}^2\varepsilon_{3i}^2\varepsilon_{4i}^2}{8}\right),$$
with
\begin{eqnarray*}
\mathcal{C}_{41}&=&h^2Lc_2^2\left(w_2+(c_{2}w_2+a_{32}w_3+a_{42}w_4)hL+c_{2}(a_{32}w_3+a_{42}w_4)h^2L^2+\frac{1}{24}h^3L^3\right),\\    \mathcal{C}_{42}&=&h^2Lc_3^2(w_3+hL(w_3c_3+w_4a_{43})+h^2L^2(w_3c_{2}a_{32}+w_4a_{31}a_{43})+h^3L^3w_4a_{43}c_{2}a_{31}), \\ 
\mathcal{C}_{43}&=&h^2Lc_4^2(w_4+hLw_4c_4+h^2L^2w_4(c_{2}a_{42}+a_{43}c_3)+h^3L^3w_4a_{43}c_{2}a_{31}),\\
\mathcal{C}_{44}&=&h^3L^2c_2^2c_3^2(1+hLc_{2})a_{32}(w_3+w_4a_{43}),\\
\mathcal{C}_{45}&=&h^5L^2c_2^2c_4^2w_4a_{42}(1+c_{2}hL),\\
\mathcal{C}_{46}&=&h^5L^2c_3^2c_4^2w_4a_{43}(1+hLa_{31}),\\
\mathcal{C}_{47}&=&h^7L^2c_2^2c_3^2c_4^2w_4a_{43}a_{32}(1+hLc_{2}),
\end{eqnarray*}
is bounded under conditions \eqref{pv41}, \eqref{pv42} and boundedness of $\varepsilon_{2i}^2$, $\varepsilon_{3i}^2$ and $\varepsilon_{4i}^2$.
Therefore, $\textbf{u}_N \to u_N = u(b)$ as $h$ tends to zero. This implies that the MQ-RBF-based RK4 method converges. The proof is complete.
