\section{Basic definitions and properties}
\label{sec: tools}
%
Throughout this article, we denote by $X$ a metrizable locally compact connected topological space and by
%we denote by 
$F$ a continuous-time flow on $X$, namely a continuous map $F:\bR\times X\to X$ such that $F^t(F^s(x))=F^{t+s}(x)$ for all $t,s\in\bR$ and $F^0(x)=x$.
%We denote by $\NW_F$ the non-wandering relation of $F$ and by $NW_F$ the set of its non-wandering points.
In this section we go over some general property and tools relative to flows.
%
\begin{definition}
    \label{def: Prol rel}
    Given a point $p\in X$, the {\bf backward orbit}, {\bf forward orbit} and {\bf orbit} of $p$ under $F$ are the sets
    $$
    \cO^-_F(p) = \{F^t(p):t\leq0\},
    $$
    $$
    \cO^+_F(p) = \{F^t(p):t\geq0\},
    $$
    $$
    \cO_F(p) = \cO^-_F(p)\cup\cO^+_F(p).
    $$
    We call {\bf orbit space} of $F$ the binary relation
    $$
    \cO_F = \{(p,q):q\in\cO^+_F(p)\}.
    $$
%    \blue
%    and {\bf forward orbits space} of $F$ the binary relation
%    $$
%    \cO^+_F = \{(p,q):q\in\cO^+_F(p)\}.
%    $$
%    $$\cO^+_F(p) = \{F^t(p):t\geq0\};$$
%    the {\bf backward orbit} of $p$ is the set
%    $$\cO^-_F(p) = \{F^t(p):t\leq0\};$$
%    the {\bf full orbit} of $p$ is the set
%    $$\cO_F(p) = \cO^-(p)\cup\cO^+(p).$$
    We call {\bf prolongational relation}~\cite{AG97} of $F$, denoted by {\BF$\NW_F$}, the topological closure of $\cO_F$ in $X\times X$ endowed with the product topology.
    If $(x,y)\in\NW_F$, we write {\BF $x\NWto y$} and we set
    $$\text{\BF$\Down_{\NW_F}(p)$}=\{q:p\NWto q\}\subset X.$$
    Sometimes we write that {\BF $q$ is prolongationally downstream from $p$} to say that $p\NWto q$.
\end{definition}
%
From now on, we will denote by $d$ a distance on $X$ compatible with its topology.
All results in the remainder of the article will not depend on the particular choice of $d$. 
The reader can verify that $p\NWto q$ if and only if, for every $\eps>0$, there is a $x$ and $t>0$ such that $d(x,p)<\eps$ and $d(F^t(x),q)<\eps$.
%
\begin{example}
    \label{ex: circle}
    Given $x,y\in\Bbb S^1$ with $x\neq y$, denote by $\overset{\frown}{xy}$ the closed arc that is the closure of all points $z$ such that $x,z,y$ are in clockwise order.
    Consider the flow $F$ on $\Bbb S^1$ which us three fixed points, in clockwise order, $p,q,r$ and where every other point moves clockwise.
    Then $x\NWto y$ if and only if either $\overset{\frown}{xy}\subset\overset{\frown}{pq}$ or $\overset{\frown}{xy}\subset\overset{\frown}{qr}$ or $\overset{\frown}{xy}\subset\overset{\frown}{rp}$.
    For instance, $p\NWto q$ because one can jump from $p$ to a point $x$ arbitrarily close to $p$ and use the flow to get arbitrarily close to $q$.
    %, $q\NWto r$ and $r\NWto p$ but $p\not\NWto r$.
    Let now $G$ be an extension of $F$ to the unit disc $D$ so that every point of $D$, except for the center of the disc, moves in a spiral that asymptotes to the unit circle.
    In this case, $x\NWGto y$ for any $x,y\in\Bbb S^1$ because from any $x$ on the unit circle one can jump to a spiral arbitrarily close to $x$ and then use the flow to move on the spiral arbitrarily close to any other point $y$ on the unit circle.
\end{example}
%
%%%%%%%%
\noindent
%{\BF Some properties of $\NW_F$.}
%We collect here some basic property of the prolongational relation. %from~\cite{DLY24}.
%
%
\begin{definition}
    We call {\BF$\omega$-limit set} of $p$ the set
    $$
    \text{\BF$\omega_F(p)$}=\{q:\text{there is }t_n\to\infty\text{ s.t. }F^{t_n}(p)\to q\}.
    $$
    Analogously, we call {\BF$\alpha$-limit set} of $p$ the set
    $$
    \text{\BF$\alpha_F(p)$}=\{q:\text{there is }t_n\to-\infty\text{ s.t. }F^{t_n}(p)\to q\}.
    $$
\end{definition}
%
The following two results illustrate some important relation between the prolongation relation and limit sets.
