\begin{proposition}[De Leo and Yorke~\cite{DLY24}]
    \label{prop:Down}
    For every flow $F$, $\NW_F$ is invariant under the induced action of $F$ on $X\times X$ given by $F^t(x,y)=(F^t(x),F^t(y))$.
    Moreover, for every $p$, the following holds:
    \begin{enumerate}
        \item $\Down_{\NW_F}(p)$ is forward-invariant under $F$;
        \item $\Down_{\NW_F}(p)
        \;\supset\; 
        \cO^+_F(p)\cup\omega_F(p)$;
        \item if $\omega_F(p)\neq\emptyset$, 
        $\cO^+_F(p)\cup\Down_{\NW_F}(\omega_F(p))
        \supset
        \Down_{\NW_F}(p)$;
        \item 
        $\Down_{\NW_F}(p)\;=\;\cO^+_F(p)\cup\Down_{\NW_F}(q)$ for all $q\in\cO^+_F(p)$.
    \end{enumerate}
\end{proposition}
