\begin{definition}
    \label{def: L^2}
    The {\bf second prolongational limit set} of $p$ under $F$ is the set {\BF $\Lambda^2_F(p)$} of all points $q$ for which there are sequences $p_n,q_n\in X$ and $k_n\in\bN$ such that:
    \begin{enumerate}
        \item $p_n\to p$;
        \item $q_n\to q$;
        \item $q_n\in\Lambda^{1,k_n}_F(p_n)$.
    \end{enumerate}
    %
    We define inductively the prolongational limit set of any given ordinal number $\alpha$ in the following way.
    Suppose that {$\Lambda^\beta_F(p)$} is defined for all $\beta<\alpha$ and let us use the notations $\Lambda^\beta_F(A)=\cup_{x\in A}\Lambda^\beta_F(x)$ and
    $$
    \Lambda^{\beta,k}_F(p)=\overbrace{\Lambda^\beta_F(\dots(\Lambda^\beta_F}^{k}(p))\dots),\;k=1,2,...\;.
    $$
    Then, if $\alpha$ is a successor ordinal, the {\BF $\alpha$-th prolongational limit set} of $p$ under $F$ is the set {\BF $\Lambda^\alpha_F(p)$} 
    of all points $q$ for which there are sequences $p_n,q_n\in X$, $k_n\in\bN$ such that:
    %
    \begin{enumerate}
        \item $p_n\to p$;
        \item $q_n\to q$;
        \item $q_n\in\Lambda^{\alpha-1,k_n}_F(p_n)$.
    \end{enumerate}
    If $\alpha$ is a limit ordinal, the {\BF $\alpha$-th prolongational limit set} of $p$ under $F$ is the set {\BF $\Lambda^\alpha_F(p)$} 
    of all points $q$ for which there are sequences $p_n,q_n\in X$, $k_n\in\bN$ and ordinals $\beta_n<\alpha$ such that:
    \begin{enumerate}
        \item $p_n\to p$;
        \item $q_n\to q$;
        \item $q_n\in\Lambda^{\beta_n,k_n}_F(p_n)$.
    \end{enumerate}
    The {\BF second and $\alpha$-th prolongations} of $p$ under $F$ are defined analogously by replacing $\Lambda$ with $D$.
