\begin{definition} 
    We say that $p$ is a {\bf non-wandering point} for $F$ if $p\in\Lambda^1_F(p)$.
    We denote by {\BF $NW_F$} the set of all non-wandering points of $F$.
\end{definition}
%
%
\begin{proposition}
    \label{prop: oa}
    For every $p\in X$, $\omega_F(p)\cup\alpha_F(p)\subset NW_F$.
\end{proposition}
%
\begin{proof}
    Let $q\in\omega_F(p)$.
    Then there is a sequence $t_n\to\infty$ such that $F^{t_n}(p)\to q$.
    Hence, for every $\eps>0$ there is a $k>0$ such that $d(q,F^{t_k}(p))<\eps$ and, for every $T>0$, there is a $k'>k$ such that $t_{k'}\geq T$ and $d(q,F^{t_{k'}}(p))<\eps$.
    In other words, for every $\eps>0$ and $T>0$ there is an $(\eps,T)$-link from $q$ to itself, namely $q\in\Lambda^1_F(q)$, i.e. $q\in NW$.
%    and so there are sequences $s_n>0$ and $r_n\to\infty$ with $F^{s_n}(p)\to q$ and $F^{r_n}(F^{s_n}(p))\to q$, so $q\in NW_F$.
    The same argument shows that $\alpha_F(p)\subset NW_F$.
\end{proof}
%
\begin{proposition}
    \label{prop: OL}
    For every $p\in X$, $\cO^+_F(p)\cap\Lambda^1_F(p)\subset NW_F$.
\end{proposition}
%
\begin{proof}
    Let $q\in\cO^+_F(p)\cap\Lambda^1_F(p)$.
    Then:
    \begin{enumerate}
        \item since $q\in\cO^+_F(p)$, there is $t_0\geq0$ such that $q=F^{t_0}(p)$;
        \item since $q\in\Lambda^1_F(p)$, for every $\eta>0$ there is a $z$ within $\eta$ from $p$ and a $t>0$ such that $d(q,F^t(z))<\eta$ and $t\to\infty$ as $\eta\to0$;
        \item by the continuity of $F^{t_0}$, for every $\eps>0$ there is $\eta>0$ such that $d(z,p)<\eta$ implies $d(F^{t_0}z,q)<\eps$.
    \end{enumerate}
    %   
    We claim that $q\in NW_F$.
    Indeed, let $\eps>0$, choose $\eta>0$ as in (3) above (if $\eta>\eps$, set $\eta=\eps$) and take a corresponding $z$ as in (2) above.
    The orbit through $z$ passes within $\eps$ from $q$, so there exists a $z'$ within $\eps$ from $q$ and a $t'>0$ such that $d(q,F^{t'}(z'))<\eps$. 
    Hence, $q\in NW_F$.
    %By construction, $t'\to\infty$ as $\eps\to0$, so that indeed $q\in NW_F$.
\end{proof}
