\begin{proposition}
    \label{prop: NW_G}
    Let $G$ be the inverse flow of $F$, namely $G^t(p) = F^{-t}(p)$.
    Then:
    \begin{enumerate}
        \item $p\NWto q$ if and only if $q\NWGto p$;
        \item $NW_F=NW_G$.
    \end{enumerate}
\end{proposition}
