\begin{definition}
    \label{def: stream}
    We say that a binary relation $D$ on $X$ is a {\bf quasi-order} if it is reflexive and transitive.
    We say that a quasi-order $E$ is an {\bf extension} of $D$ if $E\supset D$.
    We say that $D$ is a {\BF $F$-stream} (or simply a {\bf stream}, when there is no ambiguity) if $D$ is a transitive and topologically closed extension of $\NW_F$.
\end{definition}
%
\begin{proposition}
    \label{prop: A_F}
    The relation
    $$\cA_F=\{(x,y):L(x)\geq L(y) \text{ for all } L\in\cL_F(X)\}$$
    is the smallest $F$-stream.
\end{proposition}
%
\begin{proof}
    Let us prove first that $\cA_F$ is a $F$-stream.
    First of all, $\cA_F$ is closed, since it is defined by a closed relation on continuous functions.
    Moreover, $\cO_F\subset\cA_F$ by the very definition of $\cA_F$.
    Hence, $\cA_F\supset\overline{\cO_F}=\NW_F$.
    The reader can verify that $\cA_F$ is both reflexive and transitive, so it is a closed extension of $\NW_F$.

    Finally, suppose that there is a stream $D$ strictly smaller than $\cA_F$.
    Then there must be at least a pair $(x,y)$ such that $L(x)\geq L(y)$ for all $L\in\cL_F(X)$ and $(x,y)\not\in D$.
    By Lemma~A in~\cite{DLY24}, there is a function $K\in C^0(X)$ such that $K(x')\geq K(y')$ for each $(x',y')\in D$ and $K(x)<K(y)$.
    This leads to a contradiction: since $D\supset\cO_F$, then $K\in\cL_F(X)$, but then, by the very definition of $\cA_F$, $(x,y)$ cannot belong to $\cA_F$, against the initial hypothesis.
%    This leads to a contradiction: since $D\supset\cO_F$, then $K\in\cL(X)$
    % \bigskip
    % In particular, $\NW_F\subset\cA_F$, 
    % Notice first that the very definition of $\cA_F$ implies that $\cO_F\subset\cA_F$.
\end{proof}
