Our ultimate goal is classifying wandering flows according to the following equivalence relation.
%
\begin{definition}
    Two flows $F,G$ on $X$ are {\bf locally topologically equivalent} if, for every $p$, there is an open neighborhood $U_p\subset X$ of $p$ and a homeomorphism $\phi_p:U_p\to X$ such that, for every $q\in U_p$, 
    $\phi_p(\cO_F(q)\cap U_p)\subset\cO_G(\phi_p(q))$. 
    We say that $F$ and $G$ are {\bf topologically equivalent} if
    there exists a homeomorphism of $X$ that sends orbits of $F$ in orbits of $G$ and preserves the orientation of the orbits.
\end{definition}
%
\noindent
{\bf Regular flows.} A full topological classification of flows is in general highly non-trivial unless one poses some suitable restriction.
In this article, we consider the case of {\em regular} flows as defined below.
%
\begin{definition}
%    Two flows $F,G$ on $X$ are {\bf locally topologically equivalent} if, for every $p$, there is an open neighborhood $U_p\subset X$ of $p$ and a homeomorphism $\phi_p:U_p\to X$ such that, for every $q\in U_p$, $\phi_p(\cO_F(q)\cap U_p)\subset\cO_G(\phi_p(q))$. 
%    We say that $F$ and $G$ are {\bf topologically equivalent} if there exists a homeomorphism of $X$ that sends orbits of $F$ in orbits of $G$ and preserves the orientation of the orbits.
%    When $X$ is a linear space, we say that $F$ is a {\bf linear flow} if each map $F^t$ is linear.
    We say that $F$ is {\bf regular} if it is locally topologically equivalent to the flow of a constant vector field. 
    %a linear flow.
\end{definition}
%
\begin{example}
    The flow $F$ of a $C^1$ vector field $\xi$ without zeros is $C^1$ regular.
    This is an immediate consequence of the Rectification Theorem (e.g. see~\cite{Arn92b}), stating that, in the neighborhood of any point where $\xi(p)\neq0$, there is a $C^1$ diffeomorphism mapping $\xi$ into a constant vector field.
    Given any homeomorphism of the plane $\phi$, the flow $F_\phi^t=\phi^{-1}\circ F^t\circ\phi$ is $C^0$ regular.
\end{example}
%
\begin{proposition}
    Let $F$ be a regular planar flow.
    Then $F$ is wandering.
\end{proposition}
%
\begin{proof}
    By hypothesis, $F$ cannot have fixed points or periodic orbits.
    By the Poincar\'e-Bendixon theorem, this means that $NW_F=\emptyset$. 
\end{proof}
