\begin{definition}
    \label{def: inseparable}
    A set $A\subset X$ is {\BF saturated} if $p\in A$ implies that $\cO_F(p)\subset A$.
    We say that an orbit $s_1$ of $F$ is {\bf inseparable} from another orbit of $F$ $s_2\neq s_1$ if, for every saturated neighborhoods $U_1$ of $s_1$ and $U_2$ of $s_2$ we have that $U_1\cap U_2\neq\emptyset$.
    %a {\bf separatrix} if there exist another full orbit $s_2$ of $F$ and
    %two points $p\in s_1$ and $q\in s_2$ such that either 
    %$p\NWto q$
    %$q\in\Lambda^1(p)$ 
    %or viceversa.
    %, for every $eps>0$ and $T>0$, there is a $(\eps,T)$-link from $p$ to $q$.
    %an orbit $\ell_\eps$ of $F$ passing within $\eps$ from both $p$ and $q$.
    %In other words, there is a point $z$ and time $t$ such that $d(p,z)<\eps$ and $d(q,F^{t}(z))<\eps$.
    %In this case, we say that $s_1$ and $s_2$ are {\bf inseparable}.
    %Moreover, if $p\NWto q$
    %$q\in\Lambda^1_F(p)$ 
    %we say that $s_1$ {\bf precedes} $s_2$ and we write {\BF $s_1\prec s_2$}, and viceversa if $q\NWto p$.
    In this case, we say that $s_1$ and $s_2$ are {\bf separatrices} for the flow $F$.
    We denote by $\cS_F$ the set of all separatrices of $F$.
    %$p\in\Lambda^1_F(q)$.
\end{definition}
%
As we show below, the notion of inseparability is strictly related to the Auslander stream.
%
\begin{proposition}
    A separatrix $s_1\in\cS_F$ is inseparable from another separatrix $s_2\in\cS_F$ if and only if, possibly after relabeling the two separatrices, for every $p\in s_1$ and every $q\in s_2$ we have that $p\NWto q$.
\end{proposition}
%
\begin{proof}
    Assume that $s_1$ is inseparable from $s_2\neq s_1$ and let $p\in s_1$ and every $q\in s_2$.
    Let $J_p$ (resp. $J_q$) be a segment passing through $p$ and such that every orbit of $F$ meets $J_p$ (resp. $J_q$) in at most one point -- such segment always exists because $F$ is regular -- and denote by $U$ (resp. $V$) the set of all orbits that intersect $U$ (resp. $V$).
    Since $s_1$ and $s_2$ are inseparable, $s_1\cap s_2\neq\emptyset$.
    Hence, for every $\eps>0$ there is an orbit of $F$ that passes within $\eps$ from $s_1$ and within $\eps$ from $s_2$.
    Hence, $p\NWto q$.
\end{proof}
%
Notice that, for points $p,q$ belonging to distinct orbits, $p\NWto q$ is equivalent to $q\in\Lambda_F^1(p)$
