\begin{example}[\bf A first case with infinitely many separatrices]
    \label{ex:inf seps 1}
    Let $F$ be the flow of the $C^\omega$ vector field $\xi(x,y)=(\sin y,\cos y)$, whose orbits are sketched in Fig.~\ref{fig: infinitely many separatrices}(left).

    Notice that $\fL_\xi H(x,y)=0$ for $H(x,y)=e^x\cos y$, so that 
    $$
    \cO_F(x_0,y_0)\subset
    \{(x,y): H(x,y)=H(x_0,y_0)\}.
    $$
    The separatrices of this flow are the horizontal lines $s_k=\{y=k\pi+\pi/2\}$, $k\in\bZ$.
    The relations between the separatrices are the following:
    $$
    s_{2n+1}\prec s_{2n},\;
    s_{2n+1}\prec s_{2(n+1)}
    $$
    for every $n\in\bZ$.
    Hence 
    $$
    \Lambda^1_F(p)=
    \begin{cases}
        \emptyset,&p\not\in s_{2n+1}\text{ for any }n\in\bZ;\\
        s_{2(n+1)}\cup s_{2n},&p\in s_{2n+1}\text{ for some }n\in\bZ,\\
    \end{cases}
    $$
    so that: 
    \begin{enumerate}
        \item $\Lambda^\star_F(p)=\Lambda^1_F(p)$ for each %ordinal $k\geq1$ and
        $p\in\bR^2$;
        \item $rank(F)=1$;
        \item $\NW_F=\cA_F$
        %\item $\Down_{\cA_F}(p)=\cO_F(p)\bigcup\Lambda^1_F(p)$;
        \item $NW_F=A_F=\emptyset$.
    \end{enumerate}
\end{example}
