\begin{definition}
    We say that two planar foliations are {\bf n-equivalent} if they are equivalent under a orientation-reversing homeomorphism. 
    Two chordal systems $E_1$ and $E_2$ are {\bf anti-isomorphic} if there is a bijection $\phi:E_1\to E_2$ such that $|a,b,c|^+$ if and only if $|\phi(a),\phi(b),\phi(c)|^-$ and $a|b|c$ if and only if $\phi(a)|\phi(b)|\phi(c)$.
\end{definition}
%
\begin{example}
    Let $\Psi:\bR^2\to\bR^2$ be any homeomorphism of the plane that switches the orientations, for instance $\Psi(x,y)=(x,-y)$.
    Given any foliation $\cF$ of the plane with chordal system $E$, denote by $\Psi_*\cF$ the foliation of the images of the leaves of $\cF$ under $\Psi$ and denote by $\Psi_*E$ the corresponding chordal system.
    Then the map $\psi:E\to\Psi_*E$ is an anti-isomorphism, since the image under $\Psi$ of each positively oriented loop is a negatively oriented loop.
\end{example}
