\begin{lemma}
    \label{lemma: prec => CS}
    Let $\cF$ be an oriented planar foliation and let $s_1,s_2,s_3\in\cF$ be such that $s_2,s_3$ are inseparable from $s_1$ and that $s_2\in\Delta^+_{s_1}$ and $s_3\in\Delta^-_{s_1}$.
    Then, for every $\alpha\in\Theta_{s_1,s_2}$:
    \begin{enumerate}
        \item $s_1\prec s_2$ if and only if $|s_1,\alpha,s_2|^+$;
        \item $s_2\prec s_1$ if and only if $|s_1,\alpha,s_2|^-$.
    \end{enumerate}
    %
    Moreover, if $s_1\prec s_2$, then, for every  $\beta\in\Theta_{s_1,s_3}$:
    %
    \begin{enumerate}
        \item $s_1\prec s_3$ if and only if $|s_1,\beta,s_3|^-$;
        \item $s_3\prec s_1$ if and only if $|s_1,\beta,s_3|^+$.
    \end{enumerate}
    %
    While, if $s_2\prec s_1$, then, $\beta\in\Theta_{s_1,s_3}$:
    %
    \begin{enumerate}
        \item $s_1\prec s_3$ if and only if $|s_1,\beta,s_3|^+$;
        \item $s_3\prec s_1$ if and only if $|s_1,\beta,s_3|^-$.
    \end{enumerate}   
    %,  and ; moreover, if $s_1\prec s_2$, then $s_1\prec s_3$ if and only if $|s_1,\beta,s_3|^-$ and $s_3\prec s_1$ if and only if $|s_1,\beta,s_3|^+$ and similarly if $s_2\prec s_1$.
    % we have that $s_1\prec s_3$ implies 
    % and assume that one of the following four relations is satisfied:
    % %
    % \begin{enumerate}
    %     \item $s_1\prec s_2$, $s_1\prec s_3$;
    %     \item $s_1\prec s_2$, $s_3\prec s_1$;
    %     \item $s_2\prec s_1$, $s_1\prec s_3$;
    %     \item $s_2\prec s_1$, $s_3\prec s_1$.
    % \end{enumerate}
    % %
    % Then, for every $\alpha\in\Theta_{s_1,s_2}$ and $\beta\in\Theta_{s_1,s_3}$, the following, respectively, holds:
    % %
    % \begin{enumerate}
    %     \item $|s_1,\alpha,s_2|^+$, $|s_1,\beta,s_3|^-$;
    %     \item $|s_1,\alpha,s_2|^+$, $|s_1,\beta,s_3|^+$;
    %     \item $|s_1,\alpha,s_2|^-$, $|s_1,\beta,s_3|^-$;
    %     \item $|s_1,\alpha,s_2|^-$, $|s_1,\beta,s_3|^+$.
    % \end{enumerate}
    %
\end{lemma}   
%
\begin{proof}
    All possible configurations are schematically shown in Figure~\ref{fig: UU}.
    Here we discuss case (a), where $s_1\prec s_2$ and $s_1\prec s_3$, and all other cases can be done similarly.
    Let $x\in s_1$ and $y\in s_2$.
    By assumption, there are curves in $\Delta_{s_1}^+$ passing arbitrarily close to $x$ whose forward orbit passes arbitrarily close to $y$.
    We fix two charts $U_x$ about $x$ and $U_y$ about $y$ such that $U_x\cap\cF$ and $U_y\cap\cF$ are homeomorphic to a rectangle foliated by parallel vertical lines.
    Starting from $x$, we can trace a horizontal arc transversal to $\cF$ that reaches a point $z\in\alpha$.
    From $z$, we trace a small transversal arc going back towards $s_1$ and then we continue moving on a leaf of $\cF$.
    By assumption, this will lead us inside $U_y$.
    From within $U_y$, we can then continue the arc horizontally until we reach $s_2$.
    Finally, we repeat this step ``backward'' until we get back to $x$.
    This way, we build a loop that is transversal to $\cF$, touches exactly once $s_1$, $\alpha$ and $s_2$ and turns counterclockwise.
    Hence, $|s_1, \alpha, s_2|^+$.
    The same type of argument shows that $|s_1, \beta, s_3|^-$.
\end{proof}

