%====================================================================================================================%
\subsection{Implementation}\label{sec:implementation}
We map the RA-SAA+FB method to our UUV-USV model described in Section \ref{sec:modeling}. While the time-discretized version of \eqref{eq:augSOCP} with an Euler-Maruyama discretization of \eqref{eq:SDE} is skipped in the interest of space, it follows directly from \citep{lew2023risk}.
The uncertain parameter ${\bm \xi}$ is set as
\begin{equation}
        {\bm \xi}(\omega) = \left(\begin{array}{c}
             (m(\omega),\bar{m}(\omega),c_\theta(\omega),c_r(\omega))^\top \\
             (\dots,x_{\mathcal{O}_k}(\omega),\dots)^\top\\
             (\dots,d_{\mathcal{O}_k}(\omega),\dots)^\top\\
             (\dots,a_{\mathcal{O}_k}(\omega),\dots)^\top
        \end{array}\right),
        \label{eq:xi}
    \end{equation}
and using the system expression \eqref{eq:input_affine},  the drift and diffusion terms of the \eqref{eq:SDE}  are given by

\begin{align*}
    &{\bm{b}} \left({\bm x}(t),{\bm u}(t), {\bm \xi}\right) = \bm{f}_{sys}({\bm x}(t),\bm \xi) + \bm{G}_{sys}({\bm x}(t),\bm \xi){\bm u}(t), \\
    & {\bm{\sigma}} \left({\bm x}(t),{\bm u}(t), {\bm \xi}\right) = \bm{D}
\end{align*}
where $\bm{D}$ is a matrix that determines the gain multiplying the Wiener process. Next, we define the cost functions ${\ell},{\varphi}$ and the constraint functions $ C, H$.
\begin{align}
    &\ell\bigl({\bm x}_{\bm \mu}^i(t),{\bm \mu}(\bm x^i, t)\bigr) = \|{\bm \mu}(\bm x^i, t)\|^2_R, \quad \varphi( {\bm x}^i_{\bm \mu}(t_f)) = 0 \label{eq:RA-SAA_cost_func}\\
    & C( {\bm x}_{\bm \mu}^i(t),{\bm \xi^i}) = 
    \max_k \left(-\left\|\left(\begin{array}{c}x^i(t)-x^i_{\mathcal{O}_k}\\d^i(t)-d^i_{\mathcal{O}_k}\end{array}\right)\right\| + a^i_{\mathcal{O}_k} \right), \label{eq:RA-SAA_collision_constraint}\\
    & H( {\bm x}^i_{\bm \mu}(t_f)) = \|{\bm y^i_{\bm \mu}}(t_f)-{\bm y}_{d}\|^2. \label{eq:RA-SAA_terminate_constraint}
\end{align}
with the obstacle positions $(x_{\mathcal{O}},d_{\mathcal{O}})$ and size $a_{\mathcal{O}}$, $k$ the index of each obstacle and $\bm{y}=(x, d, X)^\intercal$ as defined in \eqref{eq:input_affine}. The cost function defined in Equation \eqref{eq:RA-SAA_cost_func} minimizes the energy associated with the UUV-USV control inputs with penalization weight matrix $R$.  Equation \eqref{eq:RA-SAA_collision_constraint} defines $C$ as the signed distance to the nearest obstacle, which is negative (and therefore safe) whenever the UUV is outside all obstacles, and inserts it into the CVaR constraint \eqref{eq:G_socp} to enforce collision avoidance. Equation \eqref{eq:RA-SAA_terminate_constraint} represents the distance to the target point at the terminal time, and the constraint in Equation \eqref{eq:H_socp} ensures that the target position is reached.
Finally, we apply a (smooth) saturation function $\texttt{sat}(\cdot)$  that limits the control input within $U$, such that $\bm{\mu}$ reads
\begin{align}
    {\bm \mu}(\bm x^i,t) = \texttt{sat} \left({\bm u}(t) + \bm{K}({\bm x}_{\bm{u}}^{\rm nom}(t)-{\bm x}^i(t))\right),
\end{align}
The control law ${\bm \mu}$ is Lipschitz continuous, as the norm of $\bm{K}$ is finite, and bounded, due to the saturation function. Since the system and cost functions (${\bm{b}},{\bm{\sigma}}, \ell, \varphi, G, H$) from Section \ref{sec:modeling} also meet standard assumptions (A1)-(A2), the same asymptotic optimality results can be derived as in \citep{lew2023risk}, thus providing convergence guarantees to the optimal solution of \eqref{eq:augSOCP} in the limit $N \to \infty$ of the sample size. 


