\section{Introduction and Main Theorem}
\noindent  
In the present paper, we consider a Newtonian polytropic ideal model of a compressible viscous and heat-conductive fluid in the exterior domain $\Omega=\{x \in\mathbb{R}^{n}\,(n\ge 3); |x| > r_0\}$\,($r_0$ is a positive constant and $n$ is the space dimension) described by 
\begin{eqnarray}
 \label{cns} 
 \left\{
\begin{array}{l}
\rho_t+\nabla\cdot (\rho U)=0, \\[10pt]
(\rho U)_t+\nabla\cdot(\rho U\otimes U)+\nabla p =\nabla \cdot D,\quad
t>0,\ x \in \Omega,\\[10pt]
\left\{\rho \left(e + \frac{1}{2}|U|^2\right)\right\}_t +
\nabla\cdot \left\{\rho U \left(e + \frac{1}{2}|U|^2\right)\right\}+\nabla\cdot(pU)= \nabla\cdot (DU -q),\\[10pt]
%\left\{\rho \left(e + \frac{1}{2}|U|^2\right)\right\}_t +
%\nabla\cdot \left\{\rho U \left(e + \frac{1}{2}|U|^2\right)\right\}+\nabla\cdot(pU)= \nabla\cdot (DU -q),
\end{array}
 \right.\, 
\end{eqnarray} 
in the Eulerian coordinates, where $\rho=\rho(t,x)>0$ is the mass density, $U={}^t(u_1(t,x),\cdots ,u_n(t,x))$ is the fluid velocity, $e:=c_V \theta$, and $p:=R\rho\theta$ are internal energy per unit mass and the pressure, respectively, $\theta=\theta(t,x)>0$ is the absolute temperature. In addition, $c_V$ and $R$ are the specific heat at constant volume and the gas constant, which are assumed to be positive constants. Furthermore, $D$, $\Theta$, and $q$ are the stress tensor {\it w.r.t.} viscosity, the strain tensor, and the heat flow vector, respectively, defined by 
\begin{align}
D= 2\nu\,\Theta+\lambda\,(\nabla\cdot U)I,\quad \Theta= \frac{1}{2}\{\nabla\otimes U + {}^t(\nabla\otimes U)\},\quad q=-\kappa \nabla\theta,
\end{align}
where $\nu$ and $\lambda$ are the shear and second viscosity coefficients, and $\kappa$ is the thermal conductivity, which are assumed to be constants satisfying 
\begin{align}
\label{visc}
\nu>0, \quad 2\nu+ n\lambda \ge 0, \quad \kappa>0.
\end{align}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\noindent
In this paper, we focus our attention on the radially symmetric solutions, which have the form
\begin{align}
\label{t}
\rho(t,x)=\rho(t,r), \quad U(t,x)=\frac{x}{r}\,u(t, r),\quad \theta(t,x)=\theta(t,r), \quad r= |x|,
\end{align}
where $u(t, r)$ is a scalar function. By plugging  (\ref{t}) into (\ref{cns}), 
%and using the definition of $e$
we can rewrite (\ref{cns}) and obtain the equations for the radially symmetric solution $(\rho, u,  \theta)$  in the form
\begin{equation}
\label{nr}
\left\{\begin{array}{l}
\rho_t + \dfrac{ (r^{n-1}\rho u)_r}{r^{n-1}}=0, \\[10pt]
(\rho u)_t
+ \dfrac{ (r^{n-1}\rho u^2)_r}{r^{n-1}}+ p_r =\mu \Big(\dfrac{(r^{n-1}u)_r}{r^{n-1}}\Big)_r, \\[10pt]
\left\{\rho \left(c_V\theta + \frac{1}{2}u^2\right)\right\}_t +
\dfrac{\left\{r^{n-1}\rho u \left(c_V\theta + \frac{1}{2}u^2\right)\right\}_r}{r^{n-1}}
+\dfrac{ (r^{n-1}pu)_r}{r^{n-1}}
\\
\hspace{3cm}= \kappa\dfrac{(r^{n-1}\theta_r)_r}{r^{n-1}} +
\mu \Big(\dfrac{(r^{n-1}u)_r}{r^{n-1}}\Big)_ru +\Psi, \quad \ \ t>0,\ r>r_0,
\\[10pt]
\Psi := 2\nu u_r^2 +2\nu(n-1)(\dfrac{u}{r})^2+\lambda(u_r+\dfrac{n-1}{r}u)^2,
\end{array}
 \right.\,
\end{equation}
where 
\begin{align}
\label{viscondi}
\mu := 2\nu + \lambda>0,
\end{align} and $\Psi$ is the dissipation function, a non-negative quadratic form  under the condition (\ref{visc}), representing the rise in temperature due to viscosity. By the definition (\ref{viscondi}), we also see that 
\begin{align}
\label{mutonu}
\frac{\nu}{\mu}\le \frac{n}{2(n-1)} \le 1.
\end{align}
%{\aka {and we further assume that $\mu\le 1$ throughout this paper with the next research about inviscid problem in mind.}} 

Now, we consider the initial boundary value problems 
for (\ref{nr}) under the initial condition
% is prescribed to be spatial asymptotically constant
\begin{equation}
(\rho, u, \theta)(0,r)=(\rho_0, u_0, \theta_0)(r),\quad r >r_0, 
\end{equation}
the far field condition
\begin{equation}
\displaystyle{\lim_{r \to \infty}}(\rho, u, \theta)(t,r)=(\rho_+,u_+,\theta_+),\quad t>0,
\end{equation}
% \begin{equation}
% (\rho, u)(0,r)=(\rho_0, u_0)(r),\ r >r_0, \quad
% \end{equation}
and also the following two types of boundary conditions, depending on the sign of the velocity
on the boundary
\begin{equation}
\label{bc}
 \left\{
\begin{array}{ll}
(\rho, u, \theta)(t,r_0) =(\rho_-, u_-, \theta_-),\quad t>0,& (u_->0),\\[10pt]
(u, \theta)(t,r_0) =(u_-, \theta_-),\quad t>0,& (u_-\le 0),
\end{array}
 \right.
\end{equation}
where $\rho_{\pm}>0, u_{\pm}$ and $\theta_{\pm}$ are given constants. 
The case $u_->0$ is known as ``inflow problem'', the case $u_-=0$ as 
``impermeable wall problem'', and the case $u_-<0$ as ``outflow problem''. 

Regarding the impermeable wall problem, Matsumura and Nishida \cite{MNT} first considered the original exterior problem (\ref{cns}) in $\mathbb{R}^3$, where $\Omega$ is a more general exterior domain, which includes the radially symmetric case (\ref{nr}). That is, under the boundary and far field conditions $U|_{\partial \Omega}=U|_{\infty}=0$, \ $\theta_+=\theta_-$, they showed the existence of the global solution in time around the constant state $(\rho, U, \theta)=(\rho_+, 0, \theta_+)$ and its asymptotics toward the constant state for small initial perturbations. 
% on the exterior domain of $\mathbb{R}^3$ and they prove that the solution converges to the corresponding stationary solution as time tends to infinity  under the smallness assumptions on the initial data. 
%Itaya shows a time global existence of the spherically symmetric solution to (\ref{cns}) on the bounded annulus domain in \cite{I}. 
On the other hand, for the radially symmetric problem (\ref{nr}) in $\mathbb{R}^n$ ($n=2, 3$), Jiang \cite{J} showed the time global existence of the solution to (\ref{nr}) under the conditions $u_{\pm}=0$, \ $\theta_+=\theta_-$, and derived the partial results on the asymptotic stability toward the constant state $(\rho_+, 0, \theta_+)$ for large initial perturbations. Nakamura-Nishibata-Yanagi \cite{NN} and Nakamura-Nishibata \cite{NN0} extended the results by Jiang \cite{J} to the case with external potential forces in $\mathbb{R}^n$ ($n\ge 3$) and showed the unique existence of the stationary solution and its asymptotic stability. 

Regarding the inflow and outflow problems, Hashimoto-Matsumura \cite{HM1} study the existence 
of the radially symmetric stationary solution for the compressible Navier-Stokes equation describing the motion of viscous barotropic gas 
%without external forces 
on the exterior domain of a sphere, 
in a suitably small neighborhood of the far field state. 
The asymptotic stability of the stationary solutions obtained in \cite{HM1} was considered in Hashimoto-Nishibata-Sugisaki \cite{HNS} for the outflow problem, and in Huang-Hashimoto-Nishibata \cite{HHN} for the inflow problem. 
In this paper, as the first step 
%to study the radially symmetric solutions 
%of 
to extend the results to
the compressible viscous and heat-conductive ideal fluid
% on the exterior domain of a sphere, 
we shall show the existence of stationary solutions in a suitably small neighborhood of the far field state.
% by using Banach's fixed-point theorem. 

The stationary problem corresponding to the problem (\ref{nr})-(\ref{bc}) is 
written as
\begin{equation}
\label{nrs0}
\left\{\begin{array}{l}
\dfrac{ (r^{n-1}\rho u)_r}{r^{n-1}}=0, \\[10pt]
\dfrac{ (r^{n-1}\rho u^2)_r}{r^{n-1}}+ p_r =\mu \Big(\dfrac{(r^{n-1}u)_r}{r^{n-1}}\Big)_r,
\\[10pt]
\dfrac{\left\{r^{n-1}\rho u \left(e + \frac{1}{2}u^2\right)\right\}_r}{r^{n-1}}
+\dfrac{ (r^{n-1}pu)_r}{r^{n-1}}\\[10pt]
\hspace{4cm}\!\!= \kappa\dfrac{(r^{n-1}\theta_r)_r}{r^{n-1}} +
\mu \Big(\dfrac{(r^{n-1}u)_r}{r^{n-1}}\Big)_ru +\Psi,\quad r\ge r_0,
\\[10pt]
\displaystyle{\lim_{r\to \infty}} (\rho, u, \theta)(r) =(\rho_+, u_+, \theta_+), \\[2mm]
(\rho, u, \theta)(r_0)=(\rho_-, u_-, \theta_-)\ \ (u_->0),\quad (u, \theta)(r_0)=(u_-, \theta_-) \ \ (u_- \le 0),\\[5pt]
p= R\rho\theta, \quad e=c_V \theta.
\end{array}
 \right.\,
\end{equation}
%\begin{align}
% \label{nrs0} 
% \left\{
%\begin{aligned}
%  &\ (r^{n-1}\rho u)_r = 0,   \\
%  &\ \rho uu_r+p(\rho)_r=\mu(\frac{(r^{n-1}u)_r}{r^{n-1}})_r, \qquad r>r_0,\\[2mm]
%  &\ \displaystyle{\lim_{r\to \infty}} (\rho, u)(r) =(\rho_+, u_+), \\[2mm]
%  &\ (\rho, u)(r_0)=(\rho_-, u_-)\ \ (u_->0), \quad u(r_0)=u_- \ \ (u_- \le 0).
%\end{aligned}
% \right.\,
%\end{align}
By integrating the first equation in (\ref{nrs0}) in terms of $r$, we easily see that it holds
\begin{align}
\label{n1}
r^{n-1}\rho(r) u(r)=\epsilon, \qquad r\ge r_0, 
%\qquad and \qquad  r_0^{n-1}\rho_- u_-=\epsilon,
\end{align}
for some constant $\epsilon$, which implies by the boundary conditions that
\begin{equation}
\epsilon = r^{n-1}_0\rho_- u_-\quad(u_->0),\qquad 
\epsilon = r^{n-1}_0\rho (r_0) u_-\quad(u_-\le0). 
\end{equation}
Due to the formula (\ref{n1}), we see that if $n \ge 2$, 
\begin{align*}
u_+=\lim_{r\to \infty}u(r)= \lim_{r\to \infty}\frac{\epsilon}{r^{n-1}\rho_+}=0.
\end{align*}
Hence, it is necessary to assume $u_+=0$ for the existence of multi-dimensional
stationary solutions. 
We first note the case $u_-$=0. In this case, we can easily see from the first equation of (\ref{nrs0}) that $u=0$. By using $u=0$, we can derive from the second and third equations of (\ref{nrs0}) that 
$$
p_r =0,\quad \kappa (r^{n-1}\theta_r)_r =0,
$$
which imply
$$
\rho\,\theta=\rho_+\theta_+,\quad \theta=\ti\theta(r):=\theta_+
%+\frac{\theta_--\theta_+}{(r/r_0)^{(n-2)}}.
+(\theta_--\theta_+)(r/r_0)^{-(n-2)}.
$$
 Thus, in the case $u_-=0$, the trivial solution of (\ref{nrs0}) is given by $(\rho, u, \theta)=(\rho_+\theta_+/\ti\theta, 0, \ti\theta)$ for any $\rho_+$ and $\theta_{\pm}>0$. So, in what follows, we assume that $u_-\neq 0$.
 Now we are ready to state the main results in the present paper.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%5
\begin{thm} 
\label{mt}
Let $n \ge 3$ and $u_+=0$.
Then, for any $\rho_+>0$ and $\theta_+>0$,
there exist positive constants $\epsilon_0$ and $C$ satisfying the following:

\medskip

\noindent
{\rm (I)} \ Let $u_->0$. If $|u_-|+|\rho_--\rho_+|+|\theta_--\theta_+| \le \epsilon_0$, 
there exists a unique smooth solution $(\rho,u, \theta)$ of 
the problem {\rm (\ref{nrs0})} satisfying 
\begin{align}
\label{1}
\begin{aligned}
  & |\rho(r)-\rho_+|,\ |\theta(r)-\theta_+|\le Cr^{-(n-2)}(|u_-|+|\rho_--\rho_+|+|\theta_--\theta_+|),\\[5pt]
  & C^{-1}r^{-(n-1)}|u_-| \le |u(r)| \le Cr^{-(n-1)}|u_-|, \qquad r\ge r_0.
\end{aligned}
\end{align}
%Furthermore, for any positive constant $h$, there exists a positive constant 
%$C_h$ such that it holds
%\begin{align}
%\label{bl}
%\sup_{r\ge r_0+h}|\rho(r)-\rho_+| \le C_h|u_-|^2.
%\end{align} \\
{\rm (II)} \ Let $u_-< 0$. If $|u_-|+|\theta_--\theta_+|\le \epsilon_0$, 
there exists a unique smooth solution $(\rho, u, \theta)$ 
of the problem {\rm (\ref{nrs0})} satisfying
\begin{align}
\label{decayoutflow}
\begin{aligned}
  & |\rho(r)-\rho_+|,\ |\theta(r)-\theta_+|\le Cr^{-(n-2)}(|u_-|+|\theta_--\theta_+|), \\[5pt]
  & C^{-1}r^{-(n-1)}|u_-| \le |u(r)|\le Cr^{-(n-1)}|u_-|, \qquad r\ge r_0.
\end{aligned}
\end{align}
\end{thm}

\medskip

\begin{remark}
When $u_-=0$, as we stated above, the trivial solution is given by $(\rho, u, \theta)=(\rho_+\theta_+/\ti\theta, 0, \ti\theta)$.
Therefore, when $u_->0$ and $\rho_- \neq \rho_+$, since 
$\rho_+\theta_+/\ti\theta(r_0) = \rho_+\theta_+/\theta_-$ is not $\rho_-$ in general, we can expect that a boundary layer for mass density does appear as $u_- \to +0$. 
\end{remark}
