\section{Outflow problem}
This subsection is devoted to considering the case $u_-<0$, that is, the outflow problem, and we show the result (II) in Theorem \ref{mt}. 
In this case, recalling 
\begin{align}
\label{epout}
\epsilon := u_-/(v_++\eta(1))<0, 
\end{align}
we rewrite the first equation of $\eta$ in (\ref{reforme}) in the form:
\begin{equation}
\label{etar}
\begin{array}{l}
\eta_r+\dfrac{R\theta_+r^{n-1}}{u_- \mu v_+}\eta =-\dfrac{R\theta_+\eta(1)}{u_-{\mu}v_+^2}r^{n-1}\eta+ \dfrac{Rr^{n-1}}{\epsilon  \mu v_+}\chi +F(\eta,\chi),\\
\end{array}
\end{equation}
where $F(\eta,\chi)$ is defined by the same form as (\ref{etaF}) with the definition (\ref{epout}). 
Noting $u_-<0$ and the far field condition $\eta(\infty)=0$, we can solve equation (\ref{etar}) in terms of $\eta$ by applying Duhamel's principle, provided the right hand side is known. 
%as  
%\begin{align}
%\eta(r)=-\int_{r}^{\infty} e^{-\frac{\bar\Omega}{|u_-|}(s^n-r^{n})}\left(-\dfrac{R\theta_+\eta(1)}{u_-{\mu}v_+^2}s^{n-1}\eta+ \dfrac{Rs^{n-1}}{\epsilon  \mu v_+}\chi +F(\eta,\chi)\right)(s)\,ds.
%\end{align}
%where 
%\begin{align}
%\bar\Omega:=\frac{R\theta_+}{v_+ n}(>0).
%\end{align} 
On the other hand, the integrated equation of $\chi$ is the same as the second equation of (\ref{refint}) in Section 3, so our purpose in this section is to obtain the solution of the following differential-integral equations (\ref{outequ}) in terms of $\eta$ and $\chi$ with the boundary condition $\chi(1)=\chi_-$:
\begin{equation}
\label{outequ}
\left\{\begin{array}{l}
\eta(r)=-\int_{r}^{\infty} \ti G(r,s)\left(-\dfrac{R\theta_+\eta(1)}{u_-{\mu}v_+^2}s^{n-1}\eta+ \dfrac{Rs^{n-1}}{\epsilon \mu v_+}\chi +F(\eta,\chi)\right)(s)\,ds,
\\[10pt]
\chi(r) = \dfrac{\alpha}{\kappa(n-2)r^{n-2}}+H(\eta,\eta_r,\chi)(r),
\\[10pt]
\alpha = \kappa(n-2)(\theta_--\theta_+)-\kappa(n-2)
H(\eta,\eta_r,\chi)(1),\\[10pt]
(\eta_r)(r) =-\dfrac{R\theta_+r^{n-1}}{\epsilon \mu v_+^2}\eta(r)+
\dfrac{Rr^{n-1}}{\epsilon  \mu v_+}\chi(r) +F(\eta,\chi)(r),\quad r \ge 1,
\end{array}
 \right.\,
\end{equation}
where $H$ is defined in the same form as in (\ref{GKH}) and
\begin{align}
\begin{aligned}
\ti G(r,s) := e^{-\frac{\bar\omega}{|u_-|{\mu}}(s^n-r^{n})},\qquad  \bar\omega:=\frac{R\theta_+}{v_+ n}(>0).
\end{aligned}
\end{align}
% where $F(\eta(s),s)$ is a same function defined in (\ref{eq3}). 
%By using (\ref{eq4'}), we make the iteration sequence as
To prove the existence of the solution of (\ref{outequ}) 
with the decay rate estimate (\ref{decayo}),
we look for a solution of (\ref{outequ}) in the Banach space $X_{n-2}$ defined in (\ref{bsn}) with $l=n-2$. In the same way as in the last section, 
we construct the approximate sequence $\{\eta^{(m)}\}_{m\ge 0}$, $\{\chi^{(m)}\}_{m\ge 0}$ and $\{\zeta^{(m)}\}_{m\ge 1}$ corresponding to (\ref{outequ}) by
\begin{equation}
\label{sequenceout}
\left\{\begin{array}{l}
\eta^{(0)}:=0, \qquad \chi^{(0)}:=0,\\[10pt]
\eta^{(m+1)}(r)=-\int_{r}^{\infty} \ti G(r,s)\Big(-\dfrac{R\theta_+\eta^{(m)}(1)}{u_-{\mu}v_+^2}s^{n-1}\eta^{(m)}+ \dfrac{Rs^{n-1}}{\epsilon \mu v_+}\chi^{(m+1)} \\[10pt]
\hspace{8.5cm}+ F(\eta^{(m)},\chi^{(m)})\Big)(s)\,ds,\\[10pt]
\chi^{(m+1)}(r) = \dfrac{\chi_--H(\eta^{(m)},\zeta^{(m+1)},\chi^{(m)})(1)}{r^{n-2}}+H(\eta^{(m)}, \zeta^{(m+1)},\chi^{(m)})(r),
\\[10pt]
%\alpha^{(m+1)} = \kappa(n-2)(\theta_--\theta_+)\textcolor{red}{-}\kappa(n-2)
%H(\eta^{(m)},(\eta_r)^{(m+1)},\chi^{(m)})(1),\\[10pt]
\zeta^{(m+1)}(r) =-\dfrac{R\theta_+r^{n-1}}{\epsilon \mu v_+^2}\eta^{(m)}+
\dfrac{Rr^{n-1}}{\epsilon  \mu v_+}\chi^{(m)} +F(\eta^{(m)},\chi^{(m)})(r),
\end{array}
 \right.\,
\end{equation}
where $\zeta^{(m)}(r):=(\eta_r)^{(m)}(r),\,m\ge 1$. 
Here, we note that although $\chi^{(0)}$ doesn't satisfy the boundary condition 
$\chi^{(0)}(1)= \chi_-$, 
all $(\eta^{(m)}, \chi^{(m)}), m\ge 1,$ satisfy the desired boundary and 
far field conditions, provided $(\eta^{(m)}, \chi^{(m)}) \in X_{n-2}, m\ge 1.$ 
Then, to show $\{\eta^{(m)}\}_{m\ge 0}$ and $\{\chi^{(m)}\}_{m\ge 0}$ form Cauchy sequences in $X_{n-2}$ for 
suitably small $|u_-|$ and $|\chi_-|$, we prepare the following lemma.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{lem}
\label{sekibunhyokaout}
If  $l\ge -n$, then there exists a positive constant $C_0$ which is independent of $\epsilon$ and $\mu$ such that  for $g \in X_{l}$,
\begin{align*}
\label{hyoka2''}
r^{l+n-1}|\int_{r}^{\infty}\ti G(r,s)g(s)\,ds|
\le C_0\mu|u_-|\cdot \sup_{s \ge r}|s^{l}g(s)|,\quad r\ge 1.
\end{align*}
\end{lem}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\proof \ \ Because $g \in X_l$, it holds that
\begin{align*}
\begin{aligned}
&|\int_{r}^{\infty}\ti G(r,s)g(s)\,ds|\,  \le\int_r^{\infty} |e^{-\frac{\bar\omega}{|u_-| \mu}(s^n-r^n)} g(s)| ds \\
&\le \int_r^{\infty} e^{-\frac{\bar\omega}{|u_-| \mu}(s^n-r^n)} s^{-l} ds \cdot \sup_{s \ge r}|s^{l}\cdot g(s)|\\
%=&|\int_r^{\infty} (e^{-\frac{\bar\omega}{|u_-| \mu}(s^n-r^n)})_s
%\cdot \frac{|u_-| \ti\mu}{n\ti\kappa s^{n-1}} s^{-l}\cdot s^l\cdot g(s)ds|\\
=-&\frac{|u_-| \mu}{n\bar\omega}\int_r^{\infty} (e^{-\frac{\bar\omega}{|u_-| \mu}(s^n-r^n)})_s\cdot s^{-l-(n-1)} ds\cdot \sup_{s\ge r}|s^l\cdot g(s)|\\
=-&\frac{|u_-| \mu}{n\bar\omega}\Big\{[e^{-\frac{\bar\omega}{|u_-| \mu}(s^n-r^n)}\cdot s^{-l-(n-1)}]_r^{\infty}\\
&\quad-\int_r^{\infty} e^{-\frac{\bar\omega}{|u_-| \mu}(s^n-r^n)}(-l-(n-1))\cdot s^{-l-n} ds\Big\}\cdot \sup_{s\ge r}|s^l\cdot g(s)| \\
=& -\frac{|u_-| \mu}{n\bar\omega}\{\frac{-1}{r^{l+n-1}}+(l+n-1)\int_r^{\infty} e^{-\frac{\bar\omega}{|u_-| \mu}(s^n-r^n)}\cdot s^{-l-n} ds\}\cdot \sup_{s\ge r}|s^l\cdot g(s)|\\
\le& \frac{|u_-| \mu}{n\bar\omega}\{\frac{1}{r^{l+n-1}}+\frac{|l+n-1|}{r^{l+n}} \int_r^{\infty} e^{-\frac{\bar\omega}{|u_-| \mu}(s^n-r^n)}\ ds\}\cdot \sup_{s\ge r}|s^l\cdot g(s)|\\
\le& C_0|u_-|\mu \ \frac{1}{r^{l+n-1}} \cdot \sup_{s\ge r}|s^l\cdot g(s)|. 
\end{aligned}
\end{align*}
Thus, the proof of Lemma \ref{sekibunhyokaout} is completed.$\qquad \Box
$

