\title{Architectural mechanisms of a universal fault-tolerant quantum computer}


\author{
Dolev~Bluvstein$^{1,*}$, Alexandra~A.~Geim$^{1,*}$, Sophie~H.~Li$^{1}$, Simon~J.~Evered$^{1}$, J. Pablo Bonilla Ataides$^{1}$, Gefen~Baranes$^{1,2}$, Andi~Gu$^{1}$, Tom~Manovitz$^{1}$, Muqing~Xu$^{1}$, Marcin~Kalinowski$^{1}$, Shayan~Majidy$^{1}$, Christian~Kokail$^{3,1}$, Nishad~Maskara$^{1}$, 
