\subsection{An (alternative) algebraic approach relying on the spectral decomposition, leading to an analogous Hamiltonian formulation.}\label{sec2.1}


\noindent 
The matrix $A$, being real and skew-symmetric (which ensures that $iA$ is hermitian), is amenable to a spectral decomposition:
\begin{equation}
A= i\omega( v^+\otimes \bar v^+- v^-\otimes \bar v^-),\label{spectrdec}
\end{equation}
\noindent
where $v^+$ and $v^-$ are the mutually orthogonal eigenvectors corresponding to the eigenvalues $\pm i\omega\in i{\mathbb  R}$ and the overline denotes complex conjugation.
The two eigenvectors are orthogonal with respect to the complex scalar product: throughout this subsection we set $(u,v)= \sum_{k=1}^N\bar u_k v_k$.

\noindent
Let us remind the definition of vectors $\epsilon$ and $\eta$:
\begin{equation}
\epsilon :=\{\epsilon_j\}_{j=1,\dots N}; \;~\eta:=\{B_j\epsilon_j\}_{j=1,\dots N}\label{basis}
\end{equation}
\noindent
so that ${\mathcal K}$ is given by (\ref{kerA}), and in coordinates by (\ref{coordX}); on the other  hand, the set of equilibrium configurations is given  by (\ref{Z}), and in coordinates by (\ref{coordZ}).
\noindent


 \noindent
We notice that from the eigenvalue equation
\begin{equation}\label{eigeq}
\epsilon_j\sum_{k=1}^N\epsilon_k(B_j-B_k)v_k= \lambda v_j
\end{equation}
one has  $v^-_j=\bar v^+_j,~~v^-_j=\bar v^+_j$ and we can  rewrite (\ref{spectrdec}) in the form:
 \begin{equation}
 A_{jk}=i\omega(v^+_jv^-_k - v^-_jv^+_k)\rightarrow A= i\omega(v^+\otimes v^- -v^-\otimes v^+)\label{Askew}
 \end{equation}
which makes its skew-symmetry manifest. 


\noindent
We start again by  the evolution equations written In terms of the logarithmic variables (\ref{llog}), but now we use different local coordinates. By using as a new basis the eigenvectors
$v^\pm$, we will get a decomposition of the following form
\[y_j=y_+v_j^+ + y_- v_j^- + \sum_{k=1}^N R_k \tau^{(k)}_j\]
\noindent
As $v^+=\bar v^-$, since $y_j$ are real, it holds $y_-= \bar y_+$, $x_j \in {\mathbb R}$ and the term in the sum is the same as in (\ref{decompoy}).
To keep working with real quantities, it is natural to set:
\begin{eqnarray}
y_\pm=(1/{\sqrt 2} )(p\pm iq),\label{coordinates}\\
v^\pm= (1/{\sqrt 2})(u\pm iw).\label{realbasis}
\end{eqnarray}

\noindent
It follows:
\[y_j=pu_j-qw_j+  \sum_{k=1}^N R_k \tau^{(k)}_j\]

\noindent
To make a close comparison with the procedure and the results obtained in Section 2, we write the eigenvalue equation (\ref{eigeq})
%$$\epsilon_j\sum_{k=1}^N\epsilon_k(B_j-B_k)v_k=\lambda v_j$$
%\noindent
In terms of the variables $\epsilon,\eta$, getting:

\[\sum_{k=1}^N(\epsilon_k\eta_j-\epsilon_j\eta_k)v_k=\lambda v_j\]

\noindent
By setting

\[\alpha=\sum_{k=1}^N\epsilon_kv_k,\;\;~\beta=\sum_{k=1}^N\eta_kv_k,\]

\noindent
 we can  write:

\[\eta_j\alpha-\epsilon_j\beta = \lambda v_j.\]

\noindent
Through obvious manipulations  we arrive at the following homogeneous linear system:
\begin{eqnarray}
|\eta|^2\alpha-(\eta,\epsilon)\beta = \lambda \beta\label{eigeneq1}\\
(\epsilon,\eta)\alpha - |\epsilon|^2\beta=\lambda \alpha\label{eigeneq2}
\end{eqnarray}

%\noindent
%where  we remind that $(a,b)=\sum_{k=1}^N a_kb_k$ and $||a||^2=(a,a)$

\noindent
The solution of the secular equation yields the following two complex conjugated eigenvalues:

\begin{equation}\label{eqom}
\lambda_\pm \doteq \pm i\omega = \pm i{\sqrt {|\epsilon|^2|\eta|^2-(\epsilon,\eta)^2}}.
\end{equation}
Notice that $\omega$, i.e. the expression under the square root, is positive because of Cauchy-Schwartz inequality \cite{Kreyszig}, as already noticed in the previous section. Explicitly we have:
\begin{equation}
|\epsilon|^2|\eta|^2-(\epsilon,\eta)^2=-\frac{1}{2}\textrm{Tr}(A^2)=\sum_{k,i>k}(\epsilon_i\epsilon_k)^2(B_i-B_k)^2.
\end{equation}


 \noindent
Once solved for $\alpha,\beta$ the system (\ref{eigeneq1}), (\ref{eigeneq2}),  in terms of the variables $\epsilon,\eta$ we get:

\begin{eqnarray}
u_j=\sqrt{2}\rho\epsilon_j\label{u}\\
w_j=\frac{\sqrt{2}\rho}{\omega}(\epsilon_j(\epsilon,\eta)-\eta_j|\epsilon |^2)\label{v}\\
\rho^2=1/(2|\epsilon|^2)\label{ro}
\end{eqnarray}

\noindent
A straightforward calculation yields the normalization properties:

\begin{equation}
|u|^2=|w|^2=1,~(u,w)=0.\label{norms}
\end{equation}

\noindent
Moreover, it turns out that:

\[A_{jk}=\epsilon_k\eta_j-\epsilon_j\eta_k=\omega(u_jw_k-w_ju_k)\]

\noindent
implying that the evolution equations (\ref{llog}) become:
\begin{equation}
\dot p u_j-\dot q w_j =\frac{1}{\sqrt{2}\rho}u_j+\omega (u_j\sum_{k=1}^N \mathcal{C}_kw_k\exp(pu_k-qw_k)-w_j\sum_{k=1}^N\mathcal{C}_k u_k\exp(pu_k-qw_k )
\end{equation}

\noindent
Whence:
\begin{eqnarray}
\dot p =\frac{1}{\sqrt{2}\rho} +\omega \sum_{k=1}^N{\mathcal C}_k w_k\exp(pu_k-qw_k)\label{pdot}\\
\dot q = \omega\sum_{k=1}^N{\mathcal C}_k u_k \exp(pu_k-qw_k)\label{qdot}
\end{eqnarray}

The Hamiltonian nature of equations (\ref{pdot},\ref{qdot}) stems easily from the original Poisson structure (\ref{PB}), that implies

\[\dot q = \omega \frac{\partial {\mathcal H}}{\partial p}\]
\[\dot p =-\omega \frac{\partial {\mathcal H}}{\partial q}\]

The two expressions coincide for the Hamiltonian:
\begin{equation}
{\mathcal H}=  \sum_{k=1}^N{\mathcal C}_k\exp(pu_k-qw_k)-\frac{q}{\sqrt{2}\omega\rho} \label{newHam}
\end{equation}
We conclude this Section by noticing that the variables $(p,q)$ and $(P,Q)$ are related by a linear combination, i.e.
\begin{equation}\label{tra}\left\{
\begin{split}
&p=\frac{1}{\sqrt{2}\rho}P+\sqrt{2}\rho(\epsilon,\eta)Q,\\
&q=\sqrt{2}\rho\omega Q.
\end{split}
\right.\end{equation} 
This transformation is not canonical: it is possible to get a  canonical transformation by the rescaling $(p,q)$ $\to$ $(\sqrt{2}\rho p, \frac{q}{\sqrt{2}\rho\omega})$





 \bigskip
\section{Old and new results: how to understand them?}\label{sec3}
\noindent
%\begin{remark}
In \cite{SRTZ}  we constructed a complete set of first integral in involution for the system (\ref{model}) with the interaction coefficients given by (\ref{matrix}), showing that out of the family
\begin{equation}
e^{-a\sum_i N_i(t)}\prod_{i=1}^N N_i(t)^{c_i}=I_{1,..,N},\label{eqnew}
\end{equation}
\noindent
one can extract $N-1$ independent integrals of motion in involution, with respect to the Poisson brackets (\ref{PB}). In (\ref{eqnew}) $c_k$ are a set of arbitrary constant constrained by the equation $\sum_k c_k \epsilon_k=0$ whereas $a=\sum_{k=1}^N B_k\epsilon_{k}c_k$. Clearly it is always possible to rescale the constant $c_k$ and set $a=1$ so that the constants $c_k$ can be considered the set of equilibrium configurations $z_k$ given in formulae (\ref{coordZ}).


It is  natural to ask  the following question: what is the role of the integrals of motions $\tilde C_k$ found out in \cite{SRTZ}?
As we will show, the answer to this question will be clear if one introduces again the variables $(P,Q)$. First of all, we remind that in term of the logarithmic variables $y_j$
 the generating function of the first integrals  can be written as a single exponential of the quantity:
\[
I (c_1\, \cdots, c_N) =\sum_{k=1}^N \epsilon_kc_k C_k 
\]
\noindent
where
\begin{equation}
C_k = (y_k/\epsilon_k -B_k\sum_{j=1}^N\exp (y_j))\label{newfirst}
\end{equation}

\noindent
In terms of the Poisson bracket (\ref{PB}) we obtain
\begin{equation}\label{inv}
\{C_k,C_l\}= (B_k-B_l)[1-\sum_{j=1}^N\epsilon_jB_j\exp{(y_j)}]
\end{equation}
of course, under the conditions that the matrix $A$  be of the form (\ref{matrixform}).

\noindent
The formula above entails  that the differences $C_k-C_r, C_l-C_r$, $r$ being arbitrary but fixed, $k,l$ running from $1$ to $N$, provide a family of $N-1$ integrals of motion in involution.

\noindent
In terms of the $P,Q$  variables we have (up to an irrelevant additive constant):
\begin{equation}\label{CPQ}
C_k= P+B_k\left(Q -\sum_{j=1}^N {\mathcal C}_j\exp\left(P\xi_j+Q\eta_j\right)\right)=P-B_k{\mathcal H}%
\end{equation}

\noindent
whence it follows
\begin{enumerate}
\item
The quantities $C_k$ are functionally independent, since the Jacobian of the pair $C_k,C_l$ is $\ne 0$, being in fact equal to $(B_k-B_l)\frac{\partial S}{\partial Q}$, where
$S\equiv \sum_j {\mathcal C}_j\exp({P\xi_j+Q\eta_j)}$, but are not first integrals.
\item 
On the other hand.the differences $C_k-C_r$, $C_l-C_r$ ($r$ fixed, $k,l$ running from $1$ to $N$), Poisson commute between themselves and with the Hamiltonian, but are of course functionally 
dependent, among themselves and on the Hamiltonians, as they are simply given by $(B_r-B_k){\mathcal H}$.
\end{enumerate}



\noindent
Our conclusion is that the quantities $\tilde C_k \equiv C_k-C_r$ are genuine independent integrals of motion for the original system  with $N$ degrees of freedom.  However, once the original system is reduced on ${\mathcal I}$ so being transformed into a Hamiltonian system  with one degree of freedom, those quantities are no longer independent and in fact become proportional to the Hamiltonian, which stays as the unique integral motion for the reduced system.

