\begin{document}
	\begin{abstract}
		In this manuscript, we focus on the investigation of  the BS dimension and BS packing dimension under amenable group actions. Firstly, we  obtain a Bowen’s equation which illustrate the relation of  BS packing dimension to the  packing topological pressure under amenable group actions. Moreover, we establish the variational principle and inverse variational principle for BS dimension and BS packing dimension under amenable group actions.  Finally, we also get  an analogue of Billingsley’s type theorem for  BS packing dimension under amenable group actions.

	\end{abstract}

	\maketitle



	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\section{Introduction}

	Kolmogorov \cite{kolmogorov1958new} introduced measure-theoretical entropy for measure preserving dynamical systems. Later,
	the topological entropy was proposed by Adler, Konheim and McAndrew \cite{adler1965topological} to describe the topological complexity of dynamical systems.  Bowen \cite{bowen1971entropy} gave equivalent notions for topological entropy  via spanning sets and separated sets. Besides, Bowen \cite{bowen1973topological} gave a dimensional description of entropy, which was further investigated by Pesin and Pitskel \cite{pesin1984topological},
	these new perspectives led to fruitful results in dimension theory, ergodic theory, multifractal analysis and other fields of dynamical systems. The basic relation between topological entropy and measure-theoretic entropy is the variational principle which was proved by Goodwyn, Dinaburg and Goodman \cite{goodman1971relating,dinaburg1971connection,goodwyn1969topological}.  Feng et al. \cite{feng2012variational} proposed another dimension version entropy named
	the packing topological entropy, and they also established the variational principles for the Bowen topological entropy and the packing topological entropy. Wang \cite{wang2021some} proved two new variational principles for Bowen and packing topological entropies by introducing Bowen entropy and packing entropy of measures in the sense of Katok.
	 Zheng et al. \cite{zheng2016bowen} extended the Bowen entropy variational principle to amenable group actions. Huang  et al. \cite{huang2019bowen} extended the definition of Bowen topological entropy of subsets to continuous action of amenable groups on a compact metrizable space, and they proved the Bowen topological entropy of subsets for amenable group actions can be determined via the local entropies of measures. Dou et al. \cite{dou2023packing} extended the results of the packing topological entropy  in \cite{feng2012variational} to the packing topological entropy under amenable group actions. 


	Topological pressure, as a generalization of topological entropy, was introduced by Ruelle \cite{ruelie1973statistical} and extended to compact spaces with continuous transformations by Walters \cite{walters1982introduction}.  Later, inspired by the dimension theory \cite{pesin2008dimension},  Pesin and Piskel \cite{pesin1984topological} extended the notion of topological pressure on arbitrary subsets for general compact metric space.  Tang et al. \cite{tang2015variational}  generalized the Bowen entropy variational principle in \cite{feng2012variational}  to Pensin-Pitskel pressure. Following the ideas given by Feng and Huang \cite{feng2012variational} and  Wang \cite{wang2021some}, Zhong et al.
	further studied the variational principles of Pesin–Pitskel and packing topological pressures \cite{zhong2023variational}. Recently, Huang et al. \cite{huang2020variational} established the variational principle of Pesin-Pitskel pressure under amenable group actions.  Ding et al. \cite{ding2025packing} generalized the results of \cite{dou2023packing} to the packing topological pressure under amenable group actions. 


	In the setting of quasi-circles, Bowen \cite{bowen1979hausdorff} firstly found the Hausdorff dimension of certain compact set is exactly the unique root of the equation defined by the topological pressure of geometric potential function, which was later known as Bowen’s equation. After that, Bowen’s equation has been widely investigated. Barreira and Schmeling \cite{barreira2000sets}  got Bowen’s equation of BS dimension, which was proved to be the unique root of the equation defined by topological pressure of additive potential function. In 2012, Wang et al. \cite{wang2012variational} studied Bowen’s equation of BS packing dimension, which showed BS packing dimension is the unique root of the equation defined by packing topological pressure function. Motivated by the works of  \cite{barreira2000sets,bowen1979hausdorff,jaerisch2014induced}, Xing et al. \cite{xing2015induced}  proved that an important connection between   the classical topological pressure and the induced topological pressure  is Bowen’s equation, they also pointed out  that BS dimension is a special case of the induced topological pressure. Recently, 
	Yang et al. \cite{yang2022bowen} introduced the notion of BS metric mean dimension on arbitrary subsets, then established establish Bowen’s equations for Bowen upper metric mean dimension and variational principles for BS metric mean dimension.
	Ding et al. \cite{ding2023variational} studied the  BS dimension of subsets of finitely generated free semigroup actions and they proved BS dimension of subsets of finitely generated free semigroup actions is the unique root of the equation defined by Pesin–Pitskel topological pressure in \cite{xu2018variational}. Besiders, they also obtained a variational principle for BS dimension. Liu and Peng \cite{liu2025variational} introduced and studied the BS (Barreira-Schmeling) dimension for amenable group actions. They proved a Billingsley type theorem characterizing the BS dimension in terms of measure-theoretic quantities, and established a variational principle that connects the topological and measure-theoretic versions of the BS dimension. Yang \cite{yang2025variational} developed the BS-dimension of subsets using neutralized Bowen open balls instead of usual Bowen balls. He proved  a variational principle between neutralized BS-dimension and measure-theoretic BS-dimension.


	Let $(X, G)$ be a $G$-action topological dynamical system, where $X$ is a compact metric space with metric $d$ and $G$ is a topological group acting continuously on $X$. Throughout this manuscript we assume that $G$ is a countable infinite discrete amenable group. Denote $\mathbb{F}(G)$ the collection of all finite subsets of $ G$.
	Recall that a
	countable discrete group $G$ is amenable if there is a sequence of non-empty finite subsets
	$\{F_n\}_{n=1}^{\infty}$ of $G$ such that 
	$$\lim_{n \to \infty} \frac{|F_n \bigtriangleup gF_n|}{|F_n|}=0, \forall g\in G,$$
	and such $\{F_n\}_{n=1}^{\infty}$ is called as a Følner   sequence in $G$. Since $G$ is infinite, the sequence $|F_n|$ tends to infinity. Without loss of generality we can assume that $|F_n|$ increases when $n$ increases.  One can  refer to \cite{ornstein1987entropy,kerr2016ergodic} for some more details about amenable group actions. 


	Let $\{F_n\}_{n=1}^{\infty}$ be a Følner  sequence in $G$. Throughout this manuscript, we always let the Følner  sequence $\{F_n\}_{n=1}^{\infty}$ satisfying $|F_n| \to \infty(n \to \infty)$  be fixed unless otherwise specified. These researches in \cite{barreira2000sets,dou2023packing,wang2012variational,zhong2023variational,wang2021some} provide us with the motivation to explore the variational principles of BS dimension and BS packing dimension under amenable group actions. To see it, in this manuscript, we introduce the notions of BS dimension, BS packing dimension under amenable group actions and several corresponding  measure-theoretic BS dimension. Subsequently, we obtain several variational principles and inverse variational principles, and we list them as follows.


	\begin{theorem}\label{m1}
		Let  $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function and  $H$ be a non-empty compact subset of $X$.  Then 
		\begin{align*}
			dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)&=\sup\{\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu\in {M}(X),\mu(H)=1\}\\
			&=\sup\{dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu\in {M}(X),\mu(H)=1\}\\
			&=\sup\{dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu\in {M}(X),\mu(H)=1\},
		\end{align*}
		where $dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)$, $\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)$, $dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)$ and $dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi)$ denote BS dimension of $H$, lower measure-theoretic BS dimension of $\mu$, BS dimension of $\mu$ and BS dimension in the sense of Katok of $\mu$, respectively (more details about these notions in section \ref{Preliminary}).
	\end{theorem}	


	\begin{theorem}\label{m2}
		Let  $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function and  $\mu\in {M}(X)$. Then
		$$
		\begin{aligned}
			dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)&=dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi)\\
			&=  \inf \left\{dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi):  \mu(H)=1\right\}.
		\end{aligned}
		$$
	\end{theorem}

	\begin{theorem}\label{m3}
		Let $\{F_n\}_{n=1}^{\infty}$ be a Følner  sequence in G satisfying $\lim_{n \to \infty}\frac{|F_n|}{\log n}=\infty.$ Then for any non-empty analytic subset H of X and a positive continuous function  $\Phi: X \rightarrow \mathbb{R} $.
		Then 
		\begin{align*}
			dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)&=\sup\{\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu \in \mathcal{M} (X),\mu(H)=1\}\\
			&=\sup\{dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon):\mu \in \mathcal{M} (X),\mu(H)=1\}\\
			&=\sup\{dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu \in \mathcal{M} (X),\mu(H)=1\},
		\end{align*}
		where $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)$, $\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)$, $dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)$ and $dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi)$ denote  BS  packing dimension of $H$, upper measure-theoretic BS dimension of $\mu$, BS  packing dimension of $\mu$ and BS packing dimension in the sense of Katok of $\mu$, respectively (more details about these notions in section \ref{packing dimension}).
	\end{theorem}

	\begin{theorem}\label{m4}
		Let  $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function and  $\mu\in {M}(X)$. Then
		$$
		\begin{aligned}
			dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)&=dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi)\\
			&=  \inf \left\{dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi):  \mu(H)=1\right\}.
		\end{aligned}
		$$
	\end{theorem}

	This manuscript is organized as follows. In Section 2, we introduce the notions of measure-theoretic BS dimension, BS dimension  and BS dimension in the sense of Katok under amenable group actions. The proofs of main results related to BS packing dimension and related properties are given in Section 3 and Section 4. In Section 5 and 6, we turn to investigate the BS packing dimension, and we prove the variational principle, inverse variational principle and Billingsley’s type theorem for BS packing dimension under amenable group actions.



	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\section{BS dimension under amenable group actions}\label{Preliminary}
	In this section, we introduce some notions to appear in this manuscript.
	Let  $\mathcal{C}(X, \mathbb{R})$  denote the Banach space of all continuous real-valued functions on  $X $ equipped with the supremum norm, then for  $\Phi \in \mathcal{C}(X, \mathbb{R})$. 




	Given $F\in \mathbb{F}(G)$, $x,y \in X$, the Bowen metric $d_F$  on $X$ is defined by  $d_F(x,y):=\max_{g \in F} \limits d(gx,gy).$ Then  \emph{Bowen open  ball} of radius $\epsilon$  in the metric $d_F$ around $x$ is   given by 
	$$B_F(x,\epsilon)=\{y\in X: d_F(x,y)<\epsilon\},$$
	and \emph{Bowen closed  ball }is given by
	$$\overline B_F(x,\epsilon)=\{y\in X: d_F(x,y)\leq\epsilon\}.$$
	Given $\Phi\in C(X,\mathbb{R})$, where $C(X,\mathbb{R})$ denotes the set of all continuous functions, define
	\begin{align*}
		\Phi_F(x)&=\sum_{g \in F}\Phi(gx),\\
		\Phi_F(x,\epsilon)&=\sup_{y \in B_F(x,\epsilon)}\Phi_F(y),\\
		\overline \Phi_F(x,\epsilon)&=\sup_{y \in \overline B_F(x,\epsilon)}\Phi_F(y).
	\end{align*}




	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Pesin-Pitskel topological pressure of subsets}\cite{liu2025variational}
	Let  $H\subset X$ be a non-empty subset, $\epsilon>0$, $\Phi \in \mathcal{C}(X, \mathbb{R})$, $N\in \mathbb{N}$ , $s \in \mathbb{R}$. 
	Put
	$$M^B(N,s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)=\inf\{\sum_i\limits  e^{-s\lvert F_{n_i} \rvert +\Phi_{F_{n_i}}(x_i)}\},$$
	where the infimum  is taken over all  finite or countable cover $\{B_{F_{n_i}}(x_i,\epsilon)\}_{i\in I}$ of $H$ with $n_i \geq N.$
	Since  $M^B(N,s,\epsilon,H,\{F_n\},\Phi)$ is non-decreasing when $N$ increases, the following limit exists.
	\begin{align*}
		M^B(s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)&=\lim_{N\to \infty}M^B(N,s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi),\\
		P^B(\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)&=\sup{\{s:M^B (s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty\}}\\
		&=\inf{\{s:M^B (s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)=0\}},\\
		P^B_H(\{F_n\}_{n=1}^{\infty},\Phi)&=\lim_{\epsilon \to 0}P^B(\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi).
	\end{align*}
	$P_H^B(\{F_n\}_{n=1}^{\infty},\Phi)$ is called {\it Pesin-Pitskel topological pressure} of the set  $H$ along  $\{F_n\}_{n=1}^{\infty}$ with respect to $\Phi.$  



	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Packing topological pressure of subsets}\cite{ding2025packing}
	Let $H\subset X$ be a non-empty subset, $\epsilon>0$, $\Phi \in \mathcal{C}(X, \mathbb{R})$, $N\in \mathbb{N}$, $s \in \mathbb{R}$.
	Put
	$$M^P(N,s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)=\sup\{\sum_i\limits  e^{-s\lvert F_{n_i} \rvert +\Phi_{F_{n_i}}(x_i)}\},$$
	where the supremum  is taken over all  finite or countable disjoint $\{\overline B_{F_{n_i}}(x_i,\epsilon)\}_{i\in I}$ with $n_i \geq N,~x_i \in H.$  Since $M^P(N,s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)$ is decreasing when $N$ increases,
	the following limit exists.
	Set
	$$M^P(s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{N\to \infty}M^P(N,s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi).$$
	Put
	\begin{align*}
		M^\mathcal{P} (s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)&=\inf \{{\sum_{i=1}^{\infty}M^P(s,\epsilon,H_i,\{F_n\}_{n=1}^{\infty},\Phi):H \subset \cup_{i=1}^{\infty} H_i}\},\\
		P^P(\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)&=\sup{\{s:M^\mathcal{P} (s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty\}}\\
		&=\inf{\{s:M^\mathcal{P} (s,\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)=0\}},\\
		P^P_H(\{F_n\}_{n=1}^{\infty},\Phi)&=\lim_{\epsilon \to 0}P^P(\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi).
	\end{align*}

	Since $P^P(\epsilon,H,\{F_n\}_{n=1}^{\infty},\Phi)$ is increasing when $\epsilon$ decreases, the above limit exists. Then we call $P^P_H(\{F_n\}_{n=1}^{\infty},\Phi)$ {\it packing topological pressure} of the set $H$ along $\{F_n\}_{n=1}^\infty$  with respect to $f.$
	When $\Phi=0$,  $P^P_H(\{F_n\}_{n=1}^{\infty},0)$ is packing topological entropy $h_{top}^{P}(H,\{F_n\}_{n=1}^{\infty})$ given by Dou, Zheng and Zhou \cite{dou2023packing}.


	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{BS dimension of subsets}  
	In this subsection, we offer a notion of BS dimension for arbitrary subsets  as follows.
	Let  $H\subset X$ be a non-empty subset and $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function. Given $\epsilon>0$, $N\in\mathbb{N}$, $s>0$, put
	$$M^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\inf\sum_{i\in I} \exp{[-s\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)]},$$
	where the infimum is taken over all finite or countable covers $\{B_{F_{n_i}}(x_i,\epsilon)\}_{i\in I}$ of $H$ with $n_i\geq N$ and $x_i\in X$. 

	Then the limit $M_{\epsilon}^{s}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{N\rightarrow \infty} M_{N,\epsilon}^{s}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ exists since $M^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ is non-decreasing when $N$ increases. The quantity $M^s_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ has a critical value of parameter $s$ jumping from $\infty$ to $0$. The critical value is defined by 
	$$M_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)= \inf\{s:M^s_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=0\}=\sup\{s:M^s_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty\}.$$


	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{definition}\label{bs}\cite[Definition 2.2]{liu2025variational}
		The {\it BS dimension  on the set $H$} along $\{F_n\}_{n=1}^\infty$ is defined by 
		$$dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{\epsilon\rightarrow 0} M_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$$
		When $\Phi=1$, then $dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^\infty,1)$ is just the {\it Bowen’s topological entropy on the set $H$} in \cite{zheng2016bowen}.
	\end{definition}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	Notice that the  Definition \ref{bs} can be given in an alternative way. Given $B_{F_{n_i}}(x_i,\epsilon)$, we can replace $\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{n_i}(y)$ by $\Phi_{n_i}(x_i)$ in Definition \ref{bs} to give a new definition. We denote by $\widetilde{M}^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$, $\widetilde{M}^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$,  $\widetilde{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ and $\widetilde{dim}_H^{\widetilde{BS}}(T,\{F_n\}_{n=1}^{\infty},\Phi)$ the new corresponding quantities of $M^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$, $M^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$, $M_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ and $dim_H^{\widetilde{BS}}(T,\{F_n\}_{n=1}^{\infty},\Phi)$, respectively. 
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{proposition}\label{inter}
		Let  $H\subset X$ be a non-empty subset and $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function. Then $$dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=\widetilde{dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{\epsilon\rightarrow 0}\widetilde{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$$
	\end{proposition}
	\begin{proof}
		It is clear that  $dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)\leq \widetilde{dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi).$

		Conversely, we shall prove that $dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)\geq \widetilde{dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi).$
		Given $s\geq 0$, select any finite or countable covers $\{B_{F_{n_i}}(x_i,\epsilon)\}_{i\in I}$ of $H$ with $n_i\geq N$ and $x_i\in X$.  For any $x,y\in X$, let   $\hat{\Phi}=\min_{x\in X}\Phi(x)$
		and $\Phi_{\epsilon}=\sup\{|\Phi(x)-\Phi(y)|: d(x,y)<2\epsilon\}.$ Notice that
		\begin{align}\label{equ2.1}
			\sup_{y\in B_{F_{n}}(x,\epsilon)}\Phi_{F_{n}}(y)&= \sup_{y\in B_{F_{n}}(x,\epsilon)}[\Phi_{F_{n}}(y)-\Phi_{F_{n}}(x)+\Phi_{F_{n}}(x)]\\
			& \leq \sup_{y\in B_{F_{n}}(x,\epsilon)}[|\Phi_{F_{n}}(y)-\Phi_{F_{n}}(x)|+\Phi_{F_{n}}(x)]\label{equ2.2}\\
			&\leq |F_{n}|\Phi_{\epsilon}+\Phi_{F_{n}}(x).\label{equ2.3}
		\end{align}
		Thus, for $s\geq 0$, we derive that 
		\begin{align*}
			\sum_{i\in I} \exp{[-s\Phi_{F_{n_i}}(x_i)]}&\leq \sum_{i\in I} \exp{[-s(\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)-|F_{n_i}|\Phi_{\epsilon})]}\\&
			\leq \sum_{i\in I} \exp{[-s(\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)-\frac{\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)}{\hat{\Phi}}\Phi_{\epsilon}]}\\
			&=\sum_{i\in I} \exp{[-s\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)(1-\frac{\Phi_{\epsilon}}{\hat{\Phi}})]}.  
		\end{align*}

		It follows that,
		$$\widetilde{M}^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq M^{s(1-\frac{\Phi_{\epsilon}}{\hat{\Phi}})}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$$
		Letting $N\to \infty$, we have 
		$$\widetilde{M}^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq M^{s(1-\frac{\Phi_{\epsilon}}{\hat{\Phi}})}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$$
		This implies that 
		$$(1-\frac{\Phi_{\epsilon}}{\hat{\Phi}})\widetilde{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq {M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$$
		Taking $\epsilon\to 0$, one has $dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)\geq \widetilde{dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi).$



	\end{proof}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


	By the theory of Carath{\'e}odory-Pesin structure, the proof of the  following proposition is standard, one can refer to \cite{pesin2008dimension}.
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{proposition} \label{prop 2.21}	
		(1) If $H_1\subset H_2 \subset X$, then $$dim_{H_1}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)\leq dim_{H_2}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi).$$

		(2) If $H=\cup_{i\geq 1}H_i$ is a union of  sets $H_i\subset X$, then $$dim_{H}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=\sup_{i\geq 1}dim_{H_i}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi).$$

	\end{proposition}
