	\subsection{Local  measure-theoretic BS dimension}
	We denote the set of all Borel probability measures on $X$ by $M(X)$.
	Let $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function, $\mu\in M(X)$, $\epsilon>0$ and $x\in X$, define
	$$\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,x)=\lim_{\epsilon\rightarrow 0}\liminf_{n\rightarrow \infty} \frac{-\log \mu(B_{F_{n}}(x,\epsilon))}{\Phi_{F_{n}}(x)},$$
	and
	$$\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)=\int\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,x)d\mu.$$
	We say $\underline{P}_{\mu}^{\widetilde{BK}}(T,\Phi)$ is  the {\it lower  measure-theoretic BS dimension of $\mu$} (see \cite[Definition 2.3]{liu2025variational}).


	Define
	$$\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,x)=\lim_{\epsilon\rightarrow 0}\limsup_{n\rightarrow \infty} \frac{-\log \mu(B_{F_{n}}(x,\epsilon))}{\Phi_{F_{n}}(x)},$$
	and
	$$\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)=\int\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,x)d\mu.$$
	We say $\underline{P}_{\mu}^{\widetilde{BK}}(T,\Phi)$ is  the {\it upper  measure-theoretic BS dimension of $\mu$} (see \cite[Definition 2.3]{liu2025variational}).


	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{remark}
		(1) When $\Phi=1$, then $\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},1)$ is just the {\it measure-theoretical lower entropy of Borel probability measure $\mu$} in \cite{zheng2016bowen}; $\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},1)$ is just the {\it measure-theoretical upper entropy of Borel probability measure $\mu$} given in \cite{dou2023packing}.


		(2) Notice that by  Monotone Convergence Theorem, we have 

		\begin{align*}
			\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)&=\int\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,x)d\mu\\
			&=\int \lim_{\epsilon\rightarrow 0}\liminf_{n\rightarrow \infty} \frac{-\log \mu(B_{F_{n}}(x,\epsilon))}{\Phi_{F_{n}}(x)} d\mu\\
			&=\lim_{\epsilon\rightarrow 0}\int \liminf_{n\rightarrow \infty} \frac{-\log \mu(B_{F_{n}}(x,\epsilon))}{\Phi_{F_{n}}(x)} d\mu,
		\end{align*}
		and
		\begin{align*}
			\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)&=\int\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,x)d\mu\\
			&=\int \lim_{\epsilon\rightarrow 0}\limsup_{n\rightarrow \infty} \frac{-\log \mu(B_{F_{n}}(x,\epsilon))}{\Phi_{F_{n}}(x)} d\mu\\
			&=\lim_{\epsilon\rightarrow 0}\int \limsup_{n\rightarrow \infty} \frac{-\log \mu(B_{F_{n}}(x,\epsilon))}{\Phi_{F_{n}}(x)} d\mu.
		\end{align*}
		Hence, we can define the above notions by an alternative way, put

		$$\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon,x)=\liminf_{n\rightarrow \infty} \frac{-\log \mu(B_{F_{n}}(x,\epsilon))}{\Phi_{F_{n}}(x)},$$
		and
		$$\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=\int\underline{P}_{\mu}^{\widetilde{BK}}(T,\Phi,\epsilon,x)d\mu.$$
		Then, the {\it lower  measure-theoretic BS dimension of $\mu$} is given by
		$$\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{\epsilon\rightarrow 0}\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon).$$



		Let
		$$\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon,x)=\limsup_{n\rightarrow \infty} \frac{-\log \mu(B_{F_{n}}(x,\epsilon))}{\Phi_{F_{n}}(x)},$$
		and
		$$\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=\int\overline{P}_{\mu}^{\widetilde{BK}}(T,\Phi,\epsilon,x)d\mu.$$
		Then, the {\it upper  measure-theoretic BS dimension of $\mu$} is defined by
		$$\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{\epsilon\rightarrow 0}\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon).$$
	\end{remark}
