	\subsection{BS dimension in the sense of Katok}\label{subsec 2.6}
	Following the idea of Katok \cite{katok1980lyapunov}, Wang \cite{wang2021some}  established a variational principle for Bowen  topological entropy via introducing Bowen entropy of measures in the sense of Katok. Later, Zhong et al. \cite{zhong2023variational} generalized Wang's results to topological pressure. 
	Their works motivate us to  explore the variational principles of BS dimension via introducing the notion of BS dimension in the sense of Katok as follows.


	Given $\epsilon>0$, $s>0$, $N\in\mathbb{N}$, $\mu\in M(X)$, $\delta\in (0,1)$ and $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function. Put 
	\begin{equation}\label{eq22}
		\Lambda^s_{N,\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=\inf\sum_{i\in I}\exp{[- s\Phi_{n_i}(x_i)]},
	\end{equation}
	where the infimum is taken over all finite or countable covers $\{B_{F_{n_i}}(x_i,\epsilon)\}_{i\in I}$ so that $\mu(\bigcup_{i\in I}B_{F_{n_i}}(x_i,\epsilon))>1-\delta$ with $n_i\geq N$ and $x_i\in X$.

	Let $\Lambda^s_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=\lim_{N\rightarrow \infty} \Lambda^s_{N,\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)$. There is a critical value of $s$ for $\Lambda^s_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)$ jumping from $\infty$ to $0$. Define the critical value as 
	\begin{align*}
		\Lambda_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)&=\inf\{s:\Lambda^s_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=0\}\\
		&=\sup\{s:\Lambda^s_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=\infty\}.
	\end{align*}
	Let $$dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=\lim_{\delta\rightarrow 0} \Lambda_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta).$$ 
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{definition}\label{def 2.6}
		The {\it BS dimension in the sense of Katok of $\mu$ along $\{F_n\}_{n=1}^\infty$} is defined as 
		$$dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{\epsilon \rightarrow 0}dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon).$$
	\end{definition}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{definition}\label{def 2.7}
		Moreover, let
		$$dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=\lim_{\delta\rightarrow 0} \inf\{\widetilde{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi):\mu(H)\geq 1-\delta\}.$$
		The {\it BS dimension of $\mu$ along $\{F_n\}_{n=1}^\infty$ }  is given by  
		$$dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{\epsilon\rightarrow 0}dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon).$$
	\end{definition}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%	

	\begin{remark}\label{rem2.8}
		With similar arguments in Propostion \ref{inter}, we have 

		(1)  $$dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{\epsilon\rightarrow 0}\lim_{\delta\rightarrow 0} \inf\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi):\mu(H)\geq 1-\delta\}.$$

		(2) if we replace $\Phi_{n_i}(x_i)$ by $\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)$ in equation (\ref{eq22}), we can define new function $\widetilde{\Lambda}$.
		For any $\epsilon > 0$ and $0 <\delta<1$, we denote the  critical value by  $\widetilde{\Lambda}_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)$, then we have 
		$$dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=\lim_{\delta\rightarrow 0} \lim_{\delta\rightarrow 0} \widetilde{\Lambda}_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta).$$ 

		(3) In fact, Definition \ref{def 2.6} and Definition \ref{def 2.7} are natural generalizations given in \cite{wang2021some}.
	\end{remark}

	The next result reveals  that the {\it BS dimension of $\mu$ along $\{F_n\}_{n=1}^\infty$}  is equal to \it BS dimension in the sense of Katok of $\mu$ along $\{F_n\}_{n=1}^\infty$.

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{theorem}\label{equ} Let $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function and $\mu\in M(X)$.
		For any $\epsilon>0$, then $dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon).$ Moreover, we have $dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi).$
	\end{theorem}

	\begin{proof}
		First, we  show that  $dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) \leq dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)$. For any  $n \in \mathbb{N}, 0<\epsilon,0<\delta<1 $, and $H\subset X$  with  $\mu(H) \geq 1-\delta $, then one has
		$$
		\Lambda_{N,\epsilon}^s(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)\leq \widetilde{M}_{N,\epsilon}^s(H,\{F_n\}_{n=1}^{\infty},\Phi).
		$$

		Letting  $N \rightarrow \infty$,   we get  
		$$
		\Lambda_{\epsilon}^s(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)\leq \widetilde{M}_{\epsilon}^s(H,\{F_n\}_{n=1}^{\infty},\Phi).
		$$

		This indicates that
		$$
		\Lambda_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)\leq \widetilde{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).
		$$
		and then 
		$$
		\Lambda_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta) \leq \inf \left\{\widetilde{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H) \geq 1-\delta\right\} .
		$$
		Hence, taking $ \delta \rightarrow 0$, we deduce that  $$dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) \leq dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon).$$

		On the other hand, we shall prove  $dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) \geq dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)$, set \\ $\zeta=dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)$. For any  $s>0 $,   exists  $\delta_{s} $ so that
		$$
		\Lambda_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)<\zeta+s, \forall \delta<\delta_{s} .
		$$
		This yields that  $ \Lambda_{\epsilon}^{\zeta+s}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=0 $. For any  $N \in \mathbb{N} $, we can find a sequence of  $\delta_{N, m}$  with  $\lim \limits_{m \rightarrow \infty} \delta_{N, m}=0$  and   $\{B_{F_{n_i}}(x_{i}, \epsilon)\}_{i \in I_{N, m}}$  such that  $x_{i} \in X, n_{i} \geq N ,  \mu\left(\cup_{i \in I_{N, m}} B_{F_{n_i}}(x_{i}, \epsilon)\right) \geq 1-\delta_{N, m} $, and
		$$
		\sum_{i \in I_{N, m}} e^{-(\zeta+s)\Phi_{n_i}(x_i)} \leq \frac{1}{2^{m}} .
		$$

		Let
		$$
		H_{N}=\bigcup_{m \in \mathbb{N}} \bigcup_{i \in I_{N, m}} B_{F_{n_i}}(x_{i}, \epsilon).
		$$
		Then  $\mu\left(H_{N}\right)=1 $ and
		${M}_{N,\epsilon}^{\zeta+s}(H_{N},\{F_n\}_{n=1}^{\infty},\Phi)\leq1.$
		Let  $H=\cap_{N \in \mathbb{N}} H_{N} $. Thus  $\mu\left(H\right)=1$  and
		$$
		\widetilde{M}_{N,\epsilon}^{\zeta+s}(H,\{F_n\}_{n=1}^{\infty},\Phi) \leq \widetilde{M}_{N,\epsilon}^{\zeta+s}(H_{N},\{F_n\}_{n=1}^{\infty},\Phi) \leq 1, \forall N \in \mathbb{N}.
		$$
		This indicates that
		$$
		\widetilde{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi) \leq \zeta+s.
		$$

		Thus,
		$$
		dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=\lim_{\delta\rightarrow 0} \inf\{\widetilde{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi):\mu(H)\geq 1-\delta\} \leq \zeta+s.
		$$
		Since $ s$ is arbitrary, then we have $$dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) \leq \zeta=dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) .$$ 

		Therefore,  we have 
		$$dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) =dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)$$ 
		and $$dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi).$$

	\end{proof}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



	Next, we show that  the BS dimension in the sense of Katok along $\{F_n\}_{n=1}^\infty$ is a upper bound of lower  measure-theoretic BS dimension along $\{F_n\}_{n=1}^\infty$. Moreover, by Theorem \ref{equ}, we also have that BS dimension of Borel probability measure is also a upper bound of lower  measure-theoretic BS dimension.
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{proposition}\label{prop 2.5}
		Let   $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function and  $\mu \in {M}(X)$.  Then  $$\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)\leq dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi).$$
	\end{proposition}
	\begin{proof}
		Assume that  $\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,2\epsilon)>0$.  We define 
		$$E_N=\{x\in X:  \mu (B_{F_{n}}(x, 2\epsilon))<\exp(-s\Phi_{F_{n}}(x))~ \text{for all}~n\geq N\}.$$
		Let  $s<\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,2\epsilon)$.  Then there  exists $N_0$  so that $\mu(E_{N_0})>0$. Fix  $\delta_0=\frac{1}{2}\mu(E_{N_0})>0$. Let $\{B_{F_{n_i}}(x_i,\epsilon)\}_{i\in I}$ be a  finite or countable cover  so  that  $\mu (\cup_{i\in I}B_{F_{n_i}}(x_i, \epsilon))> 1-\delta_0$  with $n_i \geq N_0,  x_i\in X$. Then $\mu(E_{N_0}\cap  \cup_{i\in I}B_{F_{n_i}}(x_i, \epsilon))\geq \frac{1}{2}\mu(E_{N_0})>0$. Denote by $I_1=\{i\in I: E_{N_0}\cap  B_{F_{n_i}}(x_i, \epsilon) \not =\emptyset\}$. For every $i \in I_1$, we choose $y_i \in E_{N_0}\cap  B_{F_{n_i}}(x_i, \epsilon)$ such that $$E_{N_0}\cap  B_{F_{n_i}}(x_i, \epsilon)\subset  B_{F_{n_i}}(y_i, 2\epsilon).$$ Notice that $ B_{F_{n_i}}(x_i, \epsilon)\subset  B_{F_{n_i}}(y_i, 2\epsilon).$
		Hence, by inequalities (\ref{equ2.1})-(\ref{equ2.3}), one has 
			\begin{align*}
			\sup_{y\in B_{F_{n}}(x,\epsilon)}\Phi_{F_{n}}(y)\leq |F_{n}|\Phi_{\epsilon}+\Phi_{F_{n}}(x)\leq \frac{\Phi_{F_{n}}(x)}{\hat{\Phi}}\Phi_{\epsilon}+\Phi_{F_{n}}(x)=(1+\frac{\Phi_{\epsilon}}{\hat{\Phi}})\Phi_{F_{n}}(x).
		\end{align*}
		Therefore, 


		we get that 
		$$
		\begin{aligned}
			\sum_{i\in I}\exp{[- s\frac{1}{1+\frac{\Phi_{\epsilon}}{\hat{\Phi}}}\sup_{z\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{n_i}(z)]}&\geq \sum_{i\in I_1}\exp{[- s\frac{1}{1+\frac{\Phi_{\epsilon}}{\hat{\Phi}}}\sup_{z\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(z)]}\\
			&\geq \sum_{i\in I_1}\exp{[- s\frac{1}{1+\frac{\Phi_{\epsilon}}{\hat{\Phi}}}\Phi_{F_{n_i}}(y_i)}(1+\frac{\Phi_{\epsilon}}{\hat{\Phi}})]\\
			&=\sum_{i\in I_1}\exp{[- s\Phi_{F_{n_i}}(y_i)}]\\
			&\geq \sum_{i\in I_1}  \mu(B_{F_{n_i}}(y_i, 2\epsilon))\\
			&\geq \frac{\mu(E_{N_0})}{2}>0,
		\end{aligned}
		$$
		Thus,  $\widetilde{\Lambda}_{\epsilon}^{s\frac{1}{1+\frac{\Phi_{\epsilon}}{\hat{\Phi}}}}(\mu, \{F_n\}_{n=1}^{\infty},\Phi, \delta_0)\geq\widetilde{\Lambda}_{N_0,\epsilon}^{s\frac{1}{1+\frac{\Phi_{\epsilon}}{\hat{\Phi}}}}(\mu,\{F_n\}_{n=1}^{\infty},\Phi, \delta_0)>0$ and hence $\widetilde{\Lambda}_{\epsilon}(\mu, \{F_n\}_{n=1}^{\infty},\Phi, \delta_0)\geq s\frac{1}{1+\frac{\Phi_{\epsilon}}{\hat{\Phi}}}.$ Consequently, $ dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) \geq s\frac{1}{1+\frac{\Phi_{\epsilon}}{\hat{\Phi}}}$ by Remark \ref{rem2.8}. 

		Hence, taking $s \to  \underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,2\epsilon)$ and $\epsilon\to 0$, we then obtain that $\underline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)\leq dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi)$. The proof is completed.
	\end{proof}
