	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\section{Variational principle and inverse variational principle for BS dimension}\label{proof}

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%	
	\subsection{ Weighted BS dimension}


	Let  $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function and $g:X\rightarrow \mathbb{R}$ be a bounded real-valued function on $X$. Given $s>0,N\in\mathbb{N}$ and $\epsilon>0$. Define
	$$W^s_{N,\epsilon}(g,\{F_n\}_{n=1}^{\infty},\Phi)=\inf\sum_{i\in I}c_i \exp{[-s\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)]},$$
	where the infimum is taken over all finite or countable families $\{(B_{F_{n_i}}(x_i,\epsilon),c_i)\}_{i\in I}$ with $0<c_i<\infty$, $x_i \in X$ and $n_i\geq N$ so that 
	$$\sum_{i\in I}c_i \chi_{B_{n_i}(x_i,\epsilon)}\geq g,$$ 
	where $\chi_A$ denotes the characteristic function of $A$.

	Let $H\subset X$ be a non-empty subset. Let $W^s_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)= W^s_{N,\epsilon}(\chi_H,\{F_n\}_{n=1}^{\infty},\Phi)$. Let $W^s_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{N\rightarrow \infty} W^s_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$. There is a critical value of $s$ such that the quantity $W^s_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ jumps from $\infty$ to $0$. Denote this critical value as 
	$$W_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\inf\{s:W^s_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=0\}=\sup\{s:W^s_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty\}.$$
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{definition}\label{weighted}\cite{liu2025variational}
		The {\it  weighted BS dimension on the set $H$ along $\{F_n\}_{n=1}^{\infty}$} is defined as 
		$$dim_H^{\widetilde{BS,WB}}(\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{\epsilon\rightarrow 0}  W_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$$
	\end{definition}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%		
	Analogous to Definition \ref{bs},  the notion of weighted BS dimension along $\{F_n\}_{n=1}^{\infty}$ can also be given in an alternative way. Given $B_{F_{n_i}}(x_i,\epsilon)$, we can replace $\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)$ by $\Phi_{F_{n_i}}(x_i)$ in Definition \ref{weighted} to give a new definition. We denote by $\widetilde{W}^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$, $\widetilde{W}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ and $\widetilde{dim}_H^{\widetilde{BS,WB}}(\{F_n\}_{n=1}^{\infty},\Phi)$ the new corresponding quantities of $W^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$, $W_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ and $dim_H^{\widetilde{BS,WB}}(\{F_n\}_{n=1}^{\infty},\Phi)$, respectively.


	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%	
	\begin{proposition}\label{inter-1}
		Let   $H\subset X$ be a non-empty subset and $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function. Then $${dim}_H^{\widetilde{BS,WB}}(\{F_n\}_{n=1}^{\infty},\Phi)=\widetilde{dim}_H^{\widetilde{BS,WB}}(\{F_n\}_{n=1}^{\infty},\Phi).$$
	\end{proposition}
	\begin{proof}
		It is similar to Proposition \ref{inter}, here we omit it.

	\end{proof}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%	




	The following covering lemma can help us to build the equivalence of the BS dimension and  the weighted BS dimension under amenable group actions.
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{lemma}\cite{wang2021variational}\label{cover}
		Let $(X,d)$ be a compact metric space. Let $r>0$ and $\mathcal{B}=\{B(x_i,r)\}_{i\in I}$ be a family of open balls of $X$. Define 
		\begin{align*}
			I(i)=\{j\in I:B(x_j,r)\cap B(x_i,r)\not=\emptyset\}.
		\end{align*}
		Then there exists a finite subset $J\subset I$ such that for any $i,j\in J$ with $i\not =j$, $I(i)\cap I(j)=\emptyset$ and 
		$$\bigcup_{i\in I}B(x_i,r)\subset \bigcup_{j\in J}B(x_j,5r).$$
	\end{lemma}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	The proof of the following result is inspired by \cite{tang2015variational,feng2012variational,wang2012variational}. N It is worth noting that Liu and Peng also proved similar results in \cite[Proposition 4.1]{liu2025variational}.  Here, we provide  a simpler  proof by using Lemma \ref{cover}.
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{proposition}\label{equality-1}
		Let   $H$ be a non-empty subset of $X$, $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function and $\{F_n\}_{n=1}^{\infty}$ be a Følner  sequence satisfying $\lim\limits_{n\to \infty}\frac{|F_{n}|}{\log n}=\infty$. Then for  $\theta>0$, $s>0$ there exists $\epsilon_0>0$ such that for $0<\epsilon<\epsilon_0$, there exists $N_0\in\mathbb{N}$, such that for any $N\geq N_0$,
		$$\widetilde{M}^{s+\theta}_{N,5\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq W^s_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq M^s_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$$
		Therefore, we have ${dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)={dim}_H^{\widetilde{BS,WB}}(\{F_n\}_{n=1}^{\infty},\Phi)$. 
	\end{proposition}


	\begin{proof}
		The inequality $W^s_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq M^s_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ is directly from the definition. Next we show that $\widetilde{M}^{s+\theta}_{N,\frac{\epsilon}{2}}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq W^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$.
		Let $\hat{\Phi}=\min_{x\in X}\Phi(x)$. Since  $\Phi: X\rightarrow \mathbb{R}$ is a  positive continuous function, then we have 
		$$\lim_{\epsilon \rightarrow 0}\limsup_{n\to \infty}\frac{\Phi_{F_n}(\epsilon)}{|F_n|}=0.$$
		where $\Phi_{F_{n}}(\epsilon)=\sup\{|\Phi_{F_{n}}(x)-\Phi_{F_{n}}(y)|:d_{F_n}(x,y)<2\epsilon\}.$
		Hence, for $\theta>0$, there exists $\epsilon_0>0$ such that for any $0<\epsilon<\epsilon_0$, there is $N_0$ such that for any $N>N_0$, we have 
		$$\Phi_{F_{n}}(\epsilon)<\frac{|F_n|\theta\hat{\Phi}}{4s}.$$

		Fix $N>N_0$ large enough such that  $\frac{n^2}{e^{|F_n|\theta\hat{\Phi}/2}}<1$ for all $n\geq N$. Let $t>0$ and $n\geq N$. Let $\{(B_{F_{n_i}}(x_i,\epsilon),c_i)\}_{i\in I}$ with $0<c_i<\infty, x_i\in X, n_i\geq N$ be a finite or countable family satisfying $\sum_{i\in I} c_i\chi_{B_{F_{n_i}}(x_i,\epsilon)}\geq \chi_{H}$. Define $I_n=\{i\in I:n_i=n\}$ for $n\geq N$. Define 
		\begin{align}
			H_{n,t}=\{z\in H:\sum_{i\in I_n}c_i\chi_{B_{F_{n}}(x_i,\epsilon)}(z)>t\}
		\end{align}
		and
		\begin{align}
			I_n^t=\{i\in I_n:B_{F_{n}}(x_i,\epsilon)\cap H_{n,t}\not=\emptyset\}.
		\end{align}
		It follows that $H_{n,t}\subset \bigcup_{i\in I_n^t} B_{F_{n}}(x_i,\epsilon)$. Let $\mathcal{B}=\{B_{F_{n}}(x_i,\epsilon)\}_{i\in I_n^t}$. By Lemma \ref{cover}, there exists a finite subset $J\subset I^t_n$ such that
		$$\bigcup_{i\in I_n^t} B_{F_{n}}(x_i,\epsilon)\subset \bigcup_{j\in J} B_{F_{n}}(x_j,5\epsilon)$$
		and for any $i,j\in J$ with $i\not= j$, one has $I_n^t(i)\cap I_n^t(j)=\emptyset$, where $$I_n^t(i)=\{j\in I_n^t:B_{F_{n}}(x_j,\epsilon)\cap B_{F_{n}}(x_i,\epsilon)\not=\emptyset\}.$$ For each $j\in J$, choose $y_j\in B_{F_{n}}(x_j,\epsilon)\cap H_{n,t}$. Then $\sum_{i\in I_n^t}c_i\chi_{B_{F_{n}}(x_i,\epsilon)}(y_j)>t$ and hence $\sum_{i\in I_n^t(j)} c_i>t$.


		For each $j\in J$ and $i\in I_n^t(j)$, there exists $z_i\in B_{F_{n}}(x_j,\epsilon)\cap B_{F_{n}}(x_i,\epsilon)$. Thus for each $j\in J$, 
		\begin{align*}
			\sum_{i\in I_n^t(j)} c_i\exp{[-s\Phi_{F_{n}}(z_i)]}&\geq\sum_{i\in I_n^t(j)} c_i\exp{[-s(\Phi_{F_{n}}(x_j)+\frac{|F_{n}|\theta\hat{\Phi}}{4s})]}\\
			&> t\exp{[-s(\Phi_{F_{n}}(x_j)+\frac{|F_{n}|\theta\hat{\Phi}}{4s})]}           \\
			&>t\exp{[-s(\Phi_{F_{n}}(x_j)+\frac{\Phi_{F_{n}}(x_j)}{\hat{\Phi}}\frac{\theta\hat{\Phi}}{4s})]}\\
			&=t\exp{[-s(1+\frac{\theta}{4s})(\Phi_{F_{n}}(x_j))]}.
		\end{align*}
		It follows that 
		\begin{align*}
			\sum_{j\in J}\exp{[-s(\Phi_{F_{n}}(x_j)+\frac{|F_{n}|\theta\hat{\Phi}}{4s})]}&<\frac{1}{t}\sum_{j\in J}\sum_{i\in I_n^t(j)} c_i\exp{[-s\Phi_{F_{n}}(z_i)]}\\
			&\leq \frac{1}{t}\sum_{i\in I_n^t} c_i\exp{[-s(\sup_{y\in B_{F_{n}}(x_i,\epsilon)}\Phi_{F_{n}}(y)-\frac{|F_{n}|\theta\hat{\Phi}}{4s})]}.
		\end{align*}
		This implies that 
		\begin{align*}
			\sum_{j\in J}\exp{[-s(\Phi_{F_{n}}(x_j)+\frac{|F_{n}|\theta\hat{\Phi}}{2s})]}
			\leq \frac{1}{t}\sum_{i\in I_n^t} c_i\exp{[-s(\sup_{y\in B_{F_{n}}(x_i,\epsilon)}\Phi_{F_{n}}(y))]}.
		\end{align*}
		Therefore,
		\begin{align*}
			\widetilde{M}^{s+\theta}_{N,5\epsilon}(H_{n,t},\{F_n\}_{n=1}^{\infty},\Phi)&\leq \sum_{j\in J} \exp{[-(s+\theta)\Phi_{F_{n}}(x_j)]}\\&
			\leq \frac{1}{n^2 t}\sum_{i \in I_n} c_i \exp{[-s\sup_{y\in B_{F_{n}}(x_i,\epsilon)}\Phi_{F_{n}}(y)]}.  
		\end{align*}

		By definition, $H=\bigcup_{n\geq N} H_{n,\frac{1}{n^2}t}$. Hence
		\begin{align*}
			\widetilde{M}_{N,5\epsilon}^{s+\theta}(H,\{F_n\}_{n=1}^{\infty},\Phi)&\leq \sum_{n\geq N} \widetilde{M}_{N,5\epsilon}^{s+\theta}(H_{n,\frac{1}{n^2}t},\{F_n\}_{n=1}^{\infty},\Phi)\\
			&\leq \frac{1}{t}\sum_{i\in I}c_i \exp{[-s\sup_{y\in B_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)]}.
		\end{align*}
		Let $t\rightarrow 1$. It follows that $\widetilde{M}^{s+\theta}_{N,\frac{\epsilon}{2}}(H,\Phi)\leq W^{s}_{N,\epsilon}(H,\Phi)$. Letting $N \to \infty$, we have $\widetilde{M}^{s+\theta}_{5\epsilon}(H,\Phi)\leq W^s_{\epsilon}(H,\Phi)\leq M^s_{\epsilon}(H,\Phi).$  

		It follows that $\widetilde{M}_{5\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq W_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)+\theta\leq M_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$ Taking $\epsilon \to 0$ tend to $0$, by Proposition \ref{inter} and with the  arbitrariness of $\theta>0$, we obtain that  ${dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)={dim}_H^{\widetilde{BS,WB}}(\{F_n\}_{n=1}^{\infty},\Phi)$. 
	\end{proof}
