	Building on the methodology developed in \cite[Theorem 1.4]{xu2024inverse}, we establish the following inverse variational relationship between BS dimension and BS dimension in the sense of Katok or BS dimension of Borel probability measure.

%	Next we follow the idea of  \cite[Theorem 1.4]{xu2024inverse} to build an inverse variational principle between BS dimension and BS dimension in the sense of Katok or BS dimension of Borel probability measure.
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{theorem}\label{inverse}(=\Cref{m2})
		Let  $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function and  $\mu\in {M}(X)$. Then
		$$
		\begin{aligned}
			dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)&=dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi)\\
			&=  \inf \left\{dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi):  \mu(H)=1\right\}\\
			&=\lim\limits_{\epsilon\to 0}\inf \left\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)=1\right\}.
		\end{aligned}
		$$
	\end{theorem}

	\begin{proof}
		Let 
		$dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=\mathfrak{S},$
		then for any  $\lambda>0 $, there exists  $\epsilon_{0}>0$  such that for any  $0<\epsilon<\epsilon_{0}<1 $, it has
		$$
		\lim_{\delta\to 0}\inf\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi):\mu(H) \geq 1-\delta\}<\mathfrak{S}+\frac{\lambda}{3}.$$

		Hence, for any $ 0<\epsilon<\epsilon_{0} $, there exists  $\delta(\epsilon)>0 $, such that for any  $0<\delta<\delta(\epsilon) $, one has
		$$
		\inf\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi):\mu(H) \geq 1-\delta\}<\mathfrak{S}+\frac{2\lambda}{3}.
		$$

		Therefore, for every  $k$  large enough, there exists $ H_{k} $ with  $\mu\left(H_{k}\right)\geq 1-\frac{1}{k} $, such that
		$$
		{M}_{\epsilon}(H_{k},\{F_n\}_{n=1}^{\infty},\Phi)<\mathfrak{S}+\lambda.
		$$

		Take $ H=\cup H_{k} $. Then we have  $\mu(H)=1 $, furthermore, one has
		$$
		{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\sup_{k} {M}_{\epsilon}(H_{k},\{F_n\}_{n=1}^{\infty},\Phi) \leq \mathfrak{S}+\lambda.
		$$

		Thus, we have
		$$
		\inf \left\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)=1\right\} \leq \mathfrak{S}+\lambda.
		$$
		Hence, 
		\begin{equation*}
			\lim\limits_{\epsilon\to0}\inf \left\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)=1\right\} \leq \mathfrak{S}=dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi).
		\end{equation*}
		In fact,  for any  $\delta>0 $, one has
		$$
		\inf \left\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)=1\right\} \geq \inf \left\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)\geq 1-\delta\right\}.
		$$

		Therefore,
		$$
		\begin{aligned}
			& \lim\limits_{\epsilon\to0}\inf \left\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)=1\right\} \\
			\geq &\lim_{\epsilon\to 0}\lim_{\delta\to 0}\inf\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi):\mu(H) \geq 1-\delta\}\\
			= &dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi).
		\end{aligned}
		$$

		Combining above arguments, we have
		\begin{equation} \label{eq3}
			dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)= \lim\limits_{\epsilon\to0}\inf \left\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)=1\right\} .
		\end{equation}

		Next, using (\ref{eq3}), we can state that
		$$
		dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=\inf \left\{dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi):  \mu(H)=1\right\}.
		$$

		To see it, for any  $\eta>0 $, there exists  $\epsilon_{0}>0$  such that for any  $0<\epsilon<\epsilon_{0} ,$
		$$
		\inf \left\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)=1\right\} <\mathfrak{S}+\frac{\eta}{2}.
		$$
		Hence, there exists $ H_{\epsilon} \subset X$  with  $\mu\left(H_{\epsilon}\right)=1 $ such that
		$$
		{M}_{\epsilon}(H_{\epsilon},\{F_n\}_{n=1}^{\infty},\Phi)<\mathfrak{S}+\eta.
		$$

		Take  $\epsilon=\frac{1}{j}$. Then for  sufficiently large $j$, there exists  $ H_{j} \subset X $ with  $\mu\left(H_{j}\right)=1$  such that
		$$
		{M}_{\frac{1}{j}}(H_{\frac{1}{j}},\{F_n\}_{n=1}^{\infty},\Phi)<\mathfrak{S}+\eta.$$

		Let  $H=\cap_{j} H_{j} $. Then we have  $\mu(H)=1$  and
		$$
		{M}_{\frac{1}{j}}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq {M}_{\frac{1}{j}}(H_{\frac{1}{j}},\{F_n\}_{n=1}^{\infty},\Phi)<\mathfrak{S}+\eta.
		$$
		It follows that
		$$\inf \left\{dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi):  \mu(H)=1\right\}\leq {M}_{\frac{1}{j}}(H,\{F_n\}_{n=1}^{\infty},\Phi)\leq \mathfrak{S}+\eta .$$
		Since $\eta$ is arbitrary, then one has
		\begin{equation*}
			\inf \left\{dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi):  \mu(H)=1\right\}\leq \mathfrak{S}=dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi).
		\end{equation*}

		Conversely, for each  $H \subset X$  with  $\mu(H)=1 $, by Proposition \ref{equ} one has
		$$
		dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi) \leq dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi),
		$$
		which implies that 
		$$
		dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)=dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi) \leq \inf \left\{dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi):  \mu(H)=1\right\}.
		$$
		Hence, we get that 
		$$
		\begin{aligned}
			dim_{\mu}^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)&=dim_{\mu}^{\widetilde{K}}(\{F_n\}_{n=1}^{\infty},\Phi)\\
			&=  \inf \left\{dim_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi):  \mu(H)=1\right\}\\
			&=\lim\limits_{\epsilon\to 0}\inf \left\{{M}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)=1\right\}.
		\end{aligned}
		$$
	\end{proof}
