	\section{BS packing dimension under amenable group actions}\label{packing dimension}
	In this section and next section, we focus on the study of BS packing dimension under amenable group actions, which is a natural generalization of BS packing   dimension in \cite[Definition 2.2]{wang2012variational} and packing topological entropy given in \cite{feng2012variational} and \cite{dou2023packing}.

	Let $H\subset X$ be a non-empty subset, $\epsilon>0$, $\Phi \in C(X,\mathbb{R})$ be a positive continuous function, $N\in \mathbb{N}$, $s >0$.
	Put
	\begin{equation}\label{eq5.1}
		L^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\sup\left\{\sum_i\limits  \exp(-s\sup_{y\in \overline{B}_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y))\right\},
	\end{equation}
	where the supremum  is taken over all  finite or countable disjoint $\{\overline B_{F_{n_i}}(x_i,\epsilon)\}_{i\in I}$ with $n_i \geq N,~x_i \in H.$  Since $L^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ is decreasing when $N$ increases,
	the following limit exists.
	Set
	$$L^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{N\to \infty}L^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$$
	Put 
	\begin{align*}
		\mathscr{L}^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)&=\inf \{{\sum_{i=1}^{\infty}L^{s}_{\epsilon}(H_i,\{F_n\}_{n=1}^{\infty},\Phi):H \subset \cup_{i=1}^{\infty} H_i}\},\\
		\mathscr{L}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)&=\sup{\{s:\mathscr{L}^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty\}}\\
		&=\inf{\{s:\mathscr{L}^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=0\}},\\
		dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)&=\lim_{\epsilon \to 0}	\mathscr{L}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).
	\end{align*}
	Since $\mathscr{L}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ is increasing when $\epsilon$ decreases, the above limit exists. Then we call $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)$ {\it BS packing dimension} of the set $H$ along $\{F_n\}_{n=1}^\infty$.
	When $\Phi=1$,  $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},1)$ is also the packing topological entropy $h_{top}^{P}(H,\{F_n\}_{n=1}^{\infty})$ given by Dou, Zheng and Zhou \cite{dou2023packing}.

	Analogous to Definition \ref{bs},  the notion of  BS packing dimension along $\{F_n\}_{n=1}^{\infty}$ can also be given in an alternative way. Given $B_{F_{n_i}}(x_i,\epsilon)$, we can replace $\sup_{y\in \overline{B}_{F_{n_i}}(x_i,\epsilon)}\Phi_{F_{n_i}}(y)$ by $\Phi_{F_{n_i}}(x_i)$ in equation (\ref{eq5.1}) to give a new definition. We denote by $\widetilde{L}^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$, $\widetilde{\mathscr{L}}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ and $\widetilde{dim}_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)$ the new corresponding quantities of \\ $L^{s}_{N,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$, $\mathscr{L}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$ and $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)$, respectively.


	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%	
	\begin{proposition}\label{inter-1-1}
		Let   $H\subset X$ be a non-empty subset and $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function. Then $${dim}_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)=\widetilde{dim}_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi).$$
	\end{proposition}
	\begin{proof}
		It is similar to Proposition \ref{inter}, here we omit it.

	\end{proof}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{proposition}\label{prop 5.2}
		Let $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function.  For any $H \subset X,$
		$${dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi) \leq {dim}_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi).$$
	\end{proposition}

	\begin{proof}
		We follow the idea of \cite[Proposition 2.4(4)]{zhong2023variational} to give the proof.  Suppose that $${dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)>s>0.$$ 
		For any $\epsilon>0$  and  $n\in \mathbb{N}$, let 
		$$\mathcal{F} _{F_n,\epsilon}=\{\mathcal{F}:\mathcal{F}=\{\overline B_{F_n}(x_i,\epsilon)\} \text{ disjoint },x_i \in H \}.$$
		Take $\mathcal{F}({F_n},\epsilon,H) \in \mathcal{F} _{F_n,\epsilon}$ such that $\lvert \mathcal{F}({F_n},\epsilon,H) \rvert=\max_{\mathcal{F} \in \mathcal{F} _{F_n,\epsilon}}{\lvert \mathcal{F} \rvert}.$
		For convenience, we denote $\mathcal{F}({F_n},\epsilon,H)=\{\overline B_{F_n}(x_i,\epsilon):i=1,...,\lvert \mathcal{F}({F_n},\epsilon,H) \rvert\}.$
		It is easy to check that
		$$H \subset \bigcup\limits_ {i=1}^{\lvert \mathcal{F}({F_n},\epsilon,H) \rvert}{B_{F_n}}(x_i,2\epsilon+\delta),\forall \delta>0.$$
		Then for any $s \in \mathbb{R},$
		\begin{align*}
			\widetilde{M}^{s}_{n,2\epsilon+\delta}(H,\{F_n\}_{n=1}^{\infty},\Phi) &\leq \sum_{i=1}^{\lvert \mathcal{F}({F_n},\epsilon,H) \rvert}  e^{-s \Phi_{F_n}(x_i)}\\
			&\leq \widetilde{L}^{s}_{n,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).
		\end{align*}
		This implies that $$\widetilde{M}^{s}_{2\epsilon+\delta}(H,\{F_n\}_{n=1}^{\infty},\Phi) \leq \widetilde{\mathscr{L}}^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi).$$
		Since ${dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi)>s>0$, $\widetilde{M}^{s}_{2\epsilon+\delta}(H,\{F_n\}_{n=1}^{\infty},\Phi) \geq 1$ when $\epsilon$  and $\delta$ are small enough, this follows that, $\widetilde{\mathscr{L}}^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi) \geq 1.$
		Hence, we get that
		$\widetilde{\mathscr{L}}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi) \geq s$ for $\epsilon$ small enough. 
		Therefore, by Propositions \ref{inter} and  \ref{inter-1-1}, one has ${dim}_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)\geq s$ and  
		${dim}_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi) \geq {dim}_H^{\widetilde{BS}}(\{F_n\}_{n=1}^{\infty},\Phi).$
	\end{proof}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

		By the theory of Carath{\'e}odory-Pesin structure, the proof of the  following proposition is standard, one can refer to \cite{pesin2008dimension}.
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{proposition} \label{prop 2.211}	
		(1) If $H_1\subset H_2 \subset X$, then $$dim_{H_1}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)\leq dim_{H_2}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi).$$

		(2) If $H=\cup_{i\geq 1}H_i$ is a union of  sets $H_i\subset X$, then $$dim_{H}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)=\sup_{i\geq 1}dim_{H_i}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi).$$
	\end{proposition}



	Analogous to Theorem \ref{bowen} and \cite[Theorem 3.6]{wang2012variational}, we also can prove that the BS packing dimension is the unique root of packing topological pressure function under amenable group actions. Actually, we extend the results of  \cite{wang2012variational}  to packing BS dimension under amenable group actions by below Theorem \ref{packing}.

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{theorem}[Bowen’s packing pressure equation] \label{packing}
		For any positive continuous function  $\Phi: X \rightarrow \mathbb{R} $, we have  $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)=t $, where  $t $ is the unique root of the equation  $P_{H}^{P}(\{F_n\}_{n=1}^{\infty}, -t \Phi)=0 .$
	\end{theorem}

	\begin{proof}
		It is similar to Theorem \ref{bowen}, here we leave this proof to readers.	Moreover, one can refer to \cite[Theorem 3.6]{wang2012variational} for similar methods under $\mathbb{Z}_{+}$-actions.
	\end{proof}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	Analogous to subsection \ref{subsec 2.6}, we can also give the notions of BS packing dimension in the sense of Katok.
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{BS packing dimension in the sense of Katok}

	\begin{definition}\label{def 5.5}
		Let 
		$$dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=\lim_{\delta\rightarrow 0} \inf\{\widetilde{\mathscr{L}}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi):\mu(H)\geq 1-\delta\}.$$

		We call the following quantity
		$$dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi):=\lim_{\epsilon \to 0}dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)$$
		BS packing dimension of $\mu$ along  $\{F_n\}_{n=1}^{\infty}$.
	\end{definition}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{definition}\label{def 5.6}
		Let $$\Xi^s_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=\inf\{\sum_{i=1}^{\infty}\widetilde{L}^{s}_{\epsilon}(H_i,\{F_n\}_{n=1}^{\infty},\Phi):\mu(\cup_{i=1}^\infty H_i)\geq 1-\delta\}$$ 
		and
		$$\Xi_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=\sup\{s:\Xi^s_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=+\infty\}.$$ 



		We call the following quantity
		$$dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi)=\lim_{\epsilon \to 0}dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)$$ BS packing dimension of $\mu$ in the sense of Katok along $\{F_n\}_{n=1}^{\infty}$, where  $$dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=\lim_{\delta\rightarrow 0} \Xi_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta).$$ 
	\end{definition}

	\begin{remark}
    Definition \ref{def 5.5} and Definition \ref{def 5.6} are natural generalizations associated with some notions of  packing topological entropy given in \cite{wang2021some}.
	\end{remark}

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{proposition}\label{prop 2.10}
		Let $\mu \in \mathcal{M} (X)$,   $\Phi: X \rightarrow \mathbb{R} $ be a  positive continuous function.
		Then, for $\epsilon>0$,
		$$dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)=dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon).$$
		As a direct result, $$dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)=dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi).$$
	\end{proposition}

	\begin{proof}
		(1)	We first prove that $dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) \leq dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon).$
		For any $s < dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon),$ there exists  $\delta'>0$ such that for any $\delta \in (0,\delta'),$
		$$\Xi_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)>s.$$
		Thus
		$$ \Xi_{\epsilon}^{s}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=\infty.$$
		If $H\subset \cup_{i=1}^\infty H_i$ with $\mu(H) \geq 1-\delta,$   then $\mu(\cup_{i=1}^\infty H_i) \geq 1-\delta.$
		It follows that
		$$\sum_{i=1}^{\infty}\widetilde{L}^{s}_{\epsilon}(H_i,\{F_n\}_{n=1}^{\infty},\Phi)=\infty,$$
		which implies that $\widetilde{\mathscr{L}}_{\epsilon}^{s}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty.$
		Hence, $$\widetilde{\mathscr{L}}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi) \geq s$$ and $$dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) \geq s.$$ Letting $s\to dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon), $ this shows that $$dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon) \leq dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon).$$

		(2)	Next, we shall show the inverse inequality. If $s<dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon),$ then there exists $\delta' >0$ such that for any  $\delta \in (0,\delta'),$
		for any family $\{H_i\}_{i=1}^\infty$ with $\mu(\cup_{i=1}^\infty H_i) \geq 1-\delta,$ we have
		$$\widetilde{\mathscr{L}}_{\epsilon}(\cup_{i=1}^\infty H_i,\{F_n\}_{n=1}^{\infty},\Phi)>s.$$
		This implies that
		$$\widetilde{\mathscr{L}}_{\epsilon}^{s}(\cup_{i=1}^\infty H_i,\{F_n\}_{n=1}^{\infty},\Phi)=\infty.$$
		Thus, one has
		$$\sum_{i=1}^\infty \widetilde{L}_{\epsilon}^{s}( H_i,\{F_n\}_{n=1}^{\infty},\Phi)=\infty,$$
		and
		$$ \Xi^s_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=\infty.$$
		Hence
		$$\Xi_{\epsilon}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)>s.$$
		Letting $\delta\to0, s\to dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon),$ then we derive that $dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)\leq dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon)$.
		The proof is finished.
	\end{proof}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



	Analogous to Theorem \ref{billing-1}, we can establish the Billingsley type theorem of packing BS dimension under amenable group actions. 
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{theorem}\label{billing-2}
		Let  $\{F_n\}_{n=1}^{\infty}$ be a Følner  sequence in $G$ satisfying $\lim\limits_{n \to \infty}\frac{|F_n|}{\log n}=\infty $,  $\mu \in {M}(X), H \subset X$  and  let $\Phi: X \to \mathbb{R}$  be a positive continuous function. For each  $s \in(0, \infty) $, then

		(1) if  $\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,x) \leq s$  for all  $x \in H $, then  $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi) \leq s $;

		(2) if  $\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,x) \geq s$  for all  $x \in H $, and  $\mu(H)>0 $, then  $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi) \geq s $.	

	\end{theorem}


	\begin{proof}
		(1)	Fix $\beta>s$, set
		$$
		H_{m}=\left\{x \in H: \limsup _{n \rightarrow \infty} \frac{-\log \mu\left(B_{F_n}(x, \epsilon)\right)}{ \Phi_{F_n}(x)}<\frac{s+\beta}{2}, \text { for any } \epsilon \in\left(0, \frac{1}{m}\right)\right\}.$$

		Since  $\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi,x) \leq s$  for all  $x \in H $, then  $H=\bigcup_{m=1}^{\infty} H_{m} .$ Fix  $m \geq 1$  and  $\epsilon \in\left(0, \frac{1}{m}\right) $, for any  $x \in H_{m} $, there exists $N\in \mathbb{N}$ so that for any $n\geq N$, 
		$$
		\mu\left(B_{F_{n}}(x, \epsilon)\right) \geq \exp \left(-\left(\frac{s+\beta}{2}\right) \Phi_{F_n}(x)\right).
		$$
		Let
		$$H_{m,N}=\left\{x \in H_m:\mu(B_{F_n}(x,\epsilon)) \geq  \exp \left(-\left(\frac{s+\beta}{2}\right) \Phi_{F_n}(x)\right),\forall n \geq N,\epsilon \in (0,\frac{1}{m})\right\}.$$

		It is clear that $H_m=\bigcup_{N=1}^{\infty}H_{m,N}.$
		Given $\epsilon>0,$ $N\in\mathbb N$ and $J \geq N.$
		Let  $\mathcal{F} =\{B_{F_{n_i}}(x_i,\epsilon)\}_{i \in I},$ where $x_i \in H_{m,N},$ $n_i \geq J $  be a finite or countable disjoint family.
		\begin{align*}
			\sum_{i}e^{-\beta \Phi_{F_{n_i}}(x_i) }&=\sum_{i}e^{-(\frac{\beta+s}{2}+\frac{\beta-s}{2})\Phi_{F_{n_i}}(x_i)}\\
			&\leq e^{-\lvert F_{J} \rvert\hat{\Phi}(\frac{\beta-s}{2})}\sum_{i}e^{-\frac{\beta+s}{2} \Phi_{F_{n_i}}(x_i)}\\
			&\leq e^{-\lvert F_{J} \rvert\hat{\Phi}(\frac{\beta-s}{2})}\sum_{i}\mu(\overline B_{F_{n_i}}(x_i,\epsilon))\\
			&\leq e^{-\lvert F_{J} \rvert\hat{\Phi}(\frac{\beta-s}{2})}.
		\end{align*}
		It follows that 
		$$\widetilde{L}^{\beta}_{J,\epsilon}(H_{m,N},\{F_n\}_{n=1}^{\infty},\Phi) \leq e^{-\lvert F_{J} \rvert\hat{\Phi}(\frac{\beta-s}{2})}.$$
		Letting $J\to\infty,$ we have $\widetilde{L}^{\beta}_{\epsilon}(H_{m,N},\{F_n\}_{n=1}^{\infty},\Phi)=0,$ which implies that $$\widetilde{\mathscr{L}}^{\beta}_{\epsilon}(H_{m},\{F_n\}_{n=1}^{\infty},\Phi)=0.$$
		Hence,  $\widetilde{\mathscr{L}}_{\epsilon}(H_{m},\{F_n\}_{n=1}^{\infty},\Phi) \leq \beta.$
		Letting $\epsilon\to0,$ and by Proposition \ref{inter-1-1}, it follows that $$dim_{H_m}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi) \leq \beta.$$

		Therefore, $dim_{H}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi) \leq \sup_m dim_{H_m}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi) \leq\beta,$ 
		Letting $\beta\to s,$ then we get that  $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi) \leq s $.

		(2) 
		Fix $\beta <s.$ Let $\delta=\frac{s-\beta}{2}$
		and
		$$H_m=\{x \in H:\limsup_{n \to \infty}\frac{-\log\mu(B_{F_n}(x,\frac{1}{m}))}{\Phi_{F_n}(x)} > \beta + \delta\}.$$
		Then $H=\bigcup_{m=1}^{\infty}H_m.$
		Since $\mu(H)>0$ and $H_n\subset H_{n+1}, n\in\mathbb N,$ there exists $m\in\mathbb N$ such that $\mu(H_m)>0.$ For any  $\epsilon \in (0,\frac{1}{m})$ and $ x \in H_m$, we have
		$$ \limsup_{n \to \infty}\frac{-\log\mu(B_{F_n}(x,\epsilon))}{\Phi_{F_n}(x)}>\beta +\delta.$$
		Next we claim that $\widetilde{\mathscr{L}}^{s}_{\frac{\epsilon}{10}}(H_{m},\{F_n\}_{n=1}^{\infty},\Phi)=\infty,$ also from Proposition \ref{inter-1-1}, this implies that 
		\begin{align*}
			dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi) &\geq dim_{H_m}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)\\ &\geq \widetilde{\mathscr{L}}_{\frac{\epsilon}{10}}(H_{m},\{F_n\}_{n=1}^{\infty},\Phi)\\ &\geq s.
		\end{align*}
		To this end, it suffices to show that $\widetilde{L}^{s}_{\frac{\epsilon}{10}}(E,\{F_n\}_{n=1}^{\infty},\Phi)=\infty$ for any Borel subset $E \subset H_m$ with $\mu (E)>0.$
		In fact, for  $E\subset H_m$ with $\mu (E)>0,$
		let 
		$$E_n=\{x\in E:\mu(B_{F_n}(x,\epsilon))<e^{-(\beta+\delta)\Phi_{F_{n}}(x)}\},~n \in \mathbb{N}.$$
		It is clear that $E=\bigcup_{n=N}^{\infty}E_n$ for each $N \in \mathbb{N}. $ Then $\mu(\bigcup_{n=N}^{\infty}E_n)=\mu(E).$
		Hence there exists $n \geq N$ such that
		$$\mu(E_n) \geq \frac{1}{n(n+1)}\mu(E).$$
		Fix such $n$ and let $\mathcal{B} =\{\overline B_{F_n}(x,\frac{\epsilon}{10}):x\in E_n\}.$
		By Lemma \ref{cover}, there exists a finite or countable pairwise disjoint family $\{\overline B_{F_n}(x_i,\frac{\epsilon}{10})\}_{i\in I}$ such that
		$$E_n \subset \bigcup_{x \in E_n}\overline B_{F_n}(x,\frac{\epsilon}{10}) \subset \bigcup_{i\in I} \overline B_{F_n}(x_i,\frac{\epsilon}{2}) \subset \bigcup_{i\in I} \overline B_{F_n}(x_i,\epsilon).$$
		Hence,
		\begin{align*}
			\widetilde{L}^{\beta}_{N,\frac{\epsilon}{10}}(E,\{F_n\}_{n=1}^{\infty},\Phi) &\geq \widetilde{L}^{\beta}_{N,\frac{\epsilon}{10}}(E_n,\{F_n\}_{n=1}^{\infty},\Phi)\\ &\geq \sum_{{i\in I}}e^{-\beta\Phi_{F_n}(x_i)}\\
			&\geq  e^{\lvert F_{n} \rvert\hat{\Phi} \delta}\sum_{{i\in I}}e^{-(\beta+\delta)\Phi_{F_n}(x_i)}\\ &=  e^{\lvert F_{n} \rvert\hat{\Phi} \delta}\sum_{{i\in I}}e^{-(\beta+\delta)\Phi_{F_n}(x_i)}\\&\geq e^{\lvert F_{n} \rvert\hat{\Phi} \delta}\sum_{{i\in I}}\mu(B_{F_n}(x_i,\epsilon))\\
			&\geq e^{\lvert F_{n} \rvert \hat{\Phi}\delta}\mu(E_n)\\ 
			&\geq \frac{e^{\lvert F_{n} \rvert \hat{\Phi}\delta}}{n(n+1)}\mu(E).
		\end{align*}	
		Since $\lim\limits_{n \to \infty}\frac{|F_n|}{\log n}=\infty $ and $\mu(E)>0,$ we have
		$$\widetilde{L}^{\beta}_{\frac{\epsilon}{10}}(E,\{F_n\}_{n=1}^{\infty},\Phi)=\infty.$$ This finishes the proof.

	\end{proof}
