	\begin{proposition}\label{prop 2.13}
		Let $\mu \in \mathcal{M} (X)$, $H \subset X,$   $\Phi: X \rightarrow \mathbb{R} $ be a  positive continuous function.
		We have $$\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi) \leq dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi).$$
	\end{proposition}
	\begin{proof}
		For any $s < \overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi),$ we can find a Borel set $A \subset X$ with $\mu(A)>0$ such that, for any $x \in A,$
		$$\lim_{\epsilon \to 0}\limsup_{n \to \infty}\frac{-\log\mu(B_{F_n}(x,\epsilon))}{\Phi_{F_n}(x)} >s.$$
		Given $\delta \in (0,\mu(A))$ and $\epsilon>0.$ We shall show that $dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi,\frac{\epsilon}{10})> s,$ which implies that $dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi) \geq s.$
		It suffices to show that
		$$\Xi^s_{\frac{\epsilon}{10}}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=\infty.$$
		Let $\{H_i\}_{{i \in I}}$ be a finite or countable family with $\mu(\cup_{i \in I} H_i)>1-\delta.$
		Since
		$$A=(A\cap (\cup_{i \in I}H_i))\cup(A\verb|\|\cup_{i \in I}H_i),$$
		it follows that $\mu(A\cap (\cup_{i \in I}H_i)) \geq \mu(A)-\delta>0.$ Thus there exists $i$ such that $\mu(A\cap H_i)>0.$
		Due to Proposition \ref{billing-2}, we have
		$$\widetilde{L}^{s}_{\frac{\epsilon}{10}}(H_i,\{F_n\}_{n=1}^{\infty},\Phi)  \geq \widetilde{L}^{s}_{\frac{\epsilon}{10}}(A\cap H_i,\{F_n\}_{n=1}^{\infty},\Phi)=\infty.$$
		Thus 
		$$\Xi^s_{\frac{\epsilon}{10}}(\mu,\{F_n\}_{n=1}^{\infty},\Phi,\delta)=\infty.$$
