		\section{Variational principle for BS packing dimension under amenable group actions}
		In this section, we shall prove the variational principle for BS packing dimension under amenable group actions, i.e., Theorem \ref{thm 1.1}, and the proof  is divided into two parts: upper bound and lower bound.

		\begin{theorem}\label{thm 1.1}(=\Cref{m3})
			Let $\{F_n\}_{n=1}^{\infty}$ be a Følner  sequence in G satisfying $\lim_{n \to \infty}\frac{|F_n|}{\log n}=\infty.$ Then for any non-empty analytic subset $H$ of $X$ and a positive continuous function  $\Phi: X \rightarrow \mathbb{R} $.
			Then 
			\begin{align*}
				dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)&=\sup\{\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu \in \mathcal{M} (X),\mu(H)=1\}\\
				&=\sup\{dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi,\epsilon):\mu \in \mathcal{M} (X),\mu(H)=1\}\\
				&=\sup\{dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu \in \mathcal{M} (X),\mu(H)=1\}.
			\end{align*}
		\end{theorem}

	\end{proof}
	\subsection{Lower bound}
	Using Proposition \ref{prop 2.10} and Proposition \ref{prop 2.13}, this shows that
	\begin{align*}
		&\sup\{\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu \in \mathcal{M} (X),\mu(H)=1\}\\
		\leq& \sup\{dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu \in \mathcal{M} (X),\mu(H)=1\}\\
		=& \sup\{dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi):\mu \in \mathcal{M} (X),\mu(H)=1\}\\
		\leq &dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi).
	\end{align*}
	\subsection{Upper bound}


	\begin{lemma}\label{lem 3.1}
		Let $H \subset X,$ $\epsilon,s >0$. If $L^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty,$ then for any given finite interval
		$(a,b) \subset [0,+\infty)$ and $N \in \mathbb{N}, $ there exists a finite disjoint collection $\{\overline B_{F_{n_i}}(x_i,\epsilon)\}$ such that $x_i \in H,$ $n_i \geq N,$
		and $\sum_{i}e^{-s\Phi_{F_{n_i}}(x_i)} \in (a,b).$
	\end{lemma}
	\begin{proof}
		Take $N_1>N$ large enough such that $e^{|F_{N_1}|\hat{\Phi}s}<b-a.$ Since $L^{s}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty,$ it follows that $L^{s}_{N_1,\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty.$
		There hence exists a finite disjoint collection $\{\overline B_{F_{n_i}}(x_i,\epsilon)\}$ such that $x_i \in H,$ $n_i \geq N_1$ and $\sum_{i}e^{-s\Phi_{F_{n_i}}(x_i)}>b.$
		Since $e^{-s\Phi_{F_{n_i}}(x_i)} \leq e^{|F_{N_1}|\hat{\Phi}s} \leq b-a,$ we can discard elements in this collection one by one until we have $\sum_{i}e^{-s\Phi_{F_{n_i}}(x_i)}  \in (a,b).$
	\end{proof}
	We now turn to show the Upper bound. We employ the approach used by Joyce and Preiss \cite{joyce1995existence} and Feng and Huang in \cite{feng2012variational}. Let $H \subset X$ be analytic with $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)>0$. For any $dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)>s>0$, there exists a compact set $K \subset H$ and $\mu\in \mathcal{M}(K)$ such that $\overline{P}_{\mu}^{\widetilde{BK}}(\{F_n\}_{n=1}^{\infty},\Phi)\geq s$.


	Since $H$ is analytic, there exists a continuous surjective map $\phi :\mathcal{N} \to H.$ Let  $\Gamma _{n_1,n_2,...,n_p}=\{(m_1,m_2,...)\in\mathcal{N}:m_1 \leq n_1,m_2 \leq n_2,...,m_p \leq n_p \} $
	and let $H_{n_1,...,n_p}=\phi(\Gamma _{n_1,n_2,...,n_p}) .$ 
	Take $\epsilon>0$ small enough so that $\mathscr{L}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)>s>0$. Take $t$ with $s<t<\mathscr{L}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)$.

	The construction is divided into the following  several steps:

	{\bf Step 1.} Construct $K_1,$ $\mu_1,$ $n_1,$ $\gamma_1,$ and  $m_1(·) .$\\%^{'}
	Note that $	\mathscr{L}^{t}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty.$ Let
	$$Q=\bigcup\{U \subset X:U~is~open,\mathscr{L}^{t}_{\epsilon}(H\cap U,\{F_n\}_{n=1}^{\infty},\Phi)=0\}.$$
	Then $\mathscr{L}^{t}_{\epsilon}(H\cap Q,\{F_n\}_{n=1}^{\infty},\Phi)= 0$ by the separability of $X$. Let 
	$$H'=H\verb|\|Q=H\cap(X\verb|\|Q).$$
	For any open set $U \subset X,$ either $H'\cap U=\emptyset$ or $\mathscr{L}^{t}_{\epsilon}(H'\cap U,\{F_n\}_{n=1}^{\infty},\Phi)>0.$
	Indeed, suppose that $\mathscr{L}^{t}_{\epsilon}(H'\cap U,\{F_n\}_{n=1}^{\infty},\Phi)=0.$
	Since $H=H'\cup (H\cap Q),$
	\begin{align*}
		\mathscr{L}^{t}_{\epsilon}(H\cap U,\{F_n\}_{n=1}^{\infty},\Phi) &\leq \mathscr{L}^{t}_{\epsilon}(H'\cap U,\{F_n\}_{n=1}^{\infty},\Phi)\\ &+\mathscr{L}^{t}_{\epsilon}(H\cap Q,\{F_n\}_{n=1}^{\infty},\Phi)\\&=0.
	\end{align*}
	Thus $U \subset Q,$ which implies that $H'\cap U=\emptyset.$
	Since
	$$\mathscr{L}^{t}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi) \leq \mathscr{L}^{t}_{\epsilon}(H\cap H,\{F_n\}_{n=1}^{\infty},\Phi)+\mathscr{L}^{t}_{\epsilon}(H',\{F_n\}_{n=1}^{\infty},\Phi) $$
	and $\mathscr{L}^{t}_{\epsilon}(H\cap Q,\{F_n\}_{n=1}^{\infty},\Phi)=0,$ we have
	$$\mathscr{L}^{t}_{\epsilon}(H',\{F_n\}_{n=1}^{\infty},\Phi)=\mathscr{L}^{t}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi)=\infty.$$
	Using Lemma \ref{lem 3.1}, we can find a finite set $K_1 \subset H',$ an integer-valued function $m_1(x)$ on $K_1$ such that the collection $ \{\overline B_{F_{m_1(x)}}(x,\epsilon)\}_{x \in K_1}$ is disjoint and
	$$\sum_{x \in K_1}  e^{-s\Phi_{F_{m_1(x)}}(x)} \in (1,2).$$
	Define
	$$\mu_1=\sum_{x \in K_1} e^{-s\Phi_{F_{m_1(x)}}(x)}\delta_x,$$ where $\delta_x$ denotes the Dirac measure at $x.$



	Take a small $\gamma_1$ such that for any function $z:K_1 \to X$ with $d(x,z(x))\leq  \gamma_1,$
	we have for each $x \in K_1,$
	$$(\overline B(z(x),\gamma_1)\cup\overline B_{F_{m_1(x)}}(z(x),\epsilon))\bigcap (\bigcup_{y \in K_1\verb|\|\{x\}}\overline B(z(y),\gamma_1)\cup \overline B_{F_{m_1(y)}}(z(y),\epsilon))=\emptyset.$$
	It follows from $K_1 \subset H'$ that for any $x \in K_1,$
	\begin{align*}
		\mathscr{L}^{t}_{\epsilon}(H \cap B(x,\frac{\gamma_1}{4}),\{F_n\}_{n=1}^{\infty},\Phi) &\geq \mathscr{L}^{t}_{\epsilon}(H' \cap B(x,\frac{\gamma_1}{4}),\{F_n\}_{n=1}^{\infty},\Phi)>0.
	\end{align*}
	Therefore, we can pick a sufficiently large $n_1 \in \mathbb{N}$ so that $K_1 \subset H_{n_1}$ and $\mathscr{L}^{t}_{\epsilon}(H_{n_1} \cap B(x,\frac{\gamma_1}{4}),\{F_n\}_{n=1}^{\infty},\Phi)>0$ for each $x \in K_1.$

	{\bf Step 2.} Construct $K_2,$ $\mu_2,$ $n_2,$ $\gamma_2,$ and  $m_2(·) .$\\
	The family of balls $\{\overline B(x,\gamma_1)\}_{x \in K_1}$ are pairwise disjoint. For each $x \in K_1,$ since $\mathscr{L}^{t}_{\epsilon}(H_{n_1} \cap B(x,\frac{\gamma_1}{4}),\{F_n\}_{n=1}^{\infty},\Phi)>0,$
	we can construct a finite set  as in  Step 1  
	$$E_2(x) \subset H_{n_1} \cap B(x,\frac{\gamma_1}{4})$$
	and an integer-valued function
	$$m_2:E_2(x) \to \mathbb{N}\cap[\max\{m_1(y):y \in K_1\},\infty)$$
	such that
	\begin{flushleft}
		(2-a) $\mathscr{L}^{t}_{\epsilon}(H_{n_1} \cap U,\{F_n\}_{n=1}^{\infty},\Phi)>0 ,$ for any open set $U$ with $U\cap E_2(x) \neq \emptyset;$\\
		(2-b) the elements in $\{\overline B_{F_{m_2(y)}}(y,\epsilon)\}_{y \in E_2(x)}$ are disjoint, and
	\end{flushleft}
	$$\mu_1(\{x\})<\sum_{y \in E_2(x)}e^{-s\Phi_{F_{m_2(y)}}(y)}<(1+2^{-2})\mu_1(\{x\}).$$
	Actually, we fix $x \in K_1.$
	Denote $F=H_{n_1} \cap B(x,\frac{\gamma_1}{4}).$ 
	Let
	$$Q_x=\bigcup\{U \subset X:U~is~open,\mathscr{L}^{t}_{\epsilon}(F\cap U,\{F_n\}_{n=1}^{\infty},\Phi)=0\}.$$
	Set 
	$$F'=F\verb|\|Q_x.$$
	Then as in {Step 1,} we can show that
	$$\mathscr{L}^{t}_{\epsilon}(F',\{F_n\}_{n=1}^{\infty},\Phi)=\mathscr{L}^{t}_{\epsilon}(F,\{F_n\}_{n=1}^{\infty},\Phi)>0$$
	and
	$$\mathscr{L}^{t}_{\epsilon}(F'\cap U,\{F_n\}_{n=1}^{\infty},\Phi)>0,$$
	for any open set $U$ with $U \cap F'\neq \emptyset.$ Since $s < t,$
	$$\mathscr{L}^{s}_{\epsilon}(F',\{F_n\}_{n=1}^{\infty},\Phi)=\infty.$$
	Using Lemma \ref{lem 3.1} again, we can find a finite set $ E_2(x) \subset F',$ an integer-valued function $m_2(x)$ on $E_2(x)$ so that (2-b) holds.
	Observe that if $U \cap E_2(x)\neq \emptyset$ and $U$ is open, then $U \cap F'\neq \emptyset.$ Hence
	$$\mathscr{L}^{t}_{\epsilon}(H_{n_1}\cap U,\{F_n\}_{n=1}^{\infty},\Phi) \geq \mathscr{L}^{t}_{\epsilon}(F'\cap U,\{F_n\}_{n=1}^{\infty},\Phi)>0.$$
	Then (2-a) holds.
	Since the family $\{\overline{B}(x,\gamma_1)\}_{x \in K_1}$ is disjoint, $E_2(x) \cap E_2(x')=\emptyset$ for different $x,x' \in K_1.$
	Define $K_2=\bigcup_{x \in K_1}E_2(x)$
	and
	$$\mu_2=\sum_{y \in K_2}e^{-s\Phi_{F_{m_2(y)}}(y)}\delta_y.$$
	The elements in  $\{\overline B_{F_{m_2(y)}}(y,\epsilon)\}_{y \in K_2} $ are disjoint. Hence we can take $\gamma_2 \in (0,\frac{\gamma_1}{4})$ such that
	for any function $z:K_2 \to X$ satisfying $d(x,z(x))<\gamma_2,$ for  $x \in K_2.$
	we have
	$$(\overline B(z(x),\gamma_2)\cup \overline B_{F_{m_2(x)}}(z(x),\epsilon))\bigcap (\bigcup_{y \in K_2\verb|\|\{x\}}\overline B(z(y),\gamma_2)\cup \overline B_{F_{m_2(y)}}(z(y),\epsilon))=\emptyset$$
	for each $x \in K_2.$
	Choose a sufficiently large $n_2 \in \mathbb{N}$ so that $K_2 \subset H_{n_1,n_2}$ and 
	$$\mathscr{L}^{t}_{\epsilon}(H_{n_1,n_2} \cap B(x,\frac{\gamma_2}{4}),\{F_n\}_{n=1}^{\infty},\Phi)>0,$$
	for each $x \in K_2.$

	{\bf Step 3.} Assume that $K_i,$ $\mu_i,$ $n_i,$ $\gamma_i,$ and  $m_i(·)$ have been constructed for $i=1,...,p.$
	In particular, suppose that for any function $z:K_p \to X$ with $d(x,z(x))<\gamma_p$ for $x\in K_p$,
	we have
	$(\overline B(z(x),\gamma_p)\cup \overline B_{F_{m_p(x)}}(z(x),\epsilon))\cap (\bigcup_{y \in K_p\verb|\|\{x\}}\overline B(z(y),\gamma_p)\cup \overline B_{F_{m_p(y)}}(z(y),\epsilon))=\emptyset,$
	for each $x \in K_p.$
	Then $K_p \subset H_{n_1...n_p}$ and 
	$$\mathscr{L}^{t}_{\epsilon}(H_{n_1...n_p} \cap B(x,\frac{\gamma_p}{4}),\{F_n\}_{n=1}^{\infty},\Phi)>0,$$
	for each $x \in K_p.$
	The family of balls $\{\overline B(x,\gamma_p)\}_{x \in K_p} $ are pairwise disjoint. For each $x \in K_p,$ since $\mathscr{L}^{t}_{\epsilon}(H_{n_1...n_p} \cap B(x,\frac{\gamma_p}{4}),\{F_n\}_{n=1}^{\infty},\Phi)>0,$
	we can construct as in Step 2 a finite set 
	$$E_{p+1}(x) \subset H_{n_1...n_p} \cap B(x,\frac{\gamma_p}{4})$$
	and an integer-valued function
	$$m_{p+1}:E_{p+1}(x) \to \mathbb{N}\cap[\max\{m_p(y):y \in K_p\},\infty)$$
	such that
	\begin{flushleft}
		(3-a) $\mathscr{L}^{t}_{\epsilon}(H_{n_1...n_p} \cap U,\{F_n\}_{n=1}^{\infty},\Phi)>0,$ for any open set $U$ with $U\cap E_{p+1}(x) \neq \emptyset;$\\
		(3-b) the elements in $\{\overline B_{F_{m_{p+1}(y)}}(y,\epsilon)\}_{y \in E_{p+1}(x)}$ are disjoint, and
	\end{flushleft}
	$$\mu_p(\{x\})<\sum_{y \in E_{p+1}(x)}e^{-s \Phi_{F_{m_{p+1}(y)}}(y)}<(1+2^{-p-1})\mu_p(\{x\}).$$
	Clearly  $E_{p+1}(x) \cap E_{p+1}(y) = \emptyset$
	for different $x,y \in K_p.$
	Define $K_{p+1}=\bigcup_{x \in K_p}E_{p+1}(x)$
	and
	$$\mu_{p+1}=\sum_{y \in K_{p+1}}e^{-s\Phi_{F_{m_{p+1}(y)}}(y)}\delta_y.$$
	The elements in  $\{\overline B_{F_{m_{p+1}(y)}}(y,\epsilon)\}_{y \in K_{p+1}} $ are disjoint. Hence we can take $\gamma_{p+1} \in (0,\frac{\gamma_p}{4})$ such that
	for any function $z:K_{p+1} \to X$ satisfying $d(x,z(x))<\gamma_{p+1},$
	we have for each $x \in K_{p+1}$,
	$$(\overline B(z(x),\gamma_{p+1})\cup \overline B_{F_{m_{p+1}(x)}}(z(x),\epsilon)) \\ \bigcap (\bigcup_{y \in K_{p+1}\verb|\|\{x\}}\overline B(z(y),\gamma_{p+1})\cup \overline B_{F_{m_{p+1}(y)}}(z(y),\epsilon))=\emptyset$$

	Choose a sufficiently large $n_{p+1} \in \mathbb{N}$ so that $K_{p+1} \subset H_{n_1...n_{p+1}}$ and 
	$$\mathscr{L}^{t}_{\epsilon}(H_{n_1...n_{p+1}} \cap B(x,\frac{\gamma_{p+1}}{4}),\{F_n\}_{n=1}^{\infty},\Phi)>0,$$
	for each $x \in K_{p+1}.$
	As in above steps, we can construct by introduction $\{K_i\},\{\mu_i\},n_i,\gamma_i,and~m_i(·) .$
	We summarize some of their basic properties as follows:

	(a)For each $i$, the family $\mathcal{F}_i:=\{\overline{B}(x,\gamma_i):x \in K_i\}$ is disjoint. For every $B \in \mathcal{F}_{i+1},$ there exists $x \in K_i$ such that $B \subset \overline{B}(x,\frac{\gamma_i}{2}).$ 

	(b)For each $x \in K_i$ and $z\in \overline{B}(x,\gamma_i),$ we have
	$$\overline B_{F_{m_{i}(x)}}(z,\epsilon) \cap \bigcup_{y \in K_i\verb|\|\{x\}}  \overline B(y,\gamma_i)=\emptyset$$
	and
	\begin{align*}
		\mu_i( \overline{B}(x,\gamma_i))&=e^{-s\Phi_{F_{m_i(x)}(x)}}<\sum_{y \in E_{i+1}(x)}e^{-s\Phi_{F_{m_{i+1}(y)}}(y)}\\
		&<(1+2^{-i-1})\mu_i( \overline{B}(x,\gamma_i)),
	\end{align*}
	where $E_{i+1}(x)=B(x,\gamma_i) \cap K_{i+1}.$
	Furthermore, for $F_i\in \mathcal{F}_{i}$, one has
	\begin{align*}
		\mu_i(F_i) \leq \mu_{i+1}(F_i)&=\sum_{F\in \mathcal{F}_{i+1}:F \subset F_i }\mu_{i+1}(F)\leq \sum_{F\in \mathcal{F}_{i+1}:F \subset F_i }(1+2^{-i-1})\mu_i(F)\\
		&=(1+2^{-i-1})\sum_{F\in \mathcal{F}_{i+1}:F \subset F_i }\mu_i(F)\\
		&\leq (1+2^{-i-1})\mu_i(F_i).
	\end{align*}

	Using the above inequalities repeatedly, we have for any $j>i,$ $F_i \in \mathcal{F}_i,$ 
	\begin{align}\label{3.1}
		\mu_i(F_i) \leq \mu_j(F_i) \leq \prod _{n=i+1}^j (1+2^{-n})\mu_i(F_i) \leq C\mu_i(F_i),
	\end{align}
	where $C:=\prod _{n=1}^\infty(1+2^{-n})<\infty.$
	Let $\widetilde\mu$ be a limit point of $\{\mu_i\}$ in the weak-$*$ topology, let
	$$K=\bigcap_{n=1}^{\infty}\overline{\bigcup_{i \geq n}K_i}.$$

	Then, $\widetilde\mu$ is supported on $K$ and $K \subset \bigcap_{p=1}^{+\infty}\overline{H_{n_1,...,n_p}}.$
	By the continuity of $\phi,$ applying the Cantor's diagonal argument, we can show that $$\bigcap_{p=1}^{+\infty}\overline{H_{n_1,...,n_p}} =\bigcap_{p=1}^{+\infty}{H_{n_1,...,n_p}}.$$
	Hence, $K$ is a compact subset of $H$. For any $x \in K_i,$ by (\ref{3.1}), 
	\begin{align*}
		e^{-s\Phi_{F_{m_i(x)}(x)}}&=\mu_i(\overline{B}(x,\gamma_i))\leq \widetilde\mu( \overline{B}(x,\gamma_i))\\
		&\leq C\mu_i(\overline{B}(x,\gamma_i))=Ce^{-s\Phi_{F_{m_i(x)}(x)}}.
	\end{align*}
	In particular,
	\begin{align*}
		1\leq \sum_{x \in K_1}\mu_1({B}(x,\gamma_1)) 
		&\leq\widetilde\mu(K)\leq \sum_{x \in K_1}C\mu_1(B(x,\gamma_1))\leq 2C.
	\end{align*}
	For every $x \in K_i$ and $z \in \overline{B}(x,\gamma_i),$
	$$\widetilde\mu(\overline B_{F_{m_i(x)}}(z,\epsilon))\leq \widetilde \mu(\overline B(x,\frac{\gamma_i}{2})) \leq Ce^{-s\Phi_{F_{m_i(x)}(x)}}.$$
	For each $z \in K$ and $i \in \mathbb{N},$ $z \in \overline B(x,\frac{\gamma_i}{2})$ for some $x \in K_i$. Thus
	$$\widetilde\mu(\overline B_{F_{m_i(x)}}(z,\epsilon)) \leq Ce^{-s\Phi_{F_{m_i(x)}(x)}}.$$
	Let $\mu=\widetilde\mu/\widetilde\mu(K).$ Then $\mu \in \mathcal{M} (K),$ $\mu(K)=1,$ and for every $z \in K,$ 
	there exists a sequence $\{k_i\}$ with $k_i \to \infty$ such that
	$$\mu(B_{F_{k_i}}(z,\epsilon)) \leq \frac{Ce^{-s\Phi_{F_{k_i}(z)}}}{\widetilde\mu(K)}.$$
	This implies that $\overline P_\mu(\{F_n\}_{n=1}^{\infty},f) \geq s.$


	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{remark}
	(1)	If $\Phi=1$,  Theorem \ref{thm 1.1} coincides with \cite[Theorem 1.3]{dou2023packing}, so we  enhance some  results about  packing topological entropy under amenable group actions.

	(2) Naturally, Theorem \ref{thm 1.1} covers the results established by Wang and Chen for the BS packing dimension under $\mathbb{Z}_{+}$-actions in \cite[Theorem 3.12:(1)]{wang2012variational}.
	\end{remark}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	Analogous to inverse variational principle for BS dimension under amenable group actions, i.e. Theorem \ref{inverse}, we can also prove the inverse variational principle for BS packing dimension under amenable group actions by a similar method in Theorem \ref{inverse}, here we leave it to readers and give the result directly. 

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{theorem}\label{inverse-packing}(=\Cref{m4})
		Let  $\Phi: X\rightarrow \mathbb{R}$ be a  positive continuous function and  $\mu\in {M}(X)$. Then
		$$
		\begin{aligned}
			dim_{\mu}^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi)&=dim_{\mu}^{\widetilde{KP}}(\{F_n\}_{n=1}^{\infty},\Phi)\\
			&=  \inf \left\{dim_H^{\widetilde{BSP}}(\{F_n\}_{n=1}^{\infty},\Phi):  \mu(H)=1\right\}\\
			&=\lim\limits_{\epsilon\to 0}\inf \left\{\mathscr{L}_{\epsilon}(H,\{F_n\}_{n=1}^{\infty},\Phi): \mu(H)=1\right\}.
		\end{aligned}
		$$
	\end{theorem}























