We have the following useful criterion, which we will use to prove \'{e}tale descendability later.



\begin{proposition}\cite{mathew2016galois}*{Proposition 3.22}\label{prop:descendability-descent}
If $f:A\rightarrow B$ is descendable then the adjunction
$$B\otimes^{\mathbb{L}}_{A}(-) \colon \mathbf{D}(A) \to \bD(B) \colon {|-|}$$
is comonadic. Thus the functor
$$\mathbf{Mod}_A(\mathbf{C})\rightarrow\varprojlim_{n\in \Delta}\mathbf{Mod}_{B^{\otimes_{A}n+1}}(\bC)$$
is an equivalence. 
\end{proposition}

 \begin{remark}
 There are maps of algebras which satisfiy descent, in that the functor
$$\mathbf{Mod}_A(\mathbf{C})\rightarrow\varprojlim_{n\in \Delta}\mathbf{Mod}_{B^{\otimes_{A}n+1}}(\bC)$$
is an equivalence, but which are not descendable in the sense of Mathew. A recent counterexample to this was provided in \cite{aoki2024cohomology}. 
 \end{remark}

 The class of descendable morphisms of commutative monoid objects forms a topology. This follows immediately from the following two results.

 \begin{proposition}\cite{mathew2016galois}*{Proposition 3.23}
 Let $A\rightarrow B$ and $B\rightarrow C$ be maps in $\mathbf{CAlg(C)}$. Then
 \begin{enumerate}
 \item
 If $A\rightarrow B$ and $B\rightarrow C$ are descendable, then so is $A\rightarrow C$.
 \item
 If $A\rightarrow C$ is descendable then so is $A\rightarrow B$.
 \end{enumerate}
 \end{proposition}

 \begin{proposition}\cite{mathew2016galois}*{Corollary 3.21}
 Let $F:\mathbf{C}\rightarrow\mathbf{C'}$ be a symmetric monoidal functor between symmetric monoidal, stable $\infty$-categories. Let $f:A\rightarrow B$ be a descendable map in $\mathbf{CAlg(C)}$. Then $F(f):F(A)\rightarrow F(B)$ is a descendable map in $\mathbf{CAlg(C')}$.
 \end{proposition}

\begin{corollary}
Let $\mathbf{C}$ be a derived algebraic context. The collection of maps $\mathrm{Spec}(B)\rightarrow\mathrm{Spec}(A)$ such that $\Theta(A)\rightarrow\Theta(B)$ is descendable defines a pre-topology on $\mathbf{Aff}^{cn}_{\mathbf{C}}$. 
\end{corollary}


\begin{proposition}\label{prop:descfull}
    Let $\mathbf{D}$ be a presentable, stable, closed symmetric monoidal $\infty$-category. Let $\mathbf{C}\subset\mathbf{D}$ be a full subcategory which is closed under finite colimits and tensor products. Let $f:A\rightarrow B$ be a map in $\mathbf{Comm}(\mathbf{C})$ which is descendable as a map in $\mathbf{Comm}(\mathbf{D})$. Then it is descendable in $\mathbf{Comm}(\mathbf{C}).$
\end{proposition}

\begin{proof}
