\subsubsection{The \'{e}tale topology}

We now define topologies that will be relevant for analytic geometry. 

\begin{definition}[\cite{ben2024perspective} Definition 8.2.23]
    Let $\mathrm{T}$ be a $\underline{\Lambda}$-generating class of algebras of homotopy polynomial type. The finite $G-T$-\textit{topology} (or $\mathrm{T}$-\textit{rational topology}) is the topology consisting of covers $\{\mathrm{Spec}(B_{i})\rightarrow\mathrm{Spec}(A)\}$ in the homotopy monomorphism topology such that each map $A\rightarrow B_{i}$ is a $\mathrm{T}$-rational localisation.  We denote this topology by \(\tau^{rat}\). 
\end{definition}


\begin{definition}
     Let $\mathrm{T}$ be a $\underline{\Lambda}$-generating class of algebras of homotopy polynomial type. A map $f:A\rightarrow B$ in $\mathbf{DAlg}^{cn}(\mathbf{C})$ is said to be $\mathrm{T}$-\textit{\'{e}tale} if there is a finite $G-T$ cover $\{\mathsf{Spec}(B_{i})\rightarrow \mathsf{Spec}(B)\}$ such that each composite map $A\rightarrow B\rightarrow B_{i}$ is $\mathrm{T}$-standard \'{e}tale. 
\end{definition}

\begin{definition}[\cite{ben2024perspective}*{Definition 8.2.25}]\label{def:\'etale-abstract}
A collection $\{\mathrm{Spec}(B_i)\rightarrow\mathrm{Spec}(A)\}_{i=0}^n$ in \(\mathbf{Aff}_\bC\) is said to be a $\mathrm{T}$-\textit{descendable \'{e}tale pre-cover} if each map $A\rightarrow B_i$ is
\begin{enumerate}
    \item 
    $\mathrm{T}$-\'{e}tale, 
    \item 
    and descendable.
\end{enumerate}
\end{definition}

Denote the collection of morphisms in a \(\mathrm{T}\)-\'etale cover above by \(\tau^{pre}_{desc-et}\). 

\begin{proposition}\label{prop:etale-top}
The collection \(\tau^{pre}_{desc-et}\) defines a Grothendieck pre-topology on \(\mathbf{Aff}_\bC^{cn}\).
\end{proposition}

\begin{proof}
That $\mathrm{T}$-\'{e}tale maps are closed under isomorphisms, compositions, and pushouts is \cite{ben2024perspective}*{Proposition 6.1.4}.

