\begin{enumerate}
\item if \(\{\mathsf{Spec}(B_i) \to \mathsf{Spec}(A)\}\) is a cover in \(\tau\), then each \(\mathsf{Spec}(B_i) \to \mathsf{Spec}(A) \in \mathbf{P}\);
\item if \(f \colon \mathsf{Spec}(B) \to \mathsf{Spec}(A)\) is a map in \(\mathbf{Aff}_\bC\) and \(\{\mathsf{Spec}(B_i) \to \mathsf{Spec}(B)\}\) is a \(\tau\)-covering family such that each composition \(\mathsf{Spec}(B_i) \to \mathsf{Spec}(A) \in \mathbf{P}\), then \(f \in \mathbf{P}\);
\item if \(f \colon \mathsf{Spec}(C) \to \mathsf{Spec}(A) \in \mathbf{P} \cap \bA\) and \(\mathsf{Spec}(B) \to \mathsf{Spec}(A)\) is any map with \(\mathsf{Spec}(B) \in \bA\), then the pullback \(\mathsf{Spec}(B) \times_{\mathsf{Spec}(A)} \mathsf{Spec}(C) \in \bA\).    
\end{enumerate}

A relative pre-geometry tuple is said to be \emph{strong} if whenever \(\{\mathsf{Spec}(A_i) \to \mathsf{Spec}(A)\}\) is a cover in \(\tau\) (not necessarily in \(\bA\)), and \(\mathsf{Spec}(B) \to \mathsf{Spec}(A)\) is a morphism in \(\mathsf{Spec}(B) \in \bA\), then \(\{\mathsf{Spec}(B \otimes_A A_i) \to \mathsf{Spec}(A)\}\) is a cover in \(\tau_{\vert \bA}\).  
\end{definition}

\begin{remark}\label{rem:forcestrong}
If a relative pre-geometry tuple is not strong, we may force this by defining \(\mathbf{P}_\bA\) to be the collection of all \(f \colon \mathsf{Spec}(B) \to \mathsf{Spec}(A) \in \mathbf{P}\) such that if \(\mathsf{Spec}(C) \to \mathsf{Spec}(A)\) is a map with \(\mathsf{Spec}(C) \in \bA\), then \(\mathsf{Spec}(C \otimes_A B) \in \bA\), and \(\tau_\bA\) the class of all covers in \(\tau\) such that each morphism belongs to \(\mathbf{P}_\bA\). Then \((\mathbf{Aff}_\bC, \tau_\bA, \mathbf{P}_\bA, \bA)\) is a strong relative pre-geometry tuple. 
\end{remark}

\begin{definition}\label{def:admissible}
Let \((\mathbf{Aff}_\bC, \tau, \mathbf{P}, \bA)\) be a relative pre-geometry tuple. We call an object \(X =\mathsf{Spec}(A) \in \mathbf{Aff}_\bC\) \emph{\(\bA\)-admissible} if the representable functor \[\mathbf{Map}_{\mathbf{Aff}_\bC}(-,X) \colon \bA^\op \to \mathbf{An}\] is a stack for the restriction of the topology \(\tau\) to \(\bA\). A relative pre-geometry tuple is called a \emph{relative geometry tuple} if every object of \(\bA\) is \(\bA\)-admissible.  
\end{definition}



\comment{The restriction to a full subcategory \(\bA\) of objects in \(\mathbf{Aff}_\bC\) necessitates that we isolate a convenient collection of full subcategories of \(\mathbf{QCoh}_{\vert \bA}\) - this is required to globalise cotangent complexes to stacks and prove descent for subcategories we will use to define \(K\)-theory.


\begin{definition}\label{def:good-system}
A \emph{good system of modules on \(\bA\)} is an assignment \(\mathbf{M}\) to each \(\mathsf{Spec}(A) \in \bA\), a full subcategory \(\mathbf{M}_A \subseteq \bD(A)\) satisfying the following conditions:
\begin{itemize}
\item \(A \in \mathbf{M}_A\) for each \(\mathsf{Spec}(A) \in \bA\);
\item the contangent complex \(\mathbb{L}_A \in \mathbf{M}_A\) for each \(\mathsf{Spec}(A) \in \bA\);
\item \(\mathbf{M}_A\) is closed under isomorphisms, finite colimits and retracts;
\item the functor \(\mathbf{M} \colon A \mapsto \mathbf{M}_A\) satisfies weak Cech descent;
