\end{definition}} 


Now consider a relative geometry tuple \((\mathbf{Aff}_\bC, \tau, \mathbf{P}, \bA)\). Denote by \(\mathbf{PSh}(\bA)\) and \(\mathbf{Stk}(\bA,\tau_{\vert \bA})\) the \(\infty\)-categories of prestacks and stacks on \(\bA^\op\). The inclusion functor \(i \colon \bA^\op  \to \mathbf{Aff}_\bC^\op\) induces a restriction-left Kan extension adjoint pair 

\[i^* \colon \mathbf{PSh}(\bC) \rightleftarrows \mathbf{PSh}(\bA) \colon i_{!}.\] The restriction functor \(\mathbf{Stk}(\bC,\tau) \rightleftarrows \mathbf{Stk}(\bA, \tau_{\vert \bA})\) also has a left adjoint given by the composition of the stackification functor with \(i\). 


\begin{lemma}\cite{kelly2022analytic}\label{lem:subgeom}
Let \((\mathbf{Aff}_\bC, \tau, \mathbf{P}, \bA)\) be a strong relative pre-geometry tuple. Then the functor \(i_{!} \colon \mathbf{Stk}(\bA, \tau_{\vert A}) \to \mathbf{Stk}(\bC, \tau)\) is fully faithful.  
\end{lemma}

We will use Lemma \ref{lem:subgeom} in later sections to embed known categories of analytic stacks inside bornological stacks. 

\subsubsection{Geometric Stacks}

In this subsection we recall the definitions of geometric stacks and schemes. These are stacks which are glued together from affines in a controllable way. 

\begin{definition}[\cite{toen2008homotopical}*{Definition 1.3.3.1}]
Let \(\bC\) be a derived algebraic context and  $(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})$ a relative $(\infty,1)$-pre-geometry tuple.

\begin{enumerate}
\item
A prestack $\mathcal{X}$ in $\mathbf{Stk}(\mathbf{A},\tau|_{\mathbf{A}})$ is $(-1)$-\textit{geometric} if it is of the form $\mathcal{X}\cong\mathbf{Map}(-,M)$ for some $\mathbf{A}$-admissible $M\in\mathbf{Aff}_{\bC}$.
\item
A morphism $f:\mathcal{X}\rightarrow\mathcal{Y}$ in $\mathbf{Stk}(\mathbf{A},\tau|_{\mathbf{A}})$ is $(-1)$-\textit{representable} if for any map $U\rightarrow\mathcal{Y}$ with $U\in\mathbf{A}$ the pullback $\mathcal{X}\times_{\mathcal{Y}}U$ is $(-1)$-geometric.
\item
A morphism $f:\mathcal{X}\rightarrow\mathcal{Y}$ in  $\mathbf{Stk}(\mathbf{A},\tau|_{\mathbf{A}})$ is in $(-1)-\mathbf{P}$ if it is $(-1)$-representable and for any map $U\rightarrow\mathcal{Y}$ with $U\in\mathbf{A}$, the map $\mathcal{X}\times_{\mathcal{Y}}U\rightarrow U$ is in $\mathbf{P}$.
\end{enumerate}
\end{definition}

\begin{definition}[\cite{toen2008homotopical}*{Definition 1.3.3.1}]\label{defn:ngeom}
Let $n\ge0$ and let $\mathcal{X}$ be in  $\mathbf{Stk}(\mathbf{A},\tau|_{\mathbf{A}})$
\begin{enumerate}
\item
An $n$\textit{-atlas} for $\mathcal{X}$ is a set of morphisms $\{U_{i}\rightarrow \mathcal{X}\}_{i\in\mathcal{I}}$ such that 
\begin{enumerate}
\item
Each $U_{i}$ is $(-1)$-geometric.
\item
Each map $U_{i}\rightarrow\mathcal{X}$ is in $(n-1)$-$\mathbf{P}$.%\textcolor{blue}{\stkout{and is an epimorphism of stacks}}.
\item
$\coprod_{i\in\mathcal{I}}U_{i}\rightarrow\mathcal{X}$ is an epimorphism of stacks.
\end{enumerate}
\item
A stack $\mathcal{X}$ is $n$-\textit{geometric}  if
\begin{enumerate}
\item
The map $\mathcal{X}\rightarrow\mathcal{X}\times\mathcal{X}$ is $(n-1)$-representable.
\item
$\mathcal{X}$ admits an $n$-atlas.
\end{enumerate}
\item
A morphism of stacks $f:\mathcal{X}\rightarrow\mathcal{Y}$ is $n$-\textit{representable} if for any map  $U\rightarrow \mathcal{Y}$ with $U\in\mathbf{A}$ the pullback $\mathcal{X}\times_{\mathcal{Y}}U$ is $n$-geometric.
\item
A morphism of stacks $\mathcal{X}\rightarrow\mathcal{Y}$ is in $n$-$\mathbf{P}$ if it is $n$-representable, and for any map $U\rightarrow\mathcal{Y}$ with $U\in\mathbf{A}$, there is an $n$-atlas $\{U_{i}\rightarrow\mathcal{X}\times_{\mathcal{Y}}U\}_{i\in\mathcal{I}}$ such that each map $U_{i}\rightarrow U$ is in $\mathbf{P}$.
\end{enumerate}
\end{definition}



The full subcategory of $\mathbf{Stk}(\mathbf{A},\tau|_{\mathbf{A}})$ consisting of $n$-geometric stacks is denoted $\mathbf{Stk}_{n}(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})$. As in \cite{toen2008homotopical}*{Proposition 1.3.3.6}, we have  $\mathbf{Stk}_{m}(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})\subseteq \mathbf{Stk}_{n}(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})$ for $-1\le m\le n$. The full subcategory of geometric stacks is $\mathbf{Stk}_{geom}(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})\defeq\bigcup_{n=-1}^{\infty}\mathbf{Stk}_{n}(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})$. As in \cite{toen2008homotopical}*{Corollary 1.3.3.5}, $\mathbf{Stk}_{n}(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})$ is closed under pullbacks.


If $(\mathbf{Aff}_\bC,\tau,\mathbf{P})$ is an $(\infty,1)$-geometry triple then $(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{Aff}_\bC)$ is a relative $(\infty,1)$-pre-geometry tuple. In this case we write
$$\mathbf{Stk}_{m}(\mathbf{Aff}_\bC,\tau,\mathbf{P})\defeq\mathbf{Stk}_{m}(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{Aff}_\bC),$$
and we say that map $f:\mathcal{X}\rightarrow\mathcal{Y}$ is $n$-representable, or in $n-\mathbf{P}$ if it is so in the sense of Definition \ref{defn:ngeom} for the relative $(\infty,1)$-pre-geometry tuple $(\mathbf{M},\tau,\mathbf{P},\mathbf{M})$. The following is immediate:

\begin{proposition}
Let $(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})$ be a strong relative geometry tuple. Then for each $m\ge -1$ we have $\mathbf{Stk}_{m}(\mathbf{A},\tau|_{\mathbf{A}},\mathbf{P}|_{\mathbf{A}})\subseteq \mathbf{Stk}_{m}(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})$.
\end{proposition}

If $(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})$ is a relative $(\infty,1)$-geometry tuple such that $(\mathbf{Aff}_\bC,\tau,\mathbf{P})$ is an $(\infty,1)$-geometry triple (i.e. all objects of $\mathbf{Aff}_\bC$ are admissible) then we have a permanence property for geometric stacks.
Consider the functor $i_!:\mathbf{Stk}(\mathbf{A},\tau|_{\mathbf{A}})\rightarrow\mathbf{Stk}(\mathbf{Aff}_\bC,\tau)$. 


