Finally, we come to the definition of schemes.

\begin{definition}
Let $(\mathbf{Aff}_\bC,\tau,\mathbf{P},\mathbf{A})$ be a relative $(\infty,1)$-geometry tuple. An $n$-geometric stack $\mathcal{X}$ in \(\mathbf{Stk}(\bA, \tau_{\vert \bA})\) is said to be an $n$-\textit{scheme} if 
\begin{enumerate}
\item
it is a $(-1)$-geometric stack for $n=-1$.
\item
for $n\ge 0$ it has an  $n$-atlas $\{U_{i}\rightarrow\mathcal{X}\}_{i\in\mathcal{I}}$ such that 
\begin{enumerate}
\item
each $U_{i}\rightarrow\mathcal{X}$ is a monomorphism in $\mathbf{PreStk}(\mathbf{A},\tau|_{\mathbf{A}})$, that is, \(U_i \to U_i \times_{\mathcal{X}} U_i\) is an equivalence;
\item
for each $n\in\mathbb{N}$ and each $(i_{1},\ldots,i_{n})\in\mathcal{I}^{n}$, each $U_{i_{1}}\times_{\mathcal{X}}U_{i_{2}}\times_{\mathcal{X}}\ldots\times_{\mathcal{X}}U_{i_{n}}$ is an $(n-1)$-scheme.
\end{enumerate}
\end{enumerate}
\end{definition}

\noindent The full subcategory of $\mathbf{Stk}(\mathbf{A},\tau|_{\mathbf{A}})$ consisting of $n$-schemes is denoted $\mathbf{Sch}_{n}(\mathbf{A}, \tau_{\vert \bA})$. We also write $\mathbf{Sch}(\mathbf{A}, \tau_{\vert \bA}) \defeq\bigcup_{n=-1}^{\infty}\mathbf{Sch}_{n}(\mathbf{A}, \tau_{\vert \bA})$.

\subsubsection{Qcqs morphisms schemes}

Following \cite{soor2024derived}*{Definition 2.19}, we define quasi-compact and quasi-separated morphisms.

\begin{definition}
    \item 
    A scheme $X$ is said to be \textit{quasi-compact} if it admits an atlas $\coprod_{i=1}^{n}\mathrm{Spec}(U_{i})\rightarrow X$ with each $U_{i}$ affine.
    \item 
    A morphism $f:\mathcal{X}\rightarrow\mathcal{Y}$ of stacks is said to be \textit{quasi-compact} if for every map $Z\rightarrow Y$ with $Z$ affine, $Z\times_{\mathcal{Y}}\mathcal{X}$ is a quasi-compact scheme.
    \item A morphism $f:\mathcal{X}\rightarrow\mathcal{Y}$ of stacks is said to be \textit{quasi-separated} if its diagonal $\Delta_{f}:\mathcal{X}\rightarrow\mathcal{X}\times_{\mathcal{Y}}\mathcal{X}$ is quasi-compact.
\end{definition}

A quasi-compact and quasi-separated morphism will be called a \textit{qcqs morphism}. 

\begin{definition}
    A scheme $X$ is said to be \textit{quasi-separated} if the map $X\rightarrow\mathrm{Spec}(R)$ is quasi-separated.
\end{definition}

The following is clear.

\begin{proposition}
    Let $X$ be quasi-separated, and let $U\rightarrow X, V\rightarrow X$ be open immersions with $U$ and $V$ affine. Then $U\times_{X}V$ is quasi-affine.
\end{proposition}

\begin{proof}
    The quasi-separated assumption means that the intersection is quasi-compact. We evidently have an open immersion $U\times_{X}V\rightarrow U$.
\end{proof}

\subsection{Derived spaces and the underlying topological space}

Here we generalise the discussion from \cite{soor2024derived}*{Section 2.3} (which in turn followd \cite{clausenscholze2}) defining the underlying space of certain schemes.

 Consider a strong geometry tuple of the form
$$\mathbf{G}=(\mathbf{Aff}_{\mathbf{C}},\tau,\mathbf{P},\mathbf{A})$$
with $\tau$ a quasi-compact topology.


\begin{definition}
\begin{enumerate}
    \item 
        An object $X$ of $\mathbf{Stk}(\mathbf{Aff}_{\mathbf{C}},\tau)$ is said to be a \textit{derived} $\mathbf{G}$-\textit{scheme} if it is a $0$-scheme.
    \item 
        An object $X$ of $\mathbf{Stk}(\mathbf{Aff}_{\mathbf{C}},\tau)$ is said to be a \textit{derived} $\mathbf{G}$-\textit{space} if it is a $1$-scheme.
        \item 
        Let $f:U\rightarrow X$ be a morphism in $\mathbf{Stk}(\mathbf{Aff}_{\mathbf{C}},\tau)$. The map $f$ is said to be a \textit{derived} $\mathbf{G}$-\textit{subspace} if
        \begin{enumerate}
            \item 
            it is a homotopy monomorphism;
            \item
            for any $Z\rightarrow X$ with $Z$ in $\mathbf{A}$, the fibre product $Z\times_{X}U$ is a derived $\mathbf{G}$-space, and the morphism $f':Z\times_{X}U\rightarrow Z$ is in $\mathbf{P}$.
        \end{enumerate}
\end{enumerate}
\end{definition}

The category of all derived $\mathbf{G}$-spaces will be denoted $\mathbf{dSp}_{\mathbf{G}}$.

    Let $X$ be a derived $\mathbf{G}$-space. Denote by $\mathrm{Op}_{\mathbf{G}}(X)$ the full subcategory of $\mathbf{Stk}_{\big\slash X}$ consisting of derived $\mathbf{G}$-subspaces. Then $\mathrm{Op}_{\mathbf{G}}(X)$ forms a locale, with join and meet operations denoted by $\cup$ and $\cap$ respectively. A basis for $\mathrm{Op}_{\mathbf{G}}(X)$ is given by subspaces $\mathrm{Spec}(A)\rightarrow X$ with $\mathrm{Spec}(A)\in\mathbf{A}$. By assumption these are quasi-compact. Thus $\mathrm{Op}_{\mathbf{G}}(X)$ is locally compact, and the locale is spatial. We let 
    $$|X|_{\mathbf{G}}=\mathrm{pt}(\mathrm{Op}_{\mathbf{G}}(X))$$
    denote the topological space of points of $X$, i.e., the set of completely prime filters on the locale. Our main reference for generalities concerning locales is \cite{MR0698074}.

As in \cite{soor2024derived}*{Remark 2.28} we have the following.

\begin{remark}
    \begin{enumerate}
        \item 
        $|X|_{\mathbf{G}}$ is sober.
        \item 
        $|\mathrm{Spec}(A)|_{\mathbf{G}}$ is spectral. 
    \end{enumerate}
\end{remark}

We also let $|X|_{Ber}$ denote the subspace of $|X|$ consisting of \textit{ultrafilters}. We will later restrict our attention to this subspace. Let $X$ be a sober topological space. We write $X_{Ber}\defeq|\mathrm{Op}(X)|_{Ber}$, where $\mathrm{Op}(X)$ denotes the locale of open subsets.

\begin{lemma}
Let $f:X\rightarrow Y$ be a surjective open continuous map of sober topological spaces. Then $f_{Ber}:X_{Ber}\rightarrow Y_{Ber}$ is a surjective open continuous map.
\end{lemma}

\begin{proof}
First we show that it is surjective.
 Let $y\in Y_{Ber}$ correspond to an ultrafilter. There is $x\in X$ mapping to $y$. Recall that $y\in Y_{Ber}$ precisely if whenever $U$ is an open set which does not contain $y$, there is an open set $V$ containing $y$ such that $U\cap V=\emptyset$. Consider $f^{-1}(y)$. We claim that $\{W:f^{-1}(y)\cap W\neq\emptyset\}$ is a maximal filter. Indeed suppose that $T$ is an open set in $X$ such that $T\cap f^{-1}(y)=\emptyset$. Then $f(T)$ is an open set in $Y$ which does not contain $y$. Pick an open set $V$ containing $y$ which does not intersect $f(T)$, and consider $f^{-1}(V)$. This is an open set intersecting $f^{-1}(y)$ which does not intersect $T$. Hence $\{W:f^{-1}(y)\cap W\neq\emptyset\}$ is a maximal filter, and there is a point $x\in X_{Ber}$ corresponding to this maximal filter. We claim that $f(x)=y$. Indeed $f(x)$ is a completely prime filter containing $y$. Since $y$ is maximal, $y=f(x)$.

 Now let $U\subset X_{Ber}$ be open. There is an open $V\subset X$ such that $U=X_{Ber}\cap V$. Now $f(U)\subset f(V)\cap Y_{Ber}$. Let $y\in f(V)\cap Y_{Ber}$. We write $y=f(x)$ for some $x\in V$. We may also write $y=f(\tilde{x})$ for some $\tilde{x}\in X_{Ber}$. We claim we may choose $\tilde{x}$ such that $\tilde{x}\in V$. Again we consider the maximal filter $\{W:f^{-1}(y)\cap W\neq\emptyset\}$. We have $V\cap f^{-1}(y)\neq\emptyset$. Thus the point corresponding to this ultrafilter must be contained in $V$. We know that this point maps to $y$.
\end{proof}

\begin{example}
    For $R$ a unital commutative ring let $\mathrm{Spec}
    _{Zar}(R)$ denote the topological space of prime ideals of $R$ with the Zariski topology. Let $\{\mathrm{Spec}(f_{i}):\mathrm{Spec}_{Zar}(R_{i})\rightarrow\mathrm{Spec}_{Zar}(R))\}$ be a collection of flat morphisms of schemes such that $\coprod_{i\in\mathcal{I}}\mathrm{Spec}_{Zar}(R_{i})_{Ber}\rightarrow\mathrm{Spec}_{Zar}(R)_{Ber}$ is surjective. Then $\{\mathrm{Spec}_{Zar}(R_{i})\rightarrow\mathrm{Spec}_{Zar}(R))\}$ is a faithfully flat cover, i.e., $\coprod_{i\in\mathcal{I}}\mathrm{Spec}_{Zar}(R_{i})\rightarrow\mathrm{Spec}_{Zar}(R)$ is surjective.  Indeed, we may assume that the collection is finite by quasi-compactness of $\mathrm{Spec}_{Zar}(R)$. We put $S=\bigoplus_{i\in\mathcal{I}}R_{i}$. It suffices to prove that the flat morphism $R\rightarrow S$ is faithfully flat. Let $\mathfrak{m}$ be a maximal ideal of $R$.  Thus there is a $\mathfrak{p}\in\mathrm{Spec}_{Zar}(S)_{Ber}$ such that $\mathrm{Spec}(f)(\mathfrak{p})=\mathfrak{m}$. Then $S\otimes_{R}R\big\slash\mathfrak{m}\cong S\big\slash\mathfrak{p}\neq0$.
\end{example}

The following are straightforward.

\begin{proposition}
    Let $h:V\rightarrow W$ be an open immersion of $\mathbf{G}$-spaces. Then the maps $|h|:|V|\rightarrow |W|$ and $|h|_{Ber}:|V|_{Ber}\rightarrow |W|_{Ber}$ are open embeddings of spaces. 
\end{proposition}


