\end{proof}


\begin{definition}
    A morphism $f:X\rightarrow Y$ is said to be a \textit{local open immersion} if we can write $X=\bigcup_{i\in\mathcal{I}}U_{i}$, with $U_{i}\rightarrow X$ an open immersion, and 
    $$f|_{U_{i}}:U_{i}\rightarrow Y$$
    is an open immersion.
\end{definition}

\begin{proposition}\label{prop:locopimm}
    Let $f:X\rightarrow Y$ be a locally open immersion. It is an open immersion if and only if $|f|:|X|\rightarrow |Y|$ is injective.
\end{proposition}

\begin{proof}
    Clearly if $f$ is an open immersion then $|f|$ is injective. Conversely, suppose that $|f|$ is injective. We need to prove that the map $X\rightarrow X\times_{Y}X$ is an equivalence. Write $X=\bigcup U_{i}$ where each $U_{i}\rightarrow Y$ is an open immersion. It is enough to prove that $U_{i}\times_{Y}X\rightarrow U_{i}$ is an equivalence. Note that $U_{i}\times_{Y}X\rightarrow X$ is an open immersion. Thus it is enough to prove that $|U_{i}|\cong |U_{i}\times_{X}Y|\cong |U_{i}|\times_{|Y|}|X|$. But this follows immediately from the fact that $|X|\rightarrow |Y|$ is injective.
    %We have $X\times_{Y}X\cong\bigcup_{i,j}U_{i}\times_{Y}U_{j}$. We claim that $U_{i}\times_{Y}U_{j}\cong U_{i}\times_{X}U_{j}$.
\end{proof}


