\subsubsection{Spatial morphisms}

Let us introduce a class of maps generalising open immersions.

\begin{definition}
    A morphism $f:X\rightarrow Y$ in $\mathbf{dSp}_{\mathbf{G}}$ is said to be \textit{spatial} if for any other morphism $Z\rightarrow Y$, the canonical map 
    $$|X\times_{Y}Z|_{Ber}\rightarrow |X|_{Ber}\times_{|Y|_{Ber}}|Z|_{Ber}$$
    is a homeomorphism.
\end{definition}

In particular, open immersions are spatial.

%When \(R = \mathbb{Z}_{triv\) is non-Archimedean, this will be the category or \(\C\), this will be the category \(\mathbf{dAn}_R\) of derived dagger affinoid spaces, and when \(R = \mathcal{O}_K\), this will be the category \(\mathbf{dAn}_R^{form}\) of derived formal schemes.




\begin{definition}
    Let $f:X\rightarrow Y$ be a morphism and $U\subset Y$ an open immersion. Then $f$ is said to be \textit{spatial on the complement of }$U$ if for every morphism $Z\rightarrow Y$, the natural map
    $$|Z\times_{Y}X|_{Ber}\setminus |Z\times_{Y}X\times_{Y}U|_{Ber}\rightarrow |Z|_{Ber}\times_{|Y|_{Ber}}|X|_{Ber}$$
  is a homeomorphism to

   $$  |Z|_{Ber}\times_{|Y|_{Ber}}|X|_{Ber}\setminus (|Z|_{Ber}\times_{|Y|_{Ber}}|X|_{Ber}\times_{|Y|_{Ber}}|U|_{Ber}).$$
\end{definition}

\begin{remark}\label{rem:absolute}
The case when $Z=Y$ is automatic. In fact this says that $|X|_{Ber}\setminus|X\times_{Y}U|_{Ber}\cong|X|_{Ber}\setminus |X|_{Ber}\times_{|Y|_{Ber}}|U|_{Ber}.$ In particular this amounts to $|X\times_{Y}U|_{Ber}\cong |X|_{Ber}\times_{|Y|_{Ber}}|U|_{Ber},$ which simply follows from the fact that $U\rightarrow Y$ is an open immersion. 
%Thus the requirement for arbitrary $Z$ is that 
%$$|Z\times_{Y}X|_{Ber}\setminus |Z\times_{Y}U|_{Ber} \rightarrow|Z|_{Ber}\times_{|Y|_{Ber}}|X|_{Ber}\setminus (|Z|_{Ber}\times_{|Y|_{Ber}}|U|_{Ber})$$
%be a homeomorphism.
\end{remark}

\begin{remark}
    If $f:X\rightarrow Y$ is spatial on the complement of $U$, then for any $Z\rightarrow Y$, $f':X\times_{Y}Z\rightarrow Z$ is spatial on the complement of $U\times_{Y}Z$.
\end{remark}

\begin{lemma}
    If $f:X\rightarrow Y$ is spatial and $U\subset Y$ any open immersion, then $f$ is spatial on the complement of $U$. 
\end{lemma}

\begin{proof}
    Let $Z\rightarrow Y$ be a morphism. We have $|X\times_{Y}Z|_{Ber}\cong |X|_{Ber}\times_{|Y|_{Ber}}\times|Z|_{Ber}$ and $|Z\times_{Y}X\times_{Y}U|_{Ber}\cong |Z|_{Ber}\times_{|Y|_{Ber}}|X|_{Ber}\times_{|Y|_{Ber}}|U|_{Ber}$. Now the claim is obvious.
\end{proof}


\begin{lemma}\label{lem:andrspat}
 Let $f:X\rightarrow Y$ be a morphism such that 
    $$X= (X\times_{Y}U)\cup V$$
    where 
    \begin{enumerate}
        \item 
        $U\rightarrow Y$ is an open immersion;
        \item 
       each $V\rightarrow X\rightarrow Y$ is an open immersion. 
    \end{enumerate}
     Then $f$ is spatial on the complement of $U$.
\end{lemma}

\begin{proof}


    Let $g:Z\rightarrow Y$ be any morphism, and $f':Z\times_{Y}X\rightarrow Z$ the morphism induced by pullback. We have 
    $$Z\times_{Y}X\cong (Z\times_{Y}X\times_{Y}U)\cup Z\times_{Y}V,$$
    where $Z\times_{Y}V\rightarrow Z$ is an open immersion, and 
    $$(Z\times_{Y}X\times_{Y}U)\cong (Z\times_{Y}X)\times_{Z}(Z\times_{Y}U),$$
    with $Z\times_{Y}U\rightarrow Z$ being an open immersion.
We then have $|Z\times_{Y}X|_{Ber}\cong |Z\times_{Y}X\times_{Y}U|_{Ber}\cup|Z\times_{Y}V|_{Ber}$.
   Then we have


\begin{align*}
       |Z\times_{Y}X|_{Ber}\setminus |Z\times_{Y}X\times_{Y}U|_{Ber} \\&=|Z\times_{Y}V|_{Ber}\setminus (|Z\times_{Y}X\times_{Y}U|_{Ber}\times_{|Z\times_{Y}X|_{Ber}}|Z\times_{Y}V|_{Ber})\\
