\subsubsection{Derived $\mathrm{T}$-analytic subspaces}\label{subsubsec:Tansub}

Let us here specialise again. Let $\mathrm{T}$ be a $\underline{\Lambda}$-generating class of algebras of homotopy polynomial type. Denote the monoidal unit in $\underline{\mathbf{C}}$ by $\mathbb{I}$. Let $p_{\lambda_{1},\ldots,\lambda_{n}}:\mathrm{Sym}(\mathbb{I}^{\oplus n})\rightarrow\mathrm{T}(\lambda_{1},\ldots,\lambda_{n})$ denote the morphisms realising $\mathrm{T}$ as a class of homotopy polynomial type. For an object $A\in\mathrm{Comm}(\mathbf{C}^{\heart})$ we write $\underline{A}=\mathrm{Hom}(\mathbb{I},A)$ for the \textit{underlying algebra of} $A$.

We fix a category $\mathbf{A}_{\mathrm{T}}$ of so-called $\mathrm{T}$-\textit{analytic affinoids}, and let $\mathbf{A}_{\mathrm{T}}^{\heart}$ be the full subcategory of $\mathbf{A}_{\mathrm{T}}$ consisting of those objects $\mathrm{Spec}(A)$ with $A$ in the heart of the $t$-structure on $\mathbf{C}$. For $\tau$ we fix the $\mathrm{T}$-rational topology. 

\begin{definition}
    $\mathbf{A}_{\mathrm{T}}$ is said to be \textit{analytic} if the following conditions hold.
    \begin{enumerate}
    \item 
    There is a consistent system of modules $\mathbf{F}_{A}\subset\mathrm{Mod}(A)$ for $\mathrm{Spec}(A)\in\mathbf{A}_{\mathrm{T}}^{\heart}$ (i.e., whenever $\mathrm{Spec}(B)\rightarrow\mathrm{Spec}(A)$ is a map in $\mathbf{P}\cap\mathbf{A}_{\mathrm{T}}^{\heart}$, and $M\in\mathbf{F}_{A}$, then $B\otimes_{A}^{\mathbb{L}}M\in\mathbf{F}_{B}$), such that a finite collection of rational localisations $\{\mathrm{Spec}(A_{i})\rightarrow\mathrm{Spec}(A)\}_{i\in\mathcal{I}}$ between objects in $\mathbf{A}^{\heart}_{\mathrm{T}}$ is a cover if and only if the restriction of the functors $A_{i}\otimes_{A}(-):\mathrm{Mod}(A)\rightarrow\mathrm{Mod}(A_{i})$ to $\mathbf{F}_{A}$ is a jointly conservative collection.
        \item 
        For any object $\mathrm{Spec}(A)$ of $\mathbf{A}_{\mathrm{T}}^{\heart}$ and any $M$ of $\mathbf{F}_{A}$, the natural morphism
     $$\underline{M}[x_{1},\ldots,x_{k}]\rightarrow \underline{M}[[x_{1},\ldots,x_{n}]]$$
     factors as 
    $$\underline{M}[x_{1},\ldots,x_{k}]\rightarrow\underline{M\otimes\mathrm{T}(\lambda_{1},\ldots,\lambda_{k})}\rightarrow \underline{M}[[x_{1},\ldots,x_{n}]],$$
    where the first map is $\mathrm{Id}_{M}\otimes p_{\lambda_{1},\ldots,\lambda_{k}}$, and the second map is a monomorphism.
       \item 
   Consider any $\mathrm{T}(\lambda)$. The \textit{multiplication by} $z$ morphism
   $$z\times:\mathrm{T}(\lambda)\rightarrow\mathrm{T}(\lambda)$$
   has cokernel isomorphic to $\mathbb{I}$.
    \end{enumerate}
    If objects of objects of $\mathbf{F}_{A}$ are transverse to $\mathrm{T}$-\'{e}tale localisations, then we say that $\mathbf{A}_{\mathrm{T}}$ is \'{e}tale analytic.
\end{definition}


The second condition in particular says that we may regard $C\otimes\mathrm{T}(\lambda_{1},\ldots,\lambda_{k})$ as a power series algebra. The third condition gives a canonical augmentation.

\begin{example}
    Let $R$ be a unital commutative ring, and let $\mathrm{T}$ be given by $\mathrm{T}(n)=R[x_{1},\ldots,x_{n}]$. Let $\mathbf{A}_{\mathrm{T}}$ be the category of all derived $R$-algebras. For $A$ a discrete algebra, let $\mathbf{F}_{A}$ denote the category of all $A$-modules. The first two conditions clearly hold. Now, a rational localisation of underived $R$-algebras is in particular \'{e}tale of finite presentation. In particular it is flat. Hence a rational localisation is a flat homotopy epimorphism, and can therefore be refined by Zariski localisations. It follows that the derived rational localisation topology is just the usual derived Zariski topology. Now a finite collection of Zariski open immersions $\{\mathrm{Spec}(A_{i})\rightarrow\mathrm{Spec}(A)\}$ of discrete $R$-algebras is a cover precisely if it is a conservative collection. 
    %Let $\mathfrak{p}$ be a prime ideal of $\mathrm{Spec}(A)$. Consider the finitely generated $A$-module $A\big\slash\mathfrak{p}$. Suppose that $A_{i}\otimes_{A}(A\big\slash\mathfrak{p})\cong A_{i}\big\slash(A_{i}\otimes_{A}\mathfrak{p})\cong0$. Then $\mathfrak{p}$ cannot be in the image of $\mathrm{Spec}(A_{i})\rightarrow\mathrm{Spec}(A)$. Thus the collection is not a cover. Conversely, suppose that the  the restriction of the functors $A_{i}\otimes_{A}(-):\mathrm{Mod}(A)\rightarrow\mathrm{Mod}(A_{i})$ to finitely generated $A$-modules is a jointly conservative collection. The same argument as above in reverse shows that the map on Zariski spectra is surjective. Hence we get a cover.
\end{example}

\begin{example}
    Let $K$ be a non-trivially valued, non-Archimedean Banach field. Let $\mathbf{C}$ be the derived context of complete bornological $K$-modules (Section \ref{sec:bornologies}), and let $\mathrm{T}$ be given by $\mathrm{T}(\lambda_{1},\ldots,\lambda_{n})=K<\frac{x_{1}}{\lambda_{1}},\ldots,\frac{x_{n}}{\lambda_{n}}>$, the Tate algebra of radius $(\lambda_{1},\ldots,\lambda_{n})$. Here each $\lambda_{i}\in |K|\cap\mathbb{R}_{>0}$, where $|K|$ is the image of $|-|:K\rightarrow\mathbb{R}_{\ge0}$. Condition $(3)$ is clearly satisfied. Let $\mathbf{A}_{\mathrm{T}}$ denote the class of objects $\mathrm{Spec}(A)$ such that $\pi_{0}(A)$ is of the form $K<\frac{x_{1}}{\lambda_{1}},\ldots,\frac{x_{n}}{\lambda_{n}}>\big\slash I$ for a (necessarily closed and finitely generated) ideal $I$, and $\pi_{n}(A)$ is a finitely generated $\pi_{0}(A)$-module. As we shall see, $\mathrm{T}$-\'{e}tale maps of discrete objects of $\mathbf{A}^{\heart}_{\mathrm{T}}$ are just \'{e}tale maps of rigid affinoids in the usual sense. Let $\tau$ be the $\mathrm{T}$-rational topology. For $\mathrm{Spec}(A)\in\mathbf{A}_{\mathrm{T}}^{\heart}$, let $\mathbf{F}_{\mathrm{A}}$ denote the class of all complete bornological $A$-modules which are transverse to $\mathrm{T}$-\'{e}tale morphisms. This class of modules clearly satisfies condition $(4)$. Condition $(2)$ is satisfied because the object $K<\frac{x_{1}}{\lambda_{1}},\ldots,\frac{x_{n}}{\lambda_{n}}>$ is strongly flat (i.e., tensoring commutes with kernels). Condition $(1)$ is a consequence of the proof of Theorem \ref{thm:refetalecoverequivalent}, and the fact that maps $A\rightarrow k$ with $k$ a non-trivial complete valued are transverse to $\mathrm{T}$-\'{e}tale morphisms, which follows from Lemma \ref{lem:discetaletrans}. If we were to restrict to localisations instead of worrying about \'{e}tale morphisms, we could instead have used \cite{MR3626003}*{Theorem 5.39}.
\end{example}

\begin{example}
    Let $\mathbf{C}$ be the derived context of complete bornological $\mathbb{C}$-modules (Section \ref{sec:bornologies}). For $(\underline{r})\in\mathbb{R}_{>0}$ let $\mathrm{T}(\underline{r})=W_n(\underline{r})^\dagger$ be the ring of overconvergent power series (Subsection \ref{subsec:overconv}). Let $\mathbf{A}_{\mathrm{T}}$ consist of objects $\mathrm{Spec}(A)$ with $\pi_{0}(A)$ of the form $\mathrm{T}(\underline{r})=W_n(\underline{r})^\dagger\big\slash I$, where $I$ is a (necessarily closed and finitely generated) ideal, and $\pi_{n}(A)$ is finitely presented over $\pi_{0}(A)$.
    Property $(3)$ is clear. For $\mathrm{Spec}(A)\in\mathbf{A}_{\mathrm{T}}$, let $\mathbf{F}_{A}$ denote the class of complete bornological $A$-modules which are transverse to rational localisations, so that Property $(4)$ is satisfied. Property $(2)$ is satisfied because the object $W_n(\underline{r})^\dagger$ is strongly flat (i.e., tensoring commutes with kernels). The joint conservativity condition follows immediately from \cite{bambozzi2016dagger}*{Theorem 5.15}. 
\end{example}

\begin{lemma}[c.f. \cite{soor2024derived}*{Lemma 2.30}]
    Let $X$ be a derived $\mathrm{T}$-analytic space. Let $V\subset t_{\le0}X_{0}$ be open immersion. Then there exists an open immersion $U\subset X$ (resp. an \'{e}tale morphism $U\rightarrow X$) such that $t_{\le0}U_{0}=V$. Moreover $U$ is unique up to equivalence. If $\mathbf{A}_{\mathrm{T}}$ is \'{e}tale analytic this is also true for \'{e}tale morphisms.
\end{lemma}

\begin{proof}
We prove the open immersion case, the \'{e}tale case being similar. Since the questions is local, we may assume that $X=\mathrm{Spec}(A)$, $V=\mathrm{Spec}(\tilde{B})$, and $\pi_{0}(A)\rightarrow\tilde{B}$ is a rational localisation. 
  We may write \begin{multline*}
    \tilde{B}\cong\pi_{0}(A)\otimes^{\mathbb{L}}\mathrm{T}(\lambda_{1},\ldots,\lambda_{n})\big\slash\big\slash(gx_{1}-f_{1},\ldots,gx_{n}-f_{n}) \\
    \cong\pi_{0}(A)\otimes\mathrm{T}(\lambda_{1},\ldots,\lambda_{n})\big\slash(gx_{1}-f_{1},\ldots,gx_{n}-f_{n})\end{multline*} where $(g,f_{1},\ldots,f_{n})$ generate the unit ideal. Put $B\defeq A\otimes^{\mathbb{L}}\mathrm{T}(\lambda_{1},\ldots,\lambda_{n})\big\slash\big\slash(gx_{1}-f_{1},\ldots,gx_{n}-f_{n})$. This is a derived rational localisation such that $\pi_{0}(B)\cong\tilde{B}$. Let $A\rightarrow B'$ be another rational localisation such that $\pi_{0}(A\rightarrow B')\cong\pi_{0}(A)\rightarrow\tilde{B}$. Now both $B$ and $B'$ are formally \'{e}tale over $A$. Thus the isomorphism $\pi_{0}(B)\cong\tilde{B}\cong\pi_{0}(B')$ lifts, uniquely up to a contractible choice, to an equivalence $B\cong B'$.
\end{proof}

\begin{corollary}
    The morphism of spaces $|X_{0}|\rightarrow |X|$ is a homeomorphism.
\end{corollary}

\begin{lemma}\label{lem:closedimlift}
Let $f:X\rightarrow Y$ be a closed immersion. For any open immersion $U\rightarrow X$, there exists an open immersion $V\rightarrow Y$ such that $U\cong V\times_{X}Y$. 
\end{lemma}

\begin{proof}
    We may assume that $X\cong\mathrm{Spec}(B)$ $Y\cong\mathrm{Spec}(A)$, and that they are both discrete. Then $B\cong A\big\slash(f_{1},\ldots,f_{n})$. Moreover we may assume that $U\cong\mathrm{Spec}(C)$ where $B\rightarrow C$ is a $\mathrm{T}$-rational localisation. Write $C\cong B\otimes T(\lambda_{1},\ldots,\lambda_{m})\big\slash(g_{0}x_{1}-g_{1},\ldots,g_{0}x_{m}-g_{m})$ with $(g_{0},\ldots,g_{m})$ generating the unit ideal in $B$. For each $0\le i\le m$ pick some preimage $\tilde{g}_{i}$ of $g_{i}$ in $A$. Then $(\tilde{g}_{0},\ldots,\tilde{g}_{m},f_{1},\ldots,f_{n})$ generate the unit ideal of $A$. Write $$\tilde{C}=A\otimes\mathrm{T}(\lambda_{1},\ldots,\lambda_{m},\gamma_{1},\ldots,\gamma_{n})\big\slash(\tilde{g}_{0}x_{1}-\tilde{g}_{1},\ldots,\tilde{g}_{0}x_{m}-\tilde{g}_{m},\tilde{g}_{0}z_{1}-f_{1},\ldots,\tilde{g}_{0}z_{n}-f_{n}).$$
    This is a rational localisation. Base-changing to $B$ gives the rational localisation
    $$B\otimes\mathrm{T}(\lambda_{1},\ldots,\lambda_{m},\gamma_{1},\ldots,\gamma_{n})\big\slash(g_{0}x_{1}-g_{1},\ldots,g_{0}x_{m}-g_{m},g_{0}z_{1},\ldots,g_{0}z_{n}).$$
    This is isomorphic to 
      $$C\otimes T(\gamma_{1},\ldots,\gamma_{n})\big\slash(g_{0}z_{1},\ldots,g_{0}z_{n}).$$
      We claim that $(g_{0}z_{1},\ldots,g_{0}z_{n})=(z_{1},\ldots,z_{n})$. Let $I$ denote the ideal on the left-hand side of the equation, and $I'$ the ideal on the right-hand side. Clearly $I\subset I'$. We have $g_{0}z_{j}\in I$ for all $j$. Then $[x_{i}]g_{0}z_{j}=g_{i}z_{j}$ for each $i$. Since we can write $1$ as a linear combination of the $g_{i}$s, we get $z_{j}\in I$ for all $j$. Thus $I'\subset I$, as required. 
\end{proof}

\begin{theorem}
Let $X$ and $Y$ be discrete and $f:X\rightarrow Y$ an algebraically closed immersion.
    $\mathrm{An}_{\mathrm{T}}(X)$ is a closed sub-locale of $\mathrm{An}_{\mathrm{T}}(Y)$. In particular $f$ is a closed immersion.
\end{theorem}

\begin{proof}
    The morphism of frames $\pi_{X}:\mathrm{An}_{\mathrm{T}}(Y)\rightarrow\mathrm{An}_{\mathrm{T}}(X)$ is a surjection by Lemma \ref{lem:closedimlift}. This proves that $\mathrm{An}_{\mathrm{T}}(X)$ is a sub-locale of $\mathrm{An}_{\mathrm{T}}(Y)$.

Now $\pi_{X}$ has a right adjoint, $\pi_{X}^{*}$, given by 
$$\pi_{X}^{*}(W)=\bigcup\{V\rightarrow Y:V\times_{Y}X\subset W\}.$$
Consider an open immersion $\mathrm{Spec}(C)\rightarrow\mathrm{Spec}(A)$. We have 
$$\pi_{X}^{*}\pi_{X}\mathrm{Spec}(C)=\bigcup\{\mathrm{Spec}(D)\rightarrow Y:\mathrm{Spec}(D\big\slash(f))\subset\mathrm{Spec}(C\big\slash(f)).$$
The fixed points of the nucleus $\pi_{X}^{*}\pi_{X}$ are those $V$ such that whenever $\mathrm{Spec}(D)\rightarrow X$ is such that $\mathrm{Spec}(D\big\slash(f))\subset X\times_{Y}V$, then $\mathrm{Spec}(D)\subset V$. 


On the other hand consider $U=\mathrm{Spec}(A_{f}^{\mathrm{T}})\subset\mathrm{Spec}(A)$. The nucleus defining the closed complement of $U$ is 
$$j_{CU}:V\mapsto V\cup U.$$
The fixed points are clearly those $V$ such that $U\subset V$.
We need to show that the fixed points of these nuclei coincide. Without loss of generality we may assume that the fixed points in both cases are of the form $V=\mathrm{Spec}(C)$ for some $C$.

