 \begin{theorem}\label{thm:tilde-nuc}
    Let $R$ be a $\pi$-adic Banach ring.
     The natural functor
     $$\mathbf{D}(\mathsf{Ban}_{R}^{\le1})^\circ\rightarrow\varprojlim_{n}\mathbf{D}(\mathsf{Mod}_{R\big\slash (\pi^{n})})$$
     is an equivalence of categories. In particular it coincides with the category of derived \(\dvgen\)-adically complete modules.
 \end{theorem}

\begin{proof}
We have that both $\mathbf{D}(\mathrm{Ban}_{R}^{\le1})^\circ$ and $\varprojlim\mathbf{D}(\mathsf{Mod}_{R\big\slash (\pi^{n})}$ are reflective subcategories of $\mathbf{Ch}(\mathrm{SNorm}_{R}^{\le1})^\circ$. The left adjoint to the first inclusion sends a dg-projective complex $\tilde{l}^{1}(V_{\bullet})$ to $l^{1}(V_{\bullet})$, and the left adjoint to the second inclusion sends $\tilde{l}^{1}(V_{\bullet})$ to $\mathbf{lim}_{n}(R\big\slash (\pi^{n}))\hat{\otimes}^{\mathbb{L}}\tilde{l}^{1}(V_{\bullet})$. We claim that term-wise this is just the completion. Now, since $\tilde{l}^{1}(V_{\bullet})$ is a dg-projective complex, it is dg-flat, so that $$(R\big\slash (\pi^{n}))\hat{\otimes}^{\mathbb{L}}\tilde{l}^{1}(V_{\bullet})\cong (R\big\slash (\pi^{n}))\hat{\otimes}\tilde{l}^{1}(V_{\bullet})\cong \tilde{l}^{1}(V_{\bullet})\big\slash\pi^{n}\tilde{l}^{1}(V_{\bullet})\cong \tilde{l}^{1}(V_{\bullet})\big\slash B_{\tilde{l}^{1}(V_{\bullet})}(0,|\pi|^{n}).$$
Thus $\mathbf{lim}_{n}(R\big\slash (\pi^{n}))\hat{\otimes}^{\mathbb{L}}\tilde{l}^{1}(V_{\bullet})$ just computes the completion, as required.
\end{proof}

