\begin{definition}
    Let $R$ be a Banach ring with pseudo-uniformiser $\pi$. An $R$-module $M$ is said to be $\pi$-\textit{adically flat} if each $M\big\slash\pi^{k}M$ is algebraically flat as an $\underline{R\big\slash(\pi^{k})}$ module.
\end{definition}

\begin{proposition}
    Let $R$ be a Banach ring with pseudo-uniformiser $\pi$ which is $\pi$-torsion free. Let $M$ and $N$ be $\pi$-adic normed $R$-modules which are $\pi$-torsion free. If $M\otimes_{R}N$ is $\pi$-torsion free then the tensor product norm on $M\otimes_{R}N$ coincides with the $\pi$-adic one.
\end{proposition}

\begin{proof}
    We have that the tensor product norm is given by the separation of the semi-norm $\rho(v)=\mathrm{inf}\{\mathrm{max}||x_{i}\otimes y_{i}||:v=\sum_{i}x_{i}\otimes y_{i}\}$.  Let us prove that $\rho(\pi v)=|\pi|\rho(v)$. In general, clearly $\rho(\pi v)\le |\pi|\rho(v)$. When $\rho(v)=0$ it is clear that $\rho(\pi v)=0=|\pi|\rho(v)$. Suppose that $\rho(v)\neq0$. We claim that $\rho(\pi v)\neq0$. Indeed, if $\rho(\pi v)=0$, then for all $l>0$ we could find a representation $\pi v=\sum x_{i}\otimes y_{i}$ with $\mathrm{max}\{||x_{i}|| ||y_{i}||\}=|\pi|^{l}$. This means we can write $x_{i}\otimes y_{i}=\pi^{l}\tilde{x}_{i}\otimes\tilde{y}_{i}$ for some $\tilde{x}_{i},\tilde{y}_{i}$. Then $v=\pi^{l-1}\sum\tilde{x}_{i}\otimes\tilde{y}_{i}$. Thus $\rho(v)\le |\pi|^{l-1}$. Since this is true for all $l$, we have $\rho(v)=0$.

    Now assume $\rho(\pi v)\neq0$, i.e. $\rho(v)\neq0$. Write $\rho(\pi v)=|\pi|^{l}$ for some $l$. Clearly $l\ge 1$. Then there is some representation $\pi v=\sum_{i}x_{i}\otimes y_{i}$, where
    $\mathrm{max}_{i}||x_{i}|| ||y_{i}||=|\pi|^{l}$. Write $x_{i}=\pi^{s_{i}}\tilde{x}_{i}, y_{i}=\pi^{t_{i}}\tilde{y}_{i}$. Then $s_{i}+t_{i}=l_{i}\ge l$ for all $i$, and for some $i_{0}$, $s_{i_{0}}+t_{i_{0}}=l$. We may write $x_{i}\otimes y_{i}=\pi^{l}\tilde{x}_{i}\otimes\tilde{y}_{i}$. Then $\pi v=\pi^{l}\sum_{i}\tilde{x}_{i}\otimes\tilde{y}_{i}=\pi^{l}\tilde{v}$, where $\tilde{v}=\sum_{i}\tilde{x}_{i}\otimes\tilde{y}_{i}$. Note we must have $\rho(\tilde{v})=1$. Otherwise the proof above shows it would be divisible by $\pi$. Thus $v=\pi^{l-1}\tilde{v}$, and so $\rho(v)\le |\pi|^{l-1}$, and $|\pi|\rho(v)\le\rho(\pi v)$. 
\end{proof}


\begin{lemma}\label{lem:flattorsfree}
Let $R$ be a Banach ring with pseudo-uniformiser $\pi$, which is $\pi$-torsion free. Let $M$ and $N$ be $\pi$-torsion free $R$-modules. Equip $R,M$, and $N$ with the $\pi$-adic norms. If $N$ is flat as an $R$-module then $N\otimes_{R}M$ is $\pi$-torsion free, and we have $N\otimes^{\mathbb{L}}_{R}M\cong N\otimes_{R}M$ in $\mathrm{Norm}_{R}^{\le1}$. In particular, we also have $N\hat{\otimes}^{\mathbb{L}}_{R}M\cong N\hat{\otimes}_{R}M$ in $\mathrm{Ban}_{R}^{\le1}$.
\end{lemma}

\begin{proof}
Pick a projective resolution $\overline{l}^{1}(V_{\bullet})\rightarrow M$ in $\mathrm{Norm}_{R}^{\le1}$. Consider
$$N\otimes_{R}\overline{l}^{1}(V_{\bullet})\rightarrow N\otimes_{R}M.$$
The complex $N\otimes_{R}\overline{l}^{1}(V_{\bullet})$ computes $N\otimes^{\mathbb{L}}_{R}M$, so it suffices to prove that the augmented complex
$$N\otimes_{R}\overline{l}^{1}(V_{\bullet})\rightarrow N\otimes_{R}M$$
is acyclic. Since $N$ is flat $N\otimes_{R}M$ is $\pi$-torsion-free. Thus its norm is the $\pi$-adic one. It now remains to prove that the augmented complex is algebraically acyclic. But this follows from flatness of $N$.
\end{proof}


\subsubsection{Derived quotients by uniformisers}


\begin{lemma}\label{lem:htpy-inv-lim}
Let $M\in\mathbf{D}(\mathsf{SNorm}_{R}^{\le1})$ be such that each $\pi_{n}(M)$ is $\pi$-torsion free (that is, multiplication by $\pi$ is an admissible monomorphism). Then the map
$$\pi_{n}(M)\big\slash\pi^{k}\rightarrow\pi_{n}(M\big\slash\big\slash(\pi^{k}))$$
is an equivalence for each $k$.
\end{lemma}

\begin{proof}
$M\big\slash\big\slash\pi^{k}$ is computed as the cone of the `multiplication by $\pi^{k}$' map
$$\times\pi^{k}:M\rightarrow M.$$
Let $C$ denote the cone.
    We have a long exact sequence
    \begin{displaymath}
        \xymatrix{
\ldots\ar[r] &\pi_{n+1}(C)\ar[r] & \pi_{n}(M)\ar[r]^{\times\pi^{k}} &\pi_{n}(M)\ar[r] &\pi_{n}(C)\ar[r] & \ldots.
        }
    \end{displaymath}
    By assumption the map $\times\pi^{k}:\pi_{n}(M)\rightarrow \pi_{n}(M)$ is an admissible monomorphism. Thus the sequence 
    \begin{displaymath}
        \xymatrix{
        0\ar[r] & \pi_{n}(M)\ar[r]^{\times\pi^{k}} &\pi_{n}(M)\ar[r] &\pi_{n}(C)\ar[r] &0
        }
    \end{displaymath}
    is short exact, which completes the proof.
\end{proof}

\begin{lemma}\label{lem:htpy-inverse-lim2}
    Let $M\in\mathbf{D}(\mathsf{Norm}_{R}^{\le1})$ be such that each $\pi_{n}(M)$ is $\pi$-torsion free and derived $\pi$-adically complete. Then the map
    $$M\rightarrow\varprojlim_{k}M\big\slash\big\slash\pi^{k}$$
    is an equivalence, and 
    $$\pi_{*}(M)\cong\varprojlim_{k}\pi_{*}(M)\big\slash\pi^{k}.$$
\end{lemma}

\begin{proof}
    We have $\pi_{n}(M\big\slash\big\slash\pi^{k})\cong\pi_{n}(M)\big\slash\pi^{k}$ by Lemma \ref{lem:htpy-inv-lim}. We therefore have that each map $\pi_{n}(M\big\slash\big\slash\pi^{k+1})\rightarrow\pi_{n}(M\big\slash\big\slash\pi^{k})$ is an epimorphism. By the long exact sequence for the homotopy groups of $\lim_{k}M\big\slash\pi^{k}$ and a Mittag-Leffler argument, we have 
    $$\pi_{*}(\varprojlim_{k}M\big\slash\big\slash\pi^{k})\cong\varprojlim_{k}\pi_{*}(M\big\slash\big\slash\pi^{k})\cong\varprojlim_{k}\pi_{*}(M)\big\slash\pi^{k}\cong\pi_{*}(M),$$
    as required. 
\end{proof}



\begin{lemma}
 Let $A\in\mathbf{DAlg}^{cn}(\bD_{\geq 0}(\mathsf{Norm}_{R}^{\le1}))$ and let $M$ be an $A$-module in $\mathbf{D}(\mathsf{Norm}_{R}^{\le1})$. Suppose that each $\pi_{n}(M)$ is $\pi$-torsion free.
    \begin{enumerate}
    \item 
  If $M$ is derived strong as an $A$-module then each $M\big\slash\big\slash\pi^{k}$ is derived strong as an $A\big\slash\big\slash\pi^{k}$-module.
\item 
If $\pi_{*}(A),\pi_{0}(M)\in\mathbf{D}_{\ge0}(\sf{Ban}_{A}^{\le1})^{\circ}$ and each $\pi_{*}(A)\otimes_{\pi_{0}(A)}\pi_{0}(M)$ is $\pi$-torsion free then the converse is true, that is if each $M\big\slash\big\slash\pi^{n}M$ is derived strong as an $A\big\slash\big\slash\pi^{k}$-module, then $M$ is derived strong as an $A$-module.
    \end{enumerate}
\end{lemma}

\begin{proof}
The first claim follows from \cite{ben2024perspective}*{Corollary 2.3.89}, and the fact that $\pi_{n}(M)$ is transverse to $\pi_{0}(A)\big\slash(\pi^{k})$ over $\pi_{0}(A)$.

To prove the partial converse claim, we are required to prove that $\pi_{*}(A)\hat{\otimes}^{\mathbb{L}}_{\pi_{0}(A)}\pi_{0}(M) \cong \pi_*(M)$ for all \(* \geq 0\). We have \(\pi_*(A//\dvgen^k) \otimes^{\mathbb{L}}_{\pi_0(A//\dvgen^k)} \pi_0(M//\dvgen^k M) \cong \pi_*(M//\dvgen^k M)\) for all \(* \geq 0\)  by the derived strength hypothesis on the reductions mod \(\dvgen\).  By Lemma \ref{lem:htpy-inv-lim}, we have \[(\pi_*(A) \hat{\otimes}_{\pi_0(A)} \pi_0(M))/\dvgen^k \cong \pi_*(M) / \dvgen^k\] for all \(* \geq 0\). Now we can conclude using Lemma \ref{lem:flattorsfree} and Lemma \ref{lem:htpy-inverse-lim2}. 
\end{proof}


