\begin{lemma}\label{lem:adic-subcat}
Let $R$ be a Banach ring such that $|r|\le1$ for all $r\in R$. Then the functor
$$\mathbf{D}_{\ge0}(\mathsf{Ban}_{R}^{\le1})^\circ\rightarrow \mathbf{D}_{\ge0}(\mathsf{Ind}(\mathsf{Ban}_R))$$
is strongly monoidal and fully faithful. 
\end{lemma}

\begin{proof}
    For full faithfullness we reduce to showing that any bounded map $f:l^{1}(V)\rightarrow l^{1}(W)$ is bounded by $1$. But any such bounded map is determined by the images of the elements $v\in V$. Moreover if $||f(v)||\le 1=||v||$ for all $v$ this implies that $||f||\le1$. This clearly follows from the fact that any element of $l^{1}(W)$ has norm bounded by $1$. 
\end{proof}


We also have the following useful fact.

\begin{lemma}
    Let $M, N\in\mathsf{Ban}^{\le1}_{R}$. If $M$ is transverse to $N$ in the strong exact structure, then it is transverse to $N$ in $\mathsf{Ban}_{R}$.
\end{lemma}

\begin{proof}
    There exists a strong resolution $P_{\bullet}\rightarrow M$ by objects $P_{n}$ which are projective in the strong exact structure on $\mathsf{Ban}^{\le1}_{R}$ and the quasi-abelian structure on $\mathsf{Ban}_{R}$. In particular $N\hat{\otimes}_{R}P_{\bullet}$ computes the derived tensor product in the strong exact structure, and in the quasi-abelian structure on $\mathsf{Ban}_{R}$. Hence if it is strongly quasi-isomorphic to $M\hat{\otimes}_{R}N$, then it is certainly quasi-isomorphic to $M\hat{\otimes}_{R}N$ in the quasi-abelian structure. 
\end{proof}

