\subsubsection{Categories of modules, and the cotangent complex}

Again let $R$ be a $\pi$-adic Banach ring which is $\pi$-torsion free. 

Let $A$ be a derived admissible adic $R$-algebra. Consider its derived category $\mathbf{D}(A)$. Let $\mathbf{D}^{coh}(A)$ denote the full subcategory of $\mathbf{D}(A)$ consisting of those modules $M$ such that each $\pi_{n}(M)$ is a coherent $A$-module. Consider the affinoid algebra $A[\frac{1}{\pi}]=K\hat{\otimes}^{\mathbb{L}}_{R}A$. We get the free-forgetful adjunction
$$\adj{A[\frac{1}{\pi}]\hat{\otimes}_{A}^{\mathbb{L}}(-)}{\mathbf{D}(A)}{\mathbf{D}(A[\frac{1}{\pi}])}{|-|}.$$

Let $\mathbf{D}^{coh}(A)$ denote the full subcategory of $A$-modules $M_{\bullet}$ such that each $\pi_{n}(M_{\bullet})$ is coherent as a $\pi_{0}(A)$-module. Similarly let $\mathbf{D}^{coh}(A)$ denote the full subcategory of $A[\frac{1}{\pi}]$-modules $N_{\bullet}$ such that each $\pi_{n}(N_{\bullet})$ is coherent (i.e. finitely presented) as a $\pi_{0}(A)[\frac{1}{\pi}]$-module.

Let $M_{\bullet}\in\mathbf{D}_{\ge0}^{coh}(A)$. We have a spectral sequence $\pi_{*}(A)[\frac{1}{\pi}]\hat{\otimes}_{\pi_{*}(A)}^{L}\pi_{*}(M_{\bullet})\cong\pi_{*}(M_{\bullet})[\frac{1}{\pi}]\Rightarrow\pi_{*}(A[\frac{1}{\pi}]\hat{\otimes}_{A}^{L}M_{\bullet})$. Each $\pi_{*}(M_{\bullet})[\frac{1}{\pi}]$ is finitely generated over $\pi_{0}(A)[\frac{1}{\pi}]$. Since $\pi_{0}(A)[\frac{1}{\pi}]$ is Noetherian, we have that $\pi_{*}(A[\frac{1}{\pi}]\hat{\otimes}_{A}^{L}M_{\bullet})$ is finitely presented. 

Thus $A[\frac{1}{\pi}]\hat{\otimes}_{A}^{L}(-)$ restricts to a functor
$$\mathbf{D}_{\ge0}^{coh}(A)\rightarrow\mathbf{D}_{\ge0}^{coh}(A[\frac{1}{\pi}]).$$

In fact we have $\mathbf{D}_{\ge0}^{coh}(A)\subseteq\mathbf{Rec}(\{A^{\oplus n}\})$, where $\mathbf{Rec}(\{A^{\oplus n}\})$ is the free cocompletion by geometric realisations, and similarly for $\mathbf{D}_{\ge 0}^{coh}(A[\frac{1}{\pi}]).$

\begin{lemma}
Let $M\in\mathbf{Mod}_A(\mathbf{D}(\sf{Ban}_{R}^{\le1}))$ be such that each $\pi_{m}(M)$ is a $\pi$-adically normed $\pi_{0}(A)$-module. Then we have 
$$\pi_{*}(M[\frac{1}{\pi}])\cong\pi_{*}(M)[\frac{1}{\pi}].$$
\end{lemma}

\begin{proof}
We may assume we are working over the ground ring $R$. By an easy truncation argument, we may also assume that everything is discrete. Thus we are reduced to proving  that, whenever $M$ is a $\pi$-adic $R$-module, it is transverse to $R[\frac{1}{\pi}]$. Now $M$ may be resolved by modules of the form $l^{1}(V)$ for $V$ a discrete normed set. Such objects are $\pi$-adic. Hence we are reduced to proving that, if
$$0\rightarrow K\rightarrow L\rightarrow M\rightarrow 0$$
is a strong exact sequence with $L$ and $M$ (and automatically $K$) being $\pi$-adic, the sequence
$$0\rightarrow K[\frac{1}{\pi}]\rightarrow L[\frac{1}{\pi}]\rightarrow M[\frac{1}{\pi}]\rightarrow 0$$
is strong exact. The sequence is evidently algebraically exact. It remains to prove that $ L[\frac{1}{\pi}]\rightarrow M[\frac{1}{\pi}]$ is a strong epimorphism. Since completion is exact, we can ignore completions. Let $\frac{m}{\pi^{k}}\in M$, which has norm $\frac{||m||}{|\pi|^{k}}$. Pick an element $l$ of $L$ mapping to $m$, which has the same norm as that of $m$. Then $\frac{l}{\pi^{k}}$ has the same norm as $\frac{m}{\pi^{k}}\in M$, and maps to it.
\end{proof}

\begin{lemma}\label{lem:formalmodelmods}
Let $M\in\mathbf{D}^{coh}_{\ge0}(A)$ be arbitrary, and $N\in\mathbf{D}^{coh}(A[\frac{1}{\pi}])$ have bounded homology. Let $f:M[\frac{1}{\pi}]\rightarrow N$ be a morphism. Then there exists an $\tilde{N}\in\mathbf{D}^{coh}(A)$ and a map $\tilde{f}:M\rightarrow\tilde{N}$ such that $f\cong\tilde{f}[\frac{1}{\pi}]$. Moreover we may assume that each $\pi_{m}(N)$ is $\pi$-torsion free. 
\end{lemma}

\begin{proof}
    This can be proven identically to \cite{antonio2018derived}*{Corollary A.2.2}, without the $\pi$-torsion free claim. For the $\pi$-torsion free claim we argue that for any $N\in\mathbf{D}^{coh}(A)$ of bounded homological dimension, there exists a $\tilde{N}\in\mathbf{D}^{coh}(A)$ concentrated in the same homological interval, together with a map $N\rightarrow\tilde{N}$, such that 
\begin{enumerate}
\item
each $\pi_{m}(\tilde{N})$ is $\pi$-torsion free;
\item
the map $N[\frac{1}{\pi}]\rightarrow\tilde{N}[\frac{1}{\pi}]$ is an equivalence.
\end{enumerate}
Let $N$ be concentrated in degress $[n,0]$. We prove the claim by induction on $n$. When $n=0$, so that $N$ is just a discrete $\pi_{0}(A)$-module, we just let $\tilde{N}=N\big\slash N_{\pi-torsion}$. Since the torsion submodule is coherent, $\tilde{N}$ is coherent.  Suppose we have proven the claim for some $n$, and let $N$ be concentrated in degrees $[n+1,0]$. We have a fibre-cofibre sequence
$$\pi_{n+1}(N)\rightarrow N\rightarrow \tau_{\le n}N.$$
Pick maps $\pi_{n+1}(N)\rightarrow\widetilde{\pi_{n+1}(N)}$, $\tau_{\le n}N\rightarrow\widetilde{\tau_{\le n}N}$ satisfying the requirements, guaranteed by the inductive hypothesis. Then we can glue these to a map $N\rightarrow\tilde{N}$ also satisfying the requirements.
\end{proof}


\begin{proposition}
    Let $A\rightarrow B$ be a map of derived topologically finitely presented adic $R$-algebras. Let $\mathbb{L}^{\le1}_{B\big\slash A}$ denote the cotangent complex computed in $\mathbf{Mod}_B(\mathbf{D}(\sf{Ban}_{R}^{\le1}))$, and let $\mathbb{L}_{B\big\slash A}$ denote the cotangent complex computed in the category $\mathbf{Mod}_B(\mathbf{D}(R))$. The natural map 
    $$i(\mathbb{L}^{\le1}_{B\big\slash A})\rightarrow\mathbb{L}_{B\big\slash A}$$
    is an equivalence.
\end{proposition}

\begin{proof}
    It suffices to prove this in the absolute case. That is, we may assume $A=R$. We may write $A\cong |R<x_{m1},\ldots,x_{mn_{m}}>|$. Thus it in fact suffices to prove the claim for rings of the form $R<y_{1},\ldots,y_{l}>$. But in this case we have $\mathbb{L}^{\le1}_{B}\cong B^{\oplus l}$, and $\mathbb{L}_{i(B)}\cong i(B)^{\oplus l}$, where in the latter case we use that $\mathrm{Sym}(R^{\oplus n})\rightarrow R<y_{1},\ldots,y_{l}>$ is a homotopy epimorphism. The map $i(B^{\oplus l})\rightarrow i(B)^{\oplus l}$ is the obvious identification.
    \end{proof}

    In particular, we can unambiguously refer to a map $A\rightarrow B$ of derived topologically finitely presented adic $R$-algebras being formally \'{e}tale, without specifying whether we are talking about $(\sf{Ban}_{R}^{\le1}))$, or $\mathbf{D}(R)$.

\begin{lemma}\label{lem:cotanderivedcomplete}
    Let $A\rightarrow B$ be a map of derived adic $R$-algebras topologically of finite type. Then $\mathbb{L}_{B\big\slash A}$ is a coherent $B$-module. If $A$ and $B$ are in fact admissible, then $\mathbb{L}_{B\big\slash A}$ is derived $\pi$-adically complete.
\end{lemma}

\begin{proof}
    It suffices to prove this in the absolute case, i.e. $A=R$. Write $\pi_{0}(B)\cong R<x_{1},\ldots,x_{n}>\big\slash I$ in $\mathrm{Comm}(\mathrm{Ban}_{R}^{\le1})$ with $I$ finitely generated. By projectivity, the map $R<x_{1},\ldots,x_{n}>\rightarrow \pi_{0}(B)$ lifts to a map $R<x_{1},\ldots,x_{n}>\rightarrow B$. Note that $\mathbb{L}_{R<x_{1},\ldots,x_{n}>\big\slash R}\cong R<x_{1},\ldots,x_{n}>^{\oplus n}$ so is coherent and derived $\pi$-adically complete. It suffices to prove that $\mathbb{L}_{B\big\slash R<x_{1},\ldots,x_{n}>}$ is coherent in the topologically finitely presented case, and derived $\pi$-adically complete in the admissible case. This follows from \cite{ben2024perspective}*{Lemma 2.4.123}.
\end{proof}

The next two results, and their proofs, are completely analogous to \cite{antonio2018derived} Theorem 4.4.4.

