\subsection{The topologies}

As in the dagger affinoid setting, we isolate a category of derived admissible formal schemes. The base category over which everything takes place is \(\mathbf{Aff}_{\bD(R)} = \mathbf{DAlg}^{cn}(\bD(R))\). To topologise this category, we consider the following:

%\begin{definition}
%Fix a class of maps $\mathbf{P}$ on derived connective (algebraic) rings which is descendable. We denote by $\mathbf{P}_{ad}$ the class of maps in $\mathbf{Ch}(\sf{Ban}_{R}^{\le1})$ such that
%each
%$$\{\mathrm{Spec}((R\big\slash\pi^{n}R)\otimes^{\mathbb{L}}B)\rightarrow\mathrm{Spec}((R\big\slash\pi^{n}R)\otimes^{\mathbb{L}}A)\}$$
%is in $\mathbf{P}$. This is called the class of \textit{adic }$\mathbf{P}$-maps.
%\end{definition}

\begin{definition}
    Let $R$ be a Banach ring with pseudo-uniformiser $\pi$. Let $f:A\rightarrow B$ be a map in either $\mathbf{DAlg}^{cn}(\bD(R))$ or in $\mathbf{DAlg}^{cn}(\bD(\sf{Ban}_{R}^{\le1}))$. We say $f$ is \textit{adically finitely presented} if it is of the form $A \to A\hat{\otimes}^\mathbb{L}R\gen{x_{1},\ldots,x_{n}}\big\slash\big\slash(f_{1},\ldots,f_{m})$ where $f_{1},\ldots,f_{m}:R\rightarrow\pi_{0}(A)\hat{\otimes} R\gen{x_{1}, \ldots,x_{n}}$.
\end{definition}

In complete analogy with the classical setting, we define derived adic topologies.

\begin{definition}
Fix a pre-topology $\tau$ on derived connective rings which is descendable and consists of algebraically finitely presented flat maps.
The \textit{adic }$\tau$-pre-topology on $\mathbf{Aff}_{\bD(\mathsf{SNorm}_R^{\le1})}$ consists of covers
$$\{\mathrm{Spec}(B)\rightarrow\mathrm{Spec}(A)\}$$
such that 
\begin{enumerate}
\item
$A\rightarrow B$ is descendable,
\item
$A\rightarrow B$ is adically finitely presented,
\item 
for any map $A\rightarrow C$ with $C$ a derived topologically finitely presented affinoid,
$$\{\mathrm{Spec}((R\big\slash\pi^{n}R\otimes^{\mathbb{L}}(C\hat{\otimes}_{A}^{\mathbb{L}}B))\rightarrow\mathrm{Spec}((R\big\slash\pi^{n}R\otimes^{\mathbb{L}}C)\}$$
is a cover in $\tau$.
\end{enumerate}
\end{definition}
We denote this topology by $\tau_{ad}$. In particular, for $\tau$ consisting of \'{e}tale covers, this gives the \textit{adic \'{e}tale pre-topology}, which we denote by \(\tau_{ad}^{\'{e}t}\). For $\tau$ consisting of faithfully flat covers, we get the \textit{adic faithfully flat topology}, which we denote by $\tau_{ad}^{ff}$. We have a further topology sitting in between:

\begin{definition}
\begin{enumerate}
    \item 
    A map $A\rightarrow B$ is said to be \textit{formally rig-\'{e}tale} if $\mathbb{L}_{B\big\slash A}[\frac{1}{\pi}]\cong 0$.
    \item 
    A morphism $A\rightarrow B$ is said to be \textit{rig-\'{e}tale} (c.f. \cite{MR4466640}*{Definition 1.3.3}) if it is formally rig-\'{e}tale, $\pi_{0}(A)\rightarrow\pi_{0}(B) $ is flat, and $\pi_{0}(A)\cong \pi_{0}(B)<x_{1},\ldots,x_{n}>\big\slash(f_{1},\ldots,f_{n})$, where the Jacobian determinant $det(J)$ generates an open ideal.
    \item
    The \textit{rig-\'{e}tale} topology, $\tau_{ad}^{rig-\'{e}t}$, is the topology consisting of covers $\{\mathrm{Spec}(B_{i})\rightarrow\mathrm{Spec}(A)\}$ in $\tau_{ad}^{ff}$ where each $A\rightarrow B_{i}$ is rig-\'{e}tale. 
    \end{enumerate}
\end{definition}
In particular if $A\rightarrow B$ is (formally) rig-\'{e}tale, then $A[\frac{1}{\pi}]\rightarrow B[\frac{1}{\pi}]$ is (formally) \'{e}tale, and rig-\'{e}tale morphisms are formally rig-\'{e}tale. 

\begin{lemma}\label{lemma:strongrigetale}
Let $A\rightarrow B$ be a map of derived admissible affinoid $\mathcal{O}_{K}$-algebras which is derived strong. Then it is formally rig-\'{e}tale if and only if $\pi_{0}(A)\rightarrow\pi_{0}(B)$ is formally rig-\'{e}tale.
\end{lemma}

\begin{proof}
If $A\rightarrow B$ is formally rig-\'{e}tale then the base change $\pi_{0}(A)\rightarrow\pi_{0}(A)\hat{\otimes}^{\mathbb{L}}_{A}B\cong\pi_{0}(B)$ is (formally) rig-\'{e}tale. 
Conversely, suppose that $\pi_{0}(A)\rightarrow\pi_{0}(B)$ is formally rig-\'{e}tale. Since the functor $M\mapsto M[\frac{1}{\pi}]$ is transverse to $\pi$-adic modules, $A[\frac{1}{\pi}]\rightarrow B[\frac{1}{\pi}]$ is still derived strong. Moreover we have $\pi_{0}(A[\frac{1}{\pi}]\rightarrow B[\frac{1}{\pi}])\cong(\pi_{0}(A)[\frac{1}{\pi}]\rightarrow\pi_{0}(B)[\frac{1}{\pi}])$ is \'{e}tale by assumption, and the result follows.
\end{proof}

