\begin{lemma}\label{lem:etale-pi_0}
    Let $\tau$ be either the \'{e}tale or faithfully flat topologies on rings. A map $f:A\rightarrow B$ of derived admissible adic rings gives rise to a cover in $\tau_{ad}$ if and only if 
    \begin{enumerate}
    \item 
    $f$ is derived strong,
    \item 
    and $\pi_{0}(f):\pi_{0}(A)\rightarrow\pi_{0}(B)$ gives rise to an \'{e}tale/ faithfully flat cover in the usual sense of adic rings.
    \end{enumerate}
\end{lemma}

\begin{proof}
    Suppose that $f$ is derived strong and $\pi_{0}(f):\pi_{0}(A)\rightarrow\pi_{0}(B)$ gives rise to an \'{e}tale/ faithfully flat cover in the usual sense of adic rings. Then each $\pi_{0}(f)\big\slash\big\slash(\pi^{k})\cong\pi_{0}(f)\big\slash(\pi^{k})$ is an \'{e}tale/ faithfully flat cover of finite presentation. Moreover the map $f\big\slash\big\slash(\pi^{k}):A\big\slash\big\slash(\pi^{k})\rightarrow B\big\slash\big\slash(\pi^{k})$ is strongly flat in the sense of \cite{toen2008homotopical}*{Definition 2.2.2.3}. Thus it is a derived faithfully flat map. By \cite{mathew2016galois}*{Proposition 3.31} it is descendable, and in fact is descendable of index $2$. Thus $A\rightarrow B$ is adically descendable of index $2$. Since $A$ is adically complete, $f$ is descendable.

    Conversely suppose that $f:A\rightarrow B$ gives rise to a cover in $\tau_{ad}$. Then each $f\big\slash\big\slash(\pi^{k})$ is a cover in $\tau$. Moreover, each $f\big\slash\big\slash(\pi^{k})$ is derived strong, by the torsion-free assumptions on $\pi_{*}(A)$ and $\pi_{*}(B)$. Thus $f$ is derived strong, and also by base-changing along $A\big\slash\big\slash(\pi^{k})\rightarrow\pi_{0}(A\big\slash\big\slash(\pi^{k}))\cong\pi_{0}(A)\big\slash(\pi^{k})$ gives that $\pi_{0}(A)\big\slash(\pi^{k})\rightarrow \pi_{0}(B)\big\slash(\pi^{k})$ is a cover in $\tau$, as required. 
\end{proof}

Denote by \(\bA_R^{form}\) the full subcategory of \(\mathbf{Aff}_{\bD(R)}\) consisting of derived admissible adic rings. Note that since the inclusion
$$\mathbf{D}_{\ge0}(\sf{Ban}_{R}^{\le1})^{o}\rightarrow\mathbf{D}_{\ge0}(R)$$
is strongly monoidal (and fully faithful), it sends descendable maps to descendable maps, so that  we may indeed view \(\mathbf{A}_R^{form}\) as a full subcategory of \(\mathbf{Aff}_R\) without changing the adic \(\tau\)-topology. The main reason to embed derived admissible algebras into bornological algebras is to be able to view these as \emph{nuclear} bornological algebras in a sense that will be made precise in the next section.  By Proposition \ref{prop:strongadc} it is easy to see that \((\mathbf{Aff}_{\bD(R)}, \tau_{ad}^{rig-et},\mathbf{P}^{sm}, \bA_R^{form})\) is a relative geometry tuple. 

\subsection{Faithfully flat descent}

In this section we prove some faithfully flat descent results in the formal, and rigid, settings. In the condensed setting, similar results along these lines have been obtained in \cite{mikami2023fppf}, \cite{mann2022p}, and \cite{anschutz2024descent}.
.
\begin{definition}
    A map $f:A\rightarrow B$ of bornological algebras is said to be \textit{algebraically flat} if the map of underlying algebras is flat.
\end{definition}

\begin{lemma}\cite{de1996etale}*{Observation 3.1.1}
Let $A\rightarrow B$ be a discrete standard \'{e}tale map of affinoids. Then it is algebraically flat. 
\end{lemma} 

\begin{lemma}
    Let $f:A\rightarrow B$ be an algebraically faithfully flat map of discrete affinoids over a non-trivially valued Banach field $K$. Then 
    $A\rightarrow B$ satisfies descent for $\mathbf{QCoh}$.
\end{lemma}

\begin{proof}
    We may find a rational cover $A\rightarrow A_{i}$ such that each map $A_{i}\rightarrow A_{i}\hat{\otimes}_{A}^{\mathbb{L}}B\cong A_{i}\hat{\otimes}_{A}B$ has a faithfully flat formal model $\tilde{A}_{i}\rightarrow\tilde{B}_{i}$ (\cite{MR4735655}*{Lemma 4.4}, \cite{MR1225983}*{Theorem 4.1}). Such a map is adically faithfully flat, and hence is descendable. Since the rational topology satisfies descent, we win. 
\end{proof}

\subsubsection{\'{E}tale maps and the \'{e}tale topology in rigid geometry}

Let us now discuss the \'{e}tale topology for rigid analytic spaces.
A \(T\)-standard \'etale map as in Definition \ref{def:T-standard-et} specialises to morphisms \(A \to B\) such that \(B\) is isomorphic to an \(A\)-algebra of the form \(A \hat{\otimes}_K^L K\gen{x_1, \dotsc, x_n}//(f_1, \dotsc, f_n)\) with invertible Jacobian.


\begin{lemma}\label{lem:discetaletrans}
   Let $A\rightarrow B$ be a discrete standard \'{e}tale map of discrete affinoids. Then $B\hat{\otimes}_A^{\mathbb{L}} B\cong B\hat{\otimes}_{A}B$ is an equivalence.
\end{lemma}

\begin{proof}
   The transversality condition $B\hat{\otimes}_A^\mathbb{L} B\cong B\hat{\otimes}_{A}B$ is local for the rational topology. Indeed for a localisation $A\rightarrow A_{i}$ we have
   $$(B\hat{\otimes}_{A}^{\mathbb{L}}A_{i})\hat{\otimes}^{\mathbb{L}}_{A_{i}}(B\hat{\otimes}_{A}^{\mathbb{L}}A_{i})\cong(B\hat{\otimes}_A^\mathbb{L} B)\hat{\otimes}^{\mathbb{L}}_{A}A_{i}.$$
   We also have 
 $$(B\hat{\otimes}_{A}A_{i})\hat{\otimes}_{A_{i}}(B\hat{\otimes}_{A}^{\mathbb{L}}A_{i})\cong(B\hat{\otimes}_A B)\hat{\otimes}_{A}A_{i}\cong(B\hat{\otimes}_A B)\hat{\otimes}^{\mathbb{L}}_{A}A_{i}$$
 where in the very last step we have used transversality of affinoids to rational localisations. Thus we may assume that $A\rightarrow B$ has a flat formal model $\tilde{A}\rightarrow\tilde{B}$ (\cite{MR1225983}*{Corollary 5.10}). Now the claim follows from Lemma \ref{lem:flattorsfree}
\end{proof}


 \begin{lemma}\label{lem:rigid-pi_0-etale}
     Let $A$ be an affinoid \(K\)-algebra, and let $B\cong A \langle x_{1},\ldots,x_{n}\rangle \big\slash(f_{1},\ldots,f_{n})$ where the determinant of the Jacobian of the $f_{i}$s is a unit in $B$. Then the diagonal map $B\hat{\otimes}_{A}^{\mathbb{L}}B\rightarrow B$ is a Zariski open immersion in $\mathbf{DAlg}(\sf{CBorn}_{K})$, and hence a localisation. In particular, the map $A\rightarrow B$ is formally \'{e}tale and the map
     $$A \hat{\otimes}_K^{\mathbb{L}} K \langle x_{1},\ldots,x_{n} \rangle \big\slash\big\slash (f_{1},\ldots,f_{n})\rightarrow B$$
     is an equivalence. 
 \end{lemma}

\begin{proof}
Consider the map $A\rightarrow A\hat{\otimes}_K^{\mathbb{L}} K \langle x_{1},\ldots,x_{n}\rangle \big\slash\big\slash (f_{1},\ldots,f_{n})$. By Proposition \ref{prop:Tstandard} this is formally \'{e}tale. In particular, the map 
$$A\rightarrow B\cong \pi_{0}(A\hat{\otimes}_K^L K \gen{x_{1},\ldots,x_{n}}\big\slash\big\slash (f_{1},\ldots,f_{n}))$$ is discrete formally \'{e}tale (i.e, $0\cong\Omega^{1}_{B\slash A}$). We have $0\cong\Omega^{1}_{B\slash A}\cong coker(I^{2}\rightarrow I)$ where $I$ is the kernel of $B\hat{\otimes}_{A}B\rightarrow B$. Now $B\hat{\otimes}_{A}B$ is affinoid, so that all ideals are admissible and we have $I^{2}=I$. The diagonal being a Zariski open immersion now follows from \cite{ben2024perspective}*{Lemma 2.6.154}. Since $B\hat{\otimes}_A^L B\cong B\hat{\otimes}_{A}B$ this implies that $A\rightarrow B$ is formally \'{e}tale. Now we have a commutative diagram
\begin{displaymath}
   \xymatrix{
    & A\ar[dl]\ar[drr] & & \\
A\hat{\otimes}^{\mathbb{L}} K \gen{x_{1},\ldots,x_{n}}\big\slash\big\slash (f_{1},\ldots,f_{n}) &&& B
}
\end{displaymath}
Both diagonal maps are formally \'{e}tale, and after applying $\pi_{0}$ to the bottom algebras, there exists an isomorphism of $A$-algebras between them. Thus it lifts uniquely, up to a contractible choice, to an equivalence over $A$
$$A\hat{\otimes}_K^{\mathbb{L}} K\gen{x_{1},\ldots,x_{n}}\big\slash\big\slash (f_{1},\ldots,f_{n})\rightarrow A$$
 \end{proof}

 \begin{corollary}\label{cor:standard-etale-characterisation}
  A map $A\rightarrow B$ of derived affinoids is standard \'{e}tale if and only if
   \begin{enumerate}
       \item 
       $A\rightarrow B$ is derived strong
       \item
        $\pi_{0}(A)\rightarrow\pi_{0}(B)$ is a discrete \'{e}tale map of affinoids.
   \end{enumerate}
 \end{corollary}

 \begin{proof}
Note that for any standard $\mathsf{Afnd}_{K}$-\'{e}tale map $A\rightarrow B$ of derived bornological algebras the map $\pi_{0}(A)\rightarrow\pi_{0}(B)$ is a discrete standard $\mathsf{Afnd}_{K}$-\'{e}tale map.

For the converse, by \cite{ben2024perspective}*{Proposition 2.6.160}, and the fact that discrete \'{e}tale maps are transverse to finitely presented modules, we know that $A\rightarrow B$ is formally \'{e}tale. Write $\pi_{0}(B)\cong\pi_{0}(A)<x_{1},\ldots,x_{n}>\big\slash(f_{1},\ldots,f_{n})$. Consider the diagram
\begin{displaymath}
    \xymatrix{
& A\ar[dl]\ar[dr] & \\
A<x_{1},\ldots,x_{n}>\big\slash\big\slash (f_{1},\ldots,f_{n}) & & B
     }
\end{displaymath}
Both $A\rightarrow A<x_{1},\ldots,x_{n}>\big\slash\big\slash (f_{1},\ldots,f_{n})$ and $A\rightarrow B$ are formally \'{e}tale. Thus the isomorphism $\pi_{0}(A<x_{1},\ldots,x_{n}>\big\slash (f_{1},\ldots,f_{n}))\cong\pi_{0}(B)$ lifts (uniquely up to a contractible choice) to an equivalence $A\cong B$ by \cite{ben2024perspective}*{Corollary 2.1.36}. 
 \end{proof}

 \begin{corollary}\label{cor:diagonal-loc}
     Let $A\rightarrow B$ be an \'{e}tale map of derived affinoids. Then $B\hat{\otimes}_{A}^{\mathbb{L}}B\rightarrow B$ is a Zariski open immersion, and hence a rational localisation.
 \end{corollary}

 \begin{proof}
This follows immediately from \cite{ben2024perspective}*{ Lemma 2.6.164}. 
 \end{proof}

