\begin{definition}\label{def:etale-desc}
    Let $K$ be a non-trivially valued non-Archimedean Banach field. Let $\tau$ be the rig-\'e{tale} pre-topology on simplicial commutative bornological $\mathcal{O}_{K}$-algebras, and consider the corresponding adic topology $\tau_{ad}$. We denote by $\tau_{pre}^{rig-\'{e}t}$ the pre-topology generated by maps $\mathrm{Spec}(B)\rightarrow\mathrm{Spec}(A)$
    such that 
    \begin{enumerate}
        \item 
     $A\rightarrow B$ is $\mathrm{Tate}_K$-\'{e}tale, that is, \(T\)-standard \'etale for \(T(x) = K\gen{x}\).
        \item 
    $A\rightarrow B$ is descendable. 
    \end{enumerate}
Denote by $\tau^{rig-\'{e}t}$ the topology generated by $\tau_{pre}^{rig-\'{e}t}$. 
\end{definition}

By construction we have the following.

\begin{theorem}\label{etaledescentadic}
    $\mathbf{QCoh}$ satisfies descent for $\tau_{pre}^{rig-\'{e}t}$, and hence $\tau^{rig-\'{e}t}$.
\end{theorem}

To describe the \'etale topology, it is convenient to define the following intermediate pre-topology $\tau_{pre}^{rig-\'et}\subset\tau^{rig-\'{e}t}_{ref}\subset\tau^{rig-\'{e}t}$, where we say that a $\mathrm{Afnd}_{K}$-\'{e}tale map $A\rightarrow B$ is a cover if there exists a rational cover $A\rightarrow A'$ such that $A'\rightarrow A'\hat{\otimes}^{\mathbb{L}}_{A}B$ is a descendable map. 

Let $\mathcal{M}(B)\rightarrow\mathcal{M}(A)$ be an \'{e}tale cover of affinoids in the usual sense. Then rationally locally, this \'{e}tale cover has a faithfully flat formal model. Faithfully flat covers of formal models, and hence their base changes are descendable. Thus the pre-topology on affinoids consisting of descendable \'{e}tale maps generates the same topology as the usual \'{e}tale topology. We denote the usual \'{e}tale topology of discrete affinoids by $\tau^{rig-\'{e}tale}_{disc}$. 

\begin{lemma}\label{lem:classical-etale}
    Let $A\rightarrow B$ be a map of derived affinoid algebras. It corresponds to a cover in $\tau_{ref}^{rig-\'{e}t}$ if and only if 
    \begin{enumerate}
        \item 
        it is derived strong,
        \item 
        $\pi_{0}(A)\rightarrow\pi_{0}(B)$
        corresponds to a cover in $\tau^{rig-\'{e}tale}_{disc}$.
    \end{enumerate}
\end{lemma}

\begin{proof}
Suppose $f:A\rightarrow B$ is a cover in $\tau_{ref}^{rig-\'{e}t}$. By Corollary \ref{cor:standard-etale-characterisation} $f$ is derived strong. Let $A\rightarrow A'$ be a rational cover. In particular it is also derived strong. Finally by transversality of finitely presented modules to \'{e}tale maps, the map $A'\rightarrow A'\hat{\otimes}_{A}^{\mathbb{L}}B$ is also derived strong. By assumption it is descendable. Now taking pushouts along the map $A\rightarrow\pi_{0}(A)$ we get a commutative diagram
\begin{displaymath}
    \xymatrix{
\pi_{0}(A)\ar[d]\ar[r]^{\pi_{0}(f)}& \pi_{0}(B)\ar[d]\\
\pi_{0}(A')\ar[r] & \pi_{0}(A')\hat{\otimes}^{\mathbb{L}}_{\pi_{0}(A)}\pi_{0}(B)\cong\pi_{0}(A')\hat{\otimes}_{\pi_{0}(A)}\pi_{0}(B).
    }
\end{displaymath}
The left-hand vertical map is a rational cover, and the bottom horizontal map is descendable and \'{e}tale.

Conversely suppose $f:A\rightarrow B$ is derived strong and $\pi_{0}(A)\rightarrow\pi_{0}(B)$ corresponds to an \'{e}tale cover of discrete affinoids. In particular this is an \'{e}tale, and hence faithfully flat, cover in the discrete sense. We can find a rational cover $\pi_{0}(A)\rightarrow A'_{0}$, and an adically faithfully flat and formally rig-\'{e}tale formal model $\tilde{A}'_{0}\rightarrow \tilde{B}'_{0}$ of the map $A'_{0}\rightarrow\ A'_{0}\hat{\otimes}^{L}_{\pi_{0}(A)}\pi_{0}(B)$. By Postnikov extension, we extend $\pi_{0}(A)\rightarrow A'_{0}$ to a derived strong rational cover $A\rightarrow A'$ as follows. Let $d^{A}_{n}:A_{\le n}\rightarrow\pi_{n+1}(A)[n+2]$ be the canonical derivation. We then just iteratively construct $A'_{\le n+1}=A'_{\le n}\oplus_{A'_{\le n}\hat{\otimes}^{\mathbb{L}}_{A_{\le n}}d^{A}_{n}}(A'_{\le n}\hat{\otimes}^{\mathbb{L}}_{A_{\le n}}\pi_{n+1}(A)[n+2]).$
%Observe that by an inductive derived strength argument we have $\pi_{*}(A'_{\le n}\hat{\otimes}^{\mathbb{L}}_{A_{\le n}}\pi_{n+1}(A))[n+2]\cong\pi_{0}(A')\hat{\otimes}^{\mathbb{L}}_{\pi_{0}(A)}\pi_{n+1}(A)[n+2],$ and under this equivalence $A'_{\le n}\hat{\otimes}^{\mathbb{L}}_{A_{\le n}}d^{A}_{n}\cong \pi_{0}(A')\hat{\otimes}_{\pi_{0}(A)}d_{n}^{A}$. 
By construction we have that $A_{\le n+1}\rightarrow A'_{\le n+1}$ is derived strong. Taking limits of the Postnikov towers we get a derived strong map $A\rightarrow A'$ such that $\pi_{0}(A)\rightarrow\pi_{0}(A')$ corresponds to a rational localisation cover. Thus $A\rightarrow A'$ corresponds to a rational localisation cover. Now pick a formal model $\tilde{A}'$ of $A'$ such that $\pi_{0}(\tilde{A}')\cong\tilde{A}'_{0}$. By a similar process we extend $\tilde{A}'_{0}\rightarrow\tilde{B}'_{0}$ to a derived strong map $\tilde{A}'\rightarrow\tilde{B}'$ of derived admissible adic $R$-algebras. Note then each $\tilde{A}'\big\slash\big\slash(\pi^{k})\rightarrow\tilde{B}'\big\slash\big\slash(\pi^{k})$ is also derived strong. Moreover $\pi_{0}(\tilde{A}'\big\slash\big\slash(\pi^{k}))\rightarrow\pi_{0}(\tilde{B}'\big\slash\big\slash(\pi^{k}))$ is a faithfully flat map of finitely presented algebras. Thus $\tilde{A}'\big\slash\big\slash(\pi^{k})\rightarrow\tilde{B}'\big\slash\big\slash(\pi^{k})$ is a faithfully flat map of derived algebras. In particular it is descendable. Thus $\tilde{A}'\rightarrow\tilde{B}'$ is in fact a cover in the adically faithfully flat topology, and so is descendable. By Lemma \ref{lemma:strongrigetale} it is further formally rig-\'{e}tale. 

Finally, we claim that $\tilde{A}'\rightarrow\tilde{B}'$ is a formal model for $A'\rightarrow A'\hat{\otimes}^{\mathbb{L}}_{A}B$. Now since tensoring with $R[\frac{1}{\pi}]$ preserves homology of $\pi$-adic objects, $\tilde{A}'[\frac{1}{\pi}]\rightarrow\tilde{B}'[\frac{1}{\pi}]$ is also derived strong, and $\pi_{0}(\tilde{A}'[\frac{1}{\pi}]\rightarrow\tilde{B}'[\frac{1}{\pi}])\cong(\pi_{0}(A)\rightarrow\pi_{0}(B))$ is formally \'{e}tale. Hence  $\tilde{A}'[\frac{1}{\pi}]\rightarrow\tilde{B}'[\frac{1}{\pi}]$ is formally \'{e}tale. Consider the diagram
\begin{displaymath}
    \xymatrix{
    & A'\ar[dl]\ar[dr] &\\
    \tilde{B}'[\frac{1}{\pi}]& & A'\hat{\otimes}^{\mathbb{L}}_{A}B.
    }
\end{displaymath}
Both legs are formally \'{e}tale maps. The isomorphism $\pi_{0}(\tilde{B}'[\frac{1}{\pi}])\cong\pi_{0}(A'\hat{\otimes}_{A}^{\mathbb{L}}B)$ then lifts, uniquely up to a contractible choice, to an isomorphism of $A'$-algebras $\tilde{B}'[\frac{1}{\pi}]\rightarrow A'\hat{\otimes}^{\mathbb{L}}_{A}B$. All this work is to say that $A\rightarrow B$ has a rational refinement to a descendable \'{e}tale cover. Hence it is a cover in $\tau_{ref}^{rig-\'{e}t}$.
\end{proof}

