\subsection{The Nisnevich topology}


As is well known from the purely algebraic setting, \(K\)-theory does not in general satisfy \'etale descent. It does however satisfy descent for a coarser topology called the \textit{Nisnevich topology}. To define this topology, we introduce some terminology originally due to Morel and Voevodsky. 

\begin{definition}\label{def:cd-structure}
Let \(\fC\) be a small category with an initial object. A \emph{cd-structure} on \(\fC\) is a collection \(\mathcal{P}\) of commuting squares \[
Q = \begin{tikzcd}
B \arrow{r}{} \arrow{d}{} & Y \arrow{d}{p}\\
A \arrow{r}{e} & X,
\end{tikzcd}
\]
 such that if \(Q \in \mathcal{P}\) and \(Q'\) is isomorphic to \(Q\), then \(Q' \in \mathcal{P}\). 
\end{definition}

Given a commuting square \(Q \in \mathcal{P}\), let \((p,e)\) denote the sieve generated by the family \(\{p \colon Y \to X, e \colon A \to X\}\). We then denote by \(\tau_P\) the smallest Grothendieck topology such that \((p,e)\) is a covering sieve, and the empty sieve is a covering sieve of the initial object. We call a covering \(\{X_i \to X\}\) \emph{simple} if it factors through some \((p,e)\). 


We call a cd structure on \(\fC\) \emph{complete} if any covering sieve of an object that is not isomorphic to the initial object, contains a sieve generated by a simple sieve. This is equivalent to the requirement that any morphism whose codomain is an initial object is an isomorphism, and that for any \(Q \in \mathcal{P}\) and any morphism \(X' \to X\) in \(\fC\), the pullback \(Q' = Q \times_X X'\) exists and belongs to \(\mathcal{P}\). Finally, we call a cd-structure \textit{regular} if the commuting squares in \(\mathcal{P}\) are pullback squares, the morphism \(e\) is a monomorphism, and for each \(Q \in \mathcal{P}\), the induced square

\[
\Delta(Q) = \begin{tikzcd}
B \arrow{r}{} \arrow{d}{} & Y \arrow{d}{}\\
B \times_A B \arrow{r}{} & Y \times_X Y,
\end{tikzcd}
\] belongs to \(\mathcal{P}\). 


\begin{definition}\label{def:Nisnevich-infty}
A cd-structure on a small \(\infty\)-category \(\bC\) is a cd-structure on its homotopy category. 
\end{definition}


\begin{lemma}\cite{voevodsky2008homotopy}*{Corollary 5.10}\label{lem:Nisnevich-sheaves}
Let \(\mathcal{P}\) be a complete, regular cd-structure on an \(\infty\)-category \(\bC\) with an initial object \(\emptyset\). Then \(\mathcal{F} \colon \bC^\op \to \mathbf{An}\) is a \(\tau_{\mathcal{P}}\)-sheaf if and only if \(\mathcal{F}(\emptyset)\) is contractible, and for every \(Q \in \mathcal{P}\), \(\mathcal{F}(Q)\) is a pullback square. 
\end{lemma} 


We now apply Morel and Voevodsky's general machinery to our setting where \(\bC\) is the \(\infty\)-category of derived \(R\)-analytic spaces. 
\subsubsection{Generating CD-structures}
Let $\mathrm{C}$ be a category with an initial object $\emptyset$ such that any map $C\rightarrow\emptyset$ is an isomorphism. 
Let $\chi$ be a class of pullback squares
    \begin{displaymath}
\xymatrix{
\mathcal{U}\times_{\mathcal{X}}\mathcal{Y}\ar[r]\ar[d]  & \mathcal{Y}\ar[d]^{p}\\
\mathcal{U}\ar[r]^{e} & \mathcal{X}
}
\end{displaymath}
where $e$ is a monomorphism. We denote by $R(\chi)$ the class of squares in $\chi$ such that pullback squares

   \begin{displaymath}
\xymatrix{
\mathcal{U}\times_{\mathcal{X}}\mathcal{Y}\times_{\mathcal{X}}\mathcal{W}\ar[r]\ar[d]  & \mathcal{Y}\times_{\mathcal{X}}\mathcal{W}\ar[d]^{p'}\\
\mathcal{U}\times_{\mathcal{X}}\mathcal{W}\ar[r]^{e'} & \mathcal{W}
}
\end{displaymath}
along morphisms $\mathcal{W}\rightarrow\mathcal{X}$ are also in $\chi$. This is a complete cd-structure. 


Let $\Delta(\chi)$ denote the class of squares $S$ in $\chi$ such that the `diagonal square', $\Delta(S)$
\begin{displaymath}
    \xymatrix{
\mathcal{U}\times_{\mathcal{X}}\mathcal{Y}\ar[d]\ar[r] & \mathcal{Y}\ar[d]\\
\mathcal{U}\times_{\mathcal{Z}}\mathcal{Y}\times_{\mathcal{X}}\mathcal{Y}\ar[r] & \mathcal{Y}\times_{\mathcal{X}}\mathcal{Y}
    }
\end{displaymath}
is also in $\chi$. Inductively define $$\Delta^{n+1}(\chi)=\Delta(\Delta^{n}(\chi))$$ 
and 
$$\Delta^{\infty}(\chi)=\bigcap_{n\ge0}\Delta^{n}(\chi)$$
This is a regular cd-structure. 

\begin{lemma}
    We have 
    $$R(\Delta(\chi)))=\Delta(R(\chi)).$$
    In particular, this is a complete and regular cd-structure.
\end{lemma}

\begin{proof}
First we show that $\Delta(R(\chi))\subset R(\Delta(\chi))$. Let $S$ be a square in $\Delta(R(\chi))\subset\Delta(\chi)$. Then it is in particular in $\Delta(\chi)$. We need to show that any pullback of $S$, $\mathcal{W}\times_{\mathcal{X}}S$, is also in $\Delta(\chi)$. But we have $\Delta(\mathcal{W}\times_{\mathcal{X}}S)\cong\mathcal{W}\times_{\mathcal{X}}\Delta(S)$ is also in $\Delta(R(\chi))$, and in particular is in $\Delta(\chi)$. Hence $S\in R(\Delta(\chi))$. Conversely suppose $S\in R(\Delta(\chi))$. Then in particular it is in $\Delta(\chi)$. We claim that it is in $\Delta(R(\chi))$. That is, we need to show that $\Delta^{n}(\mathcal{W}\times_{\mathcal{X}}S)\in\chi$ for all $n$ and all $\mathcal{W}\rightarrow\mathcal{X}$. But we have $\Delta^{n}(\mathcal{W}\times_{\mathcal{X}}S)\cong\mathcal{W}\times_{\mathcal{X}}\Delta^{n}(S)$. But $\Delta^{n}(S)\in\chi$ for all $n$, so $\mathcal{W}\times_{\mathcal{X}}\Delta^{n}(S)\in R(\chi)$ as well. This completes the proof.
\end{proof}

\begin{definition}
    Let $\mathbf{C}$ be a derived algebraic context and $\mathrm{T}$ a generating class of algebras of homotopy polynomial type. We define the $\mathrm{T}$-\textit{Nisnevich cd-structure} on $\mathbf{Sch}(\mathbf{Aff}_{\mathbf{C}},\tau_{\'{e}t},\mathbf{P}^{sm})$ to be $\chi_{N}\defeq R(\Delta(\chi^{pre}_{N}))$, where $\chi^{pre}_{N}$ consists of squares of the form
    \begin{displaymath}
        \xymatrix{
        U\times_{X}V\ar[d]\ar[r] & V\ar[d]^{p}\\
        U\ar[r]^{e} & X
        }
    \end{displaymath}
    where 
    \begin{enumerate}
        \item 
        $e:U\rightarrow X$ is an open immersion;
        \item 
        $p:V\rightarrow X$ is \'{e}tale;
        \item 
        $$U\coprod V\rightarrow X$$ is an effective epimorphism.
    \end{enumerate}
\end{definition}

Let us populate this class of squares in certain examples.



\begin{example}
    Any cover in the finite rational topology can written as a square in $\chi_{N}$. 
\end{example}



\subsubsection{Spatial squares}

Denote by \(\mathcal{P}_{sp-N}\) commuting squares of the form 

\begin{equation}\label{eq:preNis}
\begin{tikzcd}
U \times_X V \arrow{r}{} \arrow{d}{} & V \arrow{d}{p}\\
U \arrow{r}{e} & X,
\end{tikzcd}
\end{equation} where 
\begin{enumerate}
    \item 
    \(e\) is an open immersion,
    \item
    \(p\) is \'etale,  and spatial on the complement of $U$,
    \item
    \(|V|_{Ber} \times_{|X|_{Ber}} (|X|_{Ber} \setminus |U|_{Ber}) \to |X|_{Ber} \setminus |U|_{Ber}\) is a homeomorphism.
\end{enumerate} Note that in the rigid case Lemma \ref{lem:etale-pi_0}, \ref{cor:standard-etale-characterisation} and Corollary \ref{cor:diagonal-loc} say that being \'etale is equivalent to the map being derived strong and \(\pi_0\)-\'etale. We call such commuting diagrams \emph{elementary spatial Nisnevich squares}. Note that by definition, the properties of being \'{e}tale and an open immersion are local on the target. 



\begin{example}
    Let
    \begin{equation}
\begin{tikzcd}
U \times_X V \arrow{r}{} \arrow{d}{} & V \arrow{d}{p}\\
U \arrow{r}{e} & X,
\end{tikzcd}
\end{equation}
be an elementary Nisnevich square of rigid analytic spaces in the sense of Andreychev (\cite{andreychev2023k}) (or, more precisely, specialising Andreychev's definition for more general analytic adic spaces). We use the characterisation of Andreychev's elementary Nisnevich squares from \cite{TangLSeminar}. This precisely means that $U\rightarrow X$ is an open immersion, that $|V|\times_{|X|}(|X|\setminus |U|)\cong |X\setminus U|$ is a homeomorphism of degree $1$, and that for any $v\in |V\setminus U|_{Ber}$, $v$ and $p(v)$ have isomorphic residue fields. In particular for any $v\in |V|_{Ber}\times_{|X|_{Ber}}(|X|_{Ber}\setminus |U|_{Ber})$, we have an isomorphism of residue fields $F_{v}\cong F_{f(v)}$. Now suppose $v\in |V|_{Ber}$. Then by \cite{de1996etale}, we can find an open $U$ containing $f(v)$ and an open $W_{v}$ containing $v$ such that the restriction of $f$ to $V$ is an open immersion landing in $W$. Thus we have that 
$$V\cong V\times_{X}U\cup\bigcup_{v\in |V|_{Ber}\setminus |V\times_{X}U|_{Ber}}W_{v},$$
and hence $p$ is spatial on the complement of $U$ by Lemma \ref{lem:andrspat}. The other conditions are straightforward, so that this gives an example of an elementary Nisnevich square. One can also take $U,V,X$ to be derived rigid analytic spaces, and assume that it forms an Andreychev Nisnevich square on $0$-truncations.
\end{example}

\begin{corollary}\label{cor:equivalenttruncation}
    Let $f:X\rightarrow Y$ be an \'{e}tale morphism of derived rigid analytic spaces. Then the diagonal morphism $X\rightarrow X\times_{Y}X$ is an open immersion.
\end{corollary}

\begin{proof}
 It is certainly locally an open immersion. It remains to prove that it is injective. But we have $|X\times_{Y}X|\cong |X|\times_{|Y|}|X|$. The morphism of spaces $|X|\rightarrow |X|\times_{|Y|}|X|$ is evidently injective. 
\end{proof}



\begin{lemma}
   Let \begin{equation}
\begin{tikzcd}
U \times_X V \arrow{r}{} \arrow{d}{} & V \arrow{d}{p}\\
U \arrow{r}{e} & X,
\end{tikzcd}
\end{equation} be an elementary Nisnevich square of derived rigid analytic spaces. Then $|U|\coprod |V|\rightarrow |X|$ is surjective. Consequently, the map \(U \coprod V \to X\) is an effective epimorphism of geometric stacks.
\end{lemma}




\begin{theorem}\label{thm:Voevodsky-analytic}
The collection of commuting diagrams \(\mathcal{P}_{sp-N}\) in is a complete, regular cd-structure.  In particular in the rigid analytic context, such squares are contained in $\chi_{N}$.
\end{theorem}

\begin{proof}
Note that open immersions and \'etale maps are closed under base change by arbitrary morphisms. Furthermore, by construction, spatiality on the complement of $U\rightarrow X$ will be preserved by base-change. Next if $V\rightarrow V\times_{X}V$ is spatial , and $Z\rightarrow X$ any map, then $(V\times_{X}Z)\times_{Z}(V\times_{X}Z)\cong (V\times_{X}V)\times_{X}Z$, and $(V\times_{X}Z)\times_{Z}(V\times_{X}Z)$ is the pullback of $V\rightarrow V\times_{X}V$ along $V\times_{X}Z\rightarrow V$. Hence it is also spatial. Consequently, the base change of a Nisnevich square is a Nisnevich square, so that the cd-structure \(\mathcal{P}^N\) is complete. 


To see that it is reduced, it remains to show that for an elementary Nisnevich square \(Q\), the induced square \(\Delta(Q)\) is an elementary Nisnevich square. Again as open immersions are closed under base change, the map \(U \times_X V \to V\) is an open immersion. Since by hypothesis \(e \colon U \to X\) is also an open immersion, the induced map \((U \times_X V) \times_U (U \times_X V) \to V \times_X V\) is am  open immersion. In fact it is the pullback of $U$ along the map $V\times_{X}V\rightarrow X$. Now $V\rightarrow V\times_{X}V$ is an open immersion. Hence it is spatial, so it is in particular spatial on the complement of $U\times_{X}(V\times_{X}V)$. 

Finally we need to check the condition on complements. Now applying spatiality on the complement of $U$ to the pullback along $V\rightarrow X$ gives 
\begin{multline*}
|V\times_{X}V|_{Ber}\setminus |V\times_{X}V\times_{X}U|_{Ber}  \\ \cong|V|_{Ber}\times_{|X|_{Ber}}|V|_{Ber}\times_{|X|_{Ber}}|X|_{Ber}\setminus|V|_{Ber}\times_{|X|_{Ber}}|V|_{Ber}\times_{|X|_{Ber}} |U|_{Ber}\\
\cong|X|_{Ber}\setminus |U|_{Ber}.
\end{multline*}
But we also have 
\begin{multline*}
|V|_{Ber}\times_{|V\times_{X}V|_{Ber}}(|V\times_{X}V|_{Ber}\setminus |V\times_{X}V\times_{X}U|_{Ber}) \\ \cong |V|_{Ber}\setminus(|V|_{Ber}\times_{|V\times_{X}V|_{Ber}}|V\times_{X}V|_{Ber}\times_{|X|_{Ber}}|U|_{Ber})\\
\cong|V|_{Ber}\setminus(|V|_{Ber}\times_{|X|_{Ber}}|U|_{Ber})
\cong |X|_{Ber}\setminus |U|_{Ber}.
\end{multline*}
This completes the proof. 
\end{proof}



\subsection{K\"{u}nneth formulae for $\mathbf{QCoh}$}

In order to prove Nisnevich descent for $K$-theory and the Grothendieck-Riemann-Roch Theorem, we will need some facts about rigidity of functors between categories of the form $\mathbf{Nuc}^{\infty}(X)$. Here we still specialise to working with a context of the form
$$(\mathbf{Aff}_{\mathbf{C}},\tau,\mathbf{P},\mathbf{A})$$
where $\tau$ is some descendable topology. By `stack', we shall a stack on the site $(\mathbf{A},\tau|_{\mathbf{A}})$.


\begin{definition}
\begin{enumerate}
    \item 
      A stack $\mathcal{X}$ is said to be \textit{formally affine}, if the global sections functor (i.e., the pushforward to the point)
    $$\Gamma(\mathcal{X},-):\mathbf{QCoh}(\mathcal{X})\rightarrow\mathbf{C}$$
    is conservative.
    \item
    A morphism $f:\mathcal{X}\rightarrow\mathcal{Y}$ of stacks is said to be \textit{formally affine} if for every affine $\mathrm{Spec}(A)\rightarrow\mathcal{Y}$, with $\mathrm{Spec}(A)\in\mathbf{A}$, the stack $\mathrm{Spec}(A)\times_{\mathcal{Y}}\mathcal{X}$ is formally affine.
     \item 
      If the context is nuclear, a stack $\mathcal{X}$ is said to be \textit{formally nuclear} if the global sections functor (i.e., the push-forward to the point)
    $$\Gamma(\mathcal{X},-):\mathbf{QCoh}(\mathcal{X})\rightarrow\mathbf{C}$$
    sends $\mathbf{Nuc}^{\infty}(X)$ to $\mathbf{C}^{rig}$.
    \item
   If the context is nuclear, a morphism $f:\mathcal{X}\rightarrow\mathcal{Y}$ of stacks is said to be \textit{formally nuclear} if for every affine $\mathrm{Spec}(A)\rightarrow\mathcal{Y}$, with $\mathrm{Spec}(A)\in\mathbf{A}$,  the stack $\mathrm{Spec}(A)\times_{\mathcal{Y}}\mathcal{X}$ is formally nuclear.
\end{enumerate}

\end{definition}

In particular, affines are both formally affine and, in the nuclear setting, formally nuclear.

Note that if the context is nuclear, and $f:\mathcal{X}\rightarrow\mathrm{Spec}(A)$ is formally nuclear, then $f_{*}$ sends $\mathbf{Nuc}^{\infty}(\mathcal{X})$ to $\mathbf{Nuc}^{\infty}(A)$.

\begin{proposition}\label{prop:cocontqcqs}
    Let $f:\mathcal{X}\rightarrow \mathcal{Y}$ be a qcqs morphism of stacks. That is, for any morphism $\mathrm{Spec}(A)\rightarrow\mathcal{Y}$, $\mathcal{X}\times_{\mathrm{Y}}\mathrm{Spec}(A)$ is a scheme, and $\mathcal{X}\times_{\mathrm{Y}}\mathrm{Spec}(A)\rightarrow\mathrm{Spec}(A)$ is a qcqs morphism. Then $f$ satisfies base-change. Moreover, $f_{*}$ commutes with colimits. 
\end{proposition}

\begin{proof}
    Base change can be proven by pulling back to affines. Thus we may assume from the outset that $f$ is a qcqs morphism between schemes. Now an identical proof to \cite{soor2024derived}*{Lemma 3.2} works. The fact that $f_{*}$ commutes with colimits now follows from base-change, and again \cite{soor2024derived}*{Lemma 3.2}.
\end{proof}



\begin{lemma}\label{lem:qaffformrig}
    Let $f:U\rightarrow \mathrm{Spec}(A)$ be an open immersion with $U$ quasi-compact. Then $i$ is base-change, formally affine, and, in the nuclear case, is formally nuclear. In fact in this case, 
    $$f_{*}:\mathbf{QCoh}(U)\rightarrow\mathbf{QCoh}(\mathrm{Spec}(A))$$
    and, in the nuclear setting, 
       $$f_{*}:\mathbf{Nuc}^{\infty}(U)\rightarrow\mathbf{Nuc}^{\infty}(\mathrm{Spec}(A))$$
       are fully faithful. 
\end{lemma}

\begin{proof}
Since $i$ is qcqs, it satisfies base change.

    First we prove that $f_{*}$ is fully faithful. Write $U=\bigcup_{i=1}^{n}U_{i}$ with each $U_{i}$ affine. Note that $U_{i_{1}}\times_{U}\ldots\times_{U}U_{i_{n}}\cong U_{i_{1}}\times_{\mathrm{Spec}(A)}\ldots\times_{\mathrm{Spec}(A)}U_{i_{n}}$ is affine, and all of the maps $f_{(i_{1},\ldots,i_{n})}:U_{i_{1}}\times_{U}\ldots\times_{U}U_{i_{n}}\rightarrow \mathrm{Spec}(A)$ and $g_{(i_{1},\ldots,i_{n})}:U_{i_{1}}\times_{U}\ldots\times_{U}U_{i_{n}}\rightarrow \mathrm{Spec}(A)$ are open immersions. Let $\mathcal{F}\in\mathbf{QCoh}(U)$. Then we may write
    $$\mathcal{F}\cong\mathbf{lim}_{(i_{1},\ldots,i_{n})\in\mathcal{I}^{n},n\in\mathbb{N}}(g_{(i_{1},\ldots,i_{n})})_{*}g_{(i_{1},\ldots,i_{n})}^{*}\mathcal{F},$$
    where the limit is finite, since each $U_{i}\rightarrow U$ is an open immersion. 
    Then 
    $$f_{*}\mathcal{F}\cong\mathbf{lim}_{(i_{1},\ldots,i_{n})}f_{*}(g_{(i_{1},\ldots,i_{n})})_{*}g_{(i_{1},\ldots,i_{n})}^{*}\mathcal{F}\cong\mathbf{lim}_{(i_{1},\ldots,i_{n})}(f_{(i_{1},\ldots,i_{n})})_{*}g_{(i_{1},\ldots,i_{n})}^{*}\mathcal{F}.$$
    Since the limit is finite, we have 
\begin{multline*}
f^{*}\mathbf{lim}_{(i_{1},\ldots,i_{n})}(f_{(i_{1},\ldots,i_{n})})_{*}g_{(i_{1},\ldots,i_{n})}^{*}\mathcal{F}
\cong\mathbf{lim}_{(i_{1},\ldots,i_{n})}f^{*}(f_{(i_{1},\ldots,i_{n})})_{*}g_{(i_{1},\ldots,i_{n})}^{*}\mathcal{F}\\
\cong\mathbf{lim}_{(i_{1},\ldots,i_{n})}(g_{(i_{1},\ldots,i_{n})})_{*}g_{(i_{1},\ldots,i_{n})}^{*}\mathcal{F}\cong\mathcal{F},
\end{multline*}
where in the second equivalence we used that $f_{(i_{1},\ldots,i_{n})}$ is a morphism of affines so that it satisfies base-change, and that $U\times_{\mathrm{Spec}(A)}(U_{i_{1}}\times_{U}\ldots\times_{U}U_{i_{n}})\cong(U_{i_{1}}\times_{U}\ldots\times_{U}U_{i_{n}})$. 

Finally, suppose the context is nuclear, and let $\mathcal{F}$ be in $\mathbf{Nuc}^{\infty}(U)$. Again we return to the identity
 $$f_{*}\mathcal{F}\cong\mathbf{lim}_{(i_{1},\ldots,i_{n})}(f_{(i_{1},\ldots,i_{n})})_{*}g_{(i_{1},\ldots,i_{n})}^{*}\mathcal{F}.$$
Each $(f_{(i_{1},\ldots,i_{n})})_{*}g_{(i_{1},\ldots,i_{n})}^{*}\mathcal{F}$ is in $\mathbf{Nuc}^{\infty}(A)$, since $f_{(i_{1},\ldots,i_{n})}$ is a morphism of affines and pullback always preserves infinitely nuclear objects. Then $f_{*}\mathcal{F}$ is a \textit{finite limit} of infinitely nuclear objects, and therefore is infinitely nuclear. 
\end{proof}


In particular, say that a scheme $X$ is \textit{quasi-affine} if it quasi-compact and there exists an open immersion $i:X\rightarrow \mathrm{Spec}(A)$. Then such stacks are formally affine and, in the nuclear case, formally nuclear.

\begin{corollary}\label{cor:fformrigqcqs}
   Suppose the context is nuclear. Let $f:X\rightarrow Y$ be a qcqs morphism of schemes. Then $f$ is formally nuclear.
\end{corollary}

\begin{proof}
 By base-change may we may assume that $Y$ is an affine scheme, and $X$ is a qcqs scheme. Pick a finite open affine cover $X=\bigcup_{i=1}^{n}U_{i}$. Again we write $g_{(i_{1},\ldots,i_{n})}:U_{i_{1}}\times_{X}\ldots\times_{X}U_{i_{n}}\rightarrow X$, and $f_{(i_{1},\ldots,i_{n})}:U_{i_{1}}\times_{X}\ldots\times_{X}U_{i_{n}}\rightarrow Y$ for the obvious maps. Note that all of the $U_{i_{1}}\times_{X}\ldots\times_{X}U_{i_{n}}$ are quasi-affine. Using the result of Lemma \ref{lem:qaffformrig}, the proof now proceeds in a formally identical way to the proof of Lemma \ref{lem:qaffformrig}.
\end{proof}

