\begin{lemma}\label{lem:qnucpush}
    Suppose the context is nuclear. Let $f:\mathcal{X}\rightarrow\mathcal{Y}$ be a morphism of stacks which satisfies the base-change property, and is formally nuclear. Then $f_{*}$ restricts to a functor $\mathbf{Nuc}^{\infty}(\mathcal{X})\rightarrow\mathbf{Nuc}^{\infty}(\mathcal{Y})$. If $f_{*}:\mathbf{QCoh}(\mathcal{X})\rightarrow\mathbf{QCoh}(\mathcal{Y})$ commutes with colimits, then so does $f_{*}:\mathbf{Nuc}^{\infty}(\mathcal{X})\rightarrow\mathbf{Nuc}^{\infty}(\mathcal{Y})$. 
\end{lemma}

\begin{proof}
    Let $\mathcal{M}\in\mathbf{Nuc}^{\infty}(\mathcal{X})$. We need to show that $f_{*}\mathcal{M}$ is in $\mathbf{Nuc}^{\infty}(\mathcal{Y})$. Thus for any $g:U\rightarrow\mathcal{Y}$ with $U$ affine, we need to show that $g^{*}f_{*}\mathcal{M}$ is in $\mathbf{Nuc}^{\infty}(\mathcal{Y})$. By base-change, this is $f'_{*}\circ (g')^{*}\mathcal{M}$, where $f':\mathcal{X}\times_{\mathcal{Y}}U\rightarrow U$ and $g':\mathcal{X}\times_{\mathcal{Y}}U\rightarrow\mathcal{X}$ are the pullback maps. Thus the claim reduces to the fact that $(f')_{*}$, by assumption, sends infinitely nuclear objects to infinitely nuclear objects. The second  claim is clear.
\end{proof}




\begin{lemma}\label{lemma:qcohfibre}
    Let $f:\mathcal{Y}_{1}\rightarrow\mathcal{Y}_{2}$ be a formally affine, qcqs map of stacks. We may regard $f_{*}(\mathcal{O}_{\mathcal{Y}_{1}})$ as an associative algebra object in $\mathbf{QCoh}(\mathcal{Y}_{2})$. The natural functor
    $$\mathbf{QCoh}(\mathcal{Y}_{1})\rightarrow\mathbf{Mod}_{f_{*}(\mathcal{O}_{\mathcal{Y}_{1}})}(\mathbf{QCoh}(\mathcal{Y}_{2}))$$
    is an equivalence.
\end{lemma}

\begin{proof}
    We generalise the proof of \cite{MR3381473}*{Lemma B.1.4}. As in loc. cit. we use the Barr-Beck Lurie Theorem. The qcqs assumption means that the map $f$ satisfies base change, and that $f_{*}$ commutes with colimits. As in \cite{MR3381473}*{Lemma B.1.4}, base-change together with the formally affine assumption implies that $f_{*}$ is conservative. Hence $\mathbf{QCoh}(\mathcal{Y}_{1})$ is monadic over $\mathbf{QCoh}(\mathcal{Y}_{2})$, with monad given by $f_{*}f^{*}$. Yet again, as in \cite{MR3381473}*{Lemma B.1.4}, the projection formula (also yet again \cite{soor2024derived}*{Lemma 3.2}), implies that this monad is given by tensoring with $f_{*}(\mathcal{O}_{\mathcal{Y}_{1}})$. 
\end{proof}

\begin{corollary}\label{cor:nucfibre}
       Suppose the context is nuclear. Let $f:\mathcal{Y}_{1}\rightarrow\mathcal{Y}_{2}$ be a formally affine, formally nuclear map of stacks. We may regard $f_{*}(\mathcal{O}_{\mathcal{Y}_{1}})$ as an associative algebra object in $\mathbf{QCoh}(\mathcal{Y}_{2})$. There is an equivalence of categories
    $$\mathbf{Nuc}^{\infty}(\mathcal{Y}_{1})\rightarrow\mathbf{Mod}_{f_{*}(\mathcal{O}_{\mathcal{Y}_{1}})}(\mathbf{Nuc}^{\infty}(\mathcal{Y}_{2})).$$
\end{corollary}

\begin{proof}
    It suffices to prove that $f_{*}(\mathcal{O}_{Y_{1}})$ is infinitely nuclear. Then the monad from the proof of Lemma \ref{lemma:qcohfibre} restricts to $\mathbf{Nuc}^{\infty}$. By base-change we may assume that $\mathcal{Y}_{2}\cong\mathrm{Spec}(A)$ is affine, and $\mathbf{QCoh}(\mathcal{Y}_{2})\rightarrow\mathbf{C}$ sends infinitely nuclear objects to infinitely nuclear objects. But then by Proposition \ref{prop:nuclear-relative}, and using the fact that $A$ is in $\mathbf{C}$, we find that $f_{*}$ sends infinitely nuclear objects to infinitely nuclear objects. 
\end{proof}

\begin{lemma}\label{lem:tensordiagram}
    Let $f:\mathcal{Y}_{1}\rightarrow\mathcal{Y}_{2}$ be formally affine and qcqs, and let
    \begin{displaymath}
        \xymatrix{
        \mathcal{Y}_{1}'\ar[d]^{f'}\ar[r]^{g_{1}} &\mathcal{Y}_{1}\ar[d]^{f}\\
        \mathcal{Y}_{2}'\ar[r]^{g_{2}} &\mathcal{Y}_{2}.
        }
    \end{displaymath}
    be a Cartesian diagram of stacks.  The natural symmetric monoidal functor
    $$\mathbf{QCoh}(\mathcal{Y}'_{2})\otimes_{\mathbf{QCoh}(\mathcal{Y}_{2})}\mathbf{QCoh}(\mathcal{Y}_{1})\rightarrow\mathbf{QCoh}(\mathcal{Y}_{1}')$$
    is an equivalence. 

    If in addition the context is nuclear and $f$ is formally nuclear, we have an equivalence
     $$\mathbf{Nuc}^{\infty}(\mathcal{Y}'_{2})\otimes_{\mathbf{Nuc}^{\infty}(\mathcal{Y}_{2})}\mathbf{Nuc}^{\infty}(\mathcal{Y}_{1})\rightarrow\mathbf{Nuc}^{\infty}(\mathcal{Y}_{1}').$$
\end{lemma}

\begin{proof}
    Once more, this works identically to \cite{MR3381473}*{Proposition B.1.3}, using our Lemma \ref{lemma:qcohfibre} and Corollary \ref{cor:nucfibre} as inputs. 
\end{proof}

\begin{corollary}\label{cor:f*rig}
    Let $f:\mathcal{X}\rightarrow\mathcal{Y}$ be formally affine and qcqs. Then $f^{*}:\mathbf{QCoh}(\mathcal{Y})\rightarrow\mathbf{QCoh}(\mathcal{X})$ is a rigid functor. 
If in addition the context is nuclear and $f$ is formally nuclear, then this is also true for $f^{*}:\mathbf{Nuc}^{\infty}(\mathcal{Y})\rightarrow\mathbf{Nuc}^{\infty}(\mathcal{X})$.
\end{corollary}

\begin{proof}
The proof of this works as in \cite{hoyois2021categorified}*{Proposition 2.35}.
    The $\mathbf{QCoh}(\mathcal{Y})$-linearity of $f_{*}$ follows from the projection formula. Now we have 
$$\mathbf{QCoh}(\mathcal{X})\otimes_{\mathbf{QCoh}(\mathcal{Y})}\mathbf{QCoh}(\mathcal{X})\cong\mathbf{QCoh}(\mathcal{X}\times_{\mathcal{Y}}\mathcal{X}).$$
Under this identification, the functor
$$\Delta:\mathbf{QCoh}(\mathcal{X})\otimes_{\mathbf{QCoh}(\mathcal{Y})}\mathbf{QCoh}(\mathcal{X})\rightarrow\mathbf{QCoh}(\mathcal{X})$$
is given by $\Delta_{f}^{*}$, where $\Delta_{f}:\mathcal{X}\rightarrow\mathcal{X}\times_{\mathcal{Y}}\mathcal{X}$ is the diagonal. Since $f$ is qcqs, the diagonal morphism is quasi-compact. Thus the right adjoint $(\Delta_{f})_{*}$ satisfies base-change and therefore the projection formula.
\end{proof}

\begin{remark}
    Note we are \textit{not claiming} that $\mathbf{QCoh}(\mathcal{X})$ is rigid as a $\mathbf{QCoh}(\mathcal{Y})$-algebra. This would require the extra assumption that $\mathbf{QCoh}(\mathcal{X})$ is dualisable as a $\mathbf{QCoh}(\mathcal{Y})$-module. Apart from the algebraic setting, this will very rarely be true. This is one of the reasons we use $\mathbf{Nuc}^{\infty}$.
\end{remark}

