An interesting question is whether $\mathbf{Nuc}^{\infty}(X)$ is the rigidification of $\mathbf{QCoh}(X)$. 

\begin{definition}
    Say that a scheme $X$ is \textit{infinitely nuclear} if we have an equivalence $\mathbf{Nuc}^{\infty}(X)\cong\mathbf{QCoh}(X)^{rig}$.
\end{definition}


\begin{example}
    Let $X$ be a qcqs discrete dagger analytic space. We claim that $X$ is infinitely nuclear. First we prove the claim for quasi-affines. Let $X\rightarrow\mathrm{Spec}(A)$ be an open immersion, with $A$ being a discrete dagger affinoid algebra. Write $X=\bigcup_{i=1}^{n}U_{i}$ with each $U_{i}=\mathrm{Spec}(A_{i})$ being discrete dagger affinoid. Note then that each $U_{i}\times_{X}U_{j}\cong U_{i}\times_{\mathrm{Spec}(A)}U_{j}\cong\mathrm{Spec}(A_{i}\hat{\otimes}^{\mathbb{L}}_{A}A_{j})$ is a discrete dagger affinoid, and hence is infinitely nuclear. We have 
    $$\mathbf{QCoh}(X)\cong \varprojlim_n \mathbf{QCoh}(U^{\times_{X}n})$$
    where $U\defeq\sqcup_{i=1}^{n}U_{i}$. By the above each $U^{\times_{X}n}$ is representable be a discrete dagger affinoid. Applying rigidification, we get 
     $$\mathbf{QCoh}(X)^{rig}\cong \varprojlim^{dual}_n \mathbf{Nuc}^{\infty}(U^{\times_{X}n})$$
    where the limit is taken in the category of dualisable categories. On the other hand, we also know that
     $$\mathbf{Nuc}^{\infty}(X)\cong \varprojlim^{dual}_n \mathbf{Nuc}^{\infty}(U^{\times_{X}n}).$$
     This gives the equivalence. 

     Proving the claim for general qcqs schemes works in the same way, just that all terms in the limit now will be of the form $\mathbf{Nuc}^{\infty}(U^{\times_{X}n})$ for $U^{\times_{X}n}$ quasi-affine.

\end{example}

%With this result it is not futile to define what a means for a stack to be \textit{passable}, following \cite{MR3381473}*{Definition 5.1.2}. 

We can straightforwardly adapt the definition of passable maps of stacks from \cite{hoyois2021categorified}*{Definition 2.33}.

\begin{definition}
 A map $f:\mathcal{X}\rightarrow\mathcal{Y}$ of stacks is
    \textit{passable} if
    \begin{enumerate}
        \item 
        the diagonal $\mathcal{X}\rightarrow\mathcal{X}\times_{\mathcal{Y}}\mathcal{X}$ is quasi-affine;
        \item 
        the pullback $f^{*}:\mathbf{Nuc}^{\infty}(Y)\rightarrow\mathbf{Nuc}^{\infty}(\mathcal{X})$ admits a $\mathbf{Nuc}^{\infty}(\mathcal{Y})$-linear right adjoint, $f_{*}$;
        \item $\mathbf{Nuc}^{\infty}(\mathcal{X})$ is dualisable as a $\mathbf{Nuc}^{\infty}(\mathcal{Y})$-module.
    \end{enumerate}    
\end{definition}

\begin{example}
   A qcqs morphism between qcqs schemes is passable. The first condition is clearly satisfied. Now we have that $\mathbf{Nuc}^{\infty}(\mathcal{X})$ and $\mathbf{Nuc}^{\infty}(\mathcal{Y})$ are rigid over $\mathbf{Sp}$ by Lemma \ref{lem:maxime2}. Thus they are in particular locally rigid, and by \cite{nkp} Proposition 4.3.10, $\mathbf{Nuc}^{\infty}(\mathcal{X})$ is locally rigid over $\mathbf{Nuc}^{\infty}(\mathcal{Y})$. In particular it is dualisable.  Finally by Corollary \ref{cor:fformrigqcqs} and base change for qcqs morphisms, $f^{*}$ is a $\mathbf{Nuc}^{\infty}(\mathcal{Y})$-linear right adjoint. 
\end{example}


\begin{lemma}\label{lem:tensorequiv}
    Suppose that $f:\mathcal{X}\rightarrow\mathcal{Y}$ is such that $\mathbf{Nuc}^{\infty}(\mathcal{X})$ is dualisable as a $\mathbf{Nuc}^{\infty}(\mathcal{Y})$-module. Let $\mathcal{Z}\rightarrow\mathcal{Y}$ be a map with quasi-affine diagonal. Then the natural functor
    $$\mathbf{Nuc}^{\infty}(\mathcal{Z})\otimes_{\mathbf{Nuc}^{\infty}(\mathcal{Y})}\mathbf{Nuc}^{\infty}(\mathcal{X})\rightarrow\mathbf{Nuc}^{\infty}(\mathcal{Z}\times_{\mathcal{Y}}\mathcal{X})$$
    is an equivalence.
\end{lemma}

\begin{proof}
    The proof works as in the proof of \cite{hoyois2021categorified}*{Proposition 2.34}. We write $\mathbf{Nuc}^{\infty}(\mathcal{Z})\cong\lim_{\mathrm{Spec}(A)\rightarrow \mathcal{Z}}\mathbf{Nuc}^{\infty}(\mathrm{Spec}(A))$. Since tensoring with dualisable modules commutes with limits, we get 

    $$\mathbf{Nuc}^{\infty}(\mathcal{Z})\otimes_{\mathbf{Nuc}^{\infty}(\mathcal{Y})}\mathbf{Nuc}^{\infty}(\mathcal{X})\cong\lim_{\mathrm{Spec}(A)\rightarrow\mathcal{Z}}(\mathbf{Nuc}^{\infty}(\mathrm{Spec}(A))\otimes_{\mathbf{Nuc}^{\infty}(\mathcal{Y})}\mathbf{Nuc}^{\infty}(\mathcal{X})).$$
    Now since $\mathcal{Z}\rightarrow\mathcal{Y}$ has quasi-affine diagonal, the morphism $\mathrm{Spec}(A)\rightarrow\mathcal{Z}\rightarrow\mathcal{Y}$ is quasi-affine. By Lemma \ref{lem:tensordiagram}, we get that 
    $$\mathbf{Nuc}^{\infty}(\mathrm{Spec}(A))\otimes_{\mathbf{Nuc}^{\infty}(\mathcal{Y})}\mathbf{Nuc}^{\infty}(\mathcal{X})\cong\mathbf{Nuc}^{\infty}(\mathrm{Spec}(A)\times_{\mathcal{Y}}\mathcal{X}),$$
    and
     $$\mathbf{Nuc}^{\infty}(\mathcal{Z})\otimes_{\mathbf{Nuc}^{\infty}(\mathcal{Y})}\mathbf{Nuc}^{\infty}(\mathcal{X})\cong\lim_{\mathrm{Spec}(A)\rightarrow\mathcal{Z}}\mathbf{Nuc}^{\infty}(\mathrm{Spec}(A)\times_{\mathcal{Y}}\mathcal{X})\cong\mathbf{Nuc}^{\infty}(\mathcal{Z}\times_{\mathcal{Y}}\mathcal{X}).$$
\end{proof}

We can now prove an analogue of \cite{hoyois2021categorified}*{Proposition 2.34}.

\begin{lemma}
    Suppose that $f:\mathcal{X}\rightarrow\mathcal{Y}$ is passable. Then $f^{*}:\mathbf{Nuc}^{\infty}(\mathcal{Y})\rightarrow\mathbf{Nuc}^{\infty}(\mathcal{X})$ is rigid.
\end{lemma}

\begin{proof}
    By Lemma \ref{lem:tensorequiv} we have
    $$\mathbf{Nuc^{\infty}}(\mathcal{X})\otimes_{\mathbf{Nuc}^{\infty}(\mathcal{Y})}\mathbf{Nuc}^{\infty}(\mathcal{X})\cong\mathbf{Nuc}^{\infty}(\mathcal{X}\times_{\mathcal{Y}}\mathcal{X}).$$
    Since the diagonal is representable by quasi-affines, by Proposition \ref{prop:cocontqcqs} and Lemma \ref{lem:qnucpush} the functor
    $$\Delta_{*}:\mathbf{Nuc}^{\infty}(X)\rightarrow\mathbf{Nuc^{\infty}}(\mathcal{X})\otimes_{\mathbf{Nuc}^{\infty}(\mathcal{Y})}\mathbf{Nuc}^{\infty}(\mathcal{X})\cong\mathbf{Nuc}^{\infty}(\mathcal{X}\times_{\mathcal{Y}}\mathcal{X}).$$
    satisfies base-change and commutes with colimits. This completes the proof.
\end{proof}


We set up some notation. Let \(X\) be a quasi-compact, quasi-separated scheme. For a closed subspace \(Y \subseteq X\) with quasi-compact open complement \(i:U\rightarrow X\), we define the \(\infty\)-category \(\mathbf{Nuc}^\infty(X: Y)\) of \textit{nuclear modules with support in \(Y\)} as the homotopy fibre of the restriction \(\mathbf{Nuc}^\infty(X) \to \mathbf{Nuc}^\infty(U)\). 
By Corollary \ref{cor:openimmersembedding}, the functor $i_{*}:\mathbf{Nuc}^{\infty}(U)\rightarrow\mathbf{Nuc}^{\infty}(X)$ is fully faithful. Moreover this is an internal left adjoint by Proposition \ref{prop:cocontqcqs}. In particular, \(\mathbf{Nuc}^\infty(X:Y)\) is dualisable. In a very precise sense here we are really specifying $U$. Then $\mathbf{Nuc}^\infty(X:Y)$ is just notation.

The following is clear.

\begin{proposition}
    Let $U\subset V\subset X$ be open immersions with everything qcqs, and with closed complements $Y$ and $Z$ respectively. Then all squares in the following rectangle are pullbacks. 

    \begin{displaymath}
    \xymatrix{
    \mathbf{QCoh}(X:Y)\ar[d]\ar[r] & \mathbf{QCoh}(V:V\cap Y)\ar[d]\ar[r] & 0\ar[d]\\
    \mathbf{QCoh}(X)\ar[r] & \mathbf{QCoh}(V)\ar[r] & \mathbf{QCoh}(U).
    }
\end{displaymath}
In particular, we have $\mathbf{QCoh}(X:Z)\cong\mathrm{Fib}( \mathbf{QCoh}(X:Y)\rightarrow\mathbf{QCoh}(V:V\cap Y))$. In the nuclear setting, all squares in the following rectangle are pullbacks. 
   \begin{displaymath}
    \xymatrix{
    \mathbf{Nuc}^{\infty}(X:Y)\ar[d]\ar[r] & \mathbf{Nuc}^{\infty}(V:V\cap Y)\ar[d]\ar[r] & 0\ar[d]\\
    \mathbf{Nuc}^{\infty}(X)\ar[r] & \mathbf{Nuc}^{\infty}(V)\ar[r] & \mathbf{Nuc}^{\infty}(U).
    }
\end{displaymath}
In particular, we have $\mathbf{Nuc}^{\infty}(X:Z)\cong\mathrm{Fib}( \mathbf{Nuc}^{\infty}(X:Y)\rightarrow\mathbf{Nuc}^{\infty}(V:V\cap Y))$.
\end{proposition}

\begin{proposition}
    Let $U\subset X$ and $V\subset X$ be open immersions with closed complements $Y$ and $Z$ respectively. Then 
     we have a fibre product diagram
\begin{displaymath}
    \xymatrix{
    \mathbf{QCoh}(U\cup V)\ar[d]\ar[r] & \mathbf{QCoh}(U)\ar[d]\\
    \mathbf{QCoh}(V)\ar[r] & \mathbf{QCoh}(U\cap V),
    }
\end{displaymath}
in which all maps are localisations. In particular, we have
$$\mathbf{QCoh}(U\cup V:V\cap Y)=\mathbf{QCoh}(U\cup V:(U\cup V)\cap Y)\cong\mathbf{QCoh}(V:Y\cap V)$$. In the nuclear case, 
     we have a fibre product diagram
\begin{displaymath}
    \xymatrix{
    \mathbf{Nuc}^{\infty}(U\cup V)\ar[d]\ar[r] & \mathbf{Nuc}^{\infty}(U)\ar[d]\\
