\subsection{Noncommutative linear motives}

To use Corollary \ref{thm:categorified-GRR} in the context of \(K\)-theory, we first generalise the notion of noncommutative \(\bC\)-linear motives from compactly generated, presentable, stable \(\infty\)-categories to dualisable \(\infty\)-categories. To this end, let \(\bC\) be a fixed rigid category.  We call a diagram \(A \to B \to C\) in \(\mathbf{Mod}_{\bC}^{\mathrm{dual}}(\mathbf{Pr}^{L})\) a \emph{\(\bC\)-Verdier sequence} if its image under the forgetful functor \(\mathbf{Mod}_{\bC}^{\mathrm{dual}}(\mathbf{Pr}^{L}) \to \mathbf{Pr}^{L, \mathrm{dual}}\) is a Verdier sequence. A \emph{\(\bC\)-localising invariant} valued in a stable \(\infty\)-category \(\bD\) is a functor \(F \colon \mathbf{Mod}_{\bC}^{\mathrm{dual}}(\mathbf{Pr}^{L}) \to \bD\) preserving final objects and \(\bC\)-Verdier sequences. Finally, a \emph{finitary \(\bC\)-localising invariant} is a \(\bC\)-localising invariant that commutes with \(\omega_1\)-filtered colimits.  	


\begin{remark}
Notice that if \(F \colon \mathbf{Mod}_{\bC}^{\mathrm{dual}}(\mathbf{Pr}_{st}^{L}) \to \bD\) is a \(\bC\)-localising invariant for a presentably symmetric monoidal category \(\bC\), then \(F( - \otimes \bC) \colon \mathbf{Pr}^{L, \mathrm{dual}} \to \bD\) is a localising invariant. This is because tensoring by \(\bC\) preserves Verdier sequences by \cite{efimov2024k}*{Theorem 2.2}.
\end{remark}


For a presentable \(\infty\)-category \(\bC\), we define \(\mathbf{Ind}(\bC)\) as the full subcategory of \(\mathbf{Fun}(\bC^\op, \mathsf{An})\) generated by representable functors under small filtered colimits in \(\bC\). Let \(j \colon \bC \to \mathbf{Ind}(\bC) \subseteq \mathbf{Fun}(\bC^\op, \mathbf{An})\) denote the Yoneda embedding. By \cite{ramzi2024dualizable}, the \((\infty,1)\)-category \(\mathbf{Mod}_\bC^{\mathrm{dual}}(\mathbf{Pr}_{st}^{L})\) is presentable, so we may consider the following composition:


\begin{multline*}
\psi \colon \mathbf{Mod}_\bC^{\mathrm{dual}}(\mathbf{Pr}_{st}^{L}) \overset{j}\to \mathbf{Fun}((\mathbf{Mod}_\bC^{\mathrm{dual}}(\mathbf{Pr}_{st}^{L}))^\op, \mathsf{An}) \\ \overset{\mathsf{Sp}}\to \mathbf{Fun}((\mathbf{Mod}_\bC^{\mathrm{dual}}(\mathbf{Pr}_{st}^{L}))^\op, \mathsf{Sp}).
\end{multline*}

Now let \(S_{\mathrm{loc}}\) be the class of morphisms in \(\mathbf{Fun}((\mathbf{Mod}_\bC(\mathbf{Pr}_{st}^{L, \mathrm{dual}}))^\op, \mathsf{Sp})\) that map \(\omega_1\)-filtered colimits to limits, and are of the form \[0 \to \Sigma^n \psi(0), \quad \Sigma^n(\mathsf{cone}(\psi(A) \to \psi(B))) \to \Sigma^n(\psi(C)),\] where \(A \to B \to C\) is a \(\bC\)-Verdier sequence, \(n \leq 0\). 

\begin{definition}\label{def:NCMot}
For a rigid category \(\bC\), we define by \(\mathbf{NCMot}(\bC)\) the full subcategory of \(\mathbf{Fun}((\mathbf{Mod}_\bC^\mathrm{dual}(\mathbf{Pr}^{L}))^\op, \mathsf{Sp})\) generated by \(S_{\mathrm{loc}}\)-local objects. We call this is the \(\infty\)-category of \emph{noncommutative \(\bC\)-linear motives}.
\end{definition}


\begin{proposition}\label{prop:linear-localising}
Let \(\bC\) be a rigid category. Then \(\mathbf{NCMot}(\bC)\) is a stable, presentable \(\infty\)-category. 
\end{proposition}
\begin{proof}
By the definition of \(S_{\mathrm{loc}}\), the category \(\mathbf{NCMot}(\bC)\) is closed under suspensions. Furthermore, by construction it is closed under all small colimits. Finally, accessibility follows from the general fact that filtered colimit preserving functors between presentable \(\infty\)-categories is accessible. 
\end{proof}

Finally, by the presentability of \(\mathbf{NCMot}(\bC)\), the inclusion \(\mathbf{NCMot}(\bC) \to \mathbf{Fun}((\mathbf{Mod}_\bC^{\mathrm{dual}}(\mathbf{Pr}^{L}))^\op, \mathsf{Sp})\) has a left adjoint \[L \colon \mathbf{Fun}((\mathbf{Mod}_\bC^\mathrm{dual}(\mathbf{Pr}^{L}))^\op, \mathsf{Sp}) \to \mathbf{NCMot}(\bC),\] whose restriction to \(\mathbf{Mod}_\bC^\mathrm{dual}(\mathbf{Pr}^{L})\) via the Yoneda embedding yields a functor \[\mathcal{U} \colon \mathbf{Mod}_\bC^\mathrm{dual}(\mathbf{Pr}^{L}) \to \mathbf{NCMot}(\bC).\]


\begin{theorem}[Corepresentability of \(K\)-theory]\label{thm:universal-loc}
The functor \(\mathcal{U} \colon \mathbf{Mod}_\bC^{\mathrm{dual}}(\mathbf{Pr}^{L}) \to \mathbf{NCMot}(\bC)\) defined above is the universal, finitary \(\bC\)-localising invariant. Furthermore, we have \[\mathbf{NCMot}(\bC)(\mathcal{U}(\bC), \mathcal{U}(\mathbf{A})) \simeq K^\cont(\mathbf{A}).\]
\end{theorem}

\begin{proof}
By \cite{ramzi2024locally}*{Corollary 4.46}, for a rigid category \(\bC\), the forgetful functor  \[\mathbf{Mod}_{\bC}^{\mathrm{dual}} \to \mathbf{Pr}^{L, \mathrm{dual}}\] is right adjoint to extension of scalars \( - \otimes \bC\). Using the rigidity of \(\bC\), one observes that the extension of scalars functor composed with the universal localising invariant \(\mathbf{Pr}^{L, \mathrm{dual}} \to \mathbf{Mod}_{\bC}^{\mathrm{dual}} \to \mathbf{NCMot}(\bC)\) is a localising invariant, and therefore factors uniquely through \(\mathcal{U} \colon \mathbf{Pr}^{L, \mathrm{dual}} \to \mathbf{NCMot}\), yielding a symmetric monoidal, colimit-preserving functor \(\mathbf{NCMot} \to \mathbf{NCMot}(\bC)\). By the presentability of noncommutative motives, we thus have an adjunction \[\mathbf{NCMot}(\bC) \rightleftarrows \mathbf{NCMot},\] so that for a \(\bC\)-linear dualisable category \(\bD\), we have the following equivalences 
\[
\mathbf{NCMot}(\bC)(\mathcal{U}(\bC), \mathcal{U}(\bA)) \simeq \mathbf{NCMot}(\mathsf{Sp}, \mathcal{U}(\bA)) \simeq K^\mathrm{cont}(\bA),
\] where we have used that \(\mathcal{U}\) is symmetric monoidal in the first equivalence, and  \cite{blumberg2013universal}*{Theorem 9.8} for the second equivalence.
\end{proof}


\subsection{The geometric Grothendieck-Riemann-Roch Theorem}

We now specialise the results of the previous section to the rigid category \(\bC = \mathbf{Nuc}^\infty(X)\) for $X$ a qcqs scheme. To simplify notation, we will suppress the ambient symmetric monoidal \(\infty\)-category \(\mathbf{Pr}_{st}^{L}\) of presentable stable \(\infty\)-categories and simply write \(\mathbf{Mod}_{\bC}^{\mathrm{dual}}\) for \(\bC\)-linear dualisable categories. 


\begin{theorem}\label{main:GRR}
Let \(\bC = \mathbf{Nuc}^\infty(X)\) for a qcqs \(X \in \mathbf{dAn}_R\). The \(S^1\)-equivariant Chern character \[\mathsf{Ch} \colon \mathbf{Mod}_{\mathbf{C}}^{\mathrm{dual}} \to \mathcal{L}(\mathbf{Nuc}^\infty(\bC))^{S^1}\] is a \(\mathbf{C}\)-localising invariant, so it factors through \(\mathbf{C}\)-linear noncommutative motives \(\mathbf{NCMot}(\mathbf{C})\).
\end{theorem}

\begin{proof}
Let \(A \to B \to C\) be a \(\bC\)-Verdier sequence, so that it is a Verdier sequence of dualisable categories. By the same proof as in \cite{hoyois2017higher}*{Theorem 6.9}, the functors \(\mathbf{Mod}_{\mathbf{C}}^{\mathrm{dual}} \to \mathbf{Aut}(\mathcal{L}(\bC))\) and the categorified trace \(\mathbf{Aut}(\mathcal{L}(\bC)) \to \mathcal{L}(\bC)^{S^1}\) preserve zero objects and \(\bC\)-Verdier sequences. Consequently, the composition \(\mathsf{Ch}\) is a \(\bC\)-localising invariant.
\end{proof}

As a consequence, we have the following:

\begin{corollary}\label{cor:NCMot-GRR}
We have the following commuting diagram

\[
\begin{tikzcd}
\mathbf{NCMot}(\mathbf{Nuc}^\infty(X)) \arrow{r}{\mathrm{Ch}} \arrow{d}{f_*} &  \mathcal{L}(\mathbf{Nuc}^\infty(X))^{S^1} \arrow{d}{}  \\
\mathbf{NCMot}(\mathbf{Nuc}^\infty(Y)) \arrow{r}{\mathrm{Ch}} &  \mathcal{L}(\mathbf{Nuc}^\infty(Y))^{S^1}
\end{tikzcd} 
\] of \(\infty\)-categories. 
\end{corollary}


Note that the endomorphisms on the unit object on \(\mathcal{L}(\mathbf{Nuc}^\infty(X))\) is by definition the continuous topological Hochschild homology \(HH^\an(X) \defeq HH^{\mathrm{cont}}(\mathbf{Nuc}^\infty(X))\) of the dualisable category \(\mathbf{Nuc}^\infty(X)\) of infinitely nuclear sheaves. Taking mapping anima in Corollary \ref{cor:NCMot-GRR}, we obtain the following:

\begin{corollary}\label{cor:mapping-anima-mot}
For \(\mathcal{T} \in \mathbf{Mod}_{\mathbf{Nuc}^\infty(X)}^{\mathrm{dual}}(\mathcal{X})\) and \(\mathcal{T}' \in \mathbf{Mod}_{\mathbf{Nuc}^\infty(X)}^{\mathrm{dual}}(\mathcal{X})\), we have the following commuting diagram of anima 

\[
\begin{tikzcd}
\mathbf{NCMot}(\mathbf{Nuc}^\infty(X))(U(\mathbf{Nuc}^\infty(X)), U(\mathcal{T})) \arrow{r}{\mathrm{Ch}} \arrow{d}{} & \mathcal{L}(\mathbf{Nuc}^\infty(X))^{S^1}(\mathbf{1}, \mathrm{Ch}(\mathcal{T})) \arrow{d}{}\\
\mathbf{NCMot}(\mathbf{Nuc}^\infty(Y))(U(\mathbf{Nuc}^\infty(Y)), U(\mathcal{T}')) \arrow{r}{\mathrm{Ch}}  & \mathcal{L}(\mathbf{Nuc}^\infty(Y))^{S^1}(\mathbf{1}, \mathrm{Ch}(\mathcal{T}')).
\end{tikzcd}
\]
\end{corollary}




\begin{corollary}\label{thm:analytic-GRR}
Let \(f\colon X \to Y\) be a quasi-separated morphism of quasi-compact, quasi-separated derived dagger \(R\)-analytic spaces. Then the following diagram of spectra 

\[
\begin{tikzcd}
K^\an(X) \arrow{r}{\mathrm{ch}} \arrow{d}{f_*} & TC^{-,\an}(X) \arrow{d}{} \\
K^\an(Y) \arrow{r}{\mathrm{ch}} & TC^{-,\an}(Y)
\end{tikzcd}
\] commutes.
\end{corollary}

\begin{proof}
Set \(\mathcal{T} = \mathbf{Nuc}^\infty(X)\) and \(\mathcal{T}' = \mathbf{Nuc}^\infty(Y)\) in Corollary \ref{cor:NCMot-GRR}, and use Theorem \ref{thm:universal-loc}. This reduces the right hand side of the Chern character to \(\Omega \mathcal{L}(\mathbf{Nuc}^\infty(X))^{hS^1}\) and \(\Omega \mathcal{L}(\mathbf{Nuc}^\infty(Y))^{hS^1}\), which are \(HH^\an(X)^{hS^1} = TC^{-,\an}(X)\) and \(HH^\an(Y)^{hS^1} = TC^{-,\an}(Y)\), respectively. 
\end{proof}


This completes the proof of Theorem \ref{thm:GRR}. 





